    struct LTE_PHY_MIB_INFO *next; // Doubly linked list for dynamic scaling
} LTE_PHY_MIB_INFO;

LTE_PHY_MIB_INFO* create_node() {
    LTE_PHY_MIB_INFO* new_node = (LTE_PHY_MIB_INFO*) malloc(sizeof(LTE_PHY_MIB_INFO));
    if (!new_node) return NULL;

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = NULL;
    return new_node;
}

void destroy_node(LTE_PHY_MIB_INFO* node) {
    if (!node) return;

    free(node);
    pthread_mutex_destroy(&node->lock);
}

void insert_node(LTE_PHY_MIB_INFO** head, LTE_PHY_MIB_INFO* new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    LTE_PHY_MIB_INFO* current = *head;
    while (current->next != NULL) current = current->next;
    current->next = new_node;
}

LTE_PHY_MIB_INFO* remove_node(LTE_PHY_MIB_INFO** head, int cell_identity) {
