    long* offset_value;
};

void initializeRecords(std::vector<long>& offsets, std::vector<int>& keys, std::vector<std::unique_ptr<Record>>& records) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    std::mt19937 randomGenerator(std::random_device{}());

    // Allocate memory for offsets, keys and records
    offsets.resize(10000);
    keys.resize(10000);
    records.reserve(10000);

    for (size_t i = 0; i < offsets.size(); ++i) {
        // Initialize offset values with a sequential number starting from 1
        offsets[i] = static_cast<long>(i + 1);
    }

    std::uniform_int_distribution<> distribution(0, INT_MAX);

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < offsets.size(); ++i) {
        int key = keys[i] = distribution(randomGenerator);
        records.emplace_back(std::make_unique<Record>());
        records.back()->value = key;
        records.back()->offset_value = new long(offsets[i] + keys[i]);
    }
    pthread_mutex_unlock(&mutex);

