int main(int argc, char **argv) {
    FILE *input, *output;
    size_t threshold = strtoul(argv[3], NULL, 10);
    unsigned int concurrency = strtoul(argv[4], NULL, 10);
    transform_fn transformation = (transform_fn) dlsym(RTLD_DEFAULT, argv[2]);

    mmap_t *mmap = mmap(NULL, threshold, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mmap == MAP_FAILED) {
        fprintf(stderr, "Error mapping memory\n");
        return 1;
    }

    size_t read_bytes = 0;
    char *data_ptr = mmap + sizeof(mmap_t);
    chunk_t *current_chunk = NULL;

    input = fopen(argv[1], "rb");
    if (!input) {
        fprintf(stderr, "Error opening input file\n");
        return 1;
    }

    output = fopen(argv[1], "wb");
    if (!output) {
        fprintf(stderr, "Error opening output file\n");
        fclose(input);
        return 1;
    }

    while (read_bytes < ftell(input)) {
        size_t read_len = (threshold - current_chunk ? threshold : ftell(input) - read_bytes);
        void *temp_chunk = mmap(NULL, read_len, PROT_READ, MAP_PRIVATE | MAP_NOFILE, fileno(input), data_ptr + read_bytes);
        if (temp_chunk == MAP_FAILED) {
            fprintf(stderr, "Error mapping input file\n");
            fclose(input);
            fclose(output);
            return 1;
        }

        pthread_t thread_id;
        current_chunk = malloc(sizeof(chunk_t));
        current_chunk->offset = read_bytes;
        current_chunk->length = read_len;
        current_chunk->data = temp_chunk;

        pthread_create(&thread_id, NULL, process_chunk, (void *)current_chunk);

        if (read_len < threshold) {
            size_t write_len = read_len;
            memcpy(data_ptr + read_bytes + read_len, current_chunk->data, write_len);
            fwrite(data_ptr, 1, read_bytes + read_len, output);
        }

        read_bytes += read_len;
    }

    pthread_join(thread_id, NULL);
    fclose(input);
    fclose(output);
    munmap(mmap, threshold + sizeof(mmap_t));

    return 0;
}
