#include <syslog> // Logging service integration (adjust according to your logging library)

typedef struct List {
    size_t size;
    size_t capacity;
    int64_t* array;
} List;

List* list_new() {
    return calloc(1, sizeof(List));
}

void list_resize(List* list) {
    if (list->capacity == 0)
        list->capacity = 8;

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        int64_t* new_array = realloc(list->array, new_capacity * sizeof(int64_t));

        if (!new_array) {
            syslog(LOG_ERR, "Memory allocation failed");
            exit(1);
        }

        list->array = new_array;
        list->capacity = new_capacity;
    }
}

List* read_lists() {
    List* lists = list_new();
    int64_t number;
    size_t i = 0, j = 0;

    while (scanf("%" SCNi64, &number) == 1) {
        if (i >= lists->size)
            list_resize(lists);

        lists->array[i++] = number;

        if (number == -1) { // End of a list
            if (j != i - 1) {
                syslog(LOG_ERR, "Malformed data stream. Unexpected EOF.");
                exit(1);
            }
            j = i;
            continue;
        }
    }

    if (ferror(stdin)) { // Error reading from stdin
        syslog(LOG_ERR, "Error reading from stdin");
        exit(1);
    }

    lists->size = j;
    return lists;
}

void list_free(List* list) {
    free(list->array);
    free(list);
}

int main() {
    List* lists = read_lists();

    // Process the lists here...

    list_free(lists);
    return 0;
}
```

