    private readonly IDbConnectionFactory _connectionFactory;
    private readonly int _timeoutMs;

    public DatabaseExecutor(ILogger logger, IDbConnectionFactory connectionFactory, int timeoutMs = 30)
    {
        _logger = logger;
        _connectionFactory = connectionFactory;
        _timeoutMs = timeoutMs;
    }

    public async Task<IEnumerable<IDataReader>> ExecuteBatchAsync(string connectionString, IList<string> sqlCommands)
    {
        var connections = await DistributeConnections(connectionString);
        var tasks = sqlCommands.Select(ExecuteSingleCommand).ToList();
        var results = await Task.WhenAll(tasks);

        return results.Where(x => x.IsCompletedSuccessfully).Select(x => x.Result).ToList();
    }

    private async Task<IDbConnection> DistributeConnections(string connectionString)
    {
        // Implement load balancing based on geographic location or other criteria.
        var connections = new Dictionary<string, IDbConnection>();
        foreach (var server in GetAvailableServers())
        {
            connections[server] = _connectionFactory.CreateConnection(connectionString);
        }

        return await ChooseServerAsync(connections);
    }

    private async Task<IDbConnection> ChooseServerAsync(IDictionary<string, IDbConnection> connections)
    {
        var server = await ChooseServerBasedOnLatencyAsync(connections);
        _logger.LogInformation($"Selected server: {server}");
        return connections[server];
    }

    private async Task<string> ChooseServerBasedOnLatencyAsync(IDictionary<string, IDbConnection> connections)
    {
        // Implement latency measurement and choose the least-latent server.
    }

    private async Task<IDataReader> ExecuteSingleCommand(string sqlCommand)
    {
        using var connection = await DistributeConnections(connectionString);
        using var transaction = connection.BeginTransaction();
        try
        {
            await connection.OpenAsync();

            var stopwatch = Stopwatch.StartNew();
            var dbCommand = connection.CreateCommand(sqlCommand);
            dbCommand.Transaction = transaction;
            dbCommand.CommandTimeout = _timeoutMs;

            await dbCommand.ExecuteReaderAsync();

            _logger.LogInformation($"Executed command '{sqlCommand}' in {stopwatch.ElapsedMilliseconds} ms.");

            return dbCommand.CreateDataReader();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to execute command '{sqlCommand}'");
            transaction.Rollback();
            throw;
        }
    }
}
