        // Validate the optional revision number against the defined schema
        deleteSchema.validate(revision);

        const data = await getResourceByIdAndRevision(id, revision);
        if (!data) throw new Error('Resource not found or invalid revision number');

        // Delete the resource and return a new resource with default values
        const deletedData = await deleteResourceWithValidationAndRevision(id, revision + 1);

        res.status(200).json(deletedData);
    } catch (error) {
        console.error(`Error deleting resource: ${error}`);
        res.status(500).send('Internal Server Error');
    }
}
```

