public class XPathCache
{
    private readonly Dictionary<string, XPathNavigator> _cache = new();
}

public static class XmlHelper
{
    private static readonly XPathCache _xpathCache = new();

    public static IEnumerable<XElement> FindFirstXPathElement(this XDocument document, string xPath)
    {
        if (_xpathCache.TryGetValue(xPath, out var navigator))
        {
            return navigator.SelectElements(xPath);
        }

        using (var reader = document.CreateReader())
        {
            navigator = new XPathNavigator(reader, null, XmlNamespaceManager.CreateScope());
            _xpathCache[xPath] = navigator;
        }

        return navigator.SelectElements(xPath);
    }
}
