use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::Mutex;
use tempfile::{NamedTempFile, TempDir};

static DIR_CACHE: Mutex<Option<PathBuf>> = Mutex::new(None);

fn create_directory_with_envvar(dir_name: &str) -> Result<(), Box<dyn std::error::Error> {
    let path = TempDir::new(dir_name).map_err(|e| e.into())?;
    DIR_CACHE.lock().unwrap().replace(path.path());

    let dir_path = path.path();
    fs::create_dir_all(dir_path)?;
    env::set_var("PATH", dir_path.to_str().unwrap());

    // Retry logic for handling transient failures
    const RETRY_ATTEMPTS: u32 = 5;
    let mut attempts = 0;
    loop {
        match fs::metadata(dir_path) {
            Ok(_) => break,
            Err(e) => {
                if attempts >= RETRY_ATTEMPTS {
                    return Err(e);
                }

                // Exponential backoff to avoid flooding the system with requests
                std::thread::sleep(std::time::Duration::from_secs(2u32.pow(attempts)));
                attempts += 1;
            }
        }
    }

    Ok(())
}
