using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Web.Mvc;
using Microsoft.AspNetCore.Caching.Distributed;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

public class ContentController : Controller
{
    private readonly IAuthorizationService _authorizationService;
    private readonly IDistributedCache _cache;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ILogger<ContentController> _logger;

    public ContentController(IAuthorizationService authorizationService, IDistributedCache cache, IHttpClientFactory httpClientFactory, ILogger<ContentController> logger)
    {
        _authorizationService = authorizationService;
        _cache = cache;
        _httpClientFactory = httpClientFactory;
        _logger = logger;
    }

    [HttpPost]
    public async Task<ActionResult> UpdatePageContent(int pageSectionId, int elementId, string htmlContent)
    {
        if (!Request.Headers.TryGetValues("Origin", out var origins) || !origins.Contains(new Uri(Constants.ValidOrigins).OriginalString))
            return Forbid();

        if (!await _authorizationService.HasPermissionToModifySection(pageSectionId, User.Identity.Name))
            return StatusCode(403, "Forbidden.");

        var key = $"{nameof(UpdatePageContent)}:{pageSectionId}:{elementId}";
        var cachedHtmlContent = await _cache.GetAsync(key);

        if (cachedHtmlContent != null)
        {
            _logger.LogInformation($"Retrieved cached HTML content for page section {pageSectionId} and element {elementId}.");
            return Content(cachedHtmlContent, "text/html");
        }

        using var httpClient = _httpClientFactory.CreateClient();
        var response = await httpClient.PostAsync($"https://cdn-api.example.com/update", new StringContent(htmlContent));

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError($"Failed to update HTML content for page section {pageSectionId} and element {elementId}. Status code: {response.StatusCode}.");

            // Implement retry logic with exponential backoff
            throw new Exception("Update failed, retrying...");
        }

        await _cache.RemoveAsync(key);

        return Content(htmlContent, "text/html");
    }
}
```
