import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.awt.image.*;

public class MostUtility {
    private static final String THEME_DIRECTORY = System.getProperty("themeDirectory", "defaultThemeDirectory");
    private static ConcurrentHashMap<String, BufferedImage> themeCache = new ConcurrentHashMap<>();

    public static MoSTState loadState(String filePath) {
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        MoSTState state = null;

        try {
            fis = new FileInputStream(filePath);
            ois = new ObjectInputStream(fis);

            state = (MoSTState) ois.readObject();

            if (!state.getClass().equals(MoSTState.class)) {
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            try {
                if (ois != null) ois.close();
                if (fis != null) fis.close();
            } catch (IOException ex) {
                ex.printStackTrace();
            }
        }

        return state;
    }

    public static BufferedImage getTheme(String themeName) {
        synchronized (themeCache) {
            BufferedImage bitmap = themeCache.get(themeName);
            if (bitmap != null) {
                return bitmap;
            }
        }

        File themeFile = new File(THEME_DIRECTORY, themeName + ".bin");
        if (!themeFile.exists()) {
            themeFile = new File("defaultThemeDirectory", themeName + ".bin");
        }

        if (themeFile.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(themeFile))) {
                bitmap = (BufferedImage) ois.readObject();
                synchronized (themeCache) {
                    themeCache.put(themeName, bitmap);
                }
                return bitmap;
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }
        }

        return null;
    }
}
