const axios = require('axios');
const chalk = require('chalk');
const { parallelLimit } = require('async');
const { config } = require('dotenv');
const logSymbols = require('log-symbols');
const testFramework = require('your-test-framework'); // replace with your preferred test framework
const logger = require('winston'); // replace with your preferred logging library

// Initialize dotenv for config management
config();

async function runTests(repoURL, moduleName, testLabel, testFunction) {
  const MAX_CONCURRENT_TESTS = parseInt(process.env.MAX_CONCURRENT_TESTS || '3');
  let totalTestsExecuted = 0;
  let testsPassed = 0;
  let testsFailed = 0;

  // Function to load the module asynchronously
  async function loadModule() {
    try {
      const response = await axios.get(`${repoURL}/-/raw/${moduleName}.js`);
      return new Function('return ' + response.data)();
    } catch (error) {
      console.error(chalk.red(`Failed to load module from ${repoURL}: ${error.message}`));
      throw error;
    }
  }

  // Function to execute a test with logging and error handling
  async function execTest(testName, testFn) {
    try {
      const startTime = Date.now();
      await testFn();
      console.log(`${chalk.green(logSymbols.success)} ${testName}: Pass`);
      testsPassed++;
    } catch (error) {
      console.log(`${chalk.red(logSymbols.fail)} ${testName}: Fail`);
      testsFailed++;
      console.error(`Error: ${error.message}`);
    }
    const executionTime = Date.now() - startTime;
    logger.info({ testName, executionTime }, 'Test Execution');
  }

  // Load the module and run the specified tests in parallel
  async function runTestsInParallel() {
    const loadedModule = await loadModule();
    const testFunctions = Object.values(loadedModule[testLabel]);

    return new Promise((resolve, reject) => {
      parallelLimit(testFunctions.length, MAX_CONCURRENT_TESTS, (testFn, callback) => {
        execTest(`${moduleName}.${testFn.name}`, testFn);
        callback();
      }, (err) => {
        if (err) return reject(err);
        resolve();
      });
    });
  }

  try {
    await runTestsInParallel();
    console.log(`${chalk.green} Test Summary:`);
    console.log(`- Total Tests Executed: ${totalTestsExecuted}`);
    console.log(`- Tests Passed: ${testsPassed}`);
    console.log(`- Tests Failed: ${testsFailed}`);
  } catch (error) {
    console.error(chalk.red(`Test execution failed: ${error.message}`));
  }
}
