// Helper function to infer file type and extension from the identifier
function inferFileTypeAndExtension(identifier) {
  const extensions = ['.js', '.json']; // Add more supported formats as needed
  let fileTypeAndExtension = extensions.find((ext) => identifier.endsWith(ext));

  if (!fileTypeAndExtension) {
    fileTypeAndExtension = extensions[0];
  }

  return { type: fileTypeAndExtension.slice(1), extension: fileTypeAndExtension };
}

// Function to load and execute a JavaScript module
async function loadModuleByIdentifier(identifier) {
  try {
    const { type, extension } = inferFileTypeAndExtension(identifier);
    const filename = `module_${identifier}${extension}`;
    const filePath = path.join(__dirname, filename);

    if (fs.existsSync(filePath)) {
      const module = await import(filePath);
      return module.default || module;
    } else {
      console.error(`Could not find or load ${filename}`);
    }
  } catch (error) {
    console.error(`Error loading ${identifier}:`, error);
  }
}

// Example usage: An array of identifiers to be loaded and executed dynamically
