use std::time::{SystemTime, Duration};
use rustc_driver::{compile, catch_with_exit_code, BuildError};
use libc::malloc;
use libc::free;

fn compile_rust_project(source_files: Vec<String>, target: String) {
    let start = SystemTime::now();
    let mut rss_before = get_rss();

    // Check for necessary dependencies and log warnings if they are not found
    let missing_deps = check_dependencies();
    if !missing_deps.is_empty() {
        log(format!("Missing dependencies: {}", missing_deps).into_iter().collect::<Vec<String>>(), LogLevel::Warning);
    }

    // Create build script if necessary
    let build_script = "build.rs";
    if !Path::new(&build_script).exists() {
        let mut file = File::create(build_script).unwrap();
        writeln!(file, "use rustc_package::Package; fn main() {{ Package::new(\"my_project\").execute(\"compile\").unwrap(); }}").unwrap();
    }

    // Compile the project using rustc and capture output and error streams
    let mut output = Vec::new();
    let mut error = Vec::new();
    Command::new("rustc")
        .args(&source_files)
        .arg("-o")
        .arg(&target)
        .arg(build_script)
        .stdout(io::Stdout.locked())
        .stderr(io::Stderr.locked())
        .output()
        .expect("Failed to compile Rust project");

    // Measure the time taken for compilation and log it at Info level
    let duration = SystemTime::now().duration_since(start).unwrap();
    log(format!("Compilation time: {}s", duration.as_secs()), LogLevel::Info);

    // Track memory usage changes using get_resident_set_size and log at Info level
    let rss_after = get_rss();
    log(format!("Memory usage change: {}", rss_after - rss_before), LogLevel::Info);

    if error.is_empty() {
        log(format!("Successfully compiled {} to {}!", source_files.join(" "), target), LogLevel::Success);
    } else {
        let exit_code = catch_with_exit_code(|e| Command::new("cargo")
            .arg("run")
            .arg("--bin")
            .arg(&target)
            .output()
            .expect("Failed to run Cargo")
            .code()
            .unwrap_or(1), |_| {
                // Alternative build strategy if primary method fails (e.g., integrate a build cache here)
            })
            .unwrap();
        log(format!("Compilation failed with exit code: {}", exit_code), LogLevel::Error);
    }
}

fn get_rss() -> usize {
    let mut rss = 0;
    let mut proc = unsafe { libc::getprocstatus(unsafe { libc::getpid() }) };
    while libc::ptrace(libc::PTRACE_GETSTAT, proc.ts_ppid, 0, 0) == 0 {
        proc = unsafe { libc::wait(&mut proc, 0) };
    }

    let mut rss_size: libc::off_t = 0;
    unsafe {
        let rssm = mem::transmute::<libc::c_char, *mut libc::rusage>(&mut rss);
        libc::ptrace(libc::PTRACE_GETRUSAGE, proc.ts_ppid, 0, rssm as libc::c_ulong)
    }

    rss = (rss.ru_maxrss * mem::size_of::<usize>()) as usize;
    rss
}

