<?php
namespace App\Services;

use Illuminate\Support\Facades\Redis;
use Illuminate\Database\ConnectionInterface;
use Illuminate\Support\Facades\Config;

class UserService {
    protected $connection;
    protected $redis;

    public function __construct(ConnectionInterface $connection, Redis $redis) {
        $this->connection = $connection;
        $this->redis = $redis;
    }

    public function getUsers($departmentId, $status = null, $page = 1, $pageSize = Config::get('app.pagination_limit'), $customField = null) {
        $cacheKey = 'users:' . $departmentId . ':' . ($status ?: 'all') . ':' . $page;
        if (!$this->redis->exists($cacheKey)) {
            $data = $this->connection
                ->table('Users')
                ->where('DepartmentID', $departmentId)
                ->when(!is_null($status), function ($query) use ($status) {
                    return $query->where('Active', $status);
                })
                ->when(!is_null($customField), function ($query) use ($customField) {
                    return $query->where($customField, '=', request()->input($customField));
                })
                ->offset(($page - 1) * $pageSize)
                ->limit($pageSize)
                ->get(['id', 'name', 'email', 'phone', 'DepartmentID']);

            $this->storeInCache($cacheKey, $data);
        }

        return $this->redis->hgetall($cacheKey);
    }

    protected function storeInCache($key, $value) {
        $ttl = Config::get('cache.user_data_ttl');
        $this->redis->setex($key, $ttl, phpserialize($value));
    }
}
```
