    private $curl;
    private $fileUrl;
    private $lastModifiedTimestamp;
    private $hashedPassword;

    private function __construct($charSet, $length) {
        $this->charSet = $charSet;
        $this->length = $length;
        $this->curl = curl_init();
    }

    public static function getInstance($charSet, $length): self {
        if (!self::$instance) {
            self::$instance = new self($charSet, $length);
        }
        return self::$instance;
    }

    public function fetchFileContent($fileUrl) {
        $this->fileUrl = $fileUrl;
        curl_setopt($this->curl, CURLOPT_URL, $fileUrl);
        curl_setopt($this->curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($this->curl, CURLOPT_HEADER, false);
        curl_setopt($this->curl, CURLOPT_FAILONERROR, true);
        $response = curl_exec($this->curl);
        if ($response === false) {
            throw new Exception(curl_error($this->curl));
        }
        $headersSize = curl_getinfo($this->curl, CURLINFO_HEADER_SIZE);
        $header = substr($response, 0, $headersSize);
        $body = substr($response, $headersSize);
        preg_match('#\s*Last-Modified:\s*(.+)#', $header, $matches);
        if (count($matches) > 1) {
            $this->lastModifiedTimestamp = strtotime($matches[1]);
        }
        curl_close($this->curl);
        return $body;
    }

    public function hashPassword($password, $defaultHashFunction = 'sha256') {
        return password_hash($password, $defaultHashFunction);
    }

    public function generate() {
        if (!$this->lastModifiedTimestamp || !$this->hashedPassword) {
            try {
                $fileContent = $this->fetchFileContent($this->fileUrl);
                $this->lastModifiedTimestamp = strtotime(substr(sprintf("%c %<d %b %Y %T", gmdate("D, d M Y H:i:s \\G\\M\T"), $this->fileUrl), 0, -1));
                $this->hashedPassword = $this->hashPassword('your-secret-password'); // Replace with your desired password for hashing.
            } catch (Exception $e) {
                // Handle exceptions based on your application's needs.
            }
        }

        $randomString = '';
        $timeLimit = 3; // Time limit in seconds, adjust based on your server performance and requirements.
        $startTime = microtime(true);
        while ((microtime(true) - $startTime) < $timeLimit && strlen($randomString) < $this->length) {
            $charIndex = rand(0, strlen($this->charSet) - 1);
            $randomString .= $this->charSet[$charIndex];
        }

        usleep(100000); // Add a small delay to manage concurrent requests efficiently.

        return [
            'random_string' => $randomString,
            'file_last_modified_timestamp' => $this->lastModifiedTimestamp,
            'hashed_password' => $this->hashedPassword
        ];
    }
}
