async function generatePEMCertificateFromStream(oauthRequest, readStream) {
  const { primaryCert, privateKey } = extractCredentials(oauthRequest);
  let extendedCertExtensions = [];
  let isResuming = false;

  readStream.on('data', async chunk => {
    if (!isResuming) {
      // Validate and parse the external stream for certificate extensions
      const parsedChunk = parseCertificateExtension(chunk.toString());
      if (parsedChunk) {
        extendedCertExtensions = extendedCertExtensions.concat(parsedChunk);
      }
      isResuming = true;
    }

    return readStream.pause();
  });

  readStream.on('end', async () => {
    // Merge primary certificate, private key, and extensions into a single PEM file
    const finalCertificate = mergePEMCertificates(primaryCert, privateKey, extendedCertExtensions);

    // Validate the final certificate structure and content
    if (validateCertificate(finalCertificate)) {
      emitCertificateToApplicationLayer(finalCertificate);
    } else {
      handleInvalidCertificateError();
    }
  });

  readStream.on('error', error => {
    if (!isResuming) {
      // Retry reading the stream if it encounters an error, e.g., network issues
      await new Promise(resolve => setTimeout(resolve, RETRY_INTERVAL));
      return generatePEMCertificateFromStream(oauthRequest, readStream);
    }

    handleStreamError(error);
  });

  // Resume the stream reading from the current position
  return readStream.resume();
}
```

