#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char hostname[256];
    u_char ip_address[16];
    int error;
} DnsResult;

void *dns_resolve(const char* hostname) {
    struct hostent *host = gethostbyname(hostname);
    if (!host) return NULL;

    memcpy(result->ip_address, host->h_addr, host->h_length);
    result->error = 0;
    pthread_exit(result);
}

void dns_error(const char* message) {
    strcpy(result->hostname, message);
    result->error = -1;
    pthread_exit(result);
}

DnsResult* dns_query(const char* hostname) {
    DnsResult result = {0};
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, dns_resolve, hostname) != 0)
        return &result; // Failed to create the thread.

    void* thread_result = pthread_join(thread_id, (void**)&result);
    if (!thread_result) dns_error("Thread failed.");
    return &result;
}
