// Attack struct with details and usage counter
struct Attack {
    std::string name;
    int damage, visual_effects;
    uint64_t last_used = 0;
};

std::map<int, Attack> attacks; // key: id, value: attack instance
std::mutex mtx;
std::atomic<uint64_t> globalTimer(0); // Global timer for cooldown calculation
const int maxFileSize = 1024 * 1024; // 1MB file size limit
std::ofstream logFile("attackLog.txt", std::ios::app | std::ios::out);

void loadAttacks() {
    // Load attacks from AttackDB API and fetch additional details here
}

void selectAttack() {
    auto now = std::chrono::high_resolution_clock::now();
    int elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - globalTimer).count();

    if (elapsed < 500) // Cooldown period
        return;

    std::vector<Attack> candidates;
    {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& it : attacks) {
            auto elapsedSinceLastUse = now - it.second.last_used;
            if ((elapsedSinceLastUse / 1000) >= it.second.id % 4 + 1) // Prioritize less frequently used attacks
                candidates.push_back(it.second);
        }
    }

    auto selected = candidates[rand() % candidates.size()];
    selected.last_used = now;

    // Fetch additional details here using AttackDB API

    logFile << selected.name << " used at " << now.time_since_epoch().count() << std::endl;
}

void refreshCache() {
    loadAttacks();
    std::lock_guard<std::mutex> lock(mtx);
    attacks = {}; // Clear cache

    for (auto& it : loadedAttacks) {
        auto id = it.first;
        auto attack = it.second;
        attacks[id] = attack;
    }
}

void run() {
    loadAttacks();

    boost::asio::io_service ioService;
    std::unique_ptr<boost::asio::deadline_timer> timer(new boost::asio::deadline_timer(ioService, boost::posix_time::seconds(1))); // 1 second refresh interval for cache

    while (true) {
        selectAttack();
        timer->async_wait([&](const boost::system::error_code& error) {
            if (!error) {
                refreshCache();
                timer->expires_from_now(boost::posix_time::seconds(1));
                ioService.reset(); // Resetting the service ensures it doesn't get blocked indefinitely
                ioService.run_one();
            }
        });
    }
}
```

