```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private readonly object syncLock = new object();
    private Func<double, Task<(double Min, double Max)>?> dataSource;

    public RandomValueGenerator() : this((double.MinValue, double.MaxValue)) { }

    public RandomValueGenerator((double min, double max) range)
    {
        SetRange(range);
    }

    public RandomValueGenerator(Func<double, Task<(double Min, double Max)}} dataSourceFunction)
    {
        this.dataSource = dataSourceFunction;
    }

    public void SetDataSources(Func<double, Task<(double Min, double Max)}} dataSource) => this.dataSource = dataSource;

    private async Task SetRange((double min, double max) range)
    {
        if (range.min >= range.max)
            throw new ArgumentOutOfRangeException("range", "Minimum value must be less than maximum value.");

        lock (syncLock)
        {
            this.minValue = Math.Max(Math.Min(range.min, range.max), double.MinValue);
            this.maxValue = Math.Min(Math.Max(range.min, range.max), double.MaxValue);
        }
    }

    public void SetRange(double min, double max) => SetRange((min, max));

    private double GenerateRandomDoubleInclusive()
    {
        if (maxValue <= minValue)
            throw new InvalidOperationException("The range is invalid. Maximum value must be greater than minimum value.");

        return new Random().NextDouble() * (maxValue - minValue) + minValue;
    }

    private double GenerateRandomDoubleExclusive()
    {
        if (maxValue <= minValue)
            throw new InvalidOperationException("The range is invalid. Maximum value must be greater than minimum value.");

        return new Random().NextDouble() * (maxValue - minValue) + minValue;
    }

    private int GenerateRandomIntInclusive() => Convert.ToInt32(GenerateRandomDoubleInclusive());

    private int GenerateRandomIntExclusive() => Convert.ToInt32((GenerateRandomDoubleExclusive()));

    public override string ToString()
    {
        return $"Min: {minValue}, Max: {maxValue}";
    }

    public async Task<double> GetRandomDoubleInclusiveAsync()
    {
        if (dataSource == null)
            return GenerateRandomDoubleInclusive();

        var range = await dataSource();

        lock (syncLock)
        {
            minValue = Math.Max(minValue, range.Min);
            maxValue = Math.Min(maxValue, range.Max);
        }

        return GenerateRandomDoubleInclusive();
    }

    public async Task<double> GetRandomDoubleExclusiveAsync()
    {
        if (dataSource == null)
            return GenerateRandomDoubleExclusive();

        var range = await dataSource();

        lock (syncLock)
        {
            minValue = Math.Max(minValue, range.Min);
            maxValue = Math.Min(maxValue, range.Max);
        }

        return GenerateRandomDoubleExclusive();
    }
}
