// Simulate validation delay and failure rate
const VALIDATION_DELAY = Math.random() * 100; // in milliseconds
const FAILURE_RATE = Math.random() < 0.05;

const validateNumber = promisify((num, callback) => {
  setTimeout(async () => {
    if (FAILURE_RATE) return callback(new Error('Validation failure'));
    // Simulate external validation service here
    callback(null, num * 2); // Return validated number * 2 for demonstration purposes
  }, VALIDATION_DELAY);
});

const asyncReduce = (arr, initialValue, callback) => {
  let acc = initialValue;
  const maxConcurrentValidations = Math.min(arr.length, 5); // Optimize for performance with a max concurrency limit
  let validatingIndices = new Set();

  const validateAndReduce = async (index) => {
    if (!validatingIndices.has(index)) {
      validatingIndices.add(index);

      try {
        const num = arr[index];
        const validatedNum = await validateNumber(num, (err, validNum) => {
          if (err) throw err; // Propagate validation errors
          acc += validNum; // Perform reduction
          validatingIndices.delete(index);
        });
      } catch (error) {
        console.error(`Error at index ${index}:`, error.message);
        validatingIndices.delete(index);
      } finally {
        if (validatingIndices.size < maxConcurrentValidations) {
          validateAndReduce((index + 1) % arr.length); // Loop through the array and validate next number
        }
      }
    }
  };

  validateAndReduce(0); // Start the validation process
  return acc;
};

