#include "user_profiles.h"
#include <assert.h>
#include <stdlib.h>
#include <string.h>

void profile_list_init(ProfileList* list, size_t initial_capacity) {
    assert(list != NULL);

    list->profiles = malloc(initial_capacity * sizeof(UserProfile));
    if (!list->profiles) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void profile_list_destroy(ProfileList* list) {
    assert(list != NULL);

    free(list->profiles);
    pthread_mutex_destroy(&list->mutex);
}

bool profile_list_add(ProfileList* list, const UserProfile* user) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        UserProfile* new_profiles = realloc(list->profiles, new_capacity * sizeof(UserProfile));
        if (!new_profiles) {
            perror("realloc");
            return false;
        }
        list->profiles = new_profiles;
        list->capacity = new_capacity;
    }

    pthread_mutex_lock(&list->mutex);
    memcpy(&(list->profiles[list->count]), user, sizeof(UserProfile));
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return true;
}

UserProfile* profile_list_get(ProfileList* list, int id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->profiles[i].id == id) {
            return &(list->profiles[i]);
        }
    }

    return NULL;
}

bool profile_list_remove(ProfileList* list, int id) {
    UserProfile* user = profile_list_get(list, id);
    if (!user) {
        return false;
    }

    pthread_mutex_lock(&list->mutex);

    // Shift elements to fill the gap left by the removed element.
    for (size_t i = user - list->profiles; i < list->count - 1; ++i) {
        list->profiles[i] = list->profiles[i + 1];
    }

    --list->count;
    pthread_mutex_unlock(&list->mutex);

    return true;
}

void profile_list_save(const ProfileList* list, FILE* file) {
    // Implement serialization logic here...
}

ProfileList* profile_list_load(FILE* file) {
    // Implement deserialization logic here...
}
