#include <stdbool.h>
#include <string.h>
#include <X11/Xlib.h>
#include <X11/extensions/XInput2.h>
#include <xcb/xcb.h>
#include <xcb/xcb_atom.h>
#include <xcb/render.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct Config {
    int max_depth;
    int timeout;
    bool include_whitespace;
} Config;

typedef struct Node {
    char *content;
    struct Node *parent, *next;
} Node;

Node* processString(const char *str, int size_limit, const Config *cfg) {
    XrmValueList resources;
    Window root_window;
    Atom wm_protocols;
    Display *dpy = XOpenDisplay(NULL);
    int screen_num = DefaultScreen(dpy);
    Screen *screen = XScreenOfDisplay(dpy, screen_num);
    Atom atom;
    XSetWindowAttributes swa;
    Window win;
    GC gc;
    int depth = screen->depth;
    Colormap colormap = screen->root->colormap;
    Visual *visual = screen->rootVisual;
    unsigned long black_pixel, white_pixel;
    XEvent event;
    char *selector;
    Node *head = NULL, *tail = NULL, *current;
    int recursion_depth = 0, timeout_timer = cfg->timeout;

    black_pixel = BlackPixel(dpy, screen_num);
    white_pixel = WhitePixel(dpy, screen_num);
    swa.background_pixel = black_pixel;
    swa.border_pixel = white_pixel;

    atom = XInternAtom(dpy, "_NET_WM_DELETE_WINDOW", False);
    resources.atom = atom;
    resources.format = 32;
    resources.data = &win;
    resources.length = sizeof(Window);

    selector = (char *)malloc(strlen(str) + 1);
    strcpy(selector, str);

    if (!XParseGeometry(&resources)) {
        free(selector);
        return NULL;
    }

    root_window = resources.data[0];
    win = XCreateSimpleWindowArg(dpy, root_window, resources.data[1], resources.data[2],
            resources.data[3], resources.data[4], resources.data[5], swa.background_pixel, swa.border_pixel);

    gc = XCreateGC(dpy, win, 0, NULL);

    wm_protocols = XInternAtom(dpy, "WM_PROTOCOLS", False);
    XSetWMProtocols(dpy, win, &atom, 1);

    XSelectInput(dpy, win, ExposureMask | KeyPressMask);

    while (XCheckWindowEvent(dpy, win, KeyPressMask, &event) || recursion_depth < cfg->max_depth) {
        if (timeout_timer > 0) timeout_timer--;
        if (event.type == KeyPress && event.xkey.keycode == XK_Escape) {
            break;
        }
        if (recursiveTraverse(dpy, win, selector, cfg, &head, &tail, recursion_depth + 1, timeout_timer)) {
            current = head;
            if (strlen((char *)current->content) + strlen("/") > size_limit) {
                free(selector);
                return NULL;
            }
            tail->next = malloc(sizeof(Node));
            tail = tail->next;
            tail->parent = current;
            tail->content = strdup("");
            recursion_depth = 0;
            timeout_timer = cfg->timeout;
        }
    }

    if (strlen((char *)current->content) + strlen("/") <= size_limit) {
        strcat(tail->content, "/");
    }

    XCloseDisplay(dpy);
    free(selector);

    Node *result = head;
    while (head != NULL) {
        head = head->next;
        free(result->content);
        free(result);
        result = head;
    }

    return result;
}

bool recursiveTraverse(Display *dpy, Window window, const char *selector, const Config *cfg, Node **head_ptr, Node **tail_ptr, int recursion_depth, int timeout) {
    Atom wm_class;
    Atom actual_type;
    int actual_format;
    unsigned long nitems, bytes_after;
    unsigned char *property;
    XTextProperty textprop;
    int match = 0;

    if (recursion_depth > cfg->max_depth || timeout <= 0) {
        return false;
    }

    if (!XGetWMClass(dpy, window, &wm_class, NULL)) {
        return false;
    }

    if (strlen(wm_class) >= strlen(selector) && strncmp(wm_class, selector, strlen(selector)) == 0) {
        match = 1;
    }

    XGetWindowProperty(dpy, window, XA_WM_NAME, 0L, sizeof(textprop), False, AnyPropertyType, &actual_type, &actual_format, &nitems, &bytes_after, &property);

    if (match && actual_type == XA_STRING) {
        textprop.value = property;
        textprop.encoding = XA_STRING;
        textprop.format = 8;
        textprop.nitems = nitems;

        if (strlen((char *)textprop.value) >= strlen(selector) && strncmp((char *)textprop.value, selector, strlen(selector)) == 0) {
            match = 1;
        }
    }

    XFree(property);

    if (!match) {
        return false;
    }

    if (cfg->include_whitespace) {
        Window *children;
        unsigned int nb_children, i;

        XQueryTree(dpy, window, &root_window, &children, &nb_children);

        for (i = 0; i < nb_children; ++i) {
            if (recursiveTraverse(dpy, children[i], selector, cfg, head_ptr, tail_ptr, recursion_depth + 1, timeout)) {
                return true;
            }
        }

        XFree(children);
    } else {
        if (recursiveTraverse(dpy, window, selector, cfg, head_ptr, tail_ptr, recursion_depth + 1, timeout)) {
            return true;
        }
    }

    return false;
}
