    const char *default_theme_dir = get_default_theme_directory();

    if (!default_theme_dir) {
        // Initialize default theme directory using predefined value
        mkdir(default_theme_dir, 0755);
        printf("Default theme directory initialized: %s\n", default_theme_dir);
    }

    FILE *file = fopen("input.txt", "r");
    LineData *lines = NULL; // Dynamically allocated array to store line data
    size_t capacity = 0, current_size = 0;

    while (1) {
        char line[4096];
        ssize_t len = fgets(line, sizeof(line), file);

        if (len < 1) break; // End of file reached

        if (current_size >= capacity) {
            capacity *= 2;
            LineData *tmp = realloc(lines, capacity * sizeof(LineData));

            if (!tmp) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }

            lines = tmp;
        }

        size_t line_len = strlen(line);
        lines[current_size].length = line_len;
        lines[current_size].line = malloc(line_len + 1); // Extra byte for null terminator

        if (!lines[current_size].line) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        memcpy(lines[current_size].line, line, line_len + 1);
        current_size++;
    }

    fclose(file);

    // Process lines in parallel with thread safety
    pthread_t threads[current_size];
    for (size_t i = 0; i < current_size; ++i) {
        pthread_create(&threads[i], NULL, process_line, &lines[i]);
    }

    for (size_t i = 0; i < current_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (size_t i = 0; i <= current_size; ++i) {
        free(lines[i].line);
    }
    free(lines);

    return 0;
}

void *process_line(void *arg) {
    LineData *line = arg;
    char *fields[5] = {NULL}; // Comma-separated fields
    size_t num_fields = 0;
    char *token = strtok(line->line, ",");

    while (token) {
        fields[num_fields++] = token;
        token = strtok(NULL, ",");
    }

    double average = (atof(fields[num_fields - 2]) + atof(fields[num_fields - 1])) / 2.0;
    char comma_separated[1024]; // More than enough space for the formatted line
    snprintf(comma_separated, sizeof(comma_separated), "%s%s%f", fields[0], (num_fields > 1) ? "," : "", average);

    pthread_mutex_lock(&mutex);
    // Implement your optimization here to minimize memory leaks and handle concurrent access to shared resources.
    pthread_mutex_unlock(&mutex);

    return NULL;
}
