        result->error_message = data.error_message;
        return;
    }

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    if (pthread_join(thread_id, NULL) != 0) {
        snprintf(data.error_message, sizeof(data.error_message), "Failed to join thread: %s", strerror(errno));
        result->error_message = data.error_message;
        return;
    }

    gettimeofday(&end_time, NULL);
    long elapsed_milliseconds = (end_time.tv_usec - start_time.tv_usec) / 1000 + (end_time.tv_sec - start_time.tv_sec) * 1000;

    if (data.tif_ptr == NULL || strcmp(data.error_message, "")) {
        snprintf(result->error_message, sizeof(result->error_message), "%s", data.error_message);
        return;
    }

    generate_md5_hash(&data);

    sem_destroy(&lock);
    sqlite3_close(db);

    result->image_info = data.image_info;
    strcpy(result->md5_hash, data.md5_hash);
