['```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <time.h>
#include <fnmatch.h>

typedef struct {
    char *path;
    char *filename;
    size_t path_len;
    size_t filename_len;
} FileData;

unsigned int hash(const char *str) {
    unsigned int hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % UINT_MAX;
}

int is_unique(const char *filename, DIR *dir) {
    struct dirent *entry;
    bool unique = true;
    char fullpath[256];
    strcat(fullpath, dir->d_name);
    strcat(fullpath, "/");
    strcat(fullpath, filename);

    while ((entry = readdir(dir)) != NULL) {
        if (!fnmatch(".*.*", entry->d_name, 0)) continue;
        strcat(fullpath, "/");
        strcat(fullpath, entry->d_name);
        if (hash(fullpath) == hash(filename)) {
            unique = false;
            break;
        }
    }

    closedir(dir);
    return unique;
}

char *generate_identifier(const char *filename, const char *path) {
    FileData data = {.path = strdup(path), .filename = strdup(filename)};
    data.path_len = strlen(data.path);
    data.filename_len = strlen(data.filename);

    size_t max_id_length = 20 + data.filename_len; // Base length for filename content and path depth

    char *identifier = malloc(max_id_length);
    snprintf(identifier, max_id_length, "%s%lu%c", data.filename, (unsigned long)hash({data.path, data.filename, data.filename_len + data.path_len}), '_');

    DIR *dir = opendir(data.path);
    if (!dir) {
        free(identifier);
        return NULL;
    }

    while (!is_unique(identifier, dir)) {
        size_t new_length = max_id_length + 1;
        char *new_identifier = realloc(identifier, new_length);
        if (!new_identifier) {
            free(identifier);
            closedir(dir);
            return NULL;
        }
        identifier = new_identifier;
        max_id_length++;

        snprintf(identifier + (max_id_length - 1), 2, "%c", '_'); // Append underscore to extend the identifier
    }

    closedir(dir);
    return identifier;
}

void clean_up(FileData *data) {
    free(data->path);
    free(data->filename);
}

char *generate_unique_file_identifier(const char *filename, const char *directory_path) {
    FileData data = {.path = strdup(directory_path), .filename = strdup(filename)};
    char *identifier = generate_identifier(&data);
    if (!identifier) {
        clean_up(&data);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    DIR *dir = opendir(data.path);
    if (!dir) {
        free(identifier);
        clean_up(&data);
        return NULL;
    }

    struct dirent **namelist;
    int n = scandir(data.path, &namelist, NULL, alphasort);
    pthread_mutex_destroy(&lock);

    if (n < 0) {
        free(identifier);
        clean_up(&data);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        char fullpath[256];
        strcat(fullpath, data.path);
        strcat(fullpath, "/");
        strcat(fullpath, namelist[i]->d_name);

        if (fnmatch(".*.*", namelist[i]->d_name, 0) && hash({data.path, namelist[i]->d_name, data.filename_len + data.path_len}) == hash({data.path, identifier, data.filename_len + data.path_len})) {
            free(identifier);
            clean_up(&data);
            for (int j = 0; j < i; ++j)
                free(namelist[j]);
            free(namelist);
            return NULL;
        }
    }

    for (int i = 0; i < n; ++i)
        free(namelist[i]);
    free(namelist);

    clean_up(&data);
    return identifier;
}
```

