typedef struct {
    sem_t lock;
    ServiceConfig config;
    pthread_t thread_id;
    bool initialized;
} Resource;

Resource* resources;
int resource_count;

void validate(json_t* conf) {
    if (!json_is_object(conf)) {
        fprintf(stderr, "Configuration must be an object.\n");
        return;
    }

    json_t* instances = json_object_get(conf, "instances");
    if (!instances || !json_is_array(instances)) {
        fprintf(stderr, "Missing 'instances' section or it is not an array.\n");
        return;
    }

    for (int i = 0; i < json_array_size(instances); ++i) {
        json_t* instance = json_array_get(instances, i);
        if (!json_is_object(instance)) {
            fprintf(stderr, "Instance at index %d is not an object.\n", i);
            return;
        }

        json_t* server = json_object_get(instance, "server");
        json_t* database = json_object_get(instance, "database");
        json_t* logging = json_object_get(instance, "logging");

        if (!server || !database || !logging) {
            fprintf(stderr, "Missing 'server', 'database', or 'logging' section for instance %d.\n", i);
            return;
        }

        validate_service_config(server);
        validate_db_config(database);
        validate_logging_config(logging);
    }
}

void validate_service_config(json_t* conf) {
    if (!json_is_object(conf)) return;

    json_t* host = json_object_get(conf, "host");
    json_t* port = json_object_get(conf, "port");
    json_t* protocol = json_object_get(conf, "protocol");
    json_t* username = json_object_get(conf, "username");
    json_t* password = json_object_get(conf, "password");
    json_t* url = json_object_get(conf, "url");
    json_t* level = json_object_get(conf, "level");

    if (!host || !port || !protocol || !username || !password || !url || !level) {
        fprintf(stderr, "Missing field for service config.\n");
        return;
    }

    if (strlen(protocol) != 5 || strcmp(protocol, "http") && strcmp(protocol, "https")) {
        fprintf(stderr, "Invalid protocol value.\n");
        return;
    }

    if (atoi(port) < 1 || atoi(port) > 65535) {
        fprintf(stderr, "Invalid port value.\n");
        return;
    }

    if (!strcmp(level, "debug") || !strcmp(level, "info") || !strcmp(level, "warn") || !strcmp(level, "error")) {}
    else {
        fprintf(stderr, "Invalid logging level value.\n");
        return;
    }
}

// Repeat the validate_service_config function for database and logging sections as needed.

// Implement functions to initialize resources based on the configuration data and handle resource dependencies.

