    public class ImageProcessor
    {
        private const int MaxConcurrentRequests = 10;
        private readonly IDbConnection _dbConnection;
        private readonly ILoggingService _loggingService;

        public ImageProcessor(IDbConnection dbConnection, ILoggingService loggingService)
        {
            _dbConnection = dbConnection;
            _loggingService = loggingService;
        }

        public async Task<Tuple<ImageInfo, byte[], DataTableReader>> ProcessImageAndRetrieveData(Stream imageStream)
        {
            var imageInfo = ParseImage(imageStream);
            if (imageInfo == null)
                return (null, null, null);

            var byteArray = await StoreImageAndGetByteArray(imageInfo);
            if (byteArray == null)
                return (imageInfo, null, null);

            var dataTableReader = ExecuteDatabaseQuery(byteArray);

            return (imageInfo, byteArray, dataTableReader);
        }

        private ImageInfo ParseImage(Stream imageStream)
        {
            try
            {
                using (var tiff = Tiff.Open(imageStream))
                {
                    var sampleCount = tiff.SampleDescription.Length;
                    if (sampleCount < 1 || sampleCount > 4)
                        _loggingService.LogError($"Unsupported image with {sampleCount} samples.");

                    return new ImageInfo
                    {
                        BitDepth = (byte)tiff.PhotometricInterpretation,
                        Samples = Enumerable.Range(0, sampleCount).Select(i => tiff.SampleDescription[i].BitsPerSample).ToArray()
                    };
                }
            }
            catch (Exception ex)
            {
                _loggingService.LogError($"Error parsing image: {ex.Message}");
                return null;
            }
        }

        private async Task<byte[]> StoreImageAndGetByteArray(ImageInfo imageInfo)
        {
            if (!IsValidBitDepth(imageInfo))
                throw new ArgumentException("Invalid bit depth for image.");

            var byteArray = await ProcessImageForStorage(imageInfo);

            try
            {
                using (var transaction = _dbConnection.BeginTransaction())
                {
                    _dbConnection.Open();
                    await _dbConnection.InsertAsync(byteArray, "Images", transaction);
                    transaction.Commit();
                }

                return byteArray;
            }
            catch (Exception ex)
            {
                _loggingService.LogError($"Error storing image: {ex.Message}");
                throw;
            }
        }

        private static bool IsValidBitDepth(ImageInfo imageInfo)
