using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionConfiguration
{
    public string Key1 { get; set; }
    public string IV1 { get; set; }
    public string Key2 { get; set; }
    public string IV2 { get; set; }
    public string Key3 { get; set; }
    public string IV3 { get; set; }
}

public class DecryptionException : Exception
{
    public DecryptionException(string message) : base(message) { }
}

public async Task<string> DecryptBase64MessageAsync(string base64EncodedMessage, DecryptionConfiguration configuration)
{
    if (!configuration.Validate())
        throw new DecryptionConfigurationException("Invalid or incomplete configuration.");

    var key1 = TripleDESCryptoServiceProvider.Create().Key = Convert.FromBase64String(configuration.Key1);
    var iv1 = TripleDESCryptoServiceProvider.Create().IV = Convert.FromBase64String(configuration.IV1);

    var key2 = TripleDESCryptoServiceProvider.Create().Key = Convert.FromBase64String(configuration.Key2);
    var iv2 = TripleDESCryptoServiceProvider.Create().IV = Convert.FromBase64String(configuration.IV2);

    var key3 = TripleDESCryptoServiceProvider.Create().Key = Convert.FromBase64String(configuration.Key3);
    var iv3 = TripleDESCryptoServiceProvider.Create().IV = Convert.FromBase64String(configuration.IV3);

    var tripleDES = TripleDESCryptoServiceProvider.Create();

    var base64DecodedBytes = Convert.FromBase64String(base64EncodedMessage);
    var chunkSize = 1024; // Adjustable based on memory constraints
    var encryptedChunks = Partitioner.Create(base64DecodedBytes.AsEnumerable().Select((b, i) => Tuple.Create(b, i))
                               .OrderBy(t => t.Item2), chunkSize);

    var decryptedData = new List<byte>();
    var taskList = new List<Task<IEnumerable<byte>>>();

    ParallelOptions parallelOptions = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

    await Task.WhenAll(
        from chunk in encryptedChunks
         let task = Task.Run(() => DecryptData(chunk, tripleDES, key1, iv1), parallelOptions)
         select task).ContinueWith(task =>
            {
                if (task.IsFaulted && task.Exception != null)
                    Console.WriteLine("Error occurred during decryption: " + task.Exception);
                else
                    decryptedData.AddRange(task.Result);
            });

    return Encoding.UTF8.GetString(decryptedData.ToArray());
}

private IEnumerable<byte> DecryptData(Tuple<byte[], int> chunk, TripleDESCryptoServiceProvider tripleDES, byte[] key, byte[] iv)
{
    using (var memoryStream = new MemoryStream())
    {
        var encryptedChunkBytes = chunk.Item1;
        using (var cs = new CryptoStream(new MemoryStream(encryptedChunkBytes), tripleDES.CreateDecryptor(key, iv), CryptoStreamMode.Read))
            cs.CopyTo(memoryStream);
        return memoryStream.ToArray();
    }
}

public bool Validate()
{
    return !string.IsNullOrEmpty(Key1) &&
           !string.IsNullOrEmpty(IV1) &&
           !string.IsNullOrEmpty(Key2) &&
           !string.IsNullOrEmpty(IV2) &&
           !string.IsNullOrEmpty(Key3) &&
           !string.IsNullOrEmpty(IV3);
}
```

This code includes the following features:
1. A DecryptionConfiguration class that accepts keys and IVs for decryption.
2. A custom exception named DecryptionConfigurationException.
