using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Caching.Memory;

namespace FileProcessor
{
    public class FileReader
    {
        private readonly ILogger<FileReader> _logger;
        private readonly IMemoryCache _cache;
        private readonly int _maxConcurrentTasks;
        private readonly TimeSpan _retryInterval;
        private readonly IConfiguration _configuration;

        public FileReader(ILogger<FileReader> logger, IMemoryCache cache, IConfiguration configuration)
        {
            _logger = logger;
            _cache = cache;
            _configuration = configuration;

            _maxConcurrentTasks = int.Parse(_configuration["MaxConcurrentTasks"]);
            _retryInterval = TimeSpan.FromSeconds(int.Parse(_configuration["RetryInterval"]));
        }

        public async Task ProcessFilesAsync(IEnumerable<string> filePaths)
        {
            var semaphoreSlim = new SemaphoreSlim(_maxConcurrentTasks);

            foreach (var filePath in filePaths)
            {
                await ReadFileAndProcessAsync(filePath, semaphoreSlim).ContinueWith(task =>
                {
                    if (!task.IsFaulted && task.Result == false)
                    {
                        _logger.LogWarning($"File processing failed for file: {filePath}");
                        RetryReadFileAsync(filePath, semaphoreSlim).Start();
                    }
                });
            }
        }

        private async Task<bool> ReadFileAndProcessAsync(string filePath, SemaphoreSlim semaphore)
        {
            try
            {
                await semaphore.WaitAsync();

                using var fileStream = File.OpenRead(filePath);
                var cacheKey = GenerateCacheKey(filePath);
                var cachedContent = _cache.Get(cacheKey);

                if (cachedContent != null)
                    return ProcessContent(Encoding.UTF8.GetString(cachedContent as byte[]));

                using var reader = new StreamReader(fileStream, Encoding.UTF8);
                string content = await reader.ReadToEndAsync();
                _cache.Set(cacheKey, content, new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromMinutes(_configuration["CacheDuration"])));

                return ProcessContent(content);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"An error occurred while processing file: {filePath}");
                semaphore.Release();
                return false;
            }
            finally
            {
                semaphore.Release();
            }
        }

        private async Task RetryReadFileAsync(string filePath, SemaphoreSlim semaphore)
        {
            await Task.Delay(_retryInterval);
            await ReadFileAndProcessAsync(filePath, semaphore);
        }

        private bool ProcessContent(string content)
        {
            // Implement your logic here to process the file content and return a boolean value indicating success or failure
            // For example:
            // var result = SomeFunctionThatProcessesFileContent(content);
            // return result;
            return true;
        }

        private string GenerateCacheKey(string filePath)
        {
            return $"{filePath}:{Guid.NewGuid()}";
        }
    }
}
```

