using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

namespace DecryptionLibrary
{
    public class AesDecrypter
    {
        private readonly ILogger _logger;
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private readonly string _paddingScheme;
        private readonly HMACSHA256 _hmac;
        private readonly ICryptoTransform _decryptor;

        public AesDecrypter(ILogger logger, byte[] key, byte[] iv, string paddingScheme)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _key = key ?? throw new ArgumentNullException(nameof(key));
            _iv = iv ?? throw new ArgumentNullException(nameof(iv));
            _paddingScheme = paddingScheme ?? throw new ArgumentNullException(nameof(paddingScheme));

            var aes = AES.Create();
            aes.Key = _key;
            aes.IV = _iv;

            switch (_paddingScheme.ToUpperInvariant())
            {
                case "PKCS7":
                    aes.Padding = PaddingMode.PKCS7;
                    break;
                case "PKCS5":
                    aes.Padding = PaddingMode.PKCS5;
                    break;
                case "ANSI X.923":
                    aes.Padding = PaddingMode.Zeros;
                    break;
                default:
                    throw new ArgumentOutOfRangeException(nameof(_paddingScheme), $"Invalid padding scheme '{_paddingScheme}'.");
            }

            _decryptor = aes.CreateDecryptor();
            _hmac = new HMACSHA256(aes.Key);
        }

        public byte[] Decrypt(Stream ciphertext, Stream plaintext)
        {
            if (ciphertext == null) throw new ArgumentNullException(nameof(ciphertext));
            if (plaintext == null) throw new ArgumentNullException(nameof(plaintext));

            _logger.LogInformation("Decryption started.");
            Stopwatch stopwatch = Stopwatch.StartNew();

            try
            {
                var cbc = new CryptoStream(ciphertext, _decryptor, CryptoStreamMode.Read);

                byte[] buffer = new byte[cbc.ReadByte()]; // Reads the first byte to determine the padding length.
                int offset = 0;

                do
                {
                    var count = cbc.Read(buffer, offset, buffer.Length - offset);

                    if (count < 1) break;

                    offset += count;

                    if (offset == buffer.Length) // If the entire buffer has been filled, pad it with zeros for proper decryption.
                    {
                        Array.Resize(ref buffer, offset + _hmac.ComputeHash(buffer).Length);
                        offset = 0;
                    }
                } while (true);

                var plaintextBytes = new byte[offset]; // Copy the decrypted data into a new array without padding.
                Array.Copy(buffer, plaintextBytes, offset);

                if (_hmac != null)
                {
                    byte[] expectedHmac = _hmac.ComputeHash(_plaintext.ToArray());

                    for (int i = 0; i < plaintextBytes.Length - expectedHmac.Length; i++)
                    {
                        if (!new SHA256Managed().ComputeHash(plaintextBytes, i, expectedHmac.Length).SequenceEqual(expectedHmac))
                            throw new Exception("Decrypted data has been tampered with.");
                    }
                }

                _logger.LogInformation("Decryption completed.");
                _logger.LogInformation($"Elapsed time: {stopwatch.Elapsed}");

                return plaintextBytes;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred during decryption.");
                throw;
            }
            finally
            {
                ciphertext?.Dispose();
                plaintext?.Dispose();
            }
        }
    }
}
```

