import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;

public class CustomDeserializer {
    private static ObjectMapper objectMapper = new ObjectMapper();

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, DeserializationException {
        // Parse metadata to check version compatibility
        Metadata metadata = parseMetadata(data);
        if (!isCompatibleVersion(metadata.getVersion())) {
            throw new DeserializationException("Incompatible version for deserialization");
        }

        // Parse the object graph from the byte array
        JsonNode rootNode = objectMapper.readTree(data);

        // Handle class-not-found cases
        T instance = createInstance(clazz);
        mapRootNodeToObject(rootNode, instance, clazz);

        return instance;
    }

    private static Metadata parseMetadata(byte[] data) throws JsonProcessingException {
        // Parse metadata from the byte array using Jackson library
        JsonNode metadataNode = objectMapper.readTree(data).get("metadata");
        if (metadataNode == null) {
            throw new DeserializationException("Missing or invalid metadata in the byte array");
        }
        return objectMapper.treeToValue(metadataNode, Metadata.class);
    }

    private static <T> T createInstance(Class<T> clazz) {
        Constructor<T> constructor;
        try {
            constructor = clazz.getDeclaredConstructor();
            constructor.setAccessible(true);
        } catch (NoSuchMethodException e) {
            throw new DeserializationException("Unable to find a suitable constructor for the given class");
        }
        try {
            return constructor.newInstance();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
            throw new DeserializationException("Failed to create an instance of the given class", e);
        }
    }

    private static void mapRootNodeToObject(JsonNode rootNode, Object instance, Class<?> clazz) {
        Arrays.stream(rootNode.fields()).forEach(field -> {
