                    Class<?> fieldType = field.getType();
                    if (fieldType.isArray()) {
                        Array array = objectMapper.typedArrayForGeneric(fieldValueNode, fieldType.getComponentType());
                        // Map array elements to the corresponding array in the instance using recursion or parallel stream operations
