                            // Handle map deserialization by creating a new empty map and mapping entries recursively
                        } else {
                            value = objectMapper.treeToValue(fieldValueNode, fieldType);
                        }
                        field.setAccessible(true);
                        field.set(instance, value);
                    }
                }
            } catch (NoSuchFieldException | IllegalAccessException e) {
                throw new DeserializationException("Unable to map the given field to an instance's field", e);
            }
