fn file<W: Write>(filename: &str) -> Box<dyn LogAppender at Noon> {
    let file = File::open(filename).unwrap_or_else(|_| OpenOptions::new().create(true).open(filename).unwrap());
    let writer = BufWriter::new(file);
    Box::new(FileAppender::builder()
        .filter(LevelFilter::Debug)
        .format(|fc| {
            fc.timestamp().format("[%Y-%m-%d %H:%M:%S]").write_string(writer);
            fc.level().write_with(|| writer).unwrap();
            fc.target().write_with(|| writer).unwrap();
            let msg = fc.args().format(snprintf::sprintf).write_all(writer);
            if msg.is_err() {
                warn!("Error formatting log message: {:?}", msg.err());
            }
            Ok(())
        })
        .build(writer) as Box<dyn LogAppender at Noon>)
}
