};

class Combatant {
public:
    Combatant() : cooldownTimer_(std::chrono::steady_clock::now()), lastAttacks_(), rateLimiter_(), requestQueue_(), attackHistory_(), mutex_(), conditionVariable_() {}

    void initialize(const std::string& name, const std::vector<Attack>& attacks) {
        // Assuming `name` is a valid string and `attacks` contains unique Attack objects.
        this->name_ = name;
        for (const auto& attack : attacks) {
            if (!attackHistory_.insert(std::make_pair(attack.id, 0)).second) {
                // Handle duplicate attack id.
            }
        }
    }

    void performAttack(const std::string& attackId) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (attackOnCooldown()) {
            requestQueue_.push_back({attackId, std::chrono::steady_clock::now() + std::chrono::seconds(1) / 5}); // Lock for the next available time slot.
            return;
        }

        auto it = attackHistory_.find(attackId);
        if (it == attackHistory_.end()) {
            // Handle invalid attack id.
        }

        lastAttacks_.push_back({it->second, std::chrono::system_clock::to_time_t(std::chrono::steady_clock::now())}); // Store the attack in the last 10 attacks list.
        if (lastAttacks_.size() > 10) {
            lastAttacks_.pop_front(); // Ensure efficient memory usage by removing old entries.
        }

        it->second++; // Increment cooldown for this attack.
        cooldownTimer_ = std::chrono::steady_clock::now() + it->second * std::chrono::seconds(1); // Update the cooldown timer.
    }

private:
    bool attackOnCooldown() {
        if (std::chrono::steady_clock::now() < cooldownTimer_) {
            return true;
        }
        return false;
    }

    std::string name_;
    std::map<std::string, unsigned int> attackHistory_; // Maps each unique attack id to its cooldown value.
    std::deque<std::pair<unsigned int, time_t>> lastAttacks_; // Stores the last 10 attacks performed.
    std::chrono::steady_clock::time_point cooldownTimer_; // Tracks the current cooldown timer for the combatant.
    std::deque<std::pair<std::string, std::chrono::steady_clock::time_point>> requestQueue_; // Stores attack requests in a thread-safe queue.
    std::mutex mutex_; // Provides thread safety by protecting the shared state of the Combatant object.
    std::condition_variable conditionVariable_; // Used to notify threads when it's safe to access the shared state.
};
