import java.util.concurrent.TimeUnit;

public class ConnectionManager {
    private static final int MAX_RECORDS = 10000;
    private static final Random RANDOM = new Random();
    private Selector selector;
    private Map<Long, Record> recordCache = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();

    public void establishConnection(SocketChannel channel) {
        SelectionKey key = channel.register(selector, 0);
        Runnable connectionTask = createConnectionTask(key);
        scheduler.scheduleAtFixedRate(connectionTask, 100, 100, TimeUnit.MILLISECONDS);
    }

    private Runnable createConnectionTask(SelectionKey key) {
        return () -> {
            try {
                // Handle connection state changes and manage I/O operations using the third-party network library
                // ...

                // Fetch metadata from external API (handle temporary failures and retries efficiently)
                // ...

                // Create new Record instance if necessary, or retrieve from cache
                long offset = key.hashCode();
                int key = RANDOM.nextInt();
                Record record = recordCache.computeIfAbsent(offset, k -> new Record(key, getMemory()));

                // Perform serialization and communication tasks with the remote peer
                // ...
            } catch (Exception e) {
                // Log errors for debugging purposes
                // ...
            } finally {
                // Handle memory deallocation gracefully to prevent inconsistent state
                releaseMemory(record);
            }
        };
    }

    private long getMemory() {
        try {
            return Runtime.getRuntime().freeMemory();
        } catch (Exception e) {
            // Log errors for debugging purposes
            // ...
            return -1;
        }
    }

    private void releaseMemory(Record record) {
        if (record != null && record.getValue() != 0) {
            long memory = System.nanoTime();
            try {
                record.setValue(0);
                record = null;
                runtime.gc();
                memory = System.nanoTime() - memory;

                // Log memory deallocation statistics for performance analysis
                // ...
            } catch (Exception e) {
                // Log errors for debugging purposes
                // ...
            }
        }
    }

    private static class Record {
        private final int value;
        private long memoryAddress;

        public Record(int value, long memoryAddress) {
            this.value = value;
            this.memoryAddress = memoryAddress;
        }

        public int getValue() {
            return value;
        }

        public void setValue(int value) {
            this.value = value;
        }

        // Other required methods for the custom serialization framework
    }
}
