struct LTE_PHY_MIB_INFO {
    MIB_HEADER mibHeader;
    int timingAdvance;
    int cellIdentity;
    int systemFrameNumber;
};

class MibListManager {
private:
    std::list<LTE_PHY_MIB_INFO> dataList;
    std::mutex mtx;
    std::condition_variable cv;
    static std::mt19937 rng; // Static member variable for random number generator using Mersenne Twister algorithm

public:
    MibListManager() { /* Constructor */ }

    ~MibListManager() { /* Destructor */ }

    void initData(size_t numElements) {
        // Initialize data list with given number of elements using random values generated from the static member variable rng
        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_all(); // Notify all waiting threads to continue

        for (size_t i = 0; i < numElements; ++i) {
            LTE_PHY_MIB_INFO elem;
            elem.timingAdvance = rng() % 100 + 1;
            elem.cellIdentity = rng() % 100 + 1;
            elem.systemFrameNumber = rng() % 100 + 1;
            dataList.push_back(elem);
        }
    }

    LTE_PHY_MIB_INFO& getData(size_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !dataList.empty(); }); // Wait until data list is not empty

        LTE_PHY_MIB_INFO& elem = dataList.front();
        dataList.pop_front();
        return elem;
    }

    static std::mt19937& getRng() {
        // Return the static member variable rng
        return rng;
    }
};

std::mt19937 MibListManager::rng; // Initialize static member variable rng with default seed
