public class StringHasher {
    private static final int BATCH_SIZE = 1000;
    private static final Lock lock = new ReentrantLock();
    private static final Queue<String> queue = new ConcurrentLinkedQueue<>();
    private static final Map<String, String> processedStrings = new ConcurrentHashMap<>();
    private static final int skippedEmptyOrWhitespace = 0;
    private static final int skippedNull = 0;

    public static Map<String, String> hashStrings(Iterable<String> input) {
