        return string.replaceAll("[^\\x20-\\x7F]+", "");
    }

    private static void processQueue() {
        if (queue.size() < BATCH_SIZE) return;

        lock.lock();
        try {
            int processedCount = 0;
            Map<String, String> batchResults = new HashMap<>();
            while (!queue.isEmpty() && processedCount < BATCH_SIZE) {
