    private static String bytesToHex(byte[] bytes) {
        // Implement hex encoding logic here.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            String hex = Integer.toHexString(0xFF & bytes[i]);
            if (hex.length() == 1) sb.append('0');
            sb.append(hex);
        }
        return sb.toString();
    }

    private static void incrementSkippedCount(String reason) {
        switch (reason) {
            case "":
                skippedEmptyOrWhitespace++;
                break;
            case null:
                skippedNull++;
                break;
            default:
                // Log a warning or error depending on the application's requirements.
        }
    }

    private static void logProcessingError(Exception e) {
