    const char* name;
    double value;
};

static pthread_mutex_t logBufferMutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t logBufferCond = PTHREAD_COND_INITIALIZER;
static struct Metric logBuffer[1024]; // Adjust size as needed for your specific use case
static int logBufferHead = 0, logBufferTail = 0;

void recordSystemMetrics(const char* name, double value, const Config* config) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timeSinceLastLog = (long)((tv.tv_sec - logBuffer[logBufferHead].tv_sec) * 1000 + (tv.tv_usec - logBuffer[logBufferHead].tv_usec));

    if(timeSinceLastLog >= config->interval_ms) {
        struct Metric* buffer = &logBuffer[logBufferHead];
        buffer->name = name;
        buffer->value = value;
        buffer->tv_sec = tv.tv_sec;
        buffer->tv_usec = tv.tv_usec;

        pthread_mutex_lock(&logBufferMutex);
        logBufferHead = (logBufferHead + 1) % sizeof(logBuffer);
        if((logBufferHead - logBufferTail) >= sizeof(logBuffer)) { // Buffer is full, start logging
            logMetrics();
        }
        pthread_mutex_unlock(&logBufferMutex);
    }
}

void logMetrics() {
    pthread_mutex_lock(&logBufferMutex);
    int i = logBufferTail;
    while((i - logBufferHead) != sizeof(logBuffer)) { // Buffer wraparound check
        const struct Metric* buffer = &logBuffer[i];

        // Perform asynchronous logging here. For simplicity, we'll use a dummy function `asyncLog` below.
        asyncLog(buffer->name, buffer->value, config);

        i = (i + 1) % sizeof(logBuffer);
    }
    logBufferTail = i;
    pthread_mutex_unlock(&logBufferMutex);
    pthread_cond_signal(&logBufferCond);
}
