#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>
#include <dlfcn.h> // For dynamic loading of libraries

typedef struct {
    const char *name;
    void* (*crypt_func)();
    void* params;
    double avg_time;
} crypto_entry;

typedef struct set {
    int count;
    crypto_entry** data;
} crypto_set;

void free_crypto_set(crypto_set* s) {
    for (int i = 0; i < s->count; ++i)
        free(s->data[i]);
    free(s->data);
    free(s);
}

crypto_set* init_crypto_set() {
    crypto_set *s = malloc(sizeof(crypto_set));
    s->count = 0;
    s->data = NULL;
    return s;
}

crypto_entry** load_cryptographic_modules(const char* lib_name) {
    void* handle = dlopen(lib_name, RTLD_LAZY);

    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }

    int (*get_cryptos)(crypto_entry**);
    get_cryptos = dlsym(handle, "get_cryptos");

    if (!get_cryptos) {
        fprintf(stderr, "Error: %s\n", dlerror());
        dlclose(handle);
        return NULL;
    }

    return get_cryptos();
}

crypto_set* get_available_crypto_functions() {
    crypto_entry** entries = load_cryptographic_modules("path/to/your-cryptographic-library.so");
    if (entries == NULL)
        return init_crypto_set();

    crypto_set* s = init_crypto_set();
    for (int i = 0; entries[i] != NULL; ++i) {
        int j;
        for (j = 0; s->count > j && strcmp(entries[i]->name, s->data[j]->name); ++j);

        if (s->count == j) {
            crypto_entry** new_data = realloc(s->data, sizeof(crypto_entry*) * (++s->count));
            s->data = new_data;
            s->data[s->count - 1] = entries[i];
        }
    }
    s->data = realloc(s->data, sizeof(crypto_entry*) * s->count);

    return s;
}
