2. Union-Find Data Structure for identifying disjoint pairs:

```c
#define MAX 100000 // Change this value to adapt to your specific needs and dataset size
int parents[MAX];
int ranks[MAX];
int sets_count = 0;

void make_set(int x) {
    if (parents[x] == -1) {
        parents[x] = x;
        ranks[x] = 0;
        ++sets_count;
    }
}

int find_set(int x) {
    if (parents[x] != x)
        parents[x] = find_set(parents[x]);

    return parents[x];
}

void union_sets(int x, int y) {
    int root_x = find_set(x);
    int root_y = find_set(y);

    if (root_x == root_y) return;

    if (ranks[root_x] < ranks[root_y]) {
        parents[root_x] = root_y;
        ranks[root_y] += ranks[root_x];
    } else {
        parents[root_y] = root_x;
        ranks[root_x] += ranks[root_y];
    }
}
