class ProfileAPI {
public:
    // Constructor taking API base URL and caching timeout as parameters
    ProfileAPI(const std::string& apiBaseUrl, int cacheTimeout)
        : api_(io_), apiEndpoint_(apiBaseUrl + "/profiles")
        , cacheTimeout_(std::chrono::seconds(cacheTimeout)) {}

    // Asynchronously retrieve user profile by ID and handle potential errors
    void getProfileById(const std::string& id, asio::yield_context yield, std::function<void(boost::optional<UserProfile>)> callback) {
        auto self = shared_from_this();

        // Check cache for fresh profile first
        auto it = cache_.find(id);
        if (it != cache_.end() && (std::chrono::steady_clock::now() - it->second.second) < cacheTimeout_) {
            callback(it->first);
            return;
        }

        // If not in cache, fetch from API and cache the result
        asio::ip::tcp::iostream apiStream(apiEndpoint_);
        if (apiStream) {
            std::stringstream ss;
            ss << "GET /" << id << "?cacheBuster=" << std::time(nullptr);
            apiStream << ss.str();

            json j;
            if (apiStream >> j) {
                UserProfile profile = deserialize(j);
                cache_.emplace(std::move(id), std::make_pair(profile, std::chrono::steady_clock::now()));
                callback(boost::optional<UserProfile>(std::move(profile)));
            } else {
                callback(boost::none);
            }
        } else {
            callback(boost::none);
        }
    }

