        arr[i] = min + rand() % (max - min + 1);
    }
}

void resizeRecords(size_t newCapacity) {
    Record *tmp = static_cast<Record*>(malloc((newCapacity) * sizeof(Record)));
    if (!tmp) {
        std::cerr << "Out of memory" << std::endl;
        return;
    }
    sem_wait(&resizeMutex);
    if (records) {
        memcpy(tmp, records, recordCapacity * sizeof(Record));
        free(records);
    }
    records = tmp;
    recordCapacity = newCapacity;
    sem_post(&resizeMutex);
}

