        pthread_mutex_unlock(&rng_mutex);
        free(keys);
        free(offsets);
        memory_log();
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = keys[i] = pthread_rwlock_rdlock(&rng_mutex) * key_range / RTLD_THREAD_MAX + 1;
        records[i].value = offsets[i] + records[i].key;
    }

    pthread_mutex_unlock(&rng_mutex);
    pthread_join(rng_thread, NULL);

    memory_track(log_prefix, &records, num_records * record_size);

    return records;
}

