    TIFFMetadata metadata;
    memset(&metadata, 0, sizeof(TIFFMetadata));

    TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, &metadata.bit_depth);
    TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLEFORMAT, &metadata.sample_format);
