    // ... (get other metadata fields from json)

    if (!validateImageMetadata(&metadata)) {
        json_decref(root);
        free(imageData);
        TIFFCLOSE(tif);
        return;
    }

    uint8_t hash[SHA256_DIGEST_LENGTH];
    SHA256((uint8_t *)imageData, imageSize, hash);

    char report[256];
    sprintf(report, "SHA-256 Hash: %s\nTIFF Metadata:\n%s\nValidation Summary:", hashToHexString(hash), printValidationSummary(&metadata));

    logReport(report);

    json_decref(root);
    free(imageData);
    TIFFCLOSE(tif);
}
