#include <pthread.h>
#include <time.h>

typedef struct Record {
    int data;
    long *pointer;
};

// Define thread-safe pseudo-random number generator
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned long seed = time(NULL);

void initialize_prng() {
    pthread_mutex_lock(&mutex);
    seed = (seed * 1103515245 + 12345) % 0x7fffffff;
    pthread_mutex_unlock(&mutex);
}

long get_prng() {
    long temp;
    pthread_mutex_lock(&mutex);
    temp = (seed = (seed * 16807) % 0x7fffffff);
    pthread_mutex_unlock(&mutex);
    return temp / 2147483647.0;
}

Record* initializeDatabaseSystem(size_t size) {
    Record *records = (Record *)malloc((sizeof(Record) + size * sizeof(long)) * size);
    if (!records) {
        fprintf(stderr, "Out of memory!\n");
        return NULL;
    }

    long *offsets = records + size;
    int *keys = offsets + size / sizeof(long);

    for (size_t i = 0; i < size; ++i) {
        keys[i] = (int)(get_prng() * 10000);
        offsets[i] = 0;
    }

    // Resetting the PRNG is optional but recommended for reproducibility
    initialize_prng();

    return records;
}

void resetDatabaseSystem(Record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        records[i].data = 0;
        records[i].pointer = offsets + i;
    }
}

