['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    MIB_HEADER header;
    TIMING_ADVANCE timing_advance;
    int cell_identity;
    unsigned long system_frame_number;
    struct LTE_PHY_MIB_INFO *next;
} LTE_PHY_MIB_INFO;

typedef struct {
    sem_t sem_init;
    sem_t sem_count;
    struct LTE_PHY_MIB_INFO *head;
    unsigned long size;
    pthread_mutex_t mutex;
} LTE_PHY_MIB_LIST;

void lte_phy_mib_list_init(LTE_PHY_MIB_LIST *list, unsigned long initial_size) {
    list->head = NULL;
    list->size = initial_size;
    sem_init(&(list->sem_init), 0, initial_size);
    sem_init(&(list->sem_count), 0, initial_size);
    pthread_mutex_init(&(list->mutex), NULL);
}

LTE_PHY_MIB_INFO* lte_phy_mib_list_pop(LTE_PHY_MIB_LIST *list) {
    LTE_PHY_MIB_INFO *node;
    sem_wait(&(list->sem_count));
    pthread_mutex_lock(&(list->mutex));
    if (list->head == NULL) {
        pthread_mutex_unlock(&(list->mutex));
        sem_post(&(list->sem_init));
        return NULL;
    }
    node = list->head;
    list->head = node->next;
    pthread_mutex_unlock(&(list->mutex));
    sem_post(&(list->sem_count));
    return node;
}

void lte_phy_mib_list_push(LTE_PHY_MIB_LIST *list, LTE_PHY_MIB_INFO *node) {
    pthread_mutex_lock(&(list->mutex));
    sem_wait(&(list->sem_init));
    node->next = list->head;
    list->head = node;
    if (--(list->size) == 0) {
        sem_post(&(list->sem_count));
    }
    pthread_mutex_unlock(&(list->mutex));
}

void lte_phy_mib_list_destroy(LTE_PHY_MIB_LIST *list) {
    LTE_PHY_MIB_INFO *node, *temp;
    sem_wait(&(list->sem_count));
    pthread_mutex_lock(&(list->mutex));
    node = list->head;
    while (node != NULL) {
        temp = node;
        node = node->next;
        free(temp);
    }
    sem_post(&(list->sem_count));
    pthread_mutex_destroy(&(list->mutex));
    sem_destroy(&(list->sem_init));
    sem_destroy(&(list->sem_count));
}
```
In this code, `LTE_PHY_MIB_LIST` is a structure containing the dynamically scalable linked list of `LTE_PHY_MIB_INFO`, an initializer function, and functions to pop, push, and destroy the list.

The linked list is managed using semaphores to balance concurrency and resource utilization. The `sem_init` function initializes a semaphore with a specified initial value, while `sem_wait` decrements the semaphore count, and `sem_post` increments it. This ensures that only a limited number of threads can access the list at any given time, minimizing potential contention.

The `lte_phy_mib_list_pop` function removes a node from the list, ensuring that only one thread can remove a node at a time by using a semaphore to wait for the count to decrease. The function also checks if the list is empty before attempting to remove a node.

The `lte_phy_mib_list_push` function adds a new node to the list, ensuring that only one thread can add a node at a time by using a semaphore to wait for the count to decrease. The function also updates the size of the list to reflect the number of nodes currently in use.

The `lte_phy_mib_list_destroy` function frees the memory used by the list and destroys the semaphores and mutex when the list is no longer needed.']

