void create_directory(const char *dir_path) {
    mode_t mask = S_IRUSR | S_IWUSR | S_IXUSR | S_IRGRP | S_IROTH;
    mkdir(dir_path, mask);
}

time_t get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[26];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y%m%d_%H%M%S.%f", timeinfo);
    return rawtime;
}

int generate_unique_filename(const char *base_name, const char *ext, char **filename) {
    DIR *dir;
    struct dirent *entry;
    int count = 0;
    char temp_filename[256];
    strcpy(temp_filename, base_name);
    strcat(temp_filename, ext);

    dir = opendir("./");
    if (dir != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, temp_filename) == 0) {
                count++;
                strcpy(temp_filename, base_name);
                snprintf(temp_filename + strlen(temp_filename), sizeof(temp_filename) - strlen(temp_filename), "%s%d", ext, count);
            }
        }
        closedir(dir);
    }

    if (count >= MAX_BACKUPS || count == 0) {
        strftime(temp_filename + strlen(temp_filename), sizeof(temp_filename) - strlen(temp_filename), "_%Y%m%d_%H%M%S.%f", localtime(&get_timestamp()));
    }

    *filename = temp_filename;
    return 0;
}

void backup_file(const char *dir_path, const char *base_name, int max_backups) {
    char *filename;
    generate_unique_filename(base_name, ".bak", &filename);

    // Ensure the directory exists.
    char dir[256];
    snprintf(dir, sizeof(dir), "%s/%s", dir_path, filename_dirname(filename));
    create_directory(dir);

    // Create the backup file with atomicity to handle heavy load conditions.
    int fd = open((char[]) { '.', '/', '.', dir_path, filename }, O_WRONLY | O_CREAT | O_EXCL | O_ATOMIC, S_IRUSR | S_IWUSR | S_IXUSR);
    if (fd != -1) {
        // Copy the original file to the backup.
        dup2(fd, STDOUT_FILENO);
        execl(base_name, base_name, NULL);
    }
}
```

