Record* create_record_pool(size_t num_records) {
    if(num_records > MAX_RECORDS || num_records > MEM_LIMIT / sizeof(Record)) {
        fprintf(stderr, "Error: Requested number of records exceeds maximum allowed.\n");
        return NULL;
    }

    Record *record_pool = mmap(NULL, num_records * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if(record_populate(record_pool, num_records) != 0) {
        munmap(record_pool, num_records * sizeof(Record));
        return NULL;
    }

    return record_pool;
}

int record_populate(void *record_block, size_t num_records) {
    Record *records = (Record *)record_block;
    srand(time(NULL));
    for(size_t i = 0; i < num_records; ++i) {
        records[i].offset = i;
        records[i].key = i + 1; // Use key as an index plus one to avoid zero-based index confusion.
        records[i].value = (double)(rand() % 10000) / 100.0;
    }
    return 0;
}
