char *processStringWithLimit(const char *str, size_t limit) {
    if (strlen(str) > limit) {
        return NULL;
    }

    char *newStr = malloc(strlen(str) + 2);
    strcpy(newStr, str);
    newStr[strlen(str)] = '/';
    newStr[strlen(str)+1] = '\0';

    log("Process string: success - original length: %zu, processed length: %zu", strlen(str), strlen(newStr));
    return newStr;
}

