Employee *getEmployeeDetailsBySupervisor(int supervisorId) {
    Employee result;
    char sql[256];
    snprintf(sql, sizeof(sql), "SELECT name, city, address FROM Employees WHERE id = %d", supervisorId);

    sqlite3_stmt *stmt;
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        log("Failed to prepare statement: %s", sqlite3_errmsg(db));
        return NULL;
    }

    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        result.id = supervisorId;
        strcpy(result.name, (char*)sqlite3_column_text(stmt, 0));
        strcpy(result.city, (char*)sqlite3_column_text(stmt, 1));
        strcpy(result.address, (char*)sqlite3_column_text(stmt, 2));
    } else if (rc != SQLITE_DONE) {
        log("Failed to execute statement: %s", sqlite3_errmsg(db));
    }

    sqlite3_finalize(stmt);

    if (result.id > 0) {
        log("Retrieved employee details for supervisorID: success - id: %d, name: %s, city: %s, address: %s", result.id, result.name, result.city, result.address);
    } else {
        log("Retrieved employee details for supervisorID: failure - id: %d", result.id);
    }

    return &result;
}
