int convertAndProcessNFAPI_CRC(const char *input_file, const char *output_file, size_t max_entries) {
    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening input file");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        perror("Error allocating memory");
        fclose(file);
        return 1;
    }

    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file) && count < max_entries) {
        // Parse the line into RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields
        // Access the external data source to retrieve CRCFLAG based on the parsed RNTI
        // Ensure data consistency and integrity before proceeding

        if (parseLine(line, &data[count].RX_UE_INFORMATION_TAG, &data[count].RNTI, &data[count].CRC_INDICATION_REL8_TAG) &&
            retrieveCRCFlag(&data[count].CRCFLAG, data[count].RNTI)) {
            data[count].CRCFLAG = generateRandomCRCFlag();
            count++;
        } else {
            // Log the error and move to the next line without filling the structure
            fprintf(stderr, "Error processing line: %s\n", line);
        }
    }
    fclose(file);

    if (count == max_entries) {
        free(data);
        return 0; // All entries processed successfully
    } else {
        free(data);
        data = realloc(data, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            perror("Error reallocating memory");
            return 1;
        }
    }

    int pdf_status = convertToPDF(output_file, data, count);
    free(data);
    return pdf_status;
}
