typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} list_node_t;

static list_node_t *head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t element_count = 0;
static bool log_enabled = true;

void nfapi_crc_indication_pdu_list_init() {
    // Initialization of the list and mutex in a multi-threaded environment
}

void nfapi_crc_indication_pdu_list_log(const char *message) {
    if (log_enabled) {
        printf("%s\n", message);
    }
}

void nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);

    list_node_t *new_node = malloc(sizeof(list_node_t));
    if (!new_node) {
        nfapi_crc_indication_pdu_list_log("Out of memory");
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = data;
    new_node->next = head;
    head = new_node;
    element_count++;

    pthread_mutex_unlock(&mutex);
}

bool nfapi_crc_indication_pdu_list_remove_rnti(uint32_t rnti) {
    bool found = false;
    pthread_mutex_lock(&mutex);

    list_node_t *current = head;
    list_node_t *previous = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous != NULL) {
                previous->next = current->next;
            } else {
                head = current->next;
            }

            free(current);
            element_count--;
            found = true;
            break;
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
    return found;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list_peek() {
    if (element_count == 0) {
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T *data = &head->data;
    list_node_t *temp = head;
    head = temp->next;
    element_count--;
    pthread_mutex_unlock(&mutex);

    return data;
}

void nfapi_crc_indication_pdu_list_destroy() {
    while (head != NULL) {
        list_node_t *temp = head;
        head = head->next;
        free(temp);
        element_count--;
    }
}
