    int fd = open(json_file, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return (Config){0};
    }

    json_object *root = json_tokener_parse(fd, 0, "config");
    if (!root) {
        fprintf(stderr, "Failed to parse config JSON\n");
        close(fd);
        return (Config){0};
    }

    Config config;
    config.validation = json_object_get_int(json_object_find(root, "validation"));
    config.compression = json_object_get_int(json_object_find(root, "compression"));
    config.loglevel = json_object_get_int(json_object_find(root, "loglevel"));
    config.logfile = strdup(json_object_get_string(json_object_find(root, "logfile")));

    close(fd);
    return config;
}

void log(int level, const char *message) {
    if (level > config.loglevel) {
        return;
    }

    FILE *logfile = fopen(config.logfile, "a");
    if (!logfile) {
        perror("fopen");
        return;
    }

    time_t now;
    char timestamp[32];
    struct tm *tm_now;

    now = time(NULL);
    tm_now = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(logfile, "[%s] [Level: %d] %s\n", timestamp, level, message);
    fclose(logfile);
}
