typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

struct Cache {
    size_t capacity;
    size_t size;
    Record* records;
    Record** cache;
    pthread_mutex_t mutex;
};

void init_cache(struct Cache* cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = NULL;
    cache->cache = calloc(capacity, sizeof(Record*));
    pthread_mutex_init(&cache->mutex, NULL);
}

void destroy_cache(struct Cache* cache) {
    if (cache->records) free(cache->records);
    free(cache->cache);
    pthread_mutex_destroy(&cache->mutex);
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = rand() % 100;
    return record;
}

void push_record(struct Cache* cache, Record* record) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size >= cache->capacity) {
        // Implement eviction strategy here
    }
    cache->records[cache->size] = *record;
    cache->cache[record->key] = &cache->records[cache->size++];
    pthread_mutex_unlock(&cache->mutex);
}

Record* get_or_create_record(struct Cache* cache, long offset, int key) {
    pthread_mutex_lock(&cache->mutex);
    Record* cached_record = cache->cache[key];
    if (cached_record) {
        pthread_mutex_unlock(&cache->mutex);
        return cached_record;
    }

    Record* new_record = create_record();
    if (!new_record) {
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }

    new_record->offset = offset;
    push_record(cache, new_record);

    pthread_mutex_unlock(&cache->mutex);
    return new_record;
}

// Assuming you have defined the 'offsets', 'keys' and 'num_records' arrays elsewhere
