    srand(time(NULL));

    struct Cache cache;
    init_cache(&cache, 10); // Adjust the capacity as needed

    Record** offset_records = malloc(sizeof(Record*) * num_records);

    for (size_t i = 0; i < num_records; ++i) {
        offset_records[i] = get_or_create_record(&cache, offsets[i], keys[i]);
        if (!offset_records[i]) {
            printf("Failed to allocate memory for record with key %d\n", keys[i]);
            return 1;
