char* modify_filename(const char* filename) {
    size_t len = strlen(filename);
    if (len > MAX_FILENAME_LENGTH) {
        return calloc(MAX_FILENAME_LENGTH, sizeof(char)); // Truncate the string to the maximum length
    }

    int digits = 0;
    int has_ext = 0;
    char* ext = NULL;
    int i = 0;
    for (; filename[i] != '\0'; ++i) {
        if (isdigit(filename[i])) {
            ++digits;
        } else if (filename[i] == '.') {
            has_ext = 1;
            ext = &filename[i + 1]; // Start from the next character after '.'
            break;
        }
    }

    if (!has_ext) {
        ext = ".txt"; // Default file type is .txt
    }

    int num_digits_before_ext = digits;
    for (int j = i - 1; j >= 0 && !isspace(filename[j]); --j) {
        if (isdigit(filename[j])) {
            ++num_digits_before_ext;
        } else {
            break;
        }
    }

    // Create a new filename with the specified number of digits before the extension
    char* new_filename = malloc(len + (MAX_DIGITS - num_digits_before_ext) + strlen(ext) + 1);
    strncpy(new_filename, filename, i); // Copy the prefix

    for (int k = 0; k < MAX_DIGITS - num_digits_before_ext; ++k) {
        new_filename[i++] = '0' + rand() % 10; // Add random digits to fill the gap
    }

    strcpy(new_filename + i, &filename[i]); // Copy the rest of the original filename
    strcat(new_filename, ext); // Append the file type

    return new_filename;
}
