    }

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    uint8_t buffer[1024];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        SHA256_Update(&ctx, buffer, bytes_read);
    }

    SHA256_Final((unsigned char*)current_template.sha256, &ctx);

    struct Report report = {
        current_template.sha256,
        metadata ?: "",
        ERROR_NONE
    };

    if (verbose) {
        printf("SHA-256 hash: %s\n", report.sha256);
        if (metadata) printf("Metadata: %s\n", report.metadata);
    }

