    list->data[list->size] = *pdu;
    list->size++;

    return true;
}

void resize_list(NFAPI_CRC_LIST_T* list) {
    size_t new_capacity = (list->capacity == 0) ? LIST_THRESHOLD : (list->capacity * 2 > LIST_THRESHOLD) ? (list->capacity * 2) : LIST_THRESHOLD;

    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
