        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    close_file(file);
}

void nfapi_crc_list_deserialize(NFAPI_CRC_LIST_T* list, const char* filename) {
