void init_crcIndication(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    crcIndication->crcIndication.crcFlag = rand() % 2;
}

DoublyLinkedList* initializeDLL(uint32_t peakLoad) {
    DoublyLinkedList *list = (DoublyLinkedList *) malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_init(&list->listLock, NULL);
    for (uint32_t i = 0; i < peakLoad; ++i) {
        NFAPI_CRC_INDICATION_PDU* element = (NFAPI_CRC_INDICATION_PDU *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        pthread_mutex_init(&element->lock, NULL);
        init_crcIndication(element->crcIndication);
        if (!list->head) {
            list->head = element;
            list->tail = element;
        } else {
            list->tail->next = element;
            element->prev = list->tail;
            list->tail = element;
        }
        ++(list->size);
    }
    return list;
}

void enqueue(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T newElement) {
    pthread_mutex_lock(&list->listLock);
    if (!list->head) {
        list->head = &newElement;
        list->tail = &newElement;
    } else {
        newElement.next = list->head;
        list->head->prev = &newElement;
        list->head = &newElement;
    }
    ++(list->size);
    pthread_mutex_unlock(&list->listLock);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->listLock);
    NFAPI_CRC_INDICATION_PDU_T *temp = list->tail;
    if (list->size == 1) {
        list->head = NULL;
        list->tail = NULL;
    } else {
        list->tail = list->tail->prev;
        list->tail->next = NULL;
    }
    --(list->size);
    pthread_mutex_unlock(&list->listLock);
    return temp;
}

void cleanupDLL(DoublyLinkedList* list) {
    pthread_mutex_destroy(&list->listLock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        pthread_mutex_destroy(&temp->lock);
        free(temp);
    }
    free(list);
}
