    new_node->system_frame_number = system_frame_number;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void append_to_list(LinkedList *llist, LTE_PHY_MIB_INFO *new_node) {
    pthread_mutex_lock(&llist->mutex);
    while (llist->count + 1 >= llist->capacity && llist->count > 0) {
        pthread_cond_wait(&llist->not_full, &llist->mutex);
    }
    if (llist->head == NULL) {
        llist->head = new_node;
        llist->tail = new_node;
    } else {
        llist->tail->next = new_node;
        new_node->prev = llist->tail;
        llist->tail = new_node;
    }
    llist->count++;
    if (llist->count >= THRESHOLD && llist->capacity > 0) {
        size_t new_capacity = llist->capacity * 2;
        LTE_PHY_MIB_INFO **new_nodes = realloc(llist->head, new_capacity * sizeof(LTE_PHY_MIB_INFO));
        if (new_nodes) {
            llist->head = new_nodes;
            llist->capacity = new_capacity;
        }
    }
    pthread_cond_signal(&llist->not_empty);
    pthread_mutex_unlock(&llist->mutex);
}

LTE_PHY_MIB_INFO* dequeue_from_list(LinkedList *llist) {
    pthread_mutex_lock(&llist->mutex);
    while (llist->count == 0) {
        pthread_cond_wait(&llist->not_empty, &llist->mutex);
    }
    LTE_PHY_MIB_INFO *to_return = llist->head;
    if (--llist->count > 0) {
        llist->head = to_return->next;
        if (llist->head) llist->head->prev = NULL;
    } else {
        free(to_return);
    }
    pthread_cond_signal(&llist->not_full);
    pthread_mutex_unlock(&llist->mutex);
    return to_return;
}
