    unsigned short SEQUENCE_NUMBER;
    unsigned char* DATA_BYTES;
    unsigned int length;
} L1_MESSAGE;

unsigned int messageCount = 0;
const unsigned int MAX_MESSAGES = 1000;
L1_MESSAGE** messages;

void compressData(unsigned char *input, unsigned char **output) {
    gzFile file = gzopen("temp.gz", "wb");
    gzip(*file, Z_DEFAULT_COMPRESSION, input, strlen(input));
    *output = malloc(gzsize(file));
    gzread(file, *output, gzsize(file));
    gzclose(file);
}

void decompressData(unsigned char *compressed, unsigned char **decompressed) {
    gzFile file = gzopen("temp.gz", "rb");
    *decompressed = malloc(gzsize(file));
    gzread(file, *decompressed, gzsize(file));
    gzclose(file);
}

void processMessage(L1_MESSAGE *message) {
    if (messageCount >= MAX_MESSAGES) {
        free(messages[0]->DATA_BYTES);
        free(messages[0]);
        for (int i = 1; i < messageCount; ++i) {
            messages[i - 1] = messages[i];
        }
        --messageCount;
    }

    if (message->length > MAX_MESSAGES / 2) {
        unsigned char *compressedData, *decompressedData;
        compressData(message->DATA_BYTES, &compressedData);
        message->DATA_BYTES = decompressedData = malloc(strlen(compressedData));
        decompressData(compressedData, &decompressedData);
        message->length = strlen(decompressedData);
    }

    messages[messageCount] = message;
    ++messageCount;
}

void logError(const char *errorMessage) {
