} NFAPI_CRC_INDICATION_PDU;

static pthread_mutex_t allocation_log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE* allocation_log = NULL;
static size_t successful_allocations = 0;
static size_t total_allocated_memory = 0;

void log_allocation(size_t num_elements, size_t element_size) {
    pthread_mutex_lock(&allocation_log_mutex);
    if (!allocation_log) {
        allocation_log = fopen("allocation_log.txt", "w");
    }
    fprintf(allocation_log, "%zu elements of size %zu bytes allocated at %s\n", num_elements, element_size, ctime(&time(NULL)));
    pthread_mutex_unlock(&allocation_log_mutex);
}

void* allocate_memory_with_retry(size_t* out_ptr, size_t num_elements, size_t element_size) {
    void* ptr = malloc(num_elements * element_size);
    if (!ptr) {
        usleep(pow(2, backoff)); // Exponential backoff with a starting delay of 1ms
        return allocate_memory_with_retry(out_ptr, num_elements, element_size);
    }

    total_allocated_memory += num_elements * element_size;
    log_allocation(num_elements, element_size);
    successful_allocations++;

    backoff += 10; // Increment the backoff value for subsequent retries
    return ptr;
}

NFAPI_CRC_INDICATION_PDU* create_PDUs(size_t N) {
    void* memory = NULL;
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU);
    allocate_memory_with_retry((void**)&memory, N * element_size, element_size);

    NFAPI_CRC_INDICATION_PDU* pdu_array = (NFAPI_CRC_INDICATION_PDU*)memory;

    #pragma GCC diagnostic push
    #pragma GCC diagnostic ignored "-Wformat-nonliteral" // Disable warning for %zu format specifier
    for (size_t i = 0; i < N; ++i) {
        pdu_array[i].rx_ue_information_tag = i;
        pdu_array[i].rnti = i + 100;
        pdu_array[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Set CRCFLAG randomly
    }
    #pragma GCC diagnostic pop

    return pdu_array;
}
