#define MAX_CACHE 1024
#define LOG_FILE "allocation_log.txt"

struct RX_FRAME_PDU_T {
    uint32_t RX_FRAME_TAG;
    uint16_t PCI;
    float PHY_RSRP;
    int SRS_FLAG;
};

typedef struct CacheNode_T {
    struct RX_FRAME_PDU_T *data;
    struct CacheNode_T *next;
} CacheNode;

CacheNode* cacheHead = NULL;
CacheNode* cacheTail = NULL;
unsigned int numSuccessfulAllocations = 0;
FILE *logFile;
clock_t start, end;

struct RX_FRAME_PDU_T* allocateMemory(unsigned int N) {
    if (N <= 0) return NULL;

    if (N <= MAX_CACHE && cacheHead == NULL) {
        cacheHead = malloc(N * sizeof(struct RX_FRAME_PDU_T));
        cacheTail = cacheHead;
    } else if (N > MAX_CACHE && cacheHead != NULL) {
        CacheNode* newNode = malloc(N * sizeof(struct RX_FRAME_PDU_T));
        if (!newNode) return NULL;
        cacheTail->next = newNode;
        cacheTail = newNode;
    }

    if (cacheHead == NULL) {
        cacheHead = malloc(N * sizeof(struct RX_FRAME_PDU_T));
        if (!cacheHead) return NULL;
        cacheTail = cacheHead + N;
    }

    start = clock();
    for (unsigned int i = 0; i < N; ++i) {
        cacheHead[i].RX_FRAME_TAG = rand();
        cacheHead[i].PCI = rand() % 256;
        cacheHead[i].PHY_RSRP = (float)(rand() % 100 + 1);
        cacheHead[i].SRS_FLAG = rand() % 2;
    }
    end = clock();

    numSuccessfulAllocations++;
    logFile = fopen(LOG_FILE, "a");
    if (logFile) {
        fprintf(logFile, "%u allocations in %f seconds\n", N, (double)(end - start) / CLOCKS_PER_SEC);
        fclose(logFile);
    }

    return cacheHead;
}

void deallocateMemory(struct RX_FRAME_PDU_T* buffer) {
    if (!buffer || !cacheHead) return;

    start = clock();
    free(buffer);
    numSuccessfulDeallocations++;
    logFile = fopen(LOG_FILE, "a");
    if (logFile) {
        fprintf(logFile, "%u deallocations in %f seconds\n", 1, (double)(end - start) / CLOCKS_PER_SEC);
        fclose(logFile);
    }
}
