    int budget;
    struct tm start_date;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct project_dependency *dependencies;
} project_t;

typedef struct project_dependency {
    int rnti;
    struct project_dependency *next;
} project_dependency_t;

void pdu_init(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crcFlag = rand() % 2;
    // Initialize other members as needed
}

project_t* project_new(const char *name, int budget, struct tm *start_date, NFAPI_CRC_INDICATION_PDU_T *pdu) {
