    memset(project, 0, sizeof(project_t));
    strcpy(project->name, name);
    project->budget = budget;
    memcpy(&project->start_date, start_date, sizeof(struct tm));
    project->pdu = pdu_new();
    pdu_init(project->pdu);
    project->dependencies = NULL;
    return project;
}

void project_dependency_add(project_t *project, int rnti) {
    project_dependency_t *dep = (project_dependency_t*) malloc(sizeof(project_dependency_t));
    dep->rnti = rnti;
    dep->next = project->dependencies;
    project->dependencies = dep;
}

void* project_init(void *arg) {
    int *data = arg;
    project_t *project = project_new("Project", data[0], localtime(&data[1]), NULL);
    for (int i = 2; i < data[2]; ++i) {
        project_dependency_add(project, data[3 + i]);
    }
    return project;
}

void project_validate(project_t *project) {
    if (project->budget > MAX_BUDGET || project->budget < MIN_BUDGET) {
        fprintf(stderr, "Invalid budget for project: %s, budget: %d\n", project->name, project->budget);
        exit(EXIT_FAILURE);
    }
}

void project_cleanup(project_t *project) {
    project_dependency_t *dep, *temp;
    for (dep = project->dependencies; dep != NULL; dep = temp) {
        temp = dep->next;
        free(dep);
    }
    free(project->name);
    free(project);
}

void log_message(const char *format, ...) {
    va_list args;
    FILE *log_file = fopen("log.txt", "a");
    if (log_file == NULL) return;

    fprintf(log_file, "%s\n", format);
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fclose(log_file);
}

void* init_projects(int num_projects, ...) {
    pthread_t threads[num_projects];
    int arg_count = 5;
    void *arg_ptr[num_projects];
    project_t **projects = (project_t**) malloc(sizeof(project_t*) * num_projects);

    for (int i = 0; i < num_projects; ++i) {
        int args[arg_count] = {rand() % MAX_PROJECT_NAME_LENGTH, time(NULL), num_projects + i, num_projects + i};
        for (int j = arg_count; j < 2 * arg_count; ++j) {
            args[j] = rand() % MAX_PROJECTS;
        }
        arg_ptr[i] = &args;
    }

    for (int i = 0; i < num_projects; ++i) {
        pthread_create(&threads[i], NULL, project_init, arg_ptr[i]);
    }

    for (int i = 0; i < num_projects; ++i) {
        pthread_join(threads[i], (void**) &projects[i]);
    }

    // Perform validation, logging, and memory cleanup here

    free(arg_ptr);
    free(projects);

    return NULL;
