#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    sem_t mutex;
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
} ListManager;

ListManager *list_manager_init(size_t initial_capacity) {
    ListManager *lm = mmap(NULL, sizeof(ListManager), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (lm == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    sem_init(&lm->mutex, 0, 1);
    lm->capacity = initial_capacity;
    lm->count = 0;
    lm->data = (NFAPI_CRC_INDICATION_PDU_T *)((char *)lm + sizeof(ListManager));

    return lm;
}

void list_manager_destroy(ListManager *lm) {
    munmap(lm, sizeof(*lm) + lm->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

bool list_manager_add(ListManager *lm, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&lm->mutex);

    if (lm->count >= lm->capacity) {
        sem_post(&lm->mutex);
        return false;
    }

    size_t i = 0;
    for (; i < lm->count; ++i) {
        if (lm->data[i].RNTI == data.RNTI) {
            sem_post(&lm->mutex);
            return false;
        }
    }

    memcpy(&lm->data[lm->count], &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++lm->count;

    sem_post(&lm->mutex);
    return true;
}

// Implement an asynchronous function to fetch RX_UE_INFORMATION_TAG and RNTI values.
void fetch_ue_info(NFAPI_CRC_INDICATION_PDU_T *data, void (*callback)(bool success, NFAPI_CRC_INDICATION_PDU_T *data)) {
