void *worker(void *arg) {
    ListManager *lm = arg;
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T data;

        fetch_ue_info(&data, [](bool success, NFAPI_CRC_INDICATION_PDU_T *data) {
            if (!success) return; // Handle temporary failures here
            if (!list_manager_add(lm, *data)) return; // Retry on failure
        });
    }

    return NULL;
}
