#include <ctype.h>

typedef enum { ECB, EDE, EDE3, CFB, NONE } cipher_mode;
typedef struct {
    EVP_CIPHER_CTX* ctx;
    cipher_mode mode;
} encryptor;

encryptor init_cipher(const char* key, const char* iv, cipher_mode mode) {
    encryptor result = { NULL, mode };
    if (mode == ECB)
        result.ctx = EVP_ENC_CTX_new();
    else if (mode == EDE || mode == EDE3)
        result.ctx = EVP_CIPHER_CTX_new();
    else if (mode == CFB) {
        result.ctx = EVP_CFB1_CTX_new();
        EVP_CIPHER_CTX_set_cipher(result.ctx, EVP_cfb8());
    }

    if (!result.ctx) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    if (EVP_EncryptInit_ex(result.ctx, EVP_des(), key, iv, NULL) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    return result;
}

void encrypt(const uint8_t* in, uint8_t* out, size_t len, const encryptor* e) {
    EVP_EncryptUpdate(e->ctx, out, NULL, in, len);
    EVP_EncryptFinal_ex(e->ctx, out + EVP_CIPHER_update_len(e->ctx), in, len);
}

const char* adjust_filename(const char* filename) {
    static const char *extensions[] = { ".encrypted", ".des" };
    size_t extension_len = sizeof(extensions) / sizeof(char*);

    size_t i;
    for (i = 0; i < extension_len; ++i) {
        size_t pos = strlen(filename) - strlen(extensions[i]);
        if (pos > 0 && strcmp(filename + pos, extensions[i]) == 0)
            return filename;
    }

    char *new_filename = malloc(strlen(filename) + sizeof(extensions[0]));
    memcpy(new_filename, filename, strlen(filename));
    strcat(new_filename, extensions[0]);

    return new_filename;
}

char** parse_options(int argc, char **argv) {
    // Add your parsing logic here to handle command-line arguments or a configuration file
    // For simplicity, let's assume that the first 3 arguments are key, iv, and mode.

    char** options = malloc((argc - 3) * sizeof(char*));
    int i;
    for (i = 3; i < argc; ++i) {
        options[i - 3] = argv[i];
    }

    return options;
}

void cleanup_cipher(encryptor* e) {
    if (e->ctx != NULL) {
        EVP_CIPHER_CTX_free(e->ctx);
        e->ctx = NULL;
    }
}

void cleanup_options(char** options) {
    free(options);
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [key] [iv] [mode] [file1] ...\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    encryptor* e = init_cipher(argv[1], argv[2], (cipher_mode)atoi(argv[3]));
    char** options = parse_options(argc, argv);

    FILE *fp;
    size_t filename_len, i, file_count = argc - 4;
    for (i = 4; i < argc; ++i) {
        fp = fopen(argv[i], "rb");
        if (!fp) {
            perror("Error opening file");
            continue;
        }

        char* original_filename = argv[i];
        filename_len = strlen(original_filename);
        char* encrypted_filename = adjust_filename(original_filename);
        FILE *outfp = fopen(encrypted_filename, "wb");

        if (!outfp) {
            perror("Error creating output file");
            continue;
        }

        uint8_t buffer[1024];
        size_t bytes_read, bytes_written;
        while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
            encrypt(buffer, buffer, bytes_read, e);
            bytes_written = fwrite(buffer, 1, bytes_read, outfp);
            if (bytes_written != bytes_read) {
                perror("Error writing to file");
                break;
            }
        }

        fclose(outfp);
        fclose(fp);

        free(original_filename);
        free(encrypted_filename);
    }

    cleanup_cipher(e);
    cleanup_options(options);

    return EXIT_SUCCESS;
}
