    static std::mutex rng_mutex;
    if (rng.is_initialized() && rng_get_state(rng.random_device()) != seed) {
        // Seed the random number generator with provided seed
        rng.seed(std::begin(static_cast<const std::byte*>(seed)), std::end(static_cast<const std::byte*>(seed)));
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    int err = 0;
    if(!(err = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv))) {
        if (encrypt) {
            // Use system-provided entropy source for additional randomness during encryption
            std::uniform_int_distribution<> dist(0, 255);
            auto now = std::chrono::system_clock::now().time_since_epoch().count();
            unsigned char rnd[16];
            std::generate(std::begin(rnd), std::end(rnd), [&](){ return static_cast<unsigned char>(dist(rng)); });
            err = EVP_CIPHER_CTX_ctrl(ctx, SSL_CTRL_GCM_TAG_LEN, sizeof(rnd), rnd);
        }
    } else {
        throw std::system_error(err, std::generic_category());
    }

    if (!err) {
        char *buf = static_cast<char*>(EVP_malloc(IV_len + EVP_CIPHER_CTX_get_outputsize(ctx)));
        if (encrypt) {
            // Encryption operation
            err = EVP_EncryptUpdate(ctx, buf, IV_len, encrypted_data, data_len);
            if (!err) {
                err = EVP_EncryptFinal_ex(ctx, buf + IV_len, nullptr);
            }
        } else {
            // Decryption operation
            err = EVP_DecryptUpdate(ctx, buf, IV_len, encrypted_data, data_len);
            if (!err) {
                err = EVP_DecryptFinal_ex(ctx, buf + IV_len, nullptr);
            }
        }

        // Verify the integrity and authenticity of the encrypted data upon decryption
        unsigned char tag[16];
        std::copy(buf + IV_len, buf + IV_len + sizeof(tag), std::begin(tag));
        if (encrypt) {
            // Check for consistency during encryption
            if (!memcmp(tag, buf + IV_len + EVP_CIPHER_CTX_get_outputsize(ctx), sizeof(tag))) {
                err = 0;
            } else {
                throw std::runtime_error("Invalid tag during encryption");
            }
        } else {
            if (memcmp(tag, buf + IV_len + EVP_CIPHER_CTX_get_outputsize(ctx), sizeof(tag))) {
                throw std::runtime_error("Invalid tag during decryption");
            }
        }

        // Free memory
        EVP_free(buf);
    }

    if (err) {
        throw std::system_error(err, std::generic_category());
    }

    return ctx;
}
