    char *token_type;
    char *refresh_token;
} OAuth2Token;

static size_t token_parser(char *buf, size_t size, size_t nmemb, void *userp) {
    OAuth2Token *token = (OAuth2Token *)userp;
    json_object *obj = json_tokener_parse(buf);
    if (!json_object_get_string(obj, "access_token")) {
        fprintf(stderr, "Missing 'access_token' field\n");
        goto cleanup;
    }
    if (!json_object_get_int(obj, "expires_in")) {
        fprintf(stderr, "Missing 'expires_in' field or invalid value\n");
        goto cleanup;
    }
    if (strcasecmp(json_object_get_string(obj, "token_type"), "Bearer") != 0) {
        fprintf(stderr, "Invalid 'token_type' value\n");
        goto cleanup;
    }
    token->access_token = strdup(json_object_get_string(obj, "access_token"));
    token->expires_in = json_object_get_int(obj, "expires_in");
    token->token_type = strdup(json_object_get_string(obj, "token_type"));
    if (json_object_object_get(obj, "refresh_token")) {
        token->refresh_token = strdup(json_object_get_string(obj, "refresh_token"));
    }
cleanup:
    json_object_put(obj);
    return 0;
}

size_t read_file_callback(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    return fread(ptr, size, nmemb, stream);
}

int verify_hash_and_token(const char *path, const char *checksum, const char *access_token_response) {
    OAuth2Token token;
    memset(&token, 0, sizeof(OAuth2Token));
    json_object *obj = json_tokener_parse(access_token_response, token_parser, &token);
    if (!obj) return 0;

    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        goto cleanup;
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    size_t bytes_read = 0;
    while ((bytes_read = fread(hash, 1, sizeof(hash), file)) > 0) {
        SHA256_Update(&ctx, hash, bytes_read);
    }
    if (feof(file)) {
        if (ferror(file)) {
            perror("Error reading file");
            goto cleanup;
        }
    } else {
        fprintf(stderr, "Unexpected EOF while reading file\n");
        goto cleanup;
    }
    fclose(file);

    uint8_t checksum_arr[32];
    hex2bin((const char *)checksum, sizeof(checksum), checksum_arr);
    if (memcmp(hash, checksum_arr, SHA256_DIGEST_LENGTH) != 0) {
        fprintf(stderr, "Hash verification failed\n");
        goto cleanup;
    }

cleanup:
    json_object_put(obj);
    free(token.access_token);
    free(token.token_type);
    if (token.refresh_token) free(token.refresh_token);
    return 1;
}

// Helper function to convert hexadecimal string to binary array
void hex2bin(const char *str, size_t len, uint8_t *arr) {
    for (size_t i = 0; i < len; ++i) {
        arr[i] = strtol(str + (2 * i), NULL, 16);
    }
}
```

