    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (!dynamic_list[i]) {
            dynamic_list[i] = new_element;
            break;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to remove an element from the dynamic list, handling the case where the list is empty.
