typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t message_type;
    size_t payload_size;
    void* payload;
    pthread_mutex_t lock;
} LTE_UE_MESSAGE;

typedef struct {
    LTE_UE_MESSAGE** messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t list_lock;
} UE_MESSAGE_LIST;

UE_MESSAGE_LIST* init_ue_message_list(size_t initial_capacity) {
    UE_MESSAGE_LIST* list = malloc(sizeof(UE_MESSAGE_LIST));
    if (!list) return NULL;

    list->messages = calloc(initial_capacity, sizeof(LTE_UE_MESSAGE*));
    if (!list->messages) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void destroy_ue_message_list(UE_MESSAGE_LIST* list) {
    if (!list) return;

    for (size_t i = 0; i < list->capacity; ++i) {
        LTE_UE_MESSAGE* msg = list->messages[i];
        if (msg) {
            free(msg->payload);
            free(msg);
        }
    }

    free(list->messages);
    free(list);
}

void resize_ue_message_list(UE_MESSAGE_LIST* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    LTE_UE_MESSAGE** new_array = realloc(list->messages, new_capacity * sizeof(LTE_UE_MESSAGE*));
    if (!new_array) return;

    memmove(new_array + list->capacity, list->messages, (list->capacity - 1) * sizeof(LTE_UE_MESSAGE*));
    free(list->messages);

    list->messages = new_array;
    list->capacity = new_capacity;
}

void add_ue_message(UE_MESSAGE_LIST* list, LTE_UE_MESSAGE* msg) {
    pthread_mutex_lock(&list->list_lock);

    if (list->count == list->capacity) resize_ue_message_list(list, list->capacity * 2);

    list->messages[list->count] = msg;
    ++list->count;

    pthread_mutex_unlock(&list->list_lock);
}

LTE_UE_MESSAGE* get_ue_message(UE_MESSAGE_LIST* list, uint32_t tag) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i]->RX_UE_INFORMATION_TAG == tag) return list->messages[i];
    }
    return NULL;
}

LTE_UE_MESSAGE* allocate_ue_message(size_t payload_size) {
    LTE_UE_MESSAGE* msg = malloc(sizeof(LTE_UE_MESSAGE));
    if (!msg) return NULL;

    msg->payload_size = payload_size;
    msg->payload = mmap(NULL, payload_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (msg->payload == MAP_FAILED) {
        free(msg);
        return NULL;
    }

    pthread_mutex_init(&msg->lock, NULL);

    return msg;
}
