// Function to simulate attack sequences
void selectAttack(int& lastAttack) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distrib(0, 1);

    int currentAttack = distrib(gen);
    if (currentAttack != lastAttack) {
        lastAttack = currentAttack;
        std::cout << "Selected Attack: " << currentAttack + 1 << std::endl;
    }
}

// Function to handle the cooldown period
