    auto start = std::chrono::high_resolution_clock::now();
    double cooldownTime = 9.0 - (systemLoad * 1.5); // Adjust the cooldown based on system load

    while ((std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - start).count() < cooldownTime) && lastAttack != -1) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}

