    std::lock_guard<std::mutex> lock(pduListMutex);
    pduList[RX_UE_INFORMATION_TAG] = { RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG };

    int lastAttack = -1; // Reset the attack variable before each new update

    while (true) {
        selectAttack(lastAttack);
        enforceCooldown(lastAttack, /*system load calculation logic here*/);
    }
}
