import com.tinkerpop.gremlin.driver.Client;
import com.tinkerpop.gremlin.structure.Graph;
import com.tinkerpop.gremlin.structure.Vertex;
import com.tinkerpop.gremlin.process.traversal.Traversal;
import com.tinkerpop.gremlin.process.traversal.Step;
import java.util.ConcurrentLinkedQueue;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class GraphDatabaseManager {
    private final Graph graph;
    private final Client client;
    private final ConcurrentLinkedQueue<NFAPI_CRC_INDICATION_PDU_T> queue = new ConcurrentLinkedQueue<>();
    private ScheduledExecutorService service;

    @Autowired
    public GraphDatabaseManager(Graph graph, Client client) {
        this.graph = graph;
        this.client = client;
        this.service = Executors.newScheduledThreadPool(1);
    }

    public void createVertex(NFAPI_CRC_INDICATION_PDU_T pdu) {
        Traversal traversal = this.graph.traversal();
        Vertex v = traversal.V().hasId(pdu.getRxUeInformationTag()).orElse(null);
        if (v == null) {
            v = traversal.addV("PDU").property("rx_ue_information_tag", pdu.getRxUeInformationTag())
                    .property("rnti", pdu.getRnti()).next();
        }
        v.property("crc_indication_rel8_tag", pdu.getCrcIndicationRel8Tag());
        v.property("crcflag", new Random().nextBoolean());
    }

    public void enqueue(NFAPI_CRC_INDICATION_PDU_T pdu) {
        queue.add(pdu);
    }

    public NFAPI_CRC_INDICATION_PDU_T dequeue() {
        return queue.poll();
    }

    public void startService() {
        service.execute(() -> {
            try {
                while (true) {
                    Thread.sleep(new Random().nextInt(100)); // random delay interval
                    if (!queue.isEmpty()) {
                        NFAPI_CRC_INDICATION_PDU_T pdu = queue.poll();
                        createVertex(pdu);
                    }
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });
    }

    public void stopService() {
        service.shutdownNow();
        try {
            service.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

