#define MAX_RNTI 0xFFFFFFFF
#define TTL (5*60) // Time-to-live in seconds (5 minutes)

static NFAPI_CRC_INDICATION_PDU_T *head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void init_list() {
    pthread_mutex_init(&list_mutex, NULL);
    pthread_cond_init(&not_empty, NULL);
}

void cleanup() {
    NFAPI_CRC_INDICATION_PDU_T *current, *next;

    pthread_mutex_lock(&list_mutex);

    current = head;
    while (current != NULL) {
        next = current->next;
        if ((time(NULL) - current->creation_time) > TTL) {
            free(current);
        } else {
            current = next;
            continue;
        }

        head = next;
        if (current == NULL) break;
    }

    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&list_mutex);
}

int enqueue(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->rnti > MAX_RNTI || pdu->rnti < 1) return -1; // Invalid RNTI value

    pthread_mutex_lock(&list_mutex);

    while (head != NULL && head->rnti == pdu->rnti) {
        pthread_cond_wait(&not_empty, &list_mutex);
    }

    if (head != NULL && head->rnti == pdu->rnti) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Duplicate RNTI value
    }

    pdu->next = head;
    head = pdu;
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&list_mutex);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dequeue() {
    NFAPI_CRC_INDICATION_PDU_T *result = NULL;

    pthread_mutex_lock(&list_mutex);

    if (head != NULL) {
        result = head;
        head = head->next;
    }

    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&list_mutex);

    return result;
}
