struct slab {
    void *slab_start;
    size_t slab_size;
    size_t used_size;
};

void* create_slab(size_t size) {
    void *memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    struct slab *slab = calloc(1, sizeof(struct slab));
    if (!memory) return NULL;

    slab->slab_start = memory;
    slab->slab_size = size;
    slab->used_size = 0;
    return slab;
}

Node* get_node_from_slab(struct slab *slab) {
    if (slab->used_size >= slab->slab_size) return NULL;

    Node *node = (Node *)((char*)slab->slab_start + slab->used_size);
    slab->used_size += sizeof(Node);

    pthread_mutex_init(&node->lock, NULL);
    node->next = NULL;
    return node;
}

void insert(struct lte_mib *mib_array, size_t capacity, bool (*compare)(const LTE_PHY_MIB_INFO*, const LTE_PHY_MIB_INFO*)) {
