    for (size_t i = 0; i < capacity; ++i) head[i] = NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    void *slab_memory = mmap(NULL, INITIAL_SLAB_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    struct slab *slabs = calloc(1, sizeof(struct slab));
    if (!slab_memory || !slabs) {
        free(head);
        return;
    }

    slabs->slab_start = slab_memory;
    slabs->slab_size = INITIAL_SLAB_SIZE;
    slabs->used_size = 0;

    LTE_PHY_MIB_INFO *data = (LTE_PHY_MIB_INFO*)((char*)slab_memory + slabs->used_size);
    for (int i = 0; i < capacity; ++i) {
        Node *node = get_node_from_slab(slabs);
        if (!node) continue;

        node->data = data[i];
        int idx = find_index(head, &node->data, compare);
        if (idx == -1) {
            node->next = head[0];
            head[0] = node;
        } else {
            Node *temp = head[idx];
            head[idx] = node;
            node->next = temp;
        }
        ++data[i].checksum; // Increment checksum for validation
    }

    // Implement periodic pruning and concurrent access handling here
}

int find_index(Node** array, const LTE_PHY_MIB_INFO* key, bool (*compare)(const LTE_PHY_MIB_INFO*, const LTE_PHY_MIB_INFO*)) {
