        if (!array[i]) continue;

        Node *node = array[i];
        pthread_mutex_lock(&node->lock);

        if (compare(&key, &node->data)) {
            pthread_mutex_unlock(&node->lock);
            return i;
        }

        pthread_mutex_unlock(&node->lock);
    }
    return -1;
}

