    thread_pool[active_threads] = -1;

    while (active_threads < num_elements && thread_pool[active_threads] == -1) {
        pthread_create(&(thread_pool[active_threads]), &attr, worker_thread, &(pdus[active_threads]));
        ++active_threads;
    }

    // Return the PDUs and associated thread pool management function
    return (void*){pdus, create_pdu_pool, active_threads, log_fd};
}

// Worker thread function for handling individual PDU processing requests
void* worker_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = arg;
    pthread_t self = pthread_self();
    size_t active_threads = 0;
    void* pool_data = NULL;
    int log_fd = -1;

    // Lock the synchronization objects before modifying shared data structures
    pthread_mutex_lock(&pool_data_lock);

    // Update active threads counter and thread pool metadata
    pool_data = (void*){pdus, create_pdu_pool, active_threads, log_fd};
    ++active_threads;
    pool_data_ptr = pool_data;

    pthread_mutex_unlock(&pool_data_lock);

    // Process the PDU and handle any errors or anomalies
    if (pdus == NULL || *pdus == NULL) {
        fprintf(log_fd, "Error: Invalid input.\n");
        return NULL;
    }

    // ... Perform high-throughput data processing tasks here ...

    pthread_mutex_lock(&pool_data_lock);

    // Decrement the active threads counter and update thread pool metadata
    --active_threads;
    if (active_threads == 0) {
        free(pdus[0]);
        pdus[0] = NULL;
        pool_data = NULL;
    }
    pool_data_ptr = pool_data;

    pthread_mutex_unlock(&pool_data_lock);

    // Exit the worker thread and return control to the scheduler
    pthread_exit(NULL);
}
