#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <jhash.h> // For a high-quality hash function

typedef struct Node {
    int value;
    struct Node* next;
    struct Node* link; // Pointer to corresponding entry in the hash table
    pthread_mutex_t mutex;
    bool active;
} Node;

typedef struct HashTable {
    unsigned long size;
    Node** table;
    unsigned long num_elements;
    pthread_mutex_t lock;
} HashTable;

Node* create_node(int value) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->next = NULL;
    node->link = NULL;
    node->active = true;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

HashTable* create_hash_table(unsigned long size) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    if (!hash_table) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    hash_table->size = size;
    hash_table->table = calloc(size, sizeof(Node*));
    if (!hash_table->table) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    hash_table->num_elements = 0;
    pthread_mutex_init(&hash_table->lock, NULL);
    return hash_table;
}

unsigned long jenkins_one_at_a_time3(unsigned long key) {
    unsigned long hash = 17;
    unsigned long t;

    while (key-- > 0) {
        hash = (hash << 5) + hash;
        hash += hash >> 3;
        hash ^= hash << 6;
        hash ^= hash >> 21;
        hash ^= hash << 14;
        t = hash & 0xffffffff;
        hash = t + (t << 12);
        hash ^= hash >> 19;
        hash ^= hash << 8;
        hash ^= hash >> 7;
    }

    return hash % hash_table->size;
}

void insert(HashTable* hash_table, Node* node) {
    unsigned long index = jenkins_one_at_a_time3(node->value);
    pthread_mutex_lock(&hash_table->lock);

    Node** head = &hash_table->table[index];
    Node* current = *head;

    while (current != NULL) {
        if (current->value == node->value && current->active) {
            pthread_mutex_unlock(&hash_table->lock);
            return; // Collision, node already exists
        }
        current = current->next;
    }

    node->link = *head;
    *head = node;
    hash_table->num_elements++;
    pthread_mutex_unlock(&hash_table->lock);
}

Node* find(HashTable* hash_table, int value) {
    unsigned long index = jenkins_one_at_a_time3(value);
    Node** head = &hash_table->table[index];
    pthread_mutex_lock(&hash_table->lock);

    Node* current = *head;
    while (current != NULL) {
        if (current->value == value && current->active) {
            pthread_mutex_unlock(&hash_table->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&hash_table->lock);
    return NULL;
}

void toggle_active(Node* node) {
    node->active = !node->active;
}
```

