        uesession->rnti = i + 10000; // example: rnti starts from 10000 for each UE
        uesession->servingCellId = i * 100; // example: servingCellId based on ue_index
        pthread_mutex_init(&uesession->mutex, NULL);
        uesession->next = *ue_sessions;
        *ue_sessions = uesession;
    }
}

void initRRCMeasurementReports(struct LTE_UESessionConfig *ue_session) {
    for (int i = 0; i < 2; ++i) { // bands: FDD, TDD
        struct LTEPHY_RRCMeasurementReport *report = malloc(sizeof(LTEPHY_RRCMeasurementReport));
        if (!report) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        report->band = i;
        report->measurementResult = 0; // example: initialize to zero
        pthread_mutex_init(&report->mutex, NULL);
        report->next = ue_session->LTEPHY_RRCMeasurementReport;
        ue_session->LTEPHY_RRCMeasurementReport = report;
    }
}

void readAndUpdateReports(struct LTE_UESessionConfig *ue_session) {
    struct LTEPHY_RRCMeasurementReport *report = ue_session->LTEPHY_RRCMeasurementReport;
    while (report != NULL) {
        pthread_mutex_lock(&report->mutex);

        // Perform read and update operations using an external data source

        pthread_mutex_unlock(&report->mutex);

        report = report->next;
    }
}

int main() {
    struct LTE_UESessionConfig *ue_sessions = NULL;
    initUESession(&ue_sessions);

    for (int i = 0; i < MAX_UE_SESSIONS; ++i) {
        if (ue_sessions->next == NULL) break;
        struct LTE_UESessionConfig *current = ue_sessions;
        while (current->next != NULL) current = current->next;
        initRRCMeasurementReports(current);
    }

    pthread_t threads[MAX_UE_SESSIONS];
    for (int i = 0; i < MAX_UE_SESSIONS; ++i) {
        if (pthread_create(&threads[i], NULL, &readAndUpdateReports, ue_sessions)) {
