#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkInterface {
    char name[64];
    char type[16];
    uint64_t rx_bytes;
    uint64_t tx_bytes;
    pthread_mutex_t lock; // For thread safety
} Interface;

void init_interface(Interface* interface, const char* name, const char* type) {
    if (!interface || !name || !type || strlen(name) >= 64 || strlen(type) >= 16) {
        perror("Invalid arguments");
        return;
    }

    strcpy(interface->name, name);
    strcpy(interface->type, type);
    interface->rx_bytes = 0;
    interface->tx_bytes = 0;
    pthread_mutex_init(&interface->lock, NULL);
}

Interface** create_interfaces(size_t num_interfaces) {
    Interface **interfaces = malloc(num_interfaces * sizeof(Interface*));

    if (!interfaces) {
        perror("Failed to allocate memory for interfaces");
        return NULL;
    }

    for (size_t i = 0; i < num_interfaces; ++i) {
        interfaces[i] = malloc(sizeof(Interface));

        if (!interfaces[i]) {
            perror("Failed to allocate memory for interface");
            free_interfaces(interfaces, i);
            return NULL;
        }

        init_interface(interfaces[i], "", "");
    }

    return interfaces;
}

void free_interfaces(Interface** interfaces, size_t num_interfaces) {
    for (size_t i = 0; i < num_interfaces; ++i) {
        if (interfaces[i]) {
            pthread_mutex_destroy(&interfaces[i]->lock);
            free(interfaces[i]);
        }
    }

    free(interfaces);
}
```

