#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int value;
    char* name;
} Record;

void ensure_capacity(Record** arr, size_t* capacity, size_t new_size) {
    if (*capacity >= new_size) return;

    size_t old_capacity = *capacity;
    Record* tmp = realloc(*arr, sizeof(Record)*(new_size));
    if (!tmp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *arr = tmp;
    memset(&((*arr)[old_capacity]), 0, sizeof(Record)*(new_size - old_capacity));
    *capacity = new_size;
}

bool copy_string(char** dest, const char* src) {
    if (!src) return false;

    size_t len = strlen(src) + 1;
    *dest = malloc(len);
    if (!*dest) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strcpy(*dest, src);
    return true;
}

void init_records(Record** arr, size_t count, int min, int max, const char* const* names, size_t n_names) {
    *arr = malloc(sizeof(Record)*count);
    if (!*arr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    ensure_capacity(*arr, count, count);

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        Record* r = &((*arr)[i]);
        r->value = rand() % (max - min + 1) + min;

        size_t j;
        for (j = 0; j < n_names && names[j] != NULL; ++j);
        if (j == n_names) continue; // No more names left

        copy_string(&(r->name), names[j]);
    }
}

void free_records(Record* arr, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Record* r = &arr[i];
        free(r->name);
    }

    free(arr);
}
```

This code defines a `Record` structure with an integer value and a dynamically allocated string for the user name. The `ensure_capacity()` function is used to manage array resizing in a memory-efficient way by reallocating only the required amount of new memory, leaving existing data untouched.

The `copy_string()` function handles errors gracefully by checking if the source string pointer is null before attempting allocation and returning false when an allocation failure occurs.

The `init_records()` function initializes a specified number of records with random values within a given range, copying the user names from a provided list. It takes advantage of efficient array management using `ensure_capacity()`.

Finally, the `free_records()` function cleans up all allocated memory efficiently by first freeing each record's user name string and then freeing the entire array.']

