#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <ctype.h> // for isalnum()

// External library API
extern void process_record(struct record*);

typedef struct record {
    int key;
    char buffer[51];
    struct record *prev, *next;
} Record;

Record* create_linked_list(unsigned long num_nodes, unsigned int initial_key, unsigned int min_value, unsigned int max_value) {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    Record *head = NULL, *tail = NULL, *current = NULL;

    for (unsigned long i = 0; i < num_nodes; ++i) {
        Record *new_node = malloc(sizeof(Record));
        if (!new_node) {
            // Handle memory allocation failure
            perror("Memory allocation failed");
            return NULL;
        }

        new_node->key = initial_key + i;
        for (size_t j = 0; j < sizeof(new_node->buffer); ++j) {
            new_node->buffer[j] = rand() % 95 + 32; // Generate random ASCII character within the specified range
            if (new_node->buffer[j] == '\0') break; // Ensure null-terminated buffer
        }

        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    // Initialize the first node's previous pointer
    head->prev = NULL;

    // Process each record using the external library API
    for (current = head; current != NULL; current = current->next) {
        process_record(current);
    }

    return head;
}

void destroy_linked_list(Record* list) {
    Record *current = list;
    Record *temp;

    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
}
```

