    bool is_null;
};

static semaphore_t ciphers_mutex;
static List* ciphers = NULL;
static size_t num_ciphers = 0;

void add_cipher(const EVP_CIPHER *cipher, bool is_null) {
    if (!ciphers) {
        ciphers = create_list();
    }
    struct cipher_info *new_cipher = malloc(sizeof(*new_cipher));
    new_cipher->cipher = cipher;
    new_cipher->is_null = is_null;
    list_push_back(ciphers, new_cipher);
    num_ciphers++;
}

const EVP_CIPHER* get_current_cipher() {
    semaphore_wait(&ciphers_mutex);
    const EVP_CIPHER *cipher = ciphers->head ? ((struct cipher_info*)(ciphers->head->data))->cipher : NULL;
    semaphore_post(&ciphers_mutex);
    return cipher;
}

data_t* generate_pdu(size_t n) {
    data_t *pdus = malloc(n * sizeof(*pdus));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
