            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL);
            uint8_t iv[EVP_MAX_IV_LENGTH];
            randomize(iv, sizeof(iv));
            EVP_EncryptInit_ex(ctx, NULL, (unsigned char*)iv, iv);
            uint8_t data[] = {pdus[i].pdu.tag.len, pdus[i].pdu.tag.value};
            size_t data_len = sizeof(data);
            EVP_CIPHER_CTX_update(ctx, data, &data_len);
            pdus[i].pdu.crcindicationrel8tag.len = data_len;
            memcpy(pdus[i].pdu.crcindicationrel8tag.value, data, data_len);
            EVP_CIPHER_CTX_cleanup(ctx);
        }
    }
    return pdus;
}
