#define MAX_UES 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t N) {
    if (N <= 0 || N > MAX_UES) {
        perror("Invalid number of UEs");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = i + 12345678;
        pdus[i].CRC_INDICATION_REL8_TAG[0] = rand() % 256;
        pdus[i].CRC_INDICATION_REL8_TAG[1] = rand() % 256;
        pdus[i].CRC_INDICATION_REL8_TAG[2] = rand() % 256;
        pdus[i].CRC_INDICATION_REL8_TAG[3] = rand() % 256;
    }

    pthread_mutex_t *pdus_mutexes = malloc(N * sizeof(pthread_mutex_t));
    if (!pdus_mutexes) {
        perror("Memory allocation failed");
        free(pdus);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_init(&pdus_mutexes[i], NULL);
        pthread_mutex_lock(&pdus_mutexes[i]);
        pthread_mutex_unlock(&mutex);
        pthread_mutex_unlock(&pdus_mutexes[i]);
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t N) {
    if (!pdus || N == 0)
        return;

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_destroy(&pdus[i].mutex);
    }

    free(pdus);
    free(pdus[0].CRC_INDICATION_REL8_TAG);
    free(pdus); // Free the mutexes array, not needed anymore
}
