```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define TIMEOUT 60 // seconds

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

node_t *head = NULL;
node_t *tail = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t cleanup_tid;
time_t current_time;

void init() {
    pthread_create(&cleanup_tid, NULL, cleaner, NULL);
}

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);

    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        printf("Memory error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    if (!head) {
        head = new_node;
        tail = head;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    pthread_mutex_unlock(&mutex);
}

void *cleaner(void *arg) {
    struct timespec sleep_interval = { 1, 100000000 }; // 10ms
    struct timespec now;

    while (true) {
        clock_gettime(CLOCK_REALTIME, &now);
        current_time = now.tv_sec;

        pthread_mutex_lock(&mutex);

        node_t *current = head;
        node_t *temp;

        while (current != NULL) {
            if ((current->timestamp + TIMEOUT) < current_time) {
                temp = current;
                current = current->next;
                free(temp);
            } else {
                break;
            }
        }

        pthread_mutex_unlock(&mutex);

        nanosleep(&sleep_interval, NULL);
    }
}
```

In this implementation, we use a linked list for the data structure and a ring buffer to handle the cleanup process. The `cleaner` function is a separate thread that removes expired structures periodically. By using a sleep interval of 10ms, it ensures efficient cleaning under varying loads while minimizing its impact on concurrent operations.

