typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
static size_t pdu_count = 0;
static const size_t MAX_PDUS = 10000;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_pdus(size_t count) {
    if (count > MAX_PDUS || count + pdu_count > MAX_PDUS) {
        return;
    }

    pthread_mutex_lock(&list_lock);
    size_t new_pdu_index = pdu_count;
    pdu_count += count;
    pthread_mutex_unlock(&list_lock);

    if (new_pdu_index + count > pdu_count) {
        new_pdu_index = pdu_count - count;
    }

    for (size_t i = new_pdu_index; i < new_pdu_index + count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[i];
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = i % 65536;
        for (size_t j = 0; j < sizeof(pdu->CRC_INDICATION_REL8_TAG); ++j) {
            pdu->CRC_INDICATION_REL8_TAG[j] = rand() & 0xFF;
        }
        pdu->CRCFLAG = (rand() & 1) == 1;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(size_t index) {
    if (index >= pdu_count) {
        return NULL;
    }

    pthread_mutex_lock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[index];
    pthread_mutex_unlock(&list_lock);

    return pdu;
}
