namespace RandomEngine {
    class MersenneTwisterGenerator {
        private:
            std::mt19937 engine;
            unsigned long long seed;
            static std::atomic<uint64_t> globalSeedCounter;

        public:
            MersenneTwisterGenerator(unsigned long long seed = 0) : engine(seed), seed(seed + globalSeedCounter++) {}
            ~MersenneTwisterGenerator() {}

            unsigned long long generateUniform() {
                return engine();
            }

            double generateNormal() const {
                std::normal_distribution<double> dist(0.0, 1.0);
                return dist(engine);
            }

            static void initializeGlobalSeedCounter(unsigned long long seed) {
                globalSeedCounter = seed;
            }
    };

    std::atomic<uint64_t> MersenneTwisterGenerator::globalSeedCounter = 0;
