PacketManager* createPacketManager(uint32_t maxPackets, time_t syncInterval) {
    PacketManager* manager = malloc(sizeof(PacketManager));
    if (!manager) return NULL;

    manager->capacity = 0;
    manager->size = 0;
    manager->maxPackets = maxPackets;
    manager->syncInterval = syncInterval;

    manager->packets = calloc(maxPackets, sizeof(TX_PACKET));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    return manager;
}
```

4. **Adding Packet**

```c
bool addPacket(PacketManager* manager, TX_PACKET packet) {
    // Check if the array is full and grow it if necessary
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->packets = realloc(manager->packets, manager->capacity * sizeof(TX_PACKET));
    }

    manager->packets[manager->size] = packet;
    manager->size++;
    return true;
}
```

5. **Updating Packet**

```c
bool updatePacket(PacketManager* manager, uint32_t rnti, TX_PACKET newPacket) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].rnti == rnti) {
            manager->packets[i] = newPacket;
            return true;
