```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <curl/curl.h>

typedef struct {
    int fd;
    CURL *curl;
} Connection;

typedef struct ThreadData {
    pthread_t thread_id;
    Connection connection;
    size_t file_size;
    char *buffer;
} ThreadData;

static void *transfer_file(void *arg) {
    ThreadData *data = (ThreadData *) arg;
    CURLcode res;

    res = curl_easy_setopt(data->connection.curl, CURLOPT_URL, data->buffer);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }

    res = curl_easy_perform(data->connection.curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "File transfer failed: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }

    return NULL;
}

int create_connection(const char *host, const char *port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(atoi(port));
    inet_pton(AF_INET, host, &serv_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        exit(EXIT_FAILURE);
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data->connection);

    return sockfd;
}

void free_connection(Connection *conn) {
    curl_easy_cleanup(conn->curl);
    close(conn->fd);
}

int main() {
    // Initialize connection pool and load balancer
    // ...

    // Start listening for incoming connections on a given port
    int listenfd = socket(AF_INET, SOCK_STREAM, 0);
    if (listenfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);

    if (bind(listenfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(listenfd, SOMAXCONN) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int clientfd = accept(listenfd, NULL, NULL);
        if (clientfd < 0) {
            perror("accept");
            continue;
        }

        Connection connection;
        connection.fd = clientfd;
        connection.curl = curl_easy_init();

        pthread_t thread_id;
        ThreadData *data = malloc(sizeof(ThreadData));
        data->connection = connection;

        getcwd(data->buffer, 1024);
        size_t file_size = strlen(data->buffer);
        data->file_size = file_size;
        data->buffer = realloc(data->buffer, file_size + 16);

        pthread_create(&thread_id, NULL, transfer_file, (void *) data);
        pthread_detach(thread_id);
    }

    return 0;
}
```

