void push(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    num_elements++;

    if (num_elements % 10 == 0) {
        new_node->cr cflag = true; // Update the CRCFLAG every 10th element
