    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        fprintf(stderr, "List is empty\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    temp = head;
    head = head->next;
    free(temp);

    num_elements--;
    pthread_mutex_unlock(&list_mutex);
}

size_t length() {
