    private static readonly ILog Log = LogManager.GetLogger(typeof(XmlParser));
    private const int MaxSimultaneousDocuments = 50;
    private readonly XmlReaderSettings _readerSettings;

    public XmlParser()
    {
        _readerSettings = new XmlReaderSettings();
        _readerSettings.ProhibitDtd = true;
        _readerSettings.ConformanceAsDocument = true;
        _readerSettings.MaxDepth = int.MaxValue;
    }

    public XPathNavigator Parse(string xmlFilePath, string xPathQuery, string defaultNamespaceUri = null, bool outputElementPath = false)
    {
        var activeDocuments = new List<XmlDocument>();
        try
        {
            if (activeDocuments.Count >= MaxSimultaneousDocuments)
            {
                WaitForResourceRelease();
            }

            var document = new XmlDocument();
            using (var reader = XmlReader.Create(xmlFilePath, _readerSettings))
            {
                document.Load(reader);
            }

            activeDocuments.Add(document);
            return document.CreateNavigator().SelectSingleNode(xPathQuery, CreateXPathNavigatorSettings(defaultNamespaceUri));
        }
        catch (Exception ex) when (ex is OutOfMemoryException || ex is XmlException || ex is ArgumentException || ex is PathTooLongException)
        {
            LogError(xmlFilePath, xPathQuery, ex);
            throw new ApplicationException("Failed to parse XML document.", ex);
        }
        finally
        {
            if (outputElementPath && activeDocuments.Any())
            {
                var navigator = activeDocuments[activeDocuments.Count - 1].CreateNavigator();
                LogDebug(xmlFilePath, xPathQuery, GetElementPath(navigator));
            }

            if (activeDocuments.Count > 1 && activeDocuments.Count <= MaxSimultaneousDocuments)
            {
                ReleaseResource(activeDocuments);
            }
        }
    }

