            {
                WaitForResourceRelease();
            }

            var document = new XmlDocument();
            using (var reader = XmlReader.Create(new MemoryStream(xmlData), _readerSettings))
            {
                document.Load(reader);
            }

            activeDocuments.Add(document);
            return document.CreateNavigator().SelectSingleNode(xPathQuery, CreateXPathNavigatorSettings(defaultNamespaceUri));
        }
        catch (Exception ex) when (ex is OutOfMemoryException || ex is XmlException || ex is ArgumentException || ex is InvalidDataException)
        {
            LogError(null, xPathQuery, ex);
            throw new ApplicationException("Failed to parse XML document.", ex);
        }
        finally
        {
            if (outputElementPath && activeDocuments.Any())
