        pthread_mutex_lock(&cache_mutex);
        if (cache_count >= size) {
            NFAPI_CRC_INDICATION_PDU_T *array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(array, cache, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&cache_mutex);

            return array;
        }
        populate_cache();
        pthread_mutex_unlock(&cache_mutex);
    }

    pthread_t threads[size];
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    for (size_t i = 0; i < size; ++i) {
        pthread_create(&threads[i], NULL, allocate_and_populate, &i);
