[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t rnti;
    uint16_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int rxUeInfoTag;
    CRC_INDICATION_REL8_TAG crcIndication;
    uint32_t uniqueId; // Can be used for identification purposes
} NFAPI_CRC_INDICATION_PDU_T;

union set {
    int data[64];
    struct {
        int parent, rank;
    } nodes[64];
};

struct disjointSet {
    union set *set;
    int size;
};

void makeSet(struct disjointSet *ds, int i) {
    if (ds->size <= i) ds->size *= 2;
    ds->set[i].parent = i;
    ds->set[i].rank = 0;
}

int find(struct disjointSet *ds, int i) {
    return ds->set[i].parent == i ? i : (ds->set[i].parent = find(ds, ds->set[i].parent));
}

void unionSets(struct disjointSet *ds, int a, int b) {
    int rootA = find(ds, a);
    int rootB = find(ds, b);
    if (rootA == rootB) return;

    if (ds->set[rootA].rank < ds->set[rootB].rank) {
        ds->set[rootA].parent = rootB;
    } else if (ds->set[rootA].rank > ds->set[rootB].rank) {
        ds->set[rootB].parent = rootA;
    } else {
        ds->set[rootB].parent = rootA;
        ds->set[rootA].rank++;
    }
}

NFAPI_CRC_INDICATION_PDU_T* processNFAPIData(int N) {
    struct disjointSet *ds = malloc(sizeof(*ds));
    ds->size = 0;
    struct timespec start, end;

    NFAPI_CRC_INDICATION_PDU_T *result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    clock_gettime(CLOCK_MONOTONIC, &start);
    for (int i = 0; i < N; ++i) {
        makeSet(ds, i);
        int rnti = rand() % 65536;
        result[i].rxUeInfoTag = i;
        result[i].crcIndication.rnti = rnti;
        result[i].crcIndication.crcFlag = rand() % 2;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    printf("Time taken to create structures: %.3f ms\n", (end.tv_sec - start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1e6);

    clock_gettime(CLOCK_MONOTONIC, &start);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (find(ds, result[i].rxUeInfoTag) != find(ds, result[j].rxUeInfoTag)) {
                unionSets(ds, result[i].rxUeInfoTag, result[j].rxUeInfoTag);
            }
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    printf("Time taken to identify disjoint pairs: %.3f ms\n", (end.tv_sec - start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1e6);

    return result;
}
