#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TrafficFlow {
    char SourceIP[32];
    char DestinationIP[32];
    char FlowType[16];
    struct TrafficFlow *next;
} TrafficFlow;

struct DynArray {
    unsigned int capacity, size;
    TrafficFlow **array;
};

void compact(struct DynArray *dyn) {
    TrafficFlow **new_arr = malloc((dyn->capacity / 2 + 1) * sizeof(TrafficFlow*));
    int i, j = 0;

    for (i = 0; i < dyn->size; ++i) {
        if (dyn->array[i]) {
            new_arr[j++] = dyn->array[i];
        }
    }

    dyn->capacity /= 2;
    dyn->size = j;
    dyn->array = new_arr;
}

TrafficFlow* find(struct DynArray *dyn, char SourceIP[], char DestinationIP[]) {
    int i;
    for (i = 0; i < dyn->size; ++i) {
        if (!strcmp(dyn->array[i]->SourceIP, SourceIP) && !strcmp(dyn->array[i]->DestinationIP, DestinationIP)) {
            return dyn->array[i];
        }
    }
    return NULL;
}

void insert(struct DynArray *dyn, TrafficFlow *flow) {
    if (dyn->size == dyn->capacity) {
        compact(dyn);
    }

    if (dyn->size >= dyn->capacity) {
        dyn->array[dyn->size] = flow;
        dyn->size++;
    } else {
        int i;
        for (i = 0; i < dyn->size; ++i) {
            if (!dyn->array[i]) {
                dyn->array[i] = flow;
                break;
            }
        }

        if (i == dyn->size) {
            dyn->array = realloc(dyn->array, (dyn->capacity * 2 + 1) * sizeof(TrafficFlow*));
            dyn->capacity *= 2;
            dyn->array[dyn->size] = flow;
            dyn->size++;
        }
    }
}

void init_dynarray(struct DynArray *dyn, unsigned int capacity) {
    dyn->capacity = capacity > 0 ? capacity : 128;
    dyn->size = 0;
    dyn->array = calloc((dyn->capacity + 1), sizeof(TrafficFlow*));
}
```
