void create_cache(struct cache *cache, unsigned int size) {
    cache->size = size;
    cache->count = 0;
    cache->tables = calloc(size, sizeof(struct cache_node*));
}

unsigned int hash(const void *key, unsigned int table_size) {
    const unsigned char *str = (const unsigned char *) key;
    unsigned long hash = 5381;
    int c;

    while ((c = *(const unsigned char *) str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % table_size;
}

void put_cache(struct cache *cache, const void *key, const NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hash((const char *) &data.rnti, cache->size);
    struct cache_node **bucket = &(cache->tables[index]);

    if (!*bucket)
        *bucket = malloc(sizeof(struct cache_node));

    (*bucket)->data = data;
    (*bucket)->next = NULL;
