    unsigned int index = hash((const char *) &((NFAPI_CRC_INDICATION_PDU_T*) key)->rnti, cache->size);
    struct cache_node *bucket = cache->tables[index];

    if (!bucket)
        return (NFAPI_CRC_INDICATION_PDU_T){0};

    for (struct cache_node *node = bucket; node; node = node->next) {
        if (&node->data == key)
            return node->data;
    }

    return (NFAPI_CRC_INDICATION_PDU_T){0};
}

void delete_cache(struct cache *cache, const void *key) {
    unsigned int index = hash((const char *) &((NFAPI_CRC_INDICATION_PDU_T*) key)->rnti, cache->size);
    struct cache_node **bucket = &(cache->tables[index]);
    struct cache_node *prev, *current;

    for (prev = NULL, current = *bucket; current; prev = current, current = current->next) {
        if (&current->data == key) {
            if (!prev)
                *bucket = current->next;
            else
                prev->next = current->next;

            free(current);
            break;
        }
    }
}

