struct dns_cache {
    char hostname[256];
    in_addr_t ip;
    time_t expiration;
    pthread_mutex_t lock;
};

struct dynamic_list {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t list_lock;
};

void dns_cache_init(struct dns_cache *cache, const char *hostname) {
    memset(cache, 0, sizeof(*cache));
    strcpy(cache->hostname, hostname);
}

int dns_cache_lookup(const struct dns_cache *cache, in_addr_t *ip) {
    time_t current_time = time(NULL);

    if (current_time > cache->expiration)
        return 0; // Cache expired

    pthread_mutex_lock(&cache->lock);
    *ip = cache->ip;
    pthread_mutex_unlock(&cache->lock);

    return 1; // Found in cache
}

void dns_cache_update(struct dns_cache *cache, in_addr_t ip) {
    time_t current_time = time(NULL);
    cache->ip = ip;
    cache->expiration = current_time + 60; // Cache for 1 minute
}

void dynamic_list_init(struct dynamic_list *list, size_t capacity) {
    list->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = capacity;
    list->length = 0;
    pthread_mutex_init(&list->list_lock, NULL);
}

void dynamic_list_push_back(struct dynamic_list *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->list_lock);
    if (list->length >= list->capacity) {
        // Resize the array and re-lock the mutex
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_data == NULL) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&list->list_lock);
            return;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    memcpy(&list->data[list->length], data, sizeof(*data));
    list->length++;
    pthread_mutex_unlock(&list->list_lock);
}

NFAPI_CRC_INDICATION_PDU_T *dynamic_list_pop_front(struct dynamic_list *list) {
    NFAPI_CRC_INDICATION_PDU_T *data;

    pthread_mutex_lock(&list->list_lock);
    if (list->length == 0) {
        data = NULL;
    } else {
        data = &list->data[0];
        memmove(list->data, &list->data[1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->length - 1));
        list->length--;
    }
    pthread_mutex_unlock(&list->list_lock);

    return data;
}

void *dns_resolver(void *arg) {
    const char *hostname = arg;
    struct addrinfo hints, *result;
    int status;
    in_addr_t ip;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return NULL;
    }

    ip = ((struct sockaddr_in *)result->ai_addr)->sin_addr.s_addr;

    freeaddrinfo(result);

    return &ip;
}

void get_dynamic_list_entry(struct dynamic_list *list, const char *hostname, in_addr_t *ip, NFAPI_CRC_INDICATION_PDU_T *data) {
    struct dns_cache cache;
    pthread_t resolver_thread;
    in_addr_t resolved_ip;

    memset(data, 0, sizeof(*data));

    dns_cache_init(&cache, hostname);

    if (dns_cache_lookup(&cache, &resolved_ip)) {
        data->tag = ... // Set tag from cache
        data->rnti = ... // Set rnti from cache
        data->crc_indication.CRCFLAG = rand() % 2; // Randomly set CRC flag
    } else {
        pthread_create(&resolver_thread, NULL, dns_resolver, hostname);
        resolved_ip = *((in_addr_t *)pthread_join(resolver_thread, &resolved_ip));
        dns_cache_update(&cache, resolved_ip);

        data->tag = ... // Set tag from resolved IP
        data->rnti = ... // Set rnti using some logic
        data->crc_indication.CRCFLAG = rand() % 2; // Randomly set CRC flag
    }
}
