public class Record { public long Offset; public int Key; }

public async Task ProcessLargeDatasetAsync(string filePath, long maxMemoryUsage, int minThreadCount, int maxThreadCount, int recordCountLimit, (int Min, int Max) randomRange)
{
    // Prepare data structures and allocate memory for the dataset.
    var offsets = new LongPtr[recordCountLimit];
    var keys = new int[recordCountLimit];
    var records = new ConcurrentQueue<Record>();

    // Ensure memory usage is within limits.
    var recordSize = sizeof(long) + sizeof(int);
    long allocatedMemory = 0;
    if (allocatedMemory > maxMemoryUsage)
        throw new Exception($"Allocation exceeded the specified maximum memory usage of {maxMemoryUsage} bytes.");

    // Use C function to prepare necessary data structures for large datasets.
    PrepareDataStructures(filePath, offsets, keys, ref allocatedMemory);

    // Parallel deserialization using BinaryFormatter with error handling and locking.
    var taskFactory = new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = maxThreadCount };
    await Task.WhenAll(Enumerable.Range(0, minThreadCount).Select(i => Task.Run(() =>
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            var recordQueue = new FixedSizeQueue<Record>(maxThreadCount);
            Action<object> addToQueue = obj => lock (recordQueue) { recordQueue.Enqueue((Record)obj); };

            try
            {
                while (!fileStream.EndOfStream)
                {
                    var record = formatter.Deserialize(new BinaryReader(fileStream));
                    if (record != null && records.Count < recordCountLimit)
                    {
                        addToQueue((Record)record);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error while deserializing data: {ex}");
            }
        }
    })));

    // Fill the record array with random values within the specified range and store offsets.
    for (int i = 0; records.Count < recordCountLimit && i < randomRange.Max; i++)
    {
        int randomKey = random.Next(randomRange.Min, randomRange.Max);
        Record record;
        if (records.TryDequeue(out record))
        {
            record.Key = randomKey;
            offsets[i] = record.Offset;
        }
    }
}
