    log_data.pos += snprintf(log_data.buffer + log_data.pos, sizeof(log_data.buffer) - log_data.pos, "[%llu][%u][%hu][%hu]\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
}

void *create_pdu(void *arg) {
    static NFAPI_CRC_INDICATION_PDU_T pdus[MAX_THREADS];
    size_t batch_size = *(size_t *) arg;
    size_t idx = pthread_self() % MAX_THREADS;
    for (size_t i = idx; i < idx + batch_size && i < MAX_THREADS; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = ((uint64_t)time(NULL) << 32) | rand();
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
