void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    if (it == list.end()) { // Empty list
        list.push_back(insertion);
        return;
    }

    size_t count = 0;
    while (++it != list.end() && count < 2) {
        if (*it == target) {
            list.insert(++it, insertion);
            count++;
        }
    }

    // Insert at the end of the list if not found
