static double crc_threshold = 0.5;

void init(size_t initial_capacity) {
    if (initial_capacity == 0) return;

    capacity = initial_capacity;
    data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    stats = calloc(MAX_RNTIS, sizeof(STATS_DATA_T));
    if (!data || !stats) {
        perror("Memory allocation failed");
        return;
    }
}

void resize() {
    size_t new_capacity = capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) {
        perror("Memory reallocation failed");
        return;
    }
    data = temp_data;
}

void push(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);

    if (capacity == data_size()) {
        resize();
    }

    data[data_size()] = *pdu;

    update_stats(pdu->rnti);

    pthread_mutex_unlock(&mutex);
}

void filter() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < data_size(); ++i) {
        double success_rate = static_cast<double>(stats[data[i].rnti].successful_checks[data[i].rnti]) /
                              (static_cast<double>(stats[data[i].rnti].successful_checks[data[i].rnti]) +
                               stats[data[i].rnti].failed_checks[data[i].rnti]);
        if (success_rate < crc_threshold) {
            for (size_t j = i; j < data_size() - 1; ++j) {
                data[j] = data[j + 1];
                update_stats(data[j].rnti);
            }
            --capacity;
        }
    }

    pthread_mutex_unlock(&mutex);
}

size_t data_size() {
    return capacity;
}

