#include <stdio.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int connection_id;
    struct sockaddr_in remote_addr;
    unsigned short port;
    char *buffer;
    size_t buffer_size;
    pthread_mutex_t mutex;
    sem_t sem_full, sem_empty;
} TCP_CONNECTION;

TCP_CONNECTION* create_dynamic_list(size_t capacity) {
    TCP_CONNECTION *list = (TCP_CONNECTION*)malloc(capacity * sizeof(TCP_CONNECTION));
    if (!list) return NULL;

    for (size_t i = 0; i < capacity; ++i) {
        list[i].connection_id = i;
        list[i].remote_addr.sin_family = AF_INET;
        list[i].port = 0;
        list[i].buffer = NULL;
        list[i].buffer_size = 0;
        pthread_mutex_init(&list[i].mutex, NULL);
        sem_init(&list[i].sem_full, 0, 0);
        sem_init(&list[i].sem_empty, 0, capacity > 1 ? 1 : 0);
    }
    return list;
}

TCP_CONNECTION* get_free_connection(TCP_CONNECTION *list, size_t capacity) {
    pthread_mutex_lock(&list[capacity - 1].mutex);
    if (sem_trywait(&list[capacity - 1].sem_empty)) {
        TCP_CONNECTION *conn = &list[capacity - 1];
        sem_post(&list[capacity - 1].sem_full);
        return conn;
    }
    pthread_mutex_unlock(&list[capacity - 1].mutex);

    for (size_t i = 0; i < capacity - 1; ++i) {
        if (sem_trywait(&list[i].sem_empty)) {
            TCP_CONNECTION *conn = &list[i];
            sem_post(&list[i].sem_full);
            return conn;
        }
    }

    return NULL; // No free connection found
}

void release_connection(TCP_CONNECTION *conn) {
    pthread_mutex_lock(&conn->mutex);
    sem_post(&conn->sem_empty);
    pthread_mutex_unlock(&conn->mutex);
}

// Function to handle data retrieval and update operations efficiently
void handle_connection(TCP_CONNECTION *conn) {
    // Handle incoming data, update the buffer, and set port number here
    // ...
}
