    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    *indications = (NFAPI_CRC_INDICATION_PDU_T*) malloc(fileSize);
    if (!*indications) {
        fprintf(stderr, "Failed to allocate memory for deserialized list.\n");
        fclose(file);
        return;
    }

    size_t read = fread(*indications, sizeof(NFAPI_CRC_INDICATION_PDU_T), fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    if (read != fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Failed to read serialized data from file.\n");
        free(*indications);
        fclose(file);
        return;
    }

    *count = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    fclose(file);
}

