                return zlib.inflateSync(buffer).toString('utf-8');
              default:
                json = json5.parse(buffer.toString());
            }
          } catch (error) {
            reject(error);
          }

          resolve(json.length);
        })
        .catch(reject);
    }

    function readFile(filePath) {
      return new Promise((resolve, reject) => {
        const fileStream = fs.createReadStream(filePath);
        const bufferChunkSize = 1024 * 64; // 64KB
        let bufferData = Buffer.allocUnsafe(bufferChunkSize);
        let remainingLength = bufferChunkSize;

        fileStream.on('error', reject);
        fileStream.on('data', (chunk) => {
          if (remainingLength > chunk.length) {
            chunk.copy(bufferData, 0, 0, chunk.length);
            remainingLength -= chunk.length;
            bufferData = bufferData.slice(0, bufferChunkSize);
          } else {
            bufferData = Buffer.concat([bufferData, chunk]);
          }
        });
        fileStream.on('end', () => resolve(bufferData));
      });
    }
  });
}
```"]

