```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <pthread>
#include <list>
#include <cstdlib>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

struct Node {
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> data;
    std::list<Node>::iterator next;
};

class DynamicList {
private:
    std::list<Node> nodes;
    pthread_mutex_t mutex; // For concurrent access control

public:
    DynamicList() : mutex(PTHREAD_MUTEX_INITIALIZER) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T& data) {
        pthread_mutex_lock(&mutex);
        auto newNode = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(data);
        Node node{std::move(newNode), nodes.end()};
        nodes.push_back(node);
        pthread_mutex_unlock(&mutex);
    }

    bool update(const RX_UE_INFORMATION_TAG& rx_ue_info, const std::function<void(NFAPI_CRC_INDICATION_PDU_T&)>& updater) {
        pthread_mutex_lock(&mutex);
        for (auto it = nodes.begin(); it != nodes.end(); ++it) {
            if (it->data->rx_ue_info == rx_ue_info) {
                updater(*it->data);
                pthread_mutex_unlock(&mutex);
                return true;
            }
        }
        pthread_mutex_unlock(&mutex);
        return false;
    }

    bool remove(const RX_UE_INFORMATION_TAG& rx_ue_info) {
        pthread_mutex_lock(&mutex);
        for (auto it = nodes.begin(); it != nodes.end(); ) {
            if (it->data->rx_ue_info == rx_ue_info) {
                it = nodes.erase(it);
                pthread_mutex_unlock(&mutex);
                return true;
            } else {
                ++it;
            }
        }
        pthread_mutex_unlock(&mutex);
        return false;
    }
};
```

