typedef struct MAC_PACKET_BUFFER {
    PDUSESSION_ID pdu_session_id;
    UE_INDEX ue_index;
    MAC_PACKET_STATS stats;
    time_t arrival_timestamp;
} MAC_PACKET_BUFFER_T;

#define MAX_BUFFERS 4096
#define BUFFER_CHUNK 256

static MAC_PACKET_BUFFER_T* buffers = NULL;
static size_t buffer_count = 0, allocated = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void mac_packet_buffer_init() {
    if (buffers) return;
    buffers = malloc(BUFFER_CHUNK * sizeof(MAC_PACKET_BUFFER_T));
    if (!buffers) {
        fprintf(stderr, "Failed to allocate initial buffer chunk\n");
        exit(1);
    }
    allocated += BUFFER_CHUNK;
}

size_t mac_packet_buffer_get_count() {
    pthread_mutex_lock(&mutex);
    size_t count = buffer_count;
    pthread_mutex_unlock(&mutex);
    return count;
}

void* mac_packet_buffer_at(size_t index) {
    void* ret = NULL;
    pthread_mutex_lock(&mutex);
    if (index < buffer_count) {
        ret = &buffers[index];
    } else {
        fprintf(stderr, "Index out of bounds: %zu\n", index);
    }
    pthread_mutex_unlock(&mutex);
    return ret;
}

void mac_packet_buffer_append(MAC_PACKET_BUFFER_T* packet) {
    pthread_mutex_lock(&mutex);
    if (allocated + 1 > MAX_BUFFERS) {
        size_t new_buffers = buffer_count + BUFFER_CHUNK;
        MAC_PACKET_BUFFER_T* temp_buffers = realloc(buffers, new_buffers * sizeof(MAC_PACKET_BUFFER_T));
        if (!temp_buffers) {
            fprintf(stderr, "Failed to reallocate buffer chunk\n");
            exit(1);
        }
        buffers = temp_buffers;
        allocated += BUFFER_CHUNK;
    }
    buffered[buffer_count++] = *packet;
    pthread_mutex_unlock(&mutex);
}

void mac_packet_buffer_free() {
    free(buffers);
    buffers = NULL;
    buffer_count = allocated = 0;
}
```

