void addToDynamicList(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *node) {
    node->next = *head;
    *head = node;
}

NFAPI_CRC_INDICATION_PDU_T* removeFromDynamicList(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *node) {
    if (isEmptyDynamicList(*head))
        return NULL;

    if (*head == node) {
        NFAPI_CRC_INDICATION_PDU_T *temp = *head;
        *head = temp->next;
        free(temp);
        return temp;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    while (current->next != NULL && current->next != node) {
        current = current->next;
    }

    if (current->next == NULL)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *temp = current->next;
    current->next = temp->next;
    free(temp);
    return temp;
}

NFAPI_CRC_INDICATION_PDU_T* findInDynamicList(const NFAPI_CRC_INDICATION_PDU_T *head, RNTI rnti) {
