#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct DataPacket {
    int packetID;
    char *source;
    char *destination;
    size_t payloadSize;
} DataPacket;

typedef struct NetworkEvent {
    time_t eventTimestamp;
    enum EventType { INCOMING, OUTGOING } eventType;
    DataPacket* packetList; // dynamically allocated list of DataPackets
    size_t numPackets;
} NetworkEvent;

NetworkEvent* createNetworkEvent(time_t timestamp, enum EventType type) {
    NetworkEvent *newEvent = malloc(sizeof(NetworkEvent));
    if (!newEvent) {
        perror("Error allocating memory for NetworkEvent");
        return NULL;
    }

    newEvent->eventTimestamp = timestamp;
    newEvent->eventType = type;
    newEvent->packetList = NULL;
    newEvent->numPackets = 0;

    return newEvent;
}

DataPacket* createDataPacket(int id, const char *source, const char *dest, size_t payloadSize) {
    DataPacket *newPacket = malloc(sizeof(DataPacket));
    if (!newPacket) {
        perror("Error allocating memory for DataPacket");
        return NULL;
    }

    newPacket->packetID = id;
    newPacket->source = strdup(source);
    if (!newPacket->source) {
        free(newPacket);
        perror("Error duplicating source string for DataPacket");
        return NULL;
    }

    newPacket->destination = strdup(dest);
    if (!newPacket->destination) {
        free(newPacket->source);
        free(newPacket);
        perror("Error duplicating destination string for DataPacket");
        return NULL;
    }

    newPacket->payloadSize = payloadSize;

    return newPacket;
}

void addDataPacketToEvent(NetworkEvent *event, DataPacket *packet) {
    if (!event || !packet) return;

    event->numPackets++;
    packet->next = event->packetList;
    event->packetList = packet;
}

