    pthread_mutex_init(&g_mutex, NULL);
#else
    pthread_mutex_init(&g_mutex, PTHREAD_MUTEX_INITIALIZER);
#endif
}

void lockMutex() {
#if defined(_WIN32) && !defined(__CYGWIN__)
    pthread_mutex_lock(&g_mutex);
#else
    pthread_mutex_lock(&g_mutex);
#endif
}

void unlockMutex() {
#if defined(_WIN32) && !defined(__CYGWIN__)
    pthread_mutex_unlock(&g_mutex);
#else
    pthread_mutex_unlock(&g_mutex);
#endif
}

void initializeAndPopulateEvents(NetworkEvent **events, size_t numEvents) {
    lockMutex();
    for (size_t i = 0; i < numEvents; ++i) {
        time_t timestamp = time(NULL);
        NetworkEvent *event = createNetworkEvent(timestamp, (enum EventType)(i % 2 == 0 ? INCOMING : OUTGOING));
        if (!event) continue;

        for (size_t j = i * 10; j < (i + 1) * 10 && j < numEvents * 10; ++j) {
            DataPacket *packet = createDataPacket(j, "source", "dest", j);
            if (!packet) continue;

            addDataPacketToEvent(event, packet);
        }

        (*events)[i] = event;
    }
    unlockMutex();
}
