#include <sys/stat.h>
#include <unistd.h>
#include <openssl/md5.h>

typedef struct Resource {
    size_t length;
    char *data;
} Resource;

typedef struct Bundle {
    size_t count;
    Resource **resources;
    size_t max_chunk_size;
    MD5_CTX md5_state;
} Bundle;

Bundle *load_resource_bundle(const char *file_path, const char *config_path) {
    struct stat file_stat;
    if (stat(file_path, &file_stat) != 0)
        return NULL;

    FILE *file = fopen(file_path, "rb");
    if (!file)
        return NULL;

    FILE *config = fopen(config_path, "r");
    if (!config) {
        fclose(file);
        return NULL;
    }

    size_t max_chunk_size = 0;
    while (fscanf(config, "%zu", &max_chunk_size) != EOF) {}
    rewind(config);
    fclose(config);

    Bundle *bundle = malloc(sizeof(Bundle));
    bundle->count = 0;
    bundle->resources = NULL;
    bundle->max_chunk_size = max_chunk_size;

    char *buffer = malloc(max_chunk_size);
    if (!buffer) {
        free(bundle);
        fclose(file);
        return NULL;
    }

    Resource *current_resource = NULL;
    while (1) {
        size_t bytes_read = fread(buffer, 1, max_chunk_size, file);
        if (bytes_read == 0)
            break;

        if (!current_resource) {
            current_resource = malloc(sizeof(Resource));
            if (!current_resource) {
                free(buffer);
                fclose(file);
                free(bundle);
                return NULL;
            }
            current_resource->length = bytes_read;
            current_resource->data = malloc(bytes_read);
        } else if (current_resource->length + bytes_read > max_chunk_size) {
            Resource *temp_resource = malloc(sizeof(Resource));
            if (!temp_resource) {
                free(buffer);
                fclose(file);
                free(bundle);
                return NULL;
            }
            temp_resource->length = bytes_read;
            temp_resource->data = malloc(bytes_read);
            memcpy(temp_resource->data, current_resource->data + current_resource->length - max_chunk_size, max_chunk_size);
            current_resource->length -= max_chunk_size;
            memmove(current_resource->data, current_resource->data, current_resource->length);
            temp_resource->data[bytes_read - 1] = '\0';

            bundle->resources = realloc(bundle->resources, (bundle->count + 1) * sizeof(Resource*));
            if (!bundle->resources) {
                free(buffer);
                fclose(file);
                free(temp_resource->data);
                free(temp_resource);
                free(current_resource);
                free(bundle);
                return NULL;
            }
            bundle->resources[bundle->count++] = current_resource;
            current_resource = temp_resource;
        }

        memcpy(current_resource->data + current_resource->length, buffer, bytes_read);
        current_resource->length += bytes_read;

        MD5_Update(&bundle->md5_state, buffer, bytes_read);
    }

    fclose(file);

    bundle->resources = realloc(bundle->resources, bundle->count * sizeof(Resource*));
    if (!bundle->resources) {
        free(current_resource->data);
        free(current_resource);
        free(buffer);
        free(bundle);
        return NULL;
    }
    bundle->resources[bundle->count++] = current_resource;

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &bundle->md5_state);

    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->resources[i]->data);
    }
    free(current_resource);
    free(buffer);

    return bundle;
}
