int generate_and_insert(sqlite3 *db, const char *sql_cmd, size_t n, ...) {
    va_list args;
    sqlite3_stmt *stmt;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    int ret = 0;

    // Allocate memory for PDUs
    pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        fprintf(stderr, "Memory allocation error\n");
        return -1;
    }

    // Initialize the PDUs with random data
    va_start(args, n);
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        pdu[i].rxiit = va_arg(args, uint16_t);
        pdu[i].rnti = va_arg(args, uint32_t);
        pdu[i].crcflag = (rand() % 2) == 0 ? 1 : 0;
    }
    va_end(args);

    // Prepare the SQL command for batching
    if (sqlite3_prepare_v2(db, sql_cmd, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "SQL preparation error: %s\n", sqlite3_errmsg(db));
        ret = -1;
        goto cleanup;
    }

    // Batch the PDUs into groups of 100 for efficient insertion
    size_t batch_size = 100, current_batch = 0;
    while (current_batch * batch_size < n) {
        sqlite3_bind_int(stmt, 1 + 4 * current_batch, pdu[current_batch * batch_size].rxiit);
        sqlite3_bind_int(stmt, 1 + 4 * (current_batch * batch_size) + 1, pdu[current_batch * batch_size].rnti);
        sqlite3_bind_int(stmt, 1 + 4 * (current_batch * batch_size) + 2, pdu[current_batch * batch_size].crcflag);
        current_batch++;
    }

    // Execute the batch of SQL commands and handle any errors
    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "SQL execution error: %s\n", sqlite3_errmsg(db));
        ret = -1;
        goto cleanup;
    }

cleanup:
    // Free the allocated memory and finalize the statement
    if (pdu) free(pdu);
    sqlite3_finalize(stmt);
    return ret;
}
