```javascript
const scripts = new Map();
let currentScript;
let retryCount = 0;

class Script {
  constructor(name, dependencies) {
    this.name = name;
    this.dependencies = dependencies || [];
  }

  async load() {
    if (scripts.has(this.name)) return scripts.get(this.name);

    try {
      const script = await import(`./${this.name}`);
      scripts.set(this.name, script);
      resolveDependencies(script);
      return script;
    } catch (error) {
      console.error(`Failed to load script ${this.name}:`, error);
      throw error;
    }
  }

  async execute() {
    try {
      await this.load().then(() => scripts.get(this.name).default());
    } catch (error) {
      if (retryCount < 3) {
        retryCount++;
        console.error(`Script ${this.name} execution failed. Retrying...`);
        return this.execute();
      } else {
        console.error(`Script ${this.name} failed permanently. Marking as unavailable.`);
        scripts.get(this.name).unavailable = true;
      }
    }
  }
}

function resolveDependencies(module) {
  for (const dependency of module.dependencies) {
    if (!scripts.has(dependency)) {
      currentScript = new Script(dependency);
      queue.push(currentScript);
    }
  }
}

const queue = [];

function init() {
  if (queue.length === 0) return;

  currentScript = queue.shift();

  currentScript.load().then(() => currentScript.execute()).catch((error) => {
    console.error(`Initialization error:`, error);
    currentScript = queue[0] || null;
    init();
  });
}

// External update and management of dependencies
function updateDependency(name, newModule) {
  scripts.set(name, newModule);
  resolveDependencies(newModule);
}

init();
