    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = head;
    head = new_node;
}

NFAPI_CRC_INDICATION_PDU_T* get(size_t index) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    for (size_t i = 0; i < index && current != NULL; ++i)
        current = current->next;

    if (current == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* res = &current->data;
    pthread_mutex_unlock(&list_mutex);
    return res;
}

void free_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
        current = head;
    }

    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* filter(uint32_t rnti) {
    Node* current = head;
    Node* filtered_head = NULL;
    Node* filtered_tail = NULL;

    pthread_mutex_lock(&list_mutex);

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (!filtered_head) {
                filtered_head = current;
                filtered_tail = filtered_head;
            } else {
                filtered_tail->next = current;
                filtered_tail = current;
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    if (!filtered_head) return NULL;

    Node* temp = head;
    while (temp && temp != filtered_head) {
        temp = temp->next;
    }
    if (temp) temp->next = filtered_head->next;

    NFAPI_CRC_INDICATION_PDU_T* res = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * filtered_tail ? 1 : 0);
    if (res) memcpy(res, filtered_head, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (filtered_tail ? filtered_tail->next ? filtered_tail->next - filtered_head + 1 : filtered_tail + 1 : 0));
    free_list();

    return res;
}
