    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_BUFFER_T;

NFAPI_CRC_INDICATION_BUFFER_T* nfapi_crc_indication_buffer_create(size_t size) {
    if (size == 0) return NULL;

    NFAPI_CRC_INDICATION_BUFFER_T* buffer = malloc(sizeof(NFAPI_CRC_INDICATION_BUFFER_T));
    buffer->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    buffer->capacity = size;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);

    return buffer;
}

void nfapi_crc_indication_buffer_destroy(NFAPI_CRC_INDICATION_BUFFER_T* buffer) {
    if (!buffer) return;

    free(buffer->data);
    free(buffer);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_buffer_get(NFAPI_CRC_INDICATION_BUFFER_T* buffer, size_t index) {
    if (!buffer || index >= buffer->capacity) return NULL;

    pthread_mutex_lock(&buffer->mutex);
    NFAPI_CRC_INDICATION_PDU_T* element = &buffer->data[index];
    pthread_mutex_unlock(&buffer->mutex);

    return element;
}

void nfapi_crc_indication_buffer_push(NFAPI_CRC_INDICATION_BUFFER_T* buffer, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!buffer || buffer->count >= buffer->capacity) return;

    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count < buffer->capacity) {
        buffer->data[buffer->count] = data;
        buffer->count++;
