['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Threading;
using System.Threading.Tasks;
using log4net;

public class ThemeCache
{
    private static readonly ILog Logger = LogManager.GetLogger(typeof(ThemeCache));
    private readonly string _themeDirectory = "Themes";
    private readonly Dictionary<string, Bitmap> _themeCache = new Dictionary<string, Bitmap>();

    public async Task<Bitmap> GetThemeAsync(string themeName)
    {
        if (!Directory.Exists(_themeDirectory))
            Directory.CreateDirectory(_themeDirectory);

        var xmlFilePath = Path.Combine(_themeDirectory, $"{themeName}.xml");

        try
        {
            using (var reader = XmlReader.Create(xmlFilePath))
            {
                reader.MoveToContent();

                if (!reader.IsStartElement())
                    throw new Exception($"Invalid XML structure in '{xmlFilePath}'");

                var themeElement = reader.ReadSubtree().SelectSingleNode("/Theme");

                if (themeElement == null)
                    Logger.Warn($"No theme element found for theme '{themeName}' in '{xmlFilePath}'");
                else if (themeElement.HasAttributes && themeElement.GetAttribute("ambigous") == "true")
                    throw new AmbiguousThemeException($"Ambiguous theme matching name '{themeName}' in '{xmlFilePath}'");
                else if (themeElement.HasAttributes && themeElement.GetAttribute("name") != themeName)
                    throw new Exception($"Invalid theme name in '{xmlFilePath}'. Expected '{themeName}', found '{themeElement.GetAttribute("name")}'");

                lock (_themeCache)
                {
                    Bitmap currentTheme;
                    if (_themeCache.TryGetValue(themeName, out currentTheme))
                    {
                        // Theme is cached and recyclable
                        if (currentTheme.IsDisposed)
                        {
                            _themeCache[themeName] = null;
                        }
                        else
                        {
                            currentTheme.Dispose();
                            _themeCache[themeName] = null;
                        }
                    }

                    XmlNode bitmapNode = themeElement.SelectSingleNode("/Bitmap");

                    if (bitmapNode == null)
                        throw new Exception($"No Bitmap element found for theme '{themeName}' in '{xmlFilePath}'");

                    string bitmapPath = bitmapNode.Attributes["path"].Value;
                    Bitmap newTheme = new Bitmap(bitmapPath);
                    _themeCache[themeName] = newTheme;

                    return newTheme;
                }
            }
        }
        catch (Exception ex)
        {
            Logger.Error($"Error while loading theme '{themeName}': {ex.Message}", ex);
            throw; // Re-throw the exception to be handled by the calling code
        }
    }

    public class AmbiguousThemeException : Exception
    {
        public AmbiguousThemeException(string message) : base(message) { }
    }
}
```
