typedef struct LTE_DL_FRAME {
    uint32_t valid_frame_number;
    uint32_t subframe_number;
    void* uci_buffer; // dynamically allocated buffer for UCI
    pthread_mutex_t uci_mutex;
    struct LTE_DL_FRAME *next;
} LTE_DL_FRAME;

// Global variables for managing the dynamic array of frames
LTE_DL_FRAME* head = NULL;
pthread_mutex_t frames_mutex = PTHREAD_MUTEX_INITIALIZER;

void lte_dl_frame_init(LTE_DL_FRAME** frame, uint32_t valid_frame_number, uint32_t subframe_number) {
    *frame = malloc(sizeof(LTE_DL_FRAME));
    if (!*frame) {
        // Handle allocation failure gracefully
        return;
    }

    (*frame)->valid_frame_number = valid_frame_number;
    (*frame)->subframe_number = subframe_number;
    (*frame)->uci_buffer = NULL;
    pthread_mutex_init(&(*frame)->uci_mutex, NULL);
    (*frame)->next = NULL;
}

void lte_dl_frame_add(LTE_DL_FRAME** head, LTE_DL_FRAME* frame) {
    pthread_mutex_lock(&frames_mutex);

    if (!*head) {
        *head = frame;
    } else {
        LTE_DL_FRAME* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = frame;
    }

    pthread_mutex_unlock(&frames_mutex);
}

void lte_dl_frame_remove(LTE_DL_FRAME** head, LTE_DL_FRAME* frame) {
    pthread_mutex_lock(&frames_mutex);

    if (*head == frame) {
        *head = frame->next;
    } else {
        LTE_DL_FRAME* current = *head;
        while (current && current->next != frame) {
            current = current->next;
        }

        if (!current || !current->next) {
            // Frame not found, handle error gracefully
            pthread_mutex_unlock(&frames_mutex);
            return;
        }

        current->next = frame->next;
    }

    free(frame->uci_buffer);
    free(frame);
    pthread_mutex_unlock(&frames_mutex);
}

