static void generate_crc_flag(CRC_INDICATION_REL8_TAG* tag) {
    // Generate random CRC flag value using the current time as seed
    unsigned long seed = time(NULL);
    unsigned char crc = (unsigned char)(seed % 256);
    tag->crcflag = (crc >> 4) ^ ((~crc & 0xF) << 4);
}

static bool validate_crc_flag(const CRC_INDICATION_REL8_TAG* tag) {
    // Validate CRC flag strength against predefined criteria
    return (tag->crcflag == (tag->crcflag >> 4));
}

static void handle_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

static NFAPI_LTE_UE_CONTEXT** init_ue_context_array(size_t initial_size) {
    NFAPI_LTE_UE_CONTEXT** ue_ctx = malloc(initial_size * sizeof(NFAPI_LTE_UE_CONTEXT*));
    if (!ue_ctx) handle_error("Memory allocation failed for UE context array");

    for (size_t i = 0; i < initial_size; ++i) {
        ue_ctx[i] = calloc(1, sizeof(NFAPI_LTE_UE_CONTEXT));
        if (!ue_ctx[i]) handle_error("Memory allocation failed for UE context");
    }

    return ue_ctx;
}

static void resize_ue_context_array(NFAPI_LTE_UE_CONTEXT** ue_ctx, size_t new_size) {
    NFAPI_LTE_UE_CONTEXT** tmp = realloc(ue_ctx, new_size * sizeof(NFAPI_LTE_UE_CONTEXT*));
    if (!tmp) handle_error("Memory allocation failed for resized UE context array");

    memmove(tmp, ue_ctx, initial_size * sizeof(NFAPI_LTE_UE_CONTEXT*));
    free(ue_ctx);
    ue_ctx = tmp;

    for (size_t i = initial_size; i < new_size; ++i) {
        ue_ctx[i] = calloc(1, sizeof(NFAPI_LTE_UE_CONTEXT));
        if (!ue_ctx[i]) handle_error("Memory allocation failed for additional UE context");
    }
