    $accessTokenSessionKey = 'access_token';

    if (!isset($_SESSION[$accessTokenSessionKey])) {
        // OAuth 2.0 authentication logic
        $authResponse = getOAuth2AccessToken($clientId, $clientSecret);
        $_SESSION[$accessTokenSessionKey] = $authResponse['access_token'];
    }

    $apiBaseUrl = 'https://example-api.com/v1';
    $userInfoUrl = "$apiBaseUrl/user";
    $requestLimitPerMinute = 5;
    $requestIntervalInSeconds = 60 / $requestLimitPerMinute;

    $rateLimiter = new RateLimiter($requestLimitPerMinute, $requestIntervalInSeconds);
    $rateLimiter->addToken();

    $httpClient = new HttpClient();
    $userInfoResponse = $httpClient->get($userInfoUrl, [
        'headers' => [
            'Authorization' => "Bearer {$_SESSION[$accessTokenSessionKey]}"
        ]
    ]);

    if (!$rateLimiter->checkToken()) {
        usleep($requestIntervalInSeconds * 1000000); // Sleep for the remaining time in microseconds
    }

    $userData = json_decode($userInfoResponse->getBody(), true);

    $attackSelectionMutex = new Mutex();
    $cooldownTimer = new CooldownTimer(9);

    while (true) {
        if (!$cooldownTimer->isOnCooldown()) {
            $attackSelectionMutex->lock();

            if ($cooldownTimer->isOnCooldown()) { // In case lock was acquired during cooldown period
                $attackSelectionMutex->unlock();
                continue;
            }

            $selectedAttack = selectAttack($userData);
            populatePDUs($selectedAttack, $userData);

            $cooldownTimer->start();
            $attackSelectionMutex->unlock();
        }

        usleep(100000); // Sleep for 0.1 seconds to allow other processes to run
    }
}

class RateLimiter {
    private $limit;
    private $interval;
    private $tokens = [];

    public function __construct($limit, $interval) {
        $this->limit = $limit;
        $this->interval = $interval;
    }

    public function addToken() {
        array_shift($this->tokens);
        $this->tokens[] = microtime(true);
    }

    public function checkToken() {
        if (empty($this->tokens)) {
            return true;
        }

        $currentTime = microtime(true);
        $lastRequestTime = array_pop($this->tokens);

        return ($currentTime - $lastRequestTime) >= $this->interval;
    }
}

class CooldownTimer {
    private $cooldownDurationInSeconds;
    private $startTime;

    public function __construct($cooldownDurationInSeconds) {
        $this->cooldownDurationInSeconds = $cooldownDurationInSeconds;
    }

    public function start() {
        $this->startTime = microtime(true);
    }

    public function isOnCooldown() {
        if (!$this->startTime) {
            return false;
        }

        $elapsedTime = microtime(true) - $this->startTime;
        return $elapsedTime < $this->cooldownDurationInSeconds;
    }
}

class Mutex {
    private $lock = 0;

    public function lock() {
        flock(STDIN, LOCK_EX);
        $this->lock++;
    }

    public function unlock() {
        if ($this->lock > 0) {
            $this->lock--;
            flock(STDIN, LOCK_UN);
        }
    }
}

