void add_node(RX_UE_INFORMATION_TAG tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_rel8, CRC_INDICATION_REL15_TAG crc_rel15, uint8_t crcflag) {
    pthread_mutex_lock(&list_mutex);
    while (num_nodes >= BUFFER_SIZE && !tail->next) { // If buffer is full and tail has no next node, remove the oldest node
        if (!head) break;
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = temp->next;
        num_nodes--;
        free(temp);
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) { // Handle memory allocation errors
        fprintf(stderr, "Error: Out of memory\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    new_node->rnti = rnti % MAX_RNTI;
    new_node->tag = tag;
    new_node->crc_rel8 = crc_rel8;
    new_node->crc_rel15 = crc_rel15;
    new_node->crcflag = crcflag;

    pthread_mutex_init(&new_node->mutex, NULL);
    new_node->next = NULL;

    if (!head) { // If the list is empty
        head = tail = new_node;
    } else { // Add to the end of the list
        tail->next = new_node;
        tail = new_node;
    }

    num_nodes++;
    pthread_mutex_unlock(&list_mutex);

    if (callback) callback(new_node);
}

