static list_node_t *tail = NULL;

void init_list(size_t max_entries) {
    if (max_entries > 100000 || max_entries == 0) {
        return; // Invalid parameters, do not initialize the list.
    }

    this->max_entries = max_entries;
    mmap(NULL, max_entries * sizeof(list_node_t), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    pthread_mutex_lock(&mutex);
    head = (list_node_t *)mmap(NULL, sizeof(list_node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
    tail = head;
    pthread_mutex_unlock(&mutex);
