void enqueue(const NFAPI_CRFC_INDICATION_PDU_T *data) {
    if (data->crc > 65535 || data->crc < 0) {
        return; // Invalid CRC value, do not enqueue the data.
    }

    pthread_mutex_lock(&mutex);
    list_node_t *new_node = (list_node_t *)mmap(NULL, sizeof(list_node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);

    if (!new_node) { // Allocation failure, handle gracefully and continue operation without data loss.
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = *data;
    new_node->next = NULL;

    if (!head) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    pthread_mutex_unlock(&mutex);
}

size_t get_allocated_entries() {
