typedef void (*LogFunc)(const char* message);

struct LoggingData {
    LogFunc log_func;
    pthread_mutex_t mutex;
};

void init_logging(LogFunc log_func, struct LoggingData* logging_data) {
    logging_data->log_func = log_func;
    pthread_mutex_init(&logging_data->mutex, NULL);
}

void log(struct LoggingData* logging_data, const char* message) {
    pthread_mutex_lock(&logging_data->mutex);
    if (logging_data->log_func != NULL) {
        logging_data->log_func(message);
    }
    pthread_mutex_unlock(&logging_data->mutex);
}

struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock* next;
};

void* custom_malloc(size_t size) {
    if (MAX_MEMORY <= get_total_memory_usage()) {
        log(global_logging, "Error: Out of memory");
        return NULL;
    }
    struct MemBlock* mem_block = malloc(sizeof(struct MemBlock));
    if (!mem_block) {
        log(global_logging, "Error: Failed to allocate memory for memory block structure");
        return NULL;
    }
    memset(mem_block, 0, sizeof(struct MemBlock));
    mem_block->size = size;
    mem_block->data = malloc(size);
    if (!mem_block->data) {
        log(global_logging, "Error: Failed to allocate memory for data");
        free(mem_block);
        return NULL;
    }
    return mem_block->data;
}

void custom_free(void* ptr) {
    if (!ptr) {
        return;
    }
    struct MemBlock* current = global_memory_list;
    struct MemBlock* previous = NULL;
    while (current != NULL && current->data != ptr) {
        previous = current;
        current = current->next;
    }
    if (!current) {
        log(global_logging, "Error: Failed to find allocated memory block");
        return;
    }
    if (previous == NULL) {
        global_memory_list = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

void garbage_collect() {
    struct MemBlock* current = global_memory_list;
    while (current != NULL) {
        struct MemBlock* next = current->next;
        if (get_total_memory_usage() > MAX_MEMORY * 0.8) { // Perform garbage collection when memory usage exceeds 80% of the limit
            void* temp_data = current->data;
            free(current);
            current->data = temp_data;
            current->size = 0;
            current = next;
        } else {
            break;
        }
    }
}

struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
};

struct ListData {
    struct ListNode* head;
    size_t num_nodes;
    pthread_mutex_t mutex;
};

void init_list(struct ListData* list) {
    list->head = NULL;
    list->num_nodes = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(struct ListData* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (MAX_STRUCTURES <= list->num_nodes) {
        garbage_collect();
    }
    struct ListNode* new_node = malloc(sizeof(struct ListNode));
    if (!new_node) {
        log(global_logging, "Error: Failed to allocate memory for new node");
        return -1;
    }
    memset(new_node, 0, sizeof(struct ListNode));
    new_node->data = data;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        struct ListNode* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->num_nodes++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_from_list(struct ListData* list) {
    if (list->head == NULL) {
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }
    pthread_mutex_lock(&list->mutex);
    struct ListNode* current = list->head;
    list->head = current->next;
    NFAPI_CRC_INDICATION_PDU_T data = current->data;
    free(current);
    list->num_nodes--;
    pthread_mutex_unlock(&list->mutex);
    return data;
}
