#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <sys/time.h>

#define MAX_ACTIVITIES 100

typedef struct UserSessionLog {
    uint64_t sessionID;
    uint64_t timestamps[MAX_ACTIVITIES];
    size_t activitiesCount;
    double sessionDuration;
} UserSessionLog;

typedef struct SessionManager {
    UserSessionLog** sessions;
    size_t capacity;
    size_t size;
    time_t timeout;
} SessionManager;

void initSessionManager(SessionManager* manager, time_t timeout) {
    manager->timeout = timeout;
    manager->capacity = 16;
    manager->size = 0;
    manager->sessions = malloc(manager->capacity * sizeof(UserSessionLog*));
}

void addUserSessionLog(SessionManager* manager, UserSessionLog log) {
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        UserSessionLog** temp = realloc(manager->sessions, manager->capacity * sizeof(UserSessionLog*));
        if (!temp) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }
        manager->sessions = temp;
    }

    manager->sessions[manager->size++] = malloc(sizeof(UserSessionLog));
    if (!manager->sessions[manager->size - 1]) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    *manager->sessions[manager->size - 1] = log;
}

void cleanUpExpiredSessions(SessionManager* manager) {
    time_t now = time(NULL);
    size_t i;
    for (i = 0; i < manager->size; ++i) {
        if (now - manager->sessions[i]->timestamps[0] > manager->timeout * 60) {
            free(manager->sessions[i]);
            --manager->size;
            for (size_t j = i; j < manager->size; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
        }
    }
}

double calculateSessionDuration(UserSessionLog log) {
    if (log.activitiesCount == 0) return 0;

    struct timeval start, end;
    gettimeofday(&start, NULL);
    gettimerspec_np(&start, &end);
    timersub(&end, &start, &end);
    double currentTimestamp = (double)end.tv_sec + ((double)end.tv_nsec / 1000000000);

    long timestampDiff;
    for (size_t i = 1; i < log.activitiesCount; ++i) {
        timestampDiff = log.timestamps[i] - log.timestamps[i - 1];
        if (timestampDiff <= 0 || (double)timestampDiff / 1000 > currentTimestamp - log.timestamps[i - 1]) {
            return NAN; // Return NaN to indicate invalid session duration
        }
    }

    double totalDuration = 0;
    for (size_t i = 0; i < log.activitiesCount; ++i) {
        totalDuration += (double)(log.timestamps[i] - log.timestamps[0]) / 1000;
    }

    return totalDuration / 60;
}
```

