        var rndIndex = UnityEngine.Random.Range(0, range);
        var index = (int)MathF.Clamp((_minValue - _maxValue + 2 * rndIndex) / (float)(range + 2), _minValue, _maxValue);

        return index;
    }

    public int GetRandomIntInclusive() => RandomInt((int)_minValue, (int)_maxValue + 1);
    public int GetRandomIntExclusive() => RandomInt((int)_minValue, (int)_maxValue);

