}

public class CustomDistribution : IDistribution
{
    public Func<Random, double> GenerateValue;
    public string ExternalSource { get; set; }
    public bool IsReady { get; private set; }

    public CustomDistribution(Func<Random, double> generateValue, string externalSource)
