}

public interface IValueGenerator
{
    double Min { get; set; }
    double Max { get; set; }
    IDistribution Distribution { get; set; }
    Random Seed { get; set; }
    void SetSeed(int seed);
    double Generate();
    Task<double> GenerateAsync(CancellationToken cancellationToken = default);
}

public class DynamicValueGenerator : IValueGenerator
{
    private readonly ILogger _logger;
    private IDistribution _distribution;
    private Random _seed;
    private bool _isDisposed;

    public double Min { get; set; }
    public double Max { get; set; }
    public IDistribution Distribution { get; set; }
    public Random Seed { get => _seed; set => SetSeed(value); }

    public DynamicValueGenerator(ILogger<DynamicValueGenerator> logger)
    {
        _logger = logger;
        Reset();
    }

    private void SetSeed(int seed)
    {
        _seed = new Random(seed);
    }

    public double Generate()
    {
        if (_distribution == null || !_distribution.IsReady)
            throw new InvalidOperationException("Distribution is not ready for value generation.");

        return _distribution.GenerateValue(_seed);
    }

    public async Task<double> GenerateAsync(CancellationToken cancellationToken = default)
    {
        if (_distribution == null || !_distribution.IsReady)
            throw new InvalidOperationException("Distribution is not ready for value generation.");

        return await Task.Run(() => _distribution.GenerateValue(_seed), cancellationToken);
    }

    public void Reset()
    {
        _logger.LogInformation("Resetting generator to default state");
        _distribution = null;
        _isDisposed = false;
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_isDisposed)
        {
            if (disposing)
                _distribution?.Dispose();

            _isDisposed = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public override string ToString()
    {
        var builder = new StringBuilder();

        builder.AppendLine($"Generator state:");
        builder.AppendFormat(" - Seed: {0}", _seed?.GetHashCode());
        builder.AppendFormat(" - Last generated value: {0}", _distribution?.GenerateValue(_seed));
        builder.AppendFormat(" - Current range settings: Min={0}, Max={1}", Min, Max);
        builder.AppendFormat(" - Distribution type: {0}", _distribution?.GetType().Name);

        if (_distribution is CustomDistribution custom)
            builder.AppendFormat("\n - External source: {0}", custom.ExternalSource);

        return builder.ToString();
    }
}
