struct TrafficFlowStats {
    int flowID;
    std::vector<int> packetDurations; // in microseconds
    double averageThroughput; // in kilobits per second
};

class Logger {
public:
    enum class LogLevel { INFO, WARN, ERROR };
    void log(LogLevel level, const TrafficFlowStats& stats) {
        // Integrate with your external logging service here.
    }
};

std::mutex flowDataMutex;
std::vector<TrafficFlowStats> flowData;
const int maxTotalPackets = 1000000; // Maximum total packet count across all flows
const int minActiveThreads = 4;
const int maxActiveThreads = 16;
std::atomic_int activeThreadCount(0);

void addPacket(int flowID, int packetDuration) {
    std::lock_guard<std::mutex> lock(flowDataMutex);
    auto it = std::find_if(flowData.begin(), flowData.end(), [flowID](const TrafficFlowStats& stats) { return stats.flowID == flowID; });
    if (it != flowData.end()) {
        it->packetDurations.push_back(packetDuration);
    } else {
        TrafficFlowStats newFlow{ flowID, { packetDuration }, 0 };
        flowData.push_back(newFlow);
    }

    if (activeThreadCount < maxActiveThreads && std::distance(flowData.cbegin(), it) >= flowData.cbegin()) {
        activeThreadCount++;
    }
}

void calculateStats() {
    std::lock_guard<std::mutex> lock(flowDataMutex);
    for (auto& stats : flowData) {
        if (!stats.packetDurations.empty()) {
            int packetCount = static_cast<int>(stats.packetDurations.size());
            auto totalDuration = std::accumulate(stats.packetDurations.begin(), stats.packetDurations.end(), 0);
            double averageDuration = static_cast<double>(totalDuration) / packetCount;
            double throughput = (averageDuration * 1e6) / 8; // Assuming packets are 8 bytes each
            if (throughput > stats.averageThroughput) {
                Logger::LogLevel logLevel = throughput > 1000 ? Logger::LogLevel::ERROR : Logger::LogLevel::WARN;
                Logger logger;
                logger.log(logLevel, stats);
            }
            stats.averageThroughput = throughput;
            if (packetCount >= maxTotalPackets) {
                flowData.erase(std::remove_if(flowData.begin(), flowData.end(), [packetCount](const TrafficFlowStats& stats) {
                    return stats.packetDurations.size() > packetCount;
                }), flowData.end());
            }
        }
    }
}

void processPackets(std::function<void(int, int)> addPacketFunc) {
    while (true) {
        // Implement anomaly detection and dynamic max packet count adjustment here.
        auto packet = getNextPacket(); // Assume this function returns the next packet to be processed.
        if (!packet) break;
        addPacketFunc(*packet.first, *packet.second);
    }
}

void startProcessingThreads() {
    std::vector<std::thread> threads;
    for (int i = 0; i < minActiveThreads; ++i) {
        threads.push_back(std::thread(processPackets, &addPacket));
    }

    auto lambda = [&]() {
        calculateStats();
        if (activeThreadCount > minActiveThreads) activeThreadCount--;
    };

    std::thread periodicTaskThread(lambda);

    for (; activeThreadCount < maxActiveThreads; ++i) {
        threads.push_back(std::thread(processPackets, &addPacket));
    }

    for (auto& thread : threads) {
        thread.join();
    }
    periodicTaskThread.join();
}
```

