using System;
using System.Collections.Generic;
using System.Runtime.Serialization;
using System.Text;
using System.Threading;
using log4net;

[DataContract]
public class ConfigurableRandomGenerator
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(ConfigurableRandomGenerator));

    [DataMember]
    private Random _random;

    [DataMember]
    private int _min;

    [DataMember]
    private int _max;

    [DataMember]
    private bool _isInclusive;

    [DataMember]
    private CancellationTokenSource _cancellationTokenSource;

    [DataMember]
    private Queue<int> _numberSequence;

    public ConfigurableRandomGenerator(int min, int max, bool isInclusive)
    {
        _min = min;
        _max = max;
        _isInclusive = isInclusive;
        _random = new Random();
        _cancellationTokenSource = new CancellationTokenSource();
        _numberSequence = new Queue<int>();
    }

    public int NextInt(CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        if (_numberSequence.Count > 0)
        {
            var number = _numberSequence.Dequeue();
            _numberSequence.Enqueue(number);
            return number;
        }

        int range;
        if (_isInclusive)
        {
            range = _max - _min + 1;
        }
        else
        {
            range = _max - _min;
        }

        var randomValue = _random.Next(range);

        Log.DebugFormat("Generated integer: {0}", randomValue + (_min - 1));

        return randomValue + _min;
    }

    public float NextFloat(CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        if (_numberSequence.Count > 0)
        {
            var number = _numberSequence.Dequeue();
            _numberSequence.Enqueue(number);
            return (float)number;
        }

        float range;
        if (_isInclusive)
        {
            range = (_max - _min + 1) / 10f;
        }
        else
        {
            range = (_max - _min) / 10f;
        }

        var randomValue = (float)_random.NextDouble() * range + _min - range / 2;

        Log.DebugFormat("Generated float: {0}", randomValue);

        return randomValue;
    }

    public IEnumerable<int> GenerateSequence(int count, CancellationToken token)
    {
        var sequence = new List<int>();
        for (var i = 0; i < count; i++)
        {
            if (token.IsCancellationRequested) yield break;
            sequence.Add(NextInt(token));
        }
        return sequence;
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

