public class StateLoader {
 private static final Logger log = LoggerFactory.getLogger(StateLoader.class);
 private static final Map<String, Object> cache = new WeakHashMap<>();
 private static final int CACHE_SIZE = System.getProperty("cache.size", "100").parseInt();
 private static final String FILE_PATH = System.getProperty("state.file", "path/to/default/state.bin");

 public static <T extends State> T loadState(Class<T> clazz) {
 try (FileInputStream fis = new FileInputStream(FILE_PATH);
 InputStream buffer = new BufferedInputStream(fis, CACHE_SIZE * 1024)) {
 Kryo kryo = new Kryo();
 kryo.setReferencedClasses(new Class<?>[]{clazz});
 Input input = new BufferedInput(buffer);
 Object object = kryo.readObjectFromInputStreamWithClass(input, clazz);
 if (cache.containsKey(FILE_PATH)) {
 cache.put(FILE_PATH, object);
 }
 return clazz.cast(object);
 } catch (IOException | ClassNotFoundException e) {
 log.error("Failed to load state from file: {}", e.getMessage(), e);
 throw new RuntimeException("State could not be loaded", e);
 }
 }
}

public interface State {
 // Add common state object properties and methods here
}

public class MoSTState implements State {
 // Implement MoSTState class properties and methods here
}

