public class CustomPasswordValidator : PasswordValidator<ApplicationUser>
{
    public CustomPasswordValidator(UserManager<ApplicationUser> userManager) : base(userManager) { }

    protected override void CheckPasswordStrength(string password, string userName, out IdentityErrorCollection errors)
    {
        if (password.Length < 8)
            errors = new IdentityErrorCollection { new IdentityError { Code = "PasswordTooShort", Description = "Password must be at least 8 characters." } };

        // Check for common patterns and complexity rules here...

        errors = base.CheckPasswordStrength(password, userName);
