// RateLimiter.cs
public class RateLimiter : IRateLimiter
{
    private readonly IMemoryCache _cache;

    public RateLimiter(IMemoryCache cache) => _cache = cache;

    public Task<bool> GetRequestCountAsync(string key, CancellationToken cancellationToken)
    {
        return _cache.GetOrCreateAsync(key, (entry) => Task.FromResult((int?)1), new MemoryCacheEntryOptions() { SlidingExpiration = TimeSpan.FromMinutes(5) });
    }

    public Task IncrementRequestCountAsync(string key, CancellationToken cancellationToken)
    {
        return _cache.GetOrCreateAsync(key, (entry) =>
        {
            int currentCount = (int)entry.Value ?? 0;
            if (currentCount >= 10)
                throw new TooManyRequestsException("Too many requests.");

            return Task.FromResult((object)(currentCount + 1));
        }, new MemoryCacheEntryOptions() { SlidingExpiration = TimeSpan.FromMinutes(5) });
    }
}
