class CRCFLAG_COLLISION_DETECTOR {
    std::vector<bool> flags;
public:
    bool check(int index) const {
        return flags[index];
    }

    void set(int index, bool flag) {
        flags[index] = flag;
        for (size_t i = index + 1; i < flags.size(); ++i)
            if (!flags[i])
                flags[i] = !flag;
    }
};

std::mutex mtx;
CRCFLAG_COLLISION_DETECTOR collDetector;

class NFAPI_CRC_INDICATION_PDU_T {
    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int) {
        ar & rxUEInformationTag & rnti & crcIndicationRel8Tag.crCFlag;
    }

    RX_UE_INFORMATION_TAG rxUEInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
public:
    NFAPI_CRC_INDICATION_PDU_T() { }
};

struct CRC_INDICATION_REL8_TAG {
    bool crCFlag;
};

class Generator {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> dataList;
    int maxLimit;
    CRCFLAG_COLLISION_DETECTOR collisionDetector;
public:
    Generator(int m) : maxLimit(m) { }

    void generateData(int n) {
        std::priority_queue<int, std::vector<int>, std::greater<int>> freeFlags;
        for (size_t i = 0; i < maxLimit; ++i)
            freeFlags.push(i);

        int currentIndex = 0;
        for (int i = 0; i < n && !freeFlags.empty(); ++i) {
            collDetector.set(currentIndex, true);
            dataList.emplace_back(NFAPI_CRC_INDICATION_PDU_T());
            auto it = freeFlags.top();
            freeFlags.pop();
            dataList.back().rxUEInformationTag = (RX_UE_INFORMATION_TAG)it;
            dataList.back().crcIndicationRel8Tag.crCFlag = collDetector.check(currentIndex);
            currentIndex = (currentIndex + 1) % maxLimit;
            if (!freeFlags.empty()) {
                collDetector.set(currentIndex, it != freeFlags.top());
                freeFlags.push(currentIndex);
            }
        }
    }

    void serializeAndSave(const std::string & filename) {
        std::ofstream outFile(filename, std::ios_base::binary);
        boost::serialization::save(outFile, dataList, boost::serialization::make_nvp("Data", dataList));
    }
};
