using System;
using System.Collections.Concurrent;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;

public abstract class CustomRandomGenerator : IDisposable
{
    private readonly Random _random;
    private readonly ConcurrentDictionary<(Type, Tuple<double, double>), object> _cache;

    protected CustomRandomGenerator([CallerMemberName] string seedSource = "")
    {
        var seedValue = int.Parse(System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream($"{GetType()}.seed").ReadToEndAsString());
        _random = new Random((int)Math.Abs(hashCode(seedSource) ^ seedValue));
        _cache = new ConcurrentDictionary<(Type, Tuple<double, double>), object>();
    }

    private static int hashCode(string s) => (s != null ? s.GetHashCode() : 0);

    protected abstract Type DistributionType { get; }

    public void Dispose()
    {
        _random.Dispose();
        // Release any other unmanaged resources here if needed.
    }

    public int NextInt(int min, int max)
    {
        var key = (DistributionType, Tuple.Create((double)min, (double)max));
        return _cache.GetOrAdd(key, CreateCacheItem).AsParallel().Select(x => (int)x).First();
    }

    public float NextFloat(float min, float max)
    {
        var key = (DistributionType, Tuple.Create((double)min, (double)max));
        return _cache.GetOrAdd(key, CreateCacheItem).AsParallel().Select(x => (float)x).First();
    }

    public async Task<int> NextIntAsync(int min, int max)
    {
        var key = (DistributionType, Tuple.Create((double)min, (double)max));
        return await _cache.GetOrAddAsync(key, CreateCacheItem).ConfigureAwait(false);
    }

    public async Task<float> NextFloatAsync(float min, float max)
    {
        var key = (DistributionType, Tuple.Create((double)min, (double)max));
        return await _cache.GetOrAddAsync(key, CreateCacheItem).ConfigureAwait(false);
    }

    private object CreateCacheItem((Type, Tuple<double, double>) key)
    {
        var random = Thread.VolatileRead(_random); // Use volatile to ensure atomicity in multi-threaded scenarios.
        return Activator.CreateInstance(DistributionType, random, key.Item1.Item2.Item1, key.Item1.Item2.Item2);
    }

    public override string ToString()
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"CustomRandomGenerator:");
        sb.AppendLine($"\tSeed: {_random.NextState()}");
        if (DistributionType != null)
            sb.AppendLine($"\tDistributionType: {DistributionType.Name}");
        sb.AppendLine($"\tMin: -");
        sb.AppendLine($"\tMax: -");
        return sb.ToString();
    }
}
