typedef struct _list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct _list_node *next;
} list_node;

typedef struct _dynamic_list {
    list_node *head;
    size_t size;
    pthread_mutex_t lock;
} dynamic_list;

static void init_list(dynamic_list* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    free(node);
}

static void destroy_list(dynamic_list* list) {
    list_node* current = list->head;
    while (current != NULL) {
        list_node* temp = current;
        current = current->next;
        free_node(temp->data);
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

static list_node* new_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    list_node* node = (list_node*)malloc(sizeof(list_node));
    if (!node) {
        perror("Memory allocation failure");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

static void insert(dynamic_list* list, size_t index, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (index >= MAX_ELEMENTS || index < 0) {
        perror("Invalid index");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (index == list->size) {
        list->head = new_node(element);
    } else {
        list_node *current = list->head;
        for (size_t i = 0; i < index; ++i) {
            current = current->next;
        }
        list_node* new_node = new_node(element);
        new_node->next = current->next;
        current->next = new_node;
    }
    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

static void remove(dynamic_list* list, size_t index) {
    if (index >= MAX_ELEMENTS || index < 0) {
        perror("Invalid index");
        return;
    }
    pthread_mutex_lock(&list->lock);
    if (list->size == 0) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (index == 0) {
        list_node *current = list->head;
        list->head = current->next;
        free_node(current->data);
        free(current);
    } else {
        list_node *current = list->head;
        for (size_t i = 0; i < index - 1; ++i) {
            current = current->next;
        }
        list_node* temp = current->next;
        current->next = temp->next;
        free_node(temp->data);
        free(temp);
    }
    --list->size;
    pthread_mutex_unlock(&list->lock);
}

static void update_crcflag(dynamic_list* list, size_t index, bool new_value) {
    if (index >= MAX_ELEMENTS || index < 0) {
        perror("Invalid index");
        return;
    }
    pthread_mutex_lock(&list->lock);
    if (list->size == 0) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list_node *current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
        if (!current) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    current->data->crc_indication.crcflag = new_value;
    pthread_mutex_unlock(&list->lock);
}

static bool get_crcflag(dynamic_list* list, size_t index) {
    if (index >= MAX_ELEMENTS || index < 0) {
        perror("Invalid index");
        return false;
    }
    pthread_mutex_lock(&list->lock);
    if (list->size == 0) {
        bool result = false;
        pthread_mutex_unlock(&list->lock);
        return result;
    }
    list_node *current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
        if (!current) {
            bool result = false;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }
    bool result = current->data->crc_indication.crcflag;
    pthread_mutex_unlock(&list->lock);
    return result;
}

static void clear(dynamic_list* list) {
    pthread_mutex_lock(&list->lock);
    while (list->head != NULL) {
        list_node *temp = list->head;
        list->head = list->head->next;
        free_node(temp->data);
        free(temp);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
