    size_t buf_len;
    pthread_mutex_t lock;
} Buffer;

// Function to initialize buffer pool
Buffer* init_buffer_pool(size_t num_connections, size_t max_buf_size) {
    Buffer *buf_pool = malloc(num_connections * sizeof(Buffer));

    for (size_t i = 0; i < num_connections; ++i) {
        buf_pool[i].buf_len = max_buf_size;
        buf_pool[i].buf_ptr = mmap(NULL, max_buf_size, PROT_READ | PROT_WRITE, MAP_ANON | MAP_SHARED, -1, 0);

        if (buf_pool[i].buf_ptr == MAP_FAILED) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_init(&buf_pool[i].lock, NULL);
    }

    return buf_pool;
}

// Function to configure network interface
int setup_network_interface(const char *ip, const char *port) {
    struct addrinfo hints, *servinfo, *p;
    int sockfd;
    char s[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET6 for IPv6 or AF_INET for IPv4
    hints.ai_socktype = SOCK_STREAM;

    getaddrinfo(ip, port, &hints, &servinfo);

    sockfd = socket(servinfo->ai_family, servinfo->ai_socktype, servinfo->ai_protocol);
    if (sockfd == -1) {
        perror("socket");
        return -1;
    }

    if (connect(sockfd, servinfo->ai_addr, servinfo->ai_addrlen) == -1) {
        close(sockfd);
        perror("connect");
        return -1;
    }

    freeaddrinfo(servinfo);

    // Save the IP address for further use
    inet_ntop(servinfo->ai_family, getnameinfo(servinfo, s, sizeof(s), 0, NULL, 0, 0), s, sizeof(s));

    return sockfd;
}

