// Function to initialize and configure the network interface for high-throughput data transmission
int init_network(const char *ip, const char *port, size_t num_connections, size_t max_buf_size) {
    int sockfd = setup_network_interface(ip, port);
    if (sockfd == -1) {
        return -1;
    }

    Buffer* buf_pool = init_buffer_pool(num_connections, max_buf_size);

    pthread_t threads[num_connections];

    for (size_t i = 0; i < num_connections; ++i) {
        void *args[] = { &sockfd };
        if (pthread_create(&threads[i], NULL, network_thread, args)) {
            perror("pthread_create");
            return -1;
        }
    }

    for (size_t i = 0; i < num_connections; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(buf_pool);

    return sockfd;
}
```

