typedef struct NPM_Record {
    time_t timestamp;
    int cell_id;
    double throughput;
    double latency;
} NPM_Record;

struct DataPacket {
    size_t size;
    int cell_id;
    double timestamptz; // Timestamp as a double representing number of seconds since Unix Epoch
    double throughput;
    double latency;
};

typedef struct DataPacket QueueElement;
typedef struct {
    QueueElement *front, *rear;
    pthread_mutex_t lock;
} Queue;

Queue incoming_data;

void init_queue() {
    incoming_data.front = NULL;
    incoming_data.rear = NULL;
    pthread_mutex_init(&incoming_data.lock, NULL);
}

void enqueue(Queue *q, QueueElement *element) {
    pthread_mutex_lock(&q->lock);
    if (q->front == NULL) {
        q->front = element;
        q->rear = element;
    } else {
        q->rear->next = element;
        q->rear = element;
    }
    pthread_mutex_unlock(&q->lock);
}

QueueElement* dequeue(Queue *q) {
    QueueElement *result = NULL;
    pthread_mutex_lock(&q->lock);
    if (q->front != NULL) {
        result = q->front;
        q->front = q->front->next;
        if (q->front == NULL)
            q->rear = NULL;
    }
    pthread_mutex_unlock(&q->lock);
    return result;
}

void process_data() {
    NPM_Record *npm_record;
    QueueElement *packet;

    while ((packet = dequeue(&incoming_data))) {
        npm_record = malloc(sizeof(NPM_Record));
        if (npm_record == NULL) {
            free(packet); // Free the memory if allocation fails
            continue;
        }

