class NetworkPerformanceMetrics {
private:
    std::vector<NPMRecord> records;
    std::deque<double> throughputDataQueue; // FIFO queue for throughput data points
    std::deque<double> latencyDataQueue; // FIFO queue for latency data points
    double outlierThreshold{0};
    int cellID{0};
    std::unordered_map<int, NPMRecord*> cache;
    std::mutex mtx;

public:
    NetworkPerformanceMetrics(double outlierThreshold) : outlierThreshold(outlierThreshold) {}

    void processPacket(const double& throughput, const double& latency) {
        std::lock_guard<std::mutex> lock(mtx);
        throughputDataQueue.push_back(throughput);
        latencyDataQueue.push_back(latency);
        calculateMetrics();
    }

    NPMRecord* getNPMRecord(int cellID) {
        if (cache.find(cellID) != cache.end())
            return cache[cellID];
        auto it = std::find_if(records.begin(), records.end(), [&](const NPMRecord &r) { return r.cellID == cellID; });
        if (it != records.end()) {
            NPMRecord* npmRecord = new NPMRecord(*it);
            cache[cellID] = npmRecord;
            return npmRecord;
        }
        return nullptr;
    }

private:
    void calculateMetrics() {
        if (throughputDataQueue.size() < 3 || latencyDataQueue.size() < 3)
            return;

        double meanThroughput = calculateMean(throughputDataQueue);
        double medianLatency = calculateMedian(latencyDataQueue);

        // Implement your outlier detection logic here, for example:
        // If more than X% of the data points are above the mean + n * outlierThreshold, discard them.

        // Update metrics in the latest record
        auto it = throughputDataQueue.end() - 1;
        records.back().throughput = *it;
        it = latencyDataQueue.end() - 1;
        records.back().latency = *it;
    }

    double calculateMean(const std::deque<double>& data) {
        double sum{0};
        for (auto& d : data)
            sum += d;
        return sum / data.size();
    }

    double calculateMedian(const std::deque<double>& data) {
        if (data.empty())
            return 0;
        auto it = data.cbegin();
        auto middleIt = next(it, data.size() / 2);
        return (*middleIt + *next(middleIt)) / 2.0;
    }
};

