#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {SUCCESS, FAILURE_OUT_OF_MEMORY, FAILURE_FILE_WRITE, FAILURE_DISK_SPACE, FAILURE_PERMISSION} Status;

struct FAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
};

Status generateAndSerializeStructures(const char *inputFileName, uint32_t numStructures, FILE **outputFile) {
    struct FAPI_CRC_INDICATION_PDU_T *dataBuffer;
    struct FAPI_CRC_INDICATION_PDU_T data;
    size_t dataSize = sizeof(struct FAPI_CRUC_INDICATION_PDU_T);
    size_t numAllocatedStructures = 1000;
    size_t writtenStructures = 0;
    size_t bytesWritten = 0;
    FILE *output;
    char outputFileName[256];
    int i, randomCRCFlag;
    pthread_mutex_t mutex;

    if (!(dataBuffer = malloc(numAllocatedStructures * dataSize))) {
        return FAILURE_OUT_OF_MEMORY;
    }

    pthread_mutex_init(&mutex, NULL);

    snprintf(outputFileName, sizeof(outputFileName), "%s_%lu.bin", inputFileName, numStructures);

    if (!(output = fopen(outputFileName, "wb"))) {
        free(dataBuffer);
        return FAILURE_FILE_WRITE;
    }

    pthread_mutex_lock(&mutex);

    for (i = 0; i < numStructures && writtenStructures < numAllocatedStructures; ++i) {
        randomCRCFlag = rand() % 2;
        data.RX_UE_INFORMATION_TAG = i;
        data.RNTI = i + 10000;
        data.CRC_INDICATION_REL8_TAG = randomCRCFlag;

        memcpy(&dataBuffer[writtenStructures], &data, dataSize);
        ++writtenStructures;

        if (fwrite(dataBuffer + writtenStructures - bytesWritten, 1, bytesWritten, output) != bytesWritten) {
            free(dataBuffer);
            fclose(output);
            return FAILURE_FILE_WRITE;
        }

        bytesWritten = 0;

        if (ftell(output) > 50 * (1024 * 1024)) { // 50 MB limit
            free(dataBuffer);
            fclose(output);
            return FAILURE_DISK_SPACE;
        }
    }

    if (writtenStructures < numStructures) {
        free(dataBuffer);
        fclose(output);
        return FAILURE_DISK_SPACE;
    }

    pthread_mutex_unlock(&mutex);
    fclose(output);
    free(dataBuffer);

    return SUCCESS;
}
