    unsigned int session_id;
    unsigned int stream_id;
    unsigned int packet_flags;
};

struct MediaFileMetadata {
    std::string file_path;
    double duration;
    int bitrate;
    std::string format;
    bool codec_valid;
};

void ProcessMediaFile(const std::string& media_file_path, size_t expected_entries) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dist64(0, UINT64_MAX);

    // Initialize dynamically allocated list of MediaPacket structures
    std::vector<MediaPacket*> mediaPackets;
    mediaPackets.reserve(expected_entries);

    for (size_t i = 0; i < expected_entries; ++i) {
        MediaPacket* packet = new MediaPacket();
        packet->session_id = dist64(gen);
        packet->stream_id = dist64(gen);
        packet->packet_flags = dist64(gen) & 0x0F; // Set PacketType randomly (only 4 possible values with this bitmask)
        mediaPackets.push_back(packet);
    }

    MediaFileMetadata metadata;
    ParseMediaFileMetadata(media_file_path, metadata);

    if (!ValidateMediaFileAgainstTemplate(metadata)) {
        LogError("Invalid media file metadata!");
        return;
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, media_file_path.c_str(), media_file_path.size());
    SHA256_Final(hash, &ctx);

    // Perform further processing here...

    // Clean up memory
    for (auto packet : mediaPackets) {
        delete packet;
    }
}
