NFAPI_CRC_INDICATION_PDU_T* create_element() {
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element == NULL) return NULL;

    element->tag = RX_UE_INFORMATION_TAG_INITIALIZER;
    element->rnti = 0;
    element->crc_indication.crcFlag = (rand() % 2);
    element->next = NULL;
    return element;
}

void add_element(struct linked_list *list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);

    element->next = list->head;
    list->head = element;

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(struct linked_list *list, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) break;
        current = current->next;
    }
    return current;
}

void remove_element(struct linked_list *list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == element) list->head = element->next;
    else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != element) current = current->next;
        current->next = element->next;
    }

    pthread_mutex_unlock(&list->mutex);
    free(element);
}
