struct user_data {
    NFAPI_CRC_INDICATION_PDU_T* users;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

void init_user_data(struct user_data* data) {
    data->capacity = 0;
    data->length = 0;
    pthread_mutex_init(&data->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_user() {
    NFAPI_CRC_INDICATION_PDU_T* user = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!user) {
        perror("malloc failed");
        return NULL;
    }

    user->crc_ind.crcflag = rand() % 2;
    return user;
}

void push_user(struct user_data* data, NFAPI_CRC_INDICATION_PDU_T* user) {
    pthread_mutex_lock(&data->mutex);

    if (data->capacity == data->length) {
        size_t new_capacity = data->capacity ? (data->capacity * 2) : 16;
        NFAPI_CRC_INDICATION_PDU_T* tmp = realloc(data->users, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!tmp) {
            perror("realloc failed");
            pthread_mutex_unlock(&data->mutex);
            free(user);
            return;
        }
        data->users = tmp;
        data->capacity = new_capacity;
    }

    data->users[data->length] = *user;
    data->length++;

    pthread_mutex_unlock(&data->mutex);
}

void pop_user(struct user_data* data, NFAPI_CRC_INDICATION_PDU_T** user) {
    pthread_mutex_lock(&data->mutex);

    if (data->length == 0) {
        *user = NULL;
        pthread_mutex_unlock(&data->mutex);
        return;
    }

    data->length--;
    *user = &data->users[data->length];

    pthread_mutex_unlock(&data->mutex);
}

void iterate_reverse(struct user_data* data, void (*function)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&data->mutex);

    for (size_t i = data->length - 1; i != 0; --i) {
        function(&data->users[i]);
    }

    pthread_mutex_unlock(&data->mutex);
}
