#include <arpa/inet.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <unistd.h>

typedef struct {
    int sockfd;
    struct sockaddr_in local_addr, remote_addr;
    pid_t worker_id; // Store the ID of the worker thread handling this connection
    enum CONN_STATE { CONN_NEW, CONN_ESTABLISHED, CONN_CLOSING, CONN_CLOSED } state;
    pthread_mutex_t mutex;
} tcp_conn;

typedef struct list_node {
    tcp_conn *data;
    struct list_node *next;
} list_node;

list_node *head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void destroy_conn(tcp_conn *conn) {
    if (conn == NULL) return;

    // Close the socket and clean up resources
    close(conn->sockfd);
    memset(conn, 0, sizeof(*conn));
    free(conn);
}

void list_remove(list_node *node) {
    pthread_mutex_lock(&list_mutex);

    if (head == node) head = node->next;
    if (!node->next) return;

    list_node *iter = head;
    while (iter->next != node) iter = iter->next;
    iter->next = node->next;

    pthread_mutex_unlock(&list_mutex);

    destroy_conn(node->data);
    free(node);
}

tcp_conn* list_add(int sockfd, struct sockaddr_in local_addr, struct sockaddr_in remote_addr) {
    pthread_mutex_lock(&list_mutex);

    tcp_conn *new_conn = malloc(sizeof(*new_conn));
    if (!new_conn) {
        perror("malloc");
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    memcpy(&new_conn->local_addr, &local_addr, sizeof(local_addr));
    memcpy(&new_conn->remote_addr, &remote_addr, sizeof(remote_addr));
    new_conn->sockfd = sockfd;
    new_conn->state = CONN_NEW;
    pthread_mutex_init(&new_conn->mutex, NULL);

    list_node *new_node = malloc(sizeof(*new_node));
    if (!new_node) {
        perror("malloc");
        destroy_conn(new_conn);
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    new_node->data = new_conn;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&list_mutex);

    return new_conn;
}

void list_iterate(void (*func)(tcp_conn *)) {
    pthread_mutex_lock(&list_mutex);

    list_node *iter = head;
    while (iter) {
        list_node *next = iter->next;
        tcp_conn *conn = iter->data;

        // Perform the operation on the connection with a lock to ensure thread-safety
        pthread_mutex_lock(&conn->mutex);
        func(conn);
        if (conn->state == CONN_CLOSED) list_remove(iter);
        pthread_mutex_unlock(&conn->mutex);

        iter = next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void* worker_thread(void *arg) {
    tcp_conn *conn = (tcp_conn*) arg;

    // Handle the connection here, with proper error checking and resource management
    // ...

    conn->state = CONN_CLOSING;
    destroy_conn(conn);

    pthread_detach(pthread_self());
    return NULL;
}
