// Define Network Data Unit (NDU) structure
struct NDU {
    size_t metadata_size; // Size of the NDU's metadata
    size_t payload_size;   // Variable-length payload size
    void* metadata;       // Pointer to the metadata
    void* payload;        // Pointer to the payload
};

// Define a helper function to calculate the offset within an NDU's payload
void* calculateOffset(struct NDU* ndu, size_t offset) {
    return (ndu->payload + offset);
}

// Allocate memory for an NDU with given metadata and payload sizes
struct NDU* createNDU(size_t metadata_size, size_t payload_size) {
    struct NDU* ndu = malloc(sizeof(struct NDU));
    if (!ndu) return NULL;

    ndu->metadata_size = metadata_size;
    ndu->payload_size = payload_size;
    ndu->metadata = malloc(metadata_size);
    if (!ndu->metadata) {
        free(ndu);
        return NULL;
    }

    ndu->payload = malloc(payload_size);
    if (!ndu->payload) {
        free(ndu->metadata);
        free(ndu);
        return NULL;
    }

    return ndu;
}

