public class DynamicDataHandler
{
    private ConcurrentQueue<(BigInteger Value, DateTime Timestamp, IDictionary<string, object> Metadata)> _dataItems;
    private BigInteger _minValue;
    private BigInteger _maxValue;
    private TimeSpan _timeRange;
    private BigInteger _checksum;

    public DynamicDataHandler(BigInteger minValue, BigInteger maxValue, TimeSpan timeRange)
    {
        _dataItems = new ConcurrentQueue<(BigInteger, DateTime, IDictionary<string, object>)>();
        _minValue = minValue;
        _maxValue = maxValue;
        _timeRange = timeRange;
        InitializeData();
    }

    private void InitializeData()
    {
        for (int i = 0; i < 1000; i++) // Adjust the number of items to fit your requirements
        {
            AddData(GenerateRandomValue(), DateTime.UtcNow, new Dictionary<string, object>());
        }
    }

    private BigInteger GenerateRandomValue()
    {
        return _minValue + UnityEngine.Random.Range(0, (_maxValue - _minValue) + 1);
    }

    public void AddData(BigInteger value, DateTime timestamp, IDictionary<string, object> metadata = null)
    {
        if (value < _minValue || value > _maxValue)
            throw new ArgumentOutOfRangeException(nameof(value), "Value must be within the defined bounds.");

        _dataItems.Enqueue((value, timestamp, metadata));
    }

    public void RemoveData(BigInteger value)
    {
        var dataToRemove = new ValueAndTimestampComparer().OrderBy(_dataItems, (d) => d.Item1).FirstOrDefault((d) => d.Item1 == value);
        if (dataToRemove != null)
            _dataItems.TryDequeue(out _);
    }

    public (BigInteger Value, DateTime Timestamp, IDictionary<string, object> Metadata)? GetData(BigInteger value)
    {
        return _dataItems.FirstOrDefault((d) => d.Item1 == value);
    }

    public void UpdateRange(TimeSpan newTimeRange, Action onPruneComplete = null)
    {
        if (_timeRange != newTimeRange)
        {
            _timeRange = newTimeRange;
            PruneOldData(onPruneComplete);
        }
    }

    private void PruneOldData(Action onPruneComplete = null)
    {
        var pruningTask = new Task(() =>
        {
            var currentUtcNow = DateTime.UtcNow;
            while (_dataItems.Any((d) => (currentUtcNow - d.Item2) > _timeRange))
            {
                _dataItems.TryDequeue(out _);
            }

            onPruneComplete?.Invoke();
        });

        pruningTask.Start();
    }

    public BigInteger Checksum
    {
        get => _checksum;
        set
        {
            if (_checksum != value)
            {
                _checksum = value;
                ValidateDataIntegrity();
            }
        }
    }

    private void ValidateDataIntegrity()
    {
        // Implement a custom validation strategy based on your specific needs, such as hash functions or consistency checks.
    }
}

public class ValueAndTimestampComparer : IComparer<(BigInteger, DateTime)>
{
    public int Compare((BigInteger, DateTime) x, (BigInteger, DateTime) y)
    {
        return x.Item1.CompareTo(y.Item1);
    }
}
