    struct addrinfo* addr;
};

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static struct CacheEntry* cache = NULL;
static size_t cache_size = 0;

void dns_cache_init(size_t size) {
    cache = malloc(sizeof(struct CacheEntry) * size);
    memset(cache, 0, sizeof(struct CacheEntry) * size);
    cache_size = size;
}

static struct CacheEntry* find_cache_entry(const char* host) {
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache_size; ++i) {
        if (!cache[i].expiry_time && strcmp(host, cache[i].addr->ai_canonname) == 0) {
            pthread_mutex_unlock(&cache_lock);
            return &cache[i];
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void dns_cache_insert(const char* host, struct addrinfo* addr) {
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache_size; ++i) {
        if (!cache[i].expiry_time && strcmp(host, cache[i].addr->ai_canonname) == 0) {
            cache[i].addr = addr;
            cache[i].expiry_time = time(NULL) + (60 * 5); // Cache entry expires in 5 minutes.
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    // Find an empty slot.
    for (size_t i = 0; i < cache_size; ++i) {
        if (!cache[i].expiry_time) {
            cache[i].addr = addr;
            cache[i].expiry_time = time(NULL) + (60 * 5); // Cache entry expires in 5 minutes.
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }
    // If all slots are full, evict the least recently used entry.
    size_t index = 0;
    time_t oldest_time = time(NULL) + (60 * 5); // Set an arbitrary old timestamp for the first slot as reference.
    for (size_t i = 1; i < cache_size; ++i) {
        if (cache[index].expiry_time > oldest_time && cache[i].expiry_time < oldest_time) {
            index = i;
            oldest_time = cache[i].expiry_time;
        }
    }
    memcpy(&cache[index], addr, sizeof(struct CacheEntry));
    pthread_mutex_unlock(&cache_lock);
}

