#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>

typedef struct {
    struct ip ip_header;
    struct tcp tcp_header;
    uint16_t checksum; // calculated checksum for this packet
} PacketHeader;

// Custom checksum function
uint16_t custom_checksum(const void *data, size_t length) {
    const uint16_t* words = (const uint16_t*) data;
    size_t len = length / sizeof(uint16_t);
    uint32_t sum = 0;

    for (size_t i = 0; i < len; ++i) {
        sum += words[i];
        if ((i & 1) == 1) // handle endianness
            sum += (sum >> 16);
    }

    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}

// Global variables to manage memory and synchronization
static PacketHeader *packet_headers = NULL;
static size_t packet_count = 0;
static const size_t max_packets = 1024;
static pthread_mutex_t packets_lock = PTHREAD_MUTEX_INITIALIZER;

void init_packet_headers() {
    if (packet_headers) return;

    packet_headers = malloc(max_packets * sizeof(PacketHeader));
    if (!packet_headers) {
        fprintf(stderr, "Failed to allocate memory for packet headers\n");
        exit(1);
    }

    // Initialize and populate the dynamic array with empty packets
    for (size_t i = 0; i < max_packets; ++i) {
        packet_headers[i].ip_header.ihl = 5; // IP header length = 20 bytes
        packet_headers[i].tcp_header.th_off = TH_OFF(sizeof(packet_headers[i].tcp_header));
    }
}

PacketHeader* get_empty_packet() {
    pthread_mutex_lock(&packets_lock);

    for (size_t i = 0; i < packet_count; ++i) {
        if (!packet_headers[i].checksum) {
            PacketHeader *packet = &packet_headers[i];
            memset(&packet->ip_header.frag_off, 0, sizeof(packet->ip_header.frag_off)); // Clear fragment offset
            packet_count--;
            pthread_mutex_unlock(&packets_lock);
            return packet;
        }
    }

    if (packet_count < max_packets) {
        PacketHeader *packet = &packet_headers[packet_count++];
        memset(packet, 0, sizeof(*packet)); // Initialize new packet
        pthread_mutex_unlock(&packets_lock);
        return packet;
    }

    // No empty packets available. Wait for one to be freed.
    pthread_mutex_unlock(&packets_lock);
    pthread_cond_wait(&packet_wait, &packets_lock);

    PacketHeader *packet = &packet_headers[packet_count - 1];
    pthread_mutex_lock(&packets_lock);
    return packet;
}

void put_packet(PacketHeader *packet) {
    packet->checksum = 0; // Reset checksum for reuse
    pthread_mutex_lock(&packets_lock);
    packet_count++;
    pthread_mutex_unlock(&packets_lock);
    pthread_cond_signal(&packet_wait);
