fn create_list(n: u32) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut list = Vec::with_capacity(n as usize);
    for _ in 0..n {
        let rnti = (0x1 << 26) | (rand::thread_rng().gen::<u32>() & ((1 << 24) - 1));
        let rx_ue_info_tag = NFAPI_CRC_INDICATION_PDU_T { rnti, ..Default::default() };
