                crcflag: thread_rng().gen(),
            },
            rx_ue_information_tag: Some(rx_ue_info_tag),
        })
    }
    list
}

fn http_client() -> Result<Client, reqwest::Error> {
    let mut config = Config::new();

    let allowlist_path = env::var("NFAPI_ALLOWLIST").unwrap_or_else(|_| "allowlist.txt".to_owned());
    let allowlist: Vec<Url> = BufReader::new(File::open(Path::new(&allowlist_path)).unwrap())
        .lines()
        .filter_map(|line| line.ok().and_then(|url_str| Url::parse(&url_str).ok()))
        .collect();

    let tls = {
        let mut builder = TlsConnectorBuilder::new();
        config.merge(Some(builder))?;
        builder.build()?
    };

    config.merge(Some(tls))?;
    let client = Client::new(config)?;

    Ok(client)
}

fn check_url(client: &Client, url: &Url) -> Result<(), reqwest::Error> {
    if !allowlist.contains(url) {
        return Err(reqwest::Error::InvalidInput("URL not found in the whitelist."));
    }
    Ok(())
}

fn build_request(client: &Client, url: Url) -> reqwest::blocking::RequestBuilder {
    client.request(url).build()
}

fn main() {
    let n = env::args().nth(1).and_then(str::parse::<u32>).unwrap_or(1000);
    let list = create_list(n);

    let client = http_client()?;

    for pdu in &list {
        match check_url(&client, &pdu.crc_indication_rel8_tag.url) {
            Ok(_) => {
                let mut req_builder = build_request(&client, pdu.crc_indication_rel8_tag.url);
                // Configure the request as needed
                // ...
                let request = req_builder.send()?;
                // Handle response and errors
                // ...
            }
            Err(e) => println!("Error: {}", e),
        }
    }
}
