#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_RTNTI 0xFFFF // Maximum possible RNTI value
#define MEM_CACHE_SIZE 1024 // Cache size for memory-efficient access to external data sources

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CacheNode *next;
} CacheNode;

// Global variables for cache and synchronization
CacheNode *cacheHead = NULL;
CacheNode *cacheTail = NULL;
pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;
sem_t cacheSemaphore = SEM_INITIALIZER_UNLOCKED();

void initializeCache() {
    int fd;
    CacheNode *node;

    fd = open("cache.dat", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Error opening cache file");
        exit(EXIT_FAILURE);
    }

    while (MAP_FAILED != mmap(NULL, MEM_CACHE_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, fd, 0)) {
        node = calloc(1, sizeof(CacheNode));
        if (!node) {
            perror("Error allocating memory for cache node");
            exit(EXIT_FAILURE);
        }

        node->data = *(NFAPI_CRC_INDICATION_PDU_T*)mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
        if (MAP_FAILED == node->data.RNTI) {
            perror("Error mapping data to cache node");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&cacheLock);
        if (!cacheTail) {
            cacheHead = node;
            cacheTail = node;
        } else {
            cacheTail->next = node;
            cacheTail = node;
        }
        pthread_mutex_unlock(&cacheLock);
    }

    close(fd);
}

NFAPI_CRC_INDICATION_PDU_T* allocatePDU(bool debug) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    sem_wait(&cacheSemaphore);
    pthread_mutex_lock(&cacheLock);
    if (cacheHead && cacheHead->data.RNTI == 0xFFFF) { // Mark the used node as invalid for reuse
        cacheHead = cacheHead->next;
        pdu = &cacheHead->data;
        free(cacheHead);
        pthread_mutex_unlock(&cacheLock);
    } else {
        sem_post(&cacheSemaphore);

        if (debug) printf("Allocating new PDU structure\n");
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Error allocating memory for new PDU structure");
            exit(EXIT_FAILURE);
        }
        memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return pdu;
}

void manageArray(size_t size, NFAPI_CRC_INDICATION_PDU_T** array, bool debug) {
    size_t i;
    NFAPI_CRC_INDICATION_PDU_T *currentElement;

    if (!array) return;

    if (debug) printf("Managing array of %zu elements\n", size);

    *array = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("Error allocating memory for the array");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < size; ++i) {
        do {
            currentElement = allocatePDU(debug);

            if (currentElement->RNTI == 0xFFFF || (i > 0 && currentElement->RNTI == array[i - 1]->RNTI)) { // Handle edge cases and ensure unique RNTIs
                free(currentElement);
                continue;
            }
        } while ((i > 0) && (currentElement->RNTI == array[i - 1]->RNTI));

        memcpy(array[i], currentElement, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}
```

