public final class NfaPduManager {
    private static final int MAX_THREADS = 1000_000;
    private static final long TIME_WINDOW_MINUTES = 30;
    private static final int THRESHOLD_MB = 128; // Adjustable memory footprint threshold (in MB)

    private ExecutorService executor;
    private ConcurrentMap<Integer, NFAPI_CRC_INDICATION_PDU_T> pduCache;
    private Map<String, BigInteger> md5Cache;
    private boolean debugMode;

    public NfaPduManager() {
        executor = Executors.newThreadPoolExecutor(
                new ThreadFactoryBuilder().setDaemon(true).build(),
                new LinkedBlockingQueue<>(MAX_THREADS),
                new ThreadPoolExecutor.CallerRunsPolicy());

        pduCache = new ConcurrentHashMap<>();
        md5Cache = new HashMap<>();
    }

    public void addPdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
        if (pduCache.containsKey(pdu.getRnti()))
            throw new IllegalStateException("Duplicate RNTI found.");

        pduCache.putIfAbsent(pdu.getRnti(), pdu);
    }

    public void validatePdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
        // Validate CRCFLAG against predefined rules...
    }

    public void cacheDataSources() {
