        debugMode = enabled;
    }

    public Map<String, BigInteger> computeMd5Hashes(Collection<String> strings) {
        if (strings.isEmpty()) return Collections.emptyMap();

        Callable<Map<String, BigInteger>> callable = () -> {
            Map<String, BigInteger> results = new HashMap<>();
            for (String str : strings) {
                BigInteger md5 = md5Cache.computeIfAbsent(str, s -> computeMd5(s));
                results.put(s, md5);
            }
            return results;
        };

        Future<Map<String, BigInteger>> future = executor.submit(callable);
        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Error computing MD5 hashes.", e);
        }
    }

    private BigInteger computeMd5(String str) {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(str.getBytes(StandardCharsets.UTF_8));
        return new BigInteger(1, md.digest());
    }

    // Other utility methods and getters for debugging and configuration...
}
```

