static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t element_count = 0;
static size_t capacity = 10000;
NFAPI_CRC_INDICATION_PDU_T* data = NULL;

void log(const char* message) {
    printf("[LOG] %s\n", message);
}

void resize() {
    if (data != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(data, capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            log("Memory allocation failure: Unable to resize array.");
            exit(-1);
        }
        data = new_data;
        capacity *= 2;
    } else {
        data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data == NULL) {
            log("Memory allocation failure: Failed to allocate initial array.");
            exit(-1);
        }
    }
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu, float probability) {
    if (rand() / (RAND_MAX + 1.0) < probability) {
        pdu->CRCFLAG = 1;
    } else {
        pdu->CRCFLAG = 0;
    }
}

void* populate(void* arg) {
    for (size_t i = element_count; i < capacity; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i + 1;
        data[i].RNTI = i * 2 + 3;
        data[i].CRC_INDICATION_REL8_TAG = i * 3 + 5;
        set_crcflag(&data[i], 0.5); // Probability threshold is 50%
    }
    pthread_mutex_lock(&mutex);
    element_count += capacity;
    resize();
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void create_array(size_t num_elements) {
    if (num_elements <= 0) {
        log("Invalid input: Number of elements must be greater than zero.");
        return;
    }

    pthread_mutex_lock(&mutex);
    while (element_count + num_elements > capacity) {
        resize();
    }
    element_count += num_elements;
    pthread_mutex_unlock(&mutex);

    for (size_t i = element_count - num_elements; i < element_count; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i + 1;
        data[i].RNTI = i * 2 + 3;
        data[i].CRC_INDICATION_REL8_TAG = i * 3 + 5;
        set_crcflag(&data[i], 0.5); // Probability threshold is 50%
    }
}
