struct dynamic_list* create_dynamic_list(size_t initial_capacity) {
    struct dynamic_list* list = malloc(sizeof(struct dynamic_list));
    if (!list) return NULL;

    list->elements = calloc(initial_capacity, sizeof(LTE_UPLINK_NAS_TRANSPORT*));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_list(struct dynamic_list* list) {
    if (list && list->elements) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->elements[i]);
        }
        free(list->elements);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

