    if (list->count == list->capacity) {
        size_t new_capacity = 2 * list->capacity;
        LTE_UPLINK_NAS_TRANSPORT** new_elements = realloc(list->elements, new_capacity * sizeof(LTE_UPLINK_NAS_TRANSPORT*));

        if (!new_elements) {
            return; // Return early and handle allocation failure gracefully.
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }
}

void add_transport(struct dynamic_list* list, LTE_UPLINK_NAS_TRANSPORT* transport) {
    pthread_mutex_lock(&list->mutex);
    resize_dynamic_list(list);
    list->elements[list->count++] = transport;
    pthread_mutex_unlock(&list->mutex);
}

struct dynamic_list* initialize_transport_list(size_t initial_capacity) {
    struct dynamic_list* list = create_dynamic_list(initial_capacity);
    if (!list) return NULL;

    for (size_t i = 0; i < initial_capacity; ++i) {
        LTE_UPLINK_NAS_TRANSPORT* transport = allocate_transport();
        if (!transport) continue; // Handle allocation failure gracefully.

        add_transport(list, transport);
    }

    return list;
}
