```javascript
async function insertWidgets(sectionId, widgets) {
  const section = document.getElementById(sectionId) || document.createElement('div');
  section.innerHTML = ''; // Clear existing content in the section
  section.id = sectionId;

  if (!section.parentNode) {
    document.body.appendChild(section); // Add the section to the body if it's not already present
  }

  let loadedWidgetCount = 0;
  const chunkSize = 10; // Adjust as needed for optimal performance

  widgets.forEach((widget) => {
    if (!section.querySelector(`[data-name="${widget.name}"]")) { // Check if the widget already exists
      const widgetElement = document.createElement('div');
      widgetElement.dataset.name = widget.name;
      widgetElement.classList.add(widget.type);

      Object.keys(widget.attributes).forEach((key) => {
        const attributeValue = widget.attributes[key];
        widgetElement.setAttribute(key, attributeValue);
      });

      section.appendChild(widgetElement);

      if (loadedWidgetCount < widgets.length) { // Lazy loading: load more widgets as needed
        loadedWidgetCount++;
        if (loadedWidgetCount % chunkSize === 0) {
          await delay(50); // Delay between chunks to avoid overloading the browser
          const chunk = widgets.slice(loadedWidgetCount - chunkSize, loadedWidgetCount);
          insertWidgets(sectionId, chunk);
        }
      }
    }
