typedef struct LTEPHY_RLC_QosFlowStats {
    uint64_t flow_id;
    uint64_t packet_count;
    double throughput;
    double latency;
    uint32_t errors;
    sem_t lock;
} LTEPHY_RLC_QosFlowStats;

typedef struct QueueNode {
    LTEPHY_RLC_QosFlowStats flowStat;
    struct QueueNode *next;
} QueueNode;

typedef struct Queue {
    QueueNode* head;
    QueueNode* tail;
    sem_t insertSemaphore;
    pthread_mutex_t queueMutex;
    int capacity;
    int size;
} Queue;

Queue* createQueue(int capacity) {
    Queue *queue = (Queue *) malloc(sizeof(Queue));
    queue->head = NULL;
    queue->tail = NULL;
    queue->capacity = capacity;
    queue->size = 0;
    sem_init(&queue->insertSemaphore, 0, queue->capacity);
    pthread_mutex_init(&queue->queueMutex, NULL);
    return queue;
}

void enqueue(Queue *queue, LTEPHY_RLC_QosFlowStats flowStat) {
    QueueNode *newNode = (QueueNode *) malloc(sizeof(QueueNode));
    newNode->flowStat = flowStat;
    newNode->next = NULL;

    sem_wait(&queue->insertSemaphore);
    pthread_mutex_lock(&queue->queueMutex);

    if (queue->tail == NULL) {
        queue->head = newNode;
        queue->tail = newNode;
    } else {
        queue->tail->next = newNode;
        queue->tail = newNode;
    }

    queue->size++;
    pthread_mutex_unlock(&queue->queueMutex);
    sem_post(&queue->insertSemaphore);
}

