    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

int createNFAPICRCList(Node** list, unsigned int maxSize) {
    if (maxSize == 0) return -1; // Invalid input: maxSize must be greater than zero

    *list = malloc(sizeof(Node)*maxSize);
    if (*list == NULL) return -2; // Failed to allocate memory for the list

    Node* current = *list;
    for (unsigned int i = 0; i < maxSize - 1; ++i) {
        current->next = &(*list)[i + 1];
        current = current->next;
    }
    current->next = NULL; // Last node's next pointer points to NULL, marking the end of the list

    return maxSize; // Return the maximum size of the list for success indication
}

void allocateRNTI(unsigned int* rntiPool, unsigned int maxRNTIs) {
    if (maxRNTIs == 0) return; // Invalid input: maxRNTIs must be greater than zero

    *rntiPool = 0; // Initialize the RNTI pool to zero
}

bool isUniqueRNTI(unsigned int rnti, Node* current) {
    if (current == NULL) return true; // If at the beginning of the list or empty list, any RNTI is unique

    while (current != NULL) {
        if (rnti == current->data.rnti) return false; // Found duplicate RNTI, return false
        current = current->next;
    }
    return true; // Reached the end of the list without finding a duplicate RNTI, return true
}

int addToNFAPICRCList(Node** list, unsigned int* rntiPool, unsigned int maxSize) {
    if (list == NULL || *list == NULL || rntiPool == NULL) return -3; // Invalid input: pointers cannot be null
    if (*rntiPool >= maxSize) return -4; // Reached the maximum allowed RNTI limit

    Node* current = *list;
    unsigned int newRNTI;

    do {
        allocateRNTI(rntiPool, maxSize); // Allocate a new RNTI from the pool
        newRNTI = *rntiPool++;

        if (!isUniqueRNTI(newRNTI, current)) continue; // If duplicate RNTI found, try again with another RNTI
    } while (current->next != NULL); // Keep trying until the end of the list is reached

    current->data.rnti = newRNTI;
    current->data.crc_indication.crcflag = rand() % 2; // Set CRCFLAG to a random value

    return current - *list + 1; // Return the index of the added structure in the list
}

void deallocateNFAPICRCList(Node** list, unsigned int maxSize) {
    if (list == NULL || *list == NULL) return; // Invalid input: pointers cannot be null or list is empty

    Node* current = *list;
    for (unsigned int i = 0; i < maxSize; ++i) {
        Node* temp = current;
        current = current->next;
        free(temp); // Free each node in the list
    }
    *list = NULL; // Clear the pointer to the list
}
