NFAPI_CRC_INDICATION_PDU_T* create_napi_pdu(void) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    // Initialize structure with random values and non-repeating CRCFLAG.
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 10000 + 1;
    do {
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG ^= (pdu->CRC_INDICATION_REL8_TAG & 0x1);
    } while (pdu->CRCFLAG == (pdu+1)->CRCFLAG);

    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T* create_napi_pdus(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (size_t i = 0; i < n-1; ++i) {
        pdus[i] = create_napi_pdu();
        for (size_t j = i+1; j < n; ++j) {
            if (pdus[i]->RNTI == pdus[j]->RNTI) {
                free(pdus);
                return NULL;
            }
        }
    }

    pdus[n-1] = create_napi_pdu();
    return pdus;
}
