#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned short rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRGC_INDICATION_PDU_T* create_list(unsigned int num_entries, unsigned short max_rnti, unsigned long seed) {
    if (num_entries == 0 || num_entries > UINT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Invalid number of entries\n");
        return NULL;
    }

    if (max_rnti >= USHRT_MAX) {
        fprintf(stderr, "Maximum RNTI value out of bounds\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    size_t num_bytes = num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Use posix_memalign for memory allocation that's aligned to a given boundary
    if (posix_memalign((void**)&list, alignof(NFAPI_CRC_INDICATION_PDU_T), num_bytes) != 0) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    mlockall(MCL_CURRENT | MCL_FUTURE); // Prevent page swapping for better performance

    unsigned long crcflag = seed;

    #pragma omp parallel for firstprivate(list, crcflag, max_rnti) shared(num_entries, lock)
    for (unsigned int i = 0; i < num_entries; ++i) {
        if (i >= max_rnti) {
            fprintf(stderr, "Out of bounds access attempt\n");
            continue;
        }

        list[i].tag = i; // Populate tag field with index for validation purposes
        list[i].rnti = i;
        list[i].crc_indication.crcflag = (unsigned char)(crcflag & 0x1);
        crcflag >>= 1;
    }

    munlockall(); // Unlock all memory pages to allow system to manage them

    return list;
}
```

