    (*arr)->capacity = max_size;
    (*arr)->size = 0;
    (*arr)->data = calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*arr)->data) {
        free(*arr);
        return MEMORY_FAILURE;
    }
    pthread_mutex_init(&((*arr)->mutex), NULL);
