        if (!new_data) return MEMORY_FAILURE;
        arr->data = new_data;
        arr->capacity *= 2;
    }
    pthread_mutex_lock(&arr->mutex);
    arr->data[arr->size] = *element;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
    return NO_ERROR;
}

size_t get_index(const struct array_data* arr, size_t index) {
