#define MAX_N 10000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRUC_INDICATION_PDU_T *list = NULL;
static size_t count = 0;
static size_t capacity = 0;

void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

void validate_rnti(uint16_t rnti) {
    if (rnti < RNTI_MIN || RNTI_MAX < rnti) {
        log_error("Invalid RNTI value.");
    }
}

NFAPI_CRUC_INDICATION_PDU_T *create_pdu() {
    NFAPI_CRUC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRUC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Memory allocation failure.");
        return NULL;
    }

    pdu->rx_ue_information_tag = rand() % 65536;
    pdu->rnti = (rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;
    validate_rnti(pdu->rnti);
    pdu->crc_indication_rel8_tag = rand() % 65536;
    pdu->crcflag = rand() % 2;

    return pdu;
}

void resize_list(size_t new_capacity) {
    NFAPI_CRUC_INDICATION_PDU_T *new_list = realloc(list, new_capacity * sizeof(NFAPI_CRUC_INDICATION_PDU_T));

    if (!new_list) {
        log_error("Memory allocation failure during list resize.");
        return;
    }

    list = new_list;
    capacity = new_capacity;
}

void push_pdu(NFAPI_CRUC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);

    if (count == capacity) {
        resize_list(capacity ? (capacity * 2) : MAX_N);
    }

    list[count] = *pdu;
    count++;

    pthread_mutex_unlock(&mutex);
}

void init_list() {
    pthread_mutex_lock(&mutex);

    if (capacity < MAX_N) {
        resize_list(MAX_N);
    }

    for (size_t i = 0; i < count; ++i) {
        list[i] = *create_pdu();
    }

    pthread_mutex_unlock(&mutex);
}
