#include <pthread.h>
#include <semaphore.h>
#include <malloc.h>
#include <stdbool.h>
#include <limits.h>

// Define the buffer size and semaphore for synchronization
#define BUFFER_SIZE 1024
sem_t buffer_mutex;

char* process_string(const char *input, bool trim, size_t *output_len) {
    // Allocate a larger temporary buffer to handle large strings and potential ellipsis
    char *temp_buffer = malloc((BUFFER_SIZE + 5) * sizeof(char));
    if (!temp_buffer) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    // Lock the buffer mutex to ensure thread safety
    sem_wait(&buffer_mutex);

    size_t len = strlen(input);
    size_t copy_len = (trim && len > BUFFER_SIZE) ? BUFFER_SIZE : len;

    // Copy the input string into the temporary buffer, add ellipsis if necessary
    strncpy(temp_buffer, input, copy_len);
    if (trim && len > BUFFER_SIZE) {
        temp_buffer[BUFFER_SIZE - 3] = '.';
        temp_buffer[BUFFER_SIZE - 2] = '.';
        temp_buffer[BUFFER_SIZE - 1] = '\0';
    }

    // Unlock the buffer mutex to allow other threads to access it
    sem_post(&buffer_mutex);

    // Allocate the output buffer and copy the trimmed or untrimmed string as needed
    char *output_buffer = malloc((copy_len + 1) * sizeof(char));
    if (!output_buffer) {
        fprintf(stderr, "Out of memory\n");
        free(temp_buffer);
        return NULL;
    }
    strcpy(output_buffer, temp_buffer);

    // Set the output length and return the processed string
    *output_len = copy_len;
    return output_buffer;
}
```

