['```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SymmetricEncryption
{
    public class AesEncryptionService
    {
        private readonly Aes _aesAlgorithm;
        private readonly HMACSHA256 _hmac;
        private readonly Func<string, byte[]> _keyRetriever;
        private readonly Action<byte[], string> _keyUpdater;

        public AesEncryptionService(Func<string, byte[]> keyRetriever, Action<byte[], string> keyUpdater)
        {
            _aesAlgorithm = AES.Create();
            _hmac = new HMACSHA256(_aesAlgorithm.Key);
            _keyRetriever = keyRetriever;
            _keyUpdater = keyUpdater;
        }

        public byte[] GetInitializationVector() => _aesAlgorithm.IV;

        private void UpdateKeys(string key)
        {
            var newKey = _keyRetriever(key);
            _aesAlgorithm.Key = newKey;
            _hmac.Key = newKey;
            _keyUpdater(newKey, key);
        }

        public async Task<(byte[] encryptedData, byte[] hmacTag)> EncryptAsync(Stream dataStream)
        {
            using (var ms = new MemoryStream())
            {
                await dataStream.CopyToAsync(ms);
                var encryptedBytes = Encrypt(ms.ToArray());
                var hmacTag = GetHMACTag(encryptedBytes);
                return (encryptedBytes, hmacTag);
            }
        }

        public byte[] Decrypt(byte[] encryptedData, byte[] hmacTag)
        {
            if (!VerifyHMACTag(hmacTag))
                throw new InvalidOperationException("Invalid HMAC tag.");

            var decryptedBytes = Decrypt(encryptedData);
            return decryptedBytes;
        }

        private byte[] Encrypt(byte[] data) => _aesAlgorithm.Encrypt(data, CryptoConfig.CreateFromName("PKCS7Padding"), GetInitializationVector());
        private byte[] Decrypt(byte[] encryptedData) => _aesAlgorithm.Decrypt(encryptedData, CryptoConfig.CreateFromName("PKCS7Padding"), GetInitializationVector());
        private byte[] GetHMACTag(byte[] data) => _hmac.ComputeHash(data);
        private bool VerifyHMACTag(byte[] hmacTag) => _hmac.ComputeHash(Encrypt(_aesAlgorithm.IV)).SequenceEqual(hmacTag);

        public void UpdateKey(string key) => UpdateKeys(key);
    }
}
```

