typedef struct {
    RX_FRAME_HEADER header;
    char payload[1500];
} NFAPI_RX_FRAME_INFO_T;

void init_frame_array(NFAPI_RX_FRAME_INFO_T** frame_array, size_t* num_frames, size_t max_frames) {
    if (max_frames > 1024 || max_frames == 0) {
        printf("Max frames must be less than or equal to 1024 and greater than zero.\n");
        return;
    }

    *frame_array = malloc(max_frames * sizeof(NFAPI_RX_FRAME_INFO_T));
    if (!*frame_array) {
        perror("Error allocating memory for frame array.");
        return;
    }

    *num_frames = 0;

    // Initialize each frame with zeros
    for (size_t i = 0; i < max_frames; ++i) {
        (*frame_array)[i].header.checksum = 0;
        memset((*frame_array)[i].payload, 0, sizeof((*frame_array)[i].payload));
    }
}
