    SecurityInformation security;
} RRC_Context;

typedef struct CacheNode {
    RRC_Context* context;
    struct CacheNode *next;
} CacheNode;

CacheNode* cache_head = NULL;
CacheNode* cache_tail = NULL;

pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_key(SecurityInformation* security) {
    uint8_t key[16];
    for (size_t i = 0; i < sizeof(key); ++i)
        key[i] = rand();
    memcpy(security->encryption_key, key, sizeof(key));
    memcpy(security->initialization_vector, key, sizeof(key));
}

RRC_Context* get_cached_context(uint32_t UE_ID) {
    pthread_mutex_lock(&cache_mutex);
    CacheNode *current = cache_head;
    while (current != NULL) {
        if (current->UE_ID == UE_ID) {
            RRC_Context* context = current->context;
            if (current == cache_tail)
                cache_tail = NULL;
            current = current->next;
            pthread_mutex_unlock(&cache_mutex);
            return context;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

RRC_Context* allocate_context(uint32_t UE_ID) {
    RRC_Context* context = (RRC_Context*)malloc(sizeof(RRC_Context));
    if (!context) {
        perror("malloc");
        return NULL;
    }
    context->UE_ID = UE_ID;
    generate_key(&context->security);
    return context;
}

void add_to_cache(RRC_Context* context) {
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) {
        perror("malloc");
        free(context);
        return;
    }
    node->context = context;
    node->next = NULL;
    pthread_mutex_lock(&cache_mutex);
    if (cache_head == NULL) {
        cache_head = node;
        cache_tail = node;
    } else {
        cache_tail->next = node;
        cache_tail = node;
    }
    pthread_mutex_unlock(&cache_mutex);
}

void init_dynamic_array(RRC_Context** contexts, uint32_t num_UE_IDs) {
    for (uint32_t i = 0; i < num_UE_IDs; ++i) {
        RRC_Context* context = allocate_context(i);
        if (!context) continue; // Handle memory allocation errors gracefully
        contexts[i] = context;
        add_to_cache(context);
    }
}
