import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class FrameMetadataStore {
    private final ConcurrentHashMap<Long, FrameMetadata> metadataMap = new ConcurrentHashMap<>();
    private final SoftReference<byte[]>[] payloads; // Dynamic array for growing and shrinking payloads

    public FrameMetadataStore(int initialCapacity) {
        metadataMap.putAll(INITIAL_FRAME_METADATA); // Load initial frame metadata from external source if available
        payloads = new SoftReference[initialCapacity];
    }

    public void put(Long key, FrameMetadata value) {
        metadataMap.putIfAbsent(key, value);
        ensurePayloadCapacity(value.getPayloadSize());
        payloads[value.getKey() % payloads.length] = new SoftReference<>(value.getPayload());
    }

    public FrameMetadata get(Long key) {
        return metadataMap.getOrDefault(key, null);
    }

    public void remove(Long key) {
        metadataMap.remove(key);
        AtomicInteger refCount = metadataMap.get(key).getRefCount();
        if (refCount.decrementAndGet() == 0) {
            freePayload(key);
        }
    }

    private void ensurePayloadCapacity(int size) {
        // Implement a strategy to handle memory fragmentation and optimize for frequent insertions/deletions
    }

    private void freePayload(Long key) {
        int index = key % payloads.length;
        SoftReference<byte[]> ref = payloads[index];
        if (ref != null && ref.get() != null) {
            payloads[index] = null; // Mark the reference for garbage collection
        }
    }
}

