using System;
using System.Collections.Concurrent;
using UnityEngine;
using BenchmarkDotNet;
using BenchmarkDotNet.Diagnosers;

namespace DynamicValueGenerator
{
    public sealed class DynamicValueGenerator
    {
        private readonly ConcurrentDictionary<(Type type, Tuple<float, float>) ranges> _generators;

        public DynamicValueGenerator()
        {
            _generators = new ConcurrentDictionary<(Type, Tuple<float, float>)>();
        }

        public float GenerateFloat(Type type, float min, float max, bool inclusive = true)
        {
            if (_generators.TryGetValue((type, new Tuple<float, float>(min, max)), out var generator))
                return (T)(object)generator();

            var lockFreeRange = new LockFreeMinMax<float>(min, max, inclusive);
            Action<float> generate = () => lockFreeRange.Next();
            Func<float> factory = () => generate;

            if (!_generators.TryAdd((type, new Tuple<float, float>(min, max)), factory))
                _generators[((Type)type, new Tuple<float, float>(min, max))] = factory;

            return generate();
        }

        public int GenerateInt(Type type, int min, int max, bool inclusive = true)
        {
            if (_generators.TryGetValue((typeof(int), new Tuple<float, float>(min, max)), out var generator))
                return (int)(object)generator();

            var lockFreeRange = new LockFreeMinMax<int>(min, max, inclusive);
            Action<int> generate = () => lockFreeRange.Next();
            Func<int> factory = () => generate;

            if (!_generators.TryAdd((typeof(int), new Tuple<float, float>(min, max)), factory))
                _generators[(typeof(int), new Tuple<float, float>(min, max))] = factory;

            return generate();
        }

        public void EnableLogging(string logFilePath)
        {
            // Implement a logging system here with the desired verbosity level and configuration.
            // Use BenchmarkDotNet to capture performance metrics and detailed information about the generation process.
        }
    }
}
