#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>

// MIB structure definition
typedef struct LTE_PHY_MIB_INFO {
    MIB_HEADER header;
    int timing_advance;
    unsigned char cell_identity;
    uint16_t system_frame_number;
    uint32_t checksum; // Checksum validation field
} LTE_PHY_MIB_INFO;

// Record structure definition
typedef struct {
    int value;
    pthread_mutex_t lock;
} record;

// Dynamic array management function for MIB structures
void* mib_array(int* capacity, LTE_PHY_MIB_INFO*** data) {
    *data = malloc(*capacity * sizeof(LTE_PHY_MIB_INFO*));
    if (!*data) return NULL;

    for (int i = 0; i < *capacity; ++i)
        (*data)[i] = malloc(sizeof(LTE_PHY_MIB_INFO));

    pthread_mutex_t* locks = calloc(*capacity, sizeof(pthread_mutex_t));
    if (!locks) {
        for (int i = 0; i < *capacity; ++i) free((*data)[i]);
        free(*data);
        return NULL;
    }

    void** elements = realloc(*data, (*capacity + 1) * sizeof(void*));
    if (!elements) {
        free(locks);
        for (int i = 0; i < *capacity; ++i) free((*data)[i]);
        free(*data);
        return NULL;
    }
    *data = elements;

    return locks;
}

// Function to insert an element into the MIB array
void mib_insert(LTE_PHY_MIB_INFO** data, pthread_mutex_t* locks, int index, LTE_PHY_MIB_INFO item) {
    // Ensure that index is within bounds and that there is space for the insertion
    assert(index >= 0 && index < sizeof(*data) / sizeof((*data)[0]));

    pthread_mutex_lock(&locks[index]);

    void** temp = realloc((*data), ((sizeof(*data) / sizeof((*data)[0])) + 1) * sizeof(void*));
    if (!temp) {
        pthread_mutex_unlock(&locks[index]);
        return;
    }
    (*data) = temp;

    memcpy(&(*data)[index], &item, sizeof(LTE_PHY_MIB_INFO));

    pthread_mutex_unlock(&locks[index]);
}

// Function to remove an element from the MIB array
void mib_remove(LTE_PHY_MIB_INFO** data, pthread_mutex_t* locks, int index) {
    // Ensure that index is within bounds and that there are elements to remove
    assert(index >= 0 && index < sizeof(*data) / sizeof((*data)[0]));

    pthread_mutex_lock(&locks[index]);

    void** temp = realloc((*data), ((sizeof(*data) / sizeof((*data)[0])) - 1) * sizeof(void*));
    if (!temp) {
        pthread_mutex_unlock(&locks[index]);
        return;
    }
    (*data) = temp;

    memmove(&(*data)[index], &(*data)[index + 1], ((sizeof(*data) / sizeof((*data)[0])) - index - 1) * sizeof(void*));

    pthread_mutex_unlock(&locks[index]);
}

// Function to retrieve an element from the MIB array
LTE_PHY_MIB_INFO* mib_get(const LTE_PHY_MIB_INFO** data, const pthread_mutex_t* locks, int index) {
    // Ensure that index is within bounds
    assert(index >= 0 && index < sizeof(*data) / sizeof((*data)[0]));

    pthread_mutex_lock(&locks[index]);
    LTE_PHY_MIB_INFO* item = (*data)[index];
    pthread_mutex_unlock(&locks[index]);

    return item;
}

// Function to allocate and initialize an array of records
void* record_array(int capacity, int min, int max) {
    record* data = malloc(capacity * sizeof(record));
    if (!data) return NULL;

    for (int i = 0; i < capacity; ++i) {
        data[i].value = rand() % (max - min + 1) + min;
        pthread_mutex_init(&data[i].lock, NULL);
    }

    return data;
}
