#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct PHY_Transaction {
    int id; // unique identifier for each transaction
    enum ModulationScheme { MSK, FSK, GMSK } modulation;
    double bandwidth;
    double center_frequency;
    time_t creation_time;
    pthread_mutex_t lock;
    struct PHY_Transaction *next; // linked list for dynamic collection
} PHY_Transaction;

struct PHY_Collection {
    size_t capacity; // maximum number of transactions supported by the hardware
    size_t count; // current number of transactions in the collection
    PHY_Transaction **transactions; // dynamically allocated array of pointers to transaction structures
    pthread_mutex_t lock; // protect access to the collection
};

void init_phy_collection(struct PHY_Collection *collection, size_t capacity) {
    collection->capacity = capacity;
    collection->count = 0;
    collection->transactions = malloc(sizeof(PHY_Transaction*) * capacity);
    memset(collection->transactions, 0, sizeof(PHY_Transaction*) * capacity);
    pthread_mutex_init(&collection->lock, NULL);
}

struct PHY_Transaction* add_phy_transaction(struct PHY_Collection *collection, enum ModulationScheme modulation, double bandwidth, double center_frequency) {
    for (size_t i = 0; i < collection->capacity; ++i) {
        if (!collection->transactions[i]) {
            collection->transactions[i] = malloc(sizeof(PHY_Transaction));
            memset(collection->transactions[i], 0, sizeof(PHY_Transaction));
            pthread_mutex_init(&collection->transactions[i]->lock, NULL);

            collection->transactions[i]->modulation = modulation;
            collection->transactions[i]->bandwidth = bandwidth;
            collection->transactions[i]->center_frequency = center_frequency;
            collection->transactions[i]->id = collection->count++;
            collection->transactions[i]->next = NULL;

            return collection->transactions[i];
        }
    }
    // handle overflow or add additional dynamic memory allocation strategy here
    return nullptr;
}

void remove_phy_transaction(struct PHY_Collection *collection, struct PHY_Transaction *transaction) {
    pthread_mutex_lock(&collection->lock);
    if (transaction && collection->transactions[transaction->id]) {
        PHY_Transaction *current = collection->transactions[transaction->id];
        collection->transactions[transaction->id] = current->next;
        free(current);
        --collection->count;
    }
    pthread_mutex_unlock(&collection->lock);
}

void cleanup_inactive_transactions(struct PHY_Collection *collection, time_t timeout) {
    pthread_mutex_lock(&collection->lock);
    time_t now = time(NULL);

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->transactions[i] && collection->transactions[i]->creation_time + timeout < now) {
            PHY_Transaction *current = collection->transactions[i];
            collection->transactions[i] = current->next;
            free(current);
            --collection->count;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}
