import json
import time
import uuid
from abc import ABC, abstractmethod
from typing import Dict, Any, Type, Callable, Union
from functools import wraps
from concurrent.futures import ThreadPoolExecutor
from collections import defaultdict, OrderedDict
from logging import getLogger,Formatter

class JSONModelMeta(type(dict)):
    _registry = defaultdict(lambda: None)
    _versions = defaultdict(int)
    _lock = ThreadPoolExecutor()

    @classmethod
    def register(cls, factory: Callable[[str], Type[JSONModel]], id_: str) -> None:
        with cls._lock.lock():
            if cls._registry[id_]:
                raise ValueError(f"ID '{id_}' already registered.")
            cls._registry[id_] = factory

    @classmethod
    def get_model(cls, id_: str) -> Type[JSONModel]:
        with cls._lock.lock():
            return cls._registry[id_]

    @classmethod
    def delete_model(cls, id_: str) -> None:
        with cls._lock.lock():
            del cls._registry[id_]

    @classmethod
    def get_version(cls, model_type: Type[JSONModel]) -> int:
        return JSONModelMeta._versions[model_type]

    @classmethod
    def set_version(cls, model_type: Type[JSONModel], version: int) -> None:
        JSONModelMeta._versions[model_type] = version

class JSONModel(ABC):
    __metaclass__ = JSONModelMeta

    @abstractmethod
    def from_json(self, json_data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def to_json(self) -> Union[Dict[str, Any], str]:
        pass

    @classmethod
    async def deserialize(cls, json_data: Union[Dict[str, Any], str], id_: str = None):
        if not id_ and issubclass(type(cls), JSONModel):
            id_ = cls.__name__
        model = JSONManager._instantiate(id_) or await JSONManager.get_factory(id_)(JSONData)
        model.from_json(json_data)
        return model

    @classmethod
    async def serialize(cls, instance: JSONModel, version: int = None) -> str:
        serialized = instance.to_json()
        if version:
            JSONManager.set_version(cls, version)
        return json.dumps(serialized)

class JSONData:
    def __init__(self, data: Dict[str, Any]):
        self._data = OrderedDict(sorted(data.items()))

class JSONManager:
    _factories = {}

    async def get_factory(cls, id_) -> Callable[[Dict[str, Any]], JSONModel]:
        if id_ not in cls._factories:
            factory = getattr(__import__(f"{id_}.models", fromlist=["models"]), id_)
            if callable(factory):
                cls._factories[id_] = factory
        return cls._factories[id_]

    @staticmethod
    def _instantiate(id_: str) -> Union[Type[JSONModel], None]:
        for model in JSONModelMeta._registry.values():
            if issubclass(model, JSONModel) and model.__name__ == id_:
                return model
        return None

    @staticmethod
    def init_logger() -> getLogger:
        logger = getLogger(__name__)
        formatter = Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler = logging.FileHandler("jsonmanager.log", encoding="utf-8", mode="w")
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

# Example factories for testing purposes
@JSONModelMeta.register("TestModel1", "testmodel1")
class TestModel1(JSONModel):
    def __init__(self, field1: str, field2: int):
        self._field1 = field1
        self._field2 = field2

    @staticmethod
    def from_json(json_data: Dict[str, Any]):
        TestModel1(json_data["field1"], json_data["field2"])

    def to_json(self) -> Dict[str, Any]:
        return {"field1": self._field1, "field2": self._field2}

@JSONModelMeta.register("TestModel2", "testmodel2")
class TestModel2(TestModel1):
    def __init__(self, field1: str, field2: int, custom_field: str):
        super().__init__(field1, field2)
        self._custom_field = custom_field

    @staticmethod
    def from_json(json_data: Dict[str, Any]):
        TestModel2(json_data["field1"], json_data["field2"], json_data.get("custom_field", None))

    def to_json(self) -> Dict[str, Any]:
        serialized = super().to_json()
        serialized["custom_field"] = self._custom_field
        return serialized
```

