        std::unique_lock<std::mutex> lock(mtx);
        if (!futureUEInfos.valid() || futureUEInfos.wait_for(lock, std::chrono::seconds(5)) == std::future_status::timeout) {
            throw std::runtime_error("Timed out waiting for UE information");
        }
        return futureUEInfos.get();
    }
