    std::default_random_engine generator;
    std::uniform_int_distribution<> distribution(0, ueInfos.size() - 1);

    std::thread shuffleThread([&]() {
        std::shuffle(ueInfos.begin(), ueInfos.end(), generator);
    });

    for (size_t i = 0; i < num && i < ueInfos.size(); ++i) {
        auto& structToFill = structures[i];
        structToFill.RX_UE_INFORMATION_TAG = ueInfos[i].RX_UE_INFORMATION_TAG;
        structToFill.RNTI = ueInfos[i].RNTI;
        structToFill.CRC_INDICATION_REL8_TAG = ueInfos[i].CRC_INDICATION_REL8_TAG;
        structToFill.CRCFLAG = (generator() % 2) == 0;
    }

    shuffleThread.join();

    return structures;
}
