    uint32_t CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 100000
#define TIME_WINDOW_MS 1000

static NFAPI_CRC_INDICATION_PDU_T* data = NULL;
static size_t capacity = 0, size = 0;
static pthread_mutex_t lock;
static bool backoff = false;

void init() {
    if (data) return;
    data = calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) return;
    capacity = MAX_STRUCTURES;
    size = 0;
    pthread_mutex_init(&lock, NULL);
}

void destroy() {
    if (!data) return;
    free(data);
    data = NULL;
    capacity = 0;
    size = 0;
    pthread_mutex_destroy(&lock);
}

static void populate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    structure->RX_UE_INFORMATION_TAG = rand();
    structure->RNTI = rand() % 0xFFFFFFFF;
    structure->CRC_INDICATION_REL8_TAG = rand();
    structure->CRCFLAG = (rand() & 1) ? 1 : 0;
}

void add_structure(size_t count) {
    if (!data || capacity <= size + count) {
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(data, capacity + count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data) {
            data = new_data;
            capacity += count;
        } else {
            printf("Reallocation failed.\n");
            return;
        }
    }
    for (size_t i = size; i < size + count; ++i) {
        populate_structure(&data[i]);
    }
    size += count;
}

void shuffle() {
    for (size_t i = 0; i < size - 1; ++i) {
        size_t j = rand() % (size - i);
        if (!j) continue;
        std::swap(data[i], data[i + j]);
    }
}

void* fetch_and_populate(void*) {
    pthread_mutex_lock(&lock);
    if (backoff) {
        usleep(1000 * backoff++); // Exponential backoff
    }
    if (size >= capacity || !data) {
        printf("Cannot add structure: no memory or data not initialized.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    populate_structure(&data[size]);
    ++size;
    pthread_mutex_unlock(&lock);
    return &data[size - 1];
}

void process() {
    if (!data || !capacity) return;
    backoff = false;
    shuffle();
    for (size_t i = 0; i < size && clock() < TIME_WINDOW_MS + CLOCKS_PER_SEC / 1000; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, fetch_and_populate, NULL)) continue; // Ignore errors from creating threads in this loop
        pthread_detach(thread);
    }
}
