// Custom structure to manage NFAPI_CRC_INDICATION_PDU_T data.
struct NFAPICRCPDUData {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag; // randomly set to true or false on initialization
};

// Callback function for asynchronous updates.
using UpdateCallback = std::function<void(size_t)>;

class NFAPIList {
private:
    std::vector<std::shared_ptr<NFAPICRCPDUData>> data;
    std::mutex mutex;
    UpdateCallback update_callback;

public:
    // Constructor.
    NFAPIList(UpdateCallback callback) : update_callback(callback) {}

    // Adds a new element to the list.
    void addElement(const NFAPICRCPDUData& data_item) {
        std::shared_ptr<NFAPICRCPDUData> new_data(new NFAPICRCPDUData(data_item)); // Create a smart pointer for efficient memory management.
        std::unique_lock lock(mutex);
        data.emplace_back(new_data);
    }

    // Removes an element by its RNTI from the list.
    void removeElementByRNTI(uint32_t rnti) {
        std::unique_lock lock(mutex);
        auto it = std::find_if(data.begin(), data.end(), [rnti](const auto& item) { return item->getRnti() == rnti; });

        if (it != data.end()) {
            data.erase(it);
        } else {
            throw std::runtime_error("Element not found.");
        }
    }

    // Updates the CRCFLAG for a specific element based on an index.
    void updateCRCFlagByIndex(size_t index, bool crcflag) {
        std::unique_lock lock(mutex);
        if (index < data.size()) {
            data[index]->setCrcflag(crcflag);
        } else {
            throw std::runtime_error("Index out of bounds.");
        }
    }

    // Callback for asynchronous updates. Updates the CRCFLAG for a specific element based on its RNTI.
    void onDataUpdate(uint32_t rnti, bool crcflag) {
        std::unique_lock lock(mutex);
        auto it = std::find_if(data.begin(), data.end(), [rnti](const auto& item) { return item->getRnti() == rnti; });

        if (it != data.end()) {
            it->setCrcflag(crcflag);
        } else {
            std::cout << "Element not found for update: RNTI=" << rnti << std::endl;
        }
    }
};
