using RX_UE_INFORMATION_TAG = int;
using RNTI = int;
using CRC_INDICATION_REL8_TAG = int;
using CRCDATA = std::array<RX_UE_INFORMATION_TAG, 3>; // Assuming this is the size of the data array
using NFAPI_CRC_INDICATION_PDU_T = struct {
    RX_UE_INFORMATION_TAG rxTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG tag;
    CRCDATA crcData;
};

// Intermittent data provider interface
class DataProvider {
public:
    virtual ~DataProvider() = default;

    // Retrieve a single element from the data source.
    // Throws std::runtime_error if an error occurs.
    virtual NFAPI_CRC_INDICATION_PDU_T retrieveData() const = 0;
};

// Lock-free stack implementation for concurrent access
template <typename T>
class ConcurrentStack {
private:
    std::atomic<std::shared_ptr<std::queue<T>>> queuePtr;
    std::mutex mtx;
    std::condition_variable cv;

public:
    explicit ConcurrentStack() : queuePtr(new std::queue<T>()) {}

    void push(const T& data) {
        auto queue = queuePtr.load();
        queue->push(data);
        if (queuePtr.compare_exchange_weak(queue, queue)) {
            cv.notify_one();
        }
    }

    std::optional<T> pop() {
        auto queue = queuePtr.load();
        std::unique_lock<std::mutex> lock(mtx);
        while (!queue) {
            cv.wait(lock);
            queue = queuePtr.load();
        }

        T data = std::move(queue->front());
        queue->pop();
        if (queuePtr.compare_exchange_weak(queue, std::move(queue))) {
            cv.notify_one();
        }
        return data;
    }
};

class DataManager {
private:
    const int maxElements;
    DataProvider& provider;
    ConcurrentStack<NFAPI_CRC_INDICATION_PDU_T> elementQueue;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> elements;
    std::mutex logMutex;

    void processData() {
        while (true) {
            auto data = elementQueue.pop();
            if (!data) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                continue;
            }

            int index = data->rnti % maxElements;
            data->rxTag = index;
            data->tag += index + data->signalStrength * data->channelQuality;
            elements[index] = std::move(*data);

            std::lock_guard<std::mutex> lock(logMutex);
            std::cout << "Processed data: " << data->rnti << ", " << index << std::endl;
        }
    }

public:
    DataManager(int maxElements, DataProvider& provider) : maxElements(maxElements), provider(provider) {
        elements.resize(maxElements);
        for (int i = 0; i < maxElements; ++i) {
            elements[i].rnti = i;
            elements[i].rxTag = i;
            elements[i].tag = i + i * i; // Fill with some initial value for CRCFLAG calculation
        }
        std::thread dataProcessor(processData);
        dataProcessor.detach();
    }
};
