typedef struct {
    uint8_t mac[6];
    char ip[INET6_ADDRSTRLEN];
    int timeout;
} nicp_msg;

struct subnet {
    const char *ip;
    in_port_t mask;
};

static const struct subnet subnets[] = {
    {"192.168.0.0/24", 255},
    // Add more subnets as needed
};

nicp_msg* create_nicp_messages(size_t count, int ip_version, const char *config_service_url, const struct subnet *subnets, size_t subnets_len) {
    nicp_msg *messages = calloc(count, sizeof(nicp_msg));
    if (!messages) {
        perror("Memory allocation error");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    for (size_t i = 0; i < count; ++i) {
        // Initialize with random MAC address and default timeout value
        memset(messages[i].mac, rand() & 0xFF, sizeof(messages[i].mac));
        messages[i].timeout = 1000;

        // Generate unique IPv4 or IPv6 address within the specified subnet range
        in_addr_t ip4;
        in6_addr ip6;
        const struct subnet *subnet;
        for (size_t j = 0; j < subnets_len && !subnet; ++j) {
            subnet = &subnets[j];
            if (ip_version == AF_INET) {
                if (inet_pton(AF_INET, subnet->ip, &ip4) != 1) {
                    continue;
                }
                ip4 += rand() % (ntohl(subnet->mask + 1) - ntohl(subnet->mask));
                if (!in_network((char *)&ip4, subnet->ip)) {
                    continue;
                }
            } else if (ip_version == AF_INET6) {
                if (inet_pton(AF_INET6, subnet->ip, &ip6) != 1) {
                    continue;
                }
                memset(&ip6, rand(), sizeof(in6_addr)); // Set some random bits to create unique addresses within the subnet
                ip6 = in6_pton(subnet->ip);
                if (!IN6_ARE_ADDR_EQUAL(&ip6, (const in6_addr *)&ip6) || !IN6_ARE_ADDR_EQUAL(&ip6, (const in6_addr *)inet6_aton(subnet->ip))) {
                    continue;
                }
                if (!in6_network(&ip6, subnet->ip)) {
                    continue;
                }
            } else {
                continue;
            }
            subnet = &subnets[j];
        }
        if (subnet) {
            if (ip_version == AF_INET) {
                snprintf(messages[i].ip, sizeof(messages[i].ip), "%s%d", inet_ntoa(*(struct in_addr *)&ip4), rand() % 256 + 1);
            } else if (ip_version == AF_INET6) {
                snprintf(messages[i].ip, sizeof(messages[i].ip), "%s%hu%" PRIx64, subnet->ip, rand() % 65536 + 1, ((uint64_t *)&ip6)[1]);
            }
        } else {
            free(messages);
            return NULL;
        }

        // Call the network configuration service to fetch the timeout value (optional)
        if (config_service_url && *config_service_url) {
            char request[64];
            snprintf(request, sizeof(request), "timeout=%d&ip=%s", i, messages[i].ip);
            int fd = open(config_service_url, O_RDONLY);
            if (fd < 0) {
                perror("Failed to connect to network configuration service");
                messages[i].timeout = 1000; // Use default timeout value if the service is unavailable
            } else {
                pthread_t thread;
                int ret = pthread_create(&thread, NULL, fetch_timeout, &messages[i]);
                if (ret != 0) {
                    perror("Failed to create thread for network configuration service call");
                } else {
                    pthread_detach(thread);
                }
            }
        }
    }

    // Wait for all threads to complete, if needed
    while (pthread_cond_wait(&cond, &mutex) != 0) {
        if (errno == EINTR) {
            continue;
        } else {
            break;
        }
    }

    return messages;
}

void *fetch_timeout(void *arg) {
    nicp_msg *message = arg;
    int fd = open(config_service_url, O_RDONLY);
    if (fd >= 0 && fgets(message->ip + strlen(message->ip), sizeof(message->ip) - strlen(message->ip), fd)) {
        sscanf(message->ip + strlen(message->ip), "%d", &message->timeout);
        close(fd);
    } else {
        message->timeout = 1000; // Use default timeout value if the service is unavailable or an error occurs during the read operation
    }
    return NULL;
}
