    if (!net_headers) return NULL;

    net_headers->capacity = capacity;
    net_headers->count = 0;
    net_headers->headers = malloc(capacity * sizeof(header_t));
    if (!net_headers->headers) {
        free(net_headers);
        return NULL;
    }

    memset(net_headers->headers, 0, capacity * sizeof(header_t));

