}

void network_headers_push(network_headers_t* net_headers, const header_t* header) {
    validate_header(header);

    if (net_headers->count == net_headers->capacity) {
        size_t new_capacity = net_headers->capacity * 2;
        header_t* new_headers = realloc(net_headers->headers, new_capacity * sizeof(header_t));
        if (!new_headers) return;
        net_headers->headers = new_headers;
        net_headers->capacity = new_capacity;
    }

    pthread_mutex_lock(&net_headers->lock);
    memcpy(&net_headers->headers[net_headers->count], header, sizeof(header_t));
    net_headers->count++;
    pthread_mutex_unlock(&net_headers->lock);
}

char* network_headers_to_buf(network_headers_t* net_headers, size_t* len) {
    char *buffer = NULL;
    size_t buffer_len = 0;

    for (size_t i = 0; i < net_headers->count; ++i) {
        header_t* header = &net_headers->headers[i];
        char* serialized_header;
        size_t serialized_len;

        serialize_header(header, &serialized_header, &serialized_len);

        buffer_len += serialized_len + 1; // additional space for separator between headers

        if (!buffer) {
            buffer = malloc(buffer_len);
            if (!buffer) return NULL;
        } else if (buffer_len > bufferlen) {
            char *new_buffer = realloc(buffer, buffer_len);
            if (!new_buffer) {
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
        }
    }

    size_t pos = 0;
    for (size_t i = 0; i < net_headers->count; ++i) {
        header_t* header = &net_headers->headers[i];
        char* serialized_header;
        size_t serialized_len;

        serialize_header(header, &serialized_header, &serialized_len);

        memcpy(buffer + pos, serialized_header, serialized_len);
        pos += serialized_len;
        if (i < net_headers->count - 1) {
            buffer[pos++] = ',';
        }
    }

    *len = buffer_len;

    return buffer;
}
