    uint32_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t current_size;
    size_t max_size;
    pthread_rwlock_t lock;
} CRCI_ARRAY;

void init_crci_array(CRCI_ARRAY **arr) {
    *arr = malloc(sizeof(CRCI_ARRAY));
    if (!*arr) {
        perror("malloc error");
        return;
    }
    (*arr)->data = calloc(MAX_ARRAY_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*arr)->data) {
        perror("calloc error");
        free(*arr);
        *arr = NULL;
        return;
    }
    (*arr)->current_size = 0;
    (*arr)->max_size = MAX_ARRAY_SIZE;
    pthread_rwlock_init(&(*arr)->lock, NULL);
}

void resize_crci_array(CRCI_ARRAY *arr) {
    size_t new_size = arr->current_size * 2 + 1; // Growth factor of 2 + 1 for safety margin
    if (new_size > MAX_ARRAY_SIZE) return;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(arr->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("realloc error");
        return;
    }
    arr->data = new_data;
    arr->max_size = new_size;
}

void push_crci(CRCI_ARRAY *arr, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_rwlock_wrlock(&arr->lock);
    if (arr->current_size >= arr->max_size) resize_crci_array(arr);
    memcpy((void *)&arr->data[arr->current_size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->data[arr->current_size].crcflag = rand(); // Set CRCFLAG with random value
    arr->current_size++;
    pthread_rwlock_unlock(&arr->lock);
}

void iterate_crci(CRCI_ARRAY *arr, void (*action)(const NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_rwlock_rdlock(&arr->lock);
    for (size_t i = 0; i < arr->current_size; ++i)
        action(arr->data + i);
    pthread_rwlock_unlock(&arr->lock);
}

