#include <boost/asio.hpp>
#include <boost/circular_buffer.hpp>
#include <boost/bind.hpp>
#include <vector>
#include <memory>
#include <atomic>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCDFLAG;
};

class DataManager {
public:
    explicit DataManager(size_t maxArraySize) : maxArraySize_(maxArraySize), currentSize_(0), pduBuffer_(maxArraySize_, NFAPI_CRC_INDICATION_PDU_T()), worker_(ioService_) {}

    void resizeArray(size_t newSize) {
        if (newSize > maxArraySize_ || newSize == 0)
            return;

        std::vector<NFAPI_CRC_INDICATION_PDU_T> newPduBuffer(newSize);
        std::copy_if(pduBuffer_.begin(), pduBuffer_.end(), std::back_inserter(newPduBuffer), [](const auto& pdu) { return currentSize_ >= static_cast<size_t>(std::distance(pduBuffer_.begin(), pdu)); });
        pduBuffer_ = std::move(newPduBuffer);
        currentSize_ = newSize;
    }

    void addPDU(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (currentSize_ >= pduBuffer_.size())
            resizeArray(currentSize_ * 2);

        pduBuffer_[currentSize_++] = pdu;
    }

    const NFAPI_CRC_INDICATION_PDU_T* getPDU(size_t index) const {
        if (index >= currentSize_)
            return nullptr;
        return &pduBuffer_[index];
    }

private:
    size_t maxArraySize_, currentSize_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduBuffer_;

    boost::asio::io_service ioService_;
    boost::asio::io_service::work worker_;
};
```

