typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcTag;
    bool crcFlag;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct _LIST_NODE *next;
} LIST_NODE;

LIST_NODE* generateNfapiIndications(int count) {
    LIST_NODE* head = NULL;
    LIST_NODE* currentNode = NULL;
    NFAPI_CRC_INDICATION_PDU_T *dataBlock;

    for (int i = 0; i < count; ++i) {
        dataBlock = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!dataBlock) return NULL;

        dataBlock->tag = (RX_UE_INFORMATION_TAG)i;
        dataBlock->rnti = i % 1024;
        dataBlock->crcTag = (CRC_INDICATION_REL8_TAG)(i >> 16);
        dataBlock->crcFlag = rand() % 2;
        dataBlock->next = NULL;

        if (!head) {
            head = currentNode = malloc(sizeof(LIST_NODE));
            if (!currentNode) return NULL;
            currentNode->data = dataBlock;
            currentNode->next = NULL;
        } else {
            currentNode->next = malloc(sizeof(LIST_NODE));
            if (!currentNode->next) return NULL;
            currentNode = currentNode->next;
            currentNode->data = dataBlock;
            currentNode->next = NULL;
        }
    }

    return head;
}
