#define MAX_PATH_LENGTH 4096

char* constructPath(const char* path, size_t maxLength, const char* defaultDir, int isAbsolute) {
    size_t pathLen = strlen(path);
    if (isAbsolute || (pathLen > 0 && path[0] == '/')) {
        // Absolute path or leading slash detected, no need to prepend default dir
        if (pathLen <= maxLength)
            return strdup(path);
        else
            return NULL;
    }

    // Relative path detected, prepend default directory and check for validity
    size_t dirLen = strlen(defaultDir);
    if ((dirLen + pathLen + 1) <= maxLength) {
        char* newPath = malloc(pathLen + dirLen + 2); // Extra space for the '/' separator
        if (!newPath) return NULL;

        strcpy(newPath, defaultDir);
        newPath[dirLen] = '/';
        strcpy(newPath + dirLen + 1, path);

        struct stat st_buf;
        if (stat(newPath, &st_buf) == 0 && S_ISDIR(st_buf.st_mode)) {
            return newPath;
        } else {
            free(newPath);
            return NULL;
        }
    } else {
        return NULL; // Maximum path length exceeded
    }
}
