['```c
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

typedef enum { TCP, UDP, ICMP } ProtocolType;

struct NetworkHeader {
    in_port_t src_port;
    struct in_addr dest_ip;
    ProtocolType protocol;
    uint16_t payload_length;
    void *payload; // dynamic allocation based on payload_length
};

// Global variables for thread safety
pthread_mutex_t headers_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t headers_sem;

// Initialize and configure a network header
void init_network_header(struct NetworkHeader **header, in_port_t src_port, const struct in_addr *dest_ip, ProtocolType protocol, uint16_t payload_length) {
    // Acquire lock before creating the header to ensure thread safety
    pthread_mutex_lock(&headers_mutex);

    sem_wait(&headers_sem);

    // Allocate memory for the network header structure
    *header = malloc(sizeof(struct NetworkHeader));
    if (!*header) {
        perror("malloc");
        pthread_mutex_unlock(&headers_mutex);
        sem_post(&headers_sem);
        return;
    }

    // Fill in the header structure with provided parameters
    (*header)->src_port = src_port;
    memcpy((*header)->dest_ip, dest_ip, sizeof(struct in_addr));
    (*header)->protocol = protocol;
    (*header)->payload_length = payload_length;

    // Allocate memory for the header's payload using mmap and set it to zero
    void *payload_ptr = mmap(NULL, payload_length, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (payload_ptr == MAP_FAILED) {
        perror("mmap");
        free(*header);
        pthread_mutex_unlock(&headers_mutex);
        sem_post(&headers_sem);
        return;
    }

    // Set the payload field to point to the allocated memory
    (*header)->payload = payload_ptr;

    // Release the lock and semaphore after successful header creation
    pthread_mutex_unlock(&headers_mutex);
    sem_post(&headers_sem);
}

// Free network header and associated resources
void free_network_header(struct NetworkHeader *header) {
    if (header->payload != NULL) {
        munmap((void *)header->payload, header->payload_length);
    }
    free(header);
}
```

This code provides a basic implementation for initializing and configuring custom network protocol headers. It uses a global mutex lock to ensure thread safety during the creation of new headers, as well as a semaphore to coordinate access when multiple threads are attempting to create new headers concurrently. The function dynamically allocates memory for both the header structure and its payload using malloc() and mmap().

It is essential to integrate this code into your existing system carefully, considering backward compatibility with previous versions of the protocol headers. Additionally, ensure proper error handling when dealing with edge cases such as zero-length payloads or invalid IP addresses.']

