void init_array() {
    if (frames) return;
    capacity = MAX_ELEMENTS;
    frames = malloc(capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!frames) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    current_size = 0;
}

void resize_array() {
    LTE_PHY_RX_FRAME_INFO *new_frames;
    size_t new_capacity = capacity * 2;

    new_frames = realloc(frames, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!new_frames) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    frames = new_frames;
    capacity = new_capacity;
}

void log_memory() {
    printf("Current size: %zu, Capacity: %zu\n", current_size, capacity);
}

LTE_PHY_RX_FRAME_INFO* get_frame() {
    pthread_mutex_lock(&array_mutex);
    if (current_size >= capacity) resize_array();
    LTE_PHY_RX_FRAME_INFO *frame = &frames[current_size];
    current_size++;
    pthread_mutex_unlock(&array_mutex);

    frame->TIMING_ADVANCE_FLAG = rand() < prob_threshold;
    return frame;
}

void set_rx_type(LTE_PHY_RX_FRAME_INFO *frame, uint8_t type) {
