    if (current_size == 0 || current_size > capacity) {
        init_array(); // Handle edge cases for zero or negative input values
    }
    frame->RX_FRAME_TYPE = type;
    pthread_mutex_unlock(&array_mutex);
}

void set_cell_id(LTE_PHY_RX_FRAME_INFO *frame, uint16_t id) {
    pthread_mutex_lock(&array_mutex);
    if (current_size == 0 || current_size > capacity) {
        init_array(); // Handle edge cases for zero or negative input values
    }
    frame->PHY_RRC_CELL_ID = id;
    pthread_mutex_unlock(&array_mutex);
}
