    NFAPI_CRC_INDICATION_PDU_T *new_buffer;
    size_t old_size = num_elements > 0 ? num_elements : MAX_ELEMENTS;

    pthread_mutex_lock(&resize_lock);
    if (new_size <= old_size) {
