using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class QueryExecutor
{
    private readonly string _connectionString;
    private readonly IDictionary<string, object> _parameters;
    private readonly ActionOptions _options;

    public QueryExecutor(string connectionString, IDictionary<string, object> parameters, ActionOptions options)
    {
        _connectionString = connectionString;
        _parameters = parameters;
        _options = options;
    }

    public async Task<DataTable> ExecuteQueryAsync()
    {
        var sqlCommand = BuildSqlCommand();
        var conn = new SqlConnection(_connectionString);
        await conn.OpenAsync();

        using (var cmd = new SqlCommand(sqlCommand, conn))
        {
            foreach (var param in _parameters.Keys)
            {
                cmd.Parameters.AddWithValue(param, _parameters[param]);
            }

            if (_options.Logging)
            {
                LogQuery(sqlCommand);
            }

            var reader = await cmd.ExecuteReaderAsync();
            return new DataTable().Load(reader);
        }
    }

    private string BuildSqlCommand()
    {
        var sqlBuilder = new SqlServerSqlBuilder();
        _parameters.Keys.ToList().ForEach(param => sqlBuilder.AddParameter(param, _parameters[param]));
        return sqlBuilder.BuildQuery(_options.Pagination?.PageSize ?? int.MaxValue, _options.Pagination?.PageNumber);
    }

    private void LogQuery(string sqlCommand)
    {
        var logEntry = new QueryLogEntry
        {
            QueryText = sqlCommand,
            Parameters = JsonConvert.SerializeObject(_parameters),
            StartTime = DateTime.Now,
            ElapsedTime = TimeSpan.Zero,
            PageSize = _options.Pagination?.PageSize ?? 0,
            PageNumber = _options.Pagination?.PageNumber ?? 1
        };

        // You can add your custom logging implementation here
    }

    public class QueryLogEntry
    {
        public string QueryText { get; set; }
        public string Parameters { get; set; }
        public DateTime StartTime { get; set; }
        public TimeSpan ElapsedTime { get; set; }
        public int PageSize { get; set; }
        public int PageNumber { get; set; }
    }

    public class ActionOptions
    {
        public PaginationSettings Pagination { get; set; }
        public bool Logging { get; set; } = true;
        public bool CachingEnabled { get; set; } = false;
    }

    public class PaginationSettings
    {
        public int? PageSize { get; set; }
        public int? PageNumber { get; set; }
    }
}
```
