    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define HASH_TABLE_SIZE 1024 // Adjust as needed for optimal performance and memory usage

typedef struct hash_entry {
    uint16_t rnti;
    pthread_mutex_t mutex;
} hash_entry_t;

struct populator_args {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t max_list_size;
    uint16_t min_rnti;
    uint16_t max_rnti;
    bool verbose;
    bool* used;
    hash_entry_t* cache;
    pthread_mutex_t cache_mutex;
    size_t cache_size;
    size_t memory_threshold;
};

void init_cache(hash_entry_t** cache, size_t cache_size) {
    *cache = malloc(cache_size * sizeof(hash_entry_t));
    for (size_t i = 0; i < cache_size; ++i) {
        (*cache)[i].rnti = 0;
        pthread_mutex_init(&(*cache)[i].mutex, NULL);
    }
}

void cleanup_cache(hash_entry_t* cache, size_t cache_size) {
    for (size_t i = 0; i < cache_size; ++i) {
        pthread_mutex_destroy(&cache[i].mutex);
    }
    free(cache);
}

void* generate_rnti(void* arg) {
    struct populator_args* params = (struct populator_args*)arg;

    if (params->verbose) {
        printf("Generating new RNTI\n");
    }

    pthread_mutex_lock(&params->cache_mutex);
    hash_entry_t* cache = params->cache;
    size_t cache_size = params->cache_size;

    uint16_t rnti = 0;
    for (size_t i = 0; i < cache_size; ++i) {
        pthread_mutex_lock(&cache[i].mutex);
        if (cache[i].rnti == 0) {
            cache[i].rnti = rnti++;
            pthread_mutex_unlock(&cache[i].mutex);
            break;
        }
        pthread_mutex_unlock(&cache[i].mutex);
    }

    if (rnti == UINT16_MAX) { // Handle wraparound case
        rnti = 0;
    }

    pthread_mutex_unlock(&params->cache_mutex);

    return &rnti;
}

int populate_list(NFAPI_CRC_INDICATION_PDU_T* array, size_t size, size_t max_list_size, uint16_t min_rnti, uint16_t max_rnti, bool verbose, bool* used, hash_entry_t* cache, size_t cache_size, size_t memory_threshold) {
    if (max_list_size < size) {
        return -1; // Max list size exceeded
    }

    struct populator_args params = {
        .array = array,
        .size = size,
        .max_list_size = max_list_size,
        .min_rnti = min_rnti,
        .max_rnti = max_rnti,
        .verbose = verbose,
        .used = used,
        .cache = cache,
        .cache_size = cache_size,
        .cache_mutex = PTHREAD_MUTEX_INITIALIZER,
        .memory_threshold = memory_threshold,
    };

    if (cache_size == 0) {
        init_cache(&params.cache, HASH_TABLE_SIZE);
        params.cache_size = HASH_TABLE_SIZE;
    }

    pthread_t generate_rnti_threads[HASH_TABLE_SIZE];
    void* rnti_ptrs[HASH_TABLE_SIZE];

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_create(&generate_rnti_threads[i], NULL, generate_rnti, &params);
    }

    size_t successfully_created = 0;
    size_t used_count = 0;

    for (size_t i = 0; i < size && successfully_created < size; ++i) {
        // Acquire lock on memory threshold check and RNTI generation
        pthread_mutex_lock(&params.cache_mutex);

        bool can_create = true;
        for (size_t j = 0; j + 1 < successfully_created && j < i; ++j) {
            if (array[j].rnti == array[i].rnti) {
                can_create = false;
                break;
            }
        }

        if (!can_create || used_count >= max_list_size - size + i) {
            pthread_mutex_unlock(&params.cache_mutex);
            continue;
        }

        // Generate RNTI and set its corresponding flag in used array
        for (size_t j = 0; j < HASH_TABLE_SIZE; ++j) {
            if (rnti_ptrs[j] == NULL) {
                pthread_join(generate_rnti_threads[j], &rnti_ptrs[j]);
                break;
            }
        }

        used_count++;
        used[i] = true;

        NFAPI_CRC_INDICATION_PDU_T* current_element = array + i;
        current_element->rnti = *((uint16_t*)rnti_ptrs[0]);
        rnti_ptrs[0] = NULL; // Reset for reuse in the next iteration

        if (params.verbose) {
            printf("Created element with RNTI: %u\n", current_element->rnti);
        }

        successfully_created++;
        pthread_mutex_unlock(&params.cache_mutex);
    }

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_join(generate_rnti_threads[i], NULL);
    }

    if (successfully_created < size) {
        return -1; // Failed to create required elements
    }

    cleanup_cache(params.cache, params.cache_size);

    return 0;
}']

