#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct UEState {
    unsigned long ue_id;
    RadioResourceBlock* rrb;
    bool pending_tx;
    time_t last_active;
    void (*callback)(struct UEState*);
} UEState;

typedef struct UEStateList {
    UEState** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    time_t inactivity_timeout;
    void (*callback_fn)(UEState*, bool); // added callback function pointer
} UEStateList;

// Initialize UEStateList with a given inactivity timeout and callback function
void ue_state_list_init(UEStateList* list, time_t inactivity_timeout, void(*callback)(UEState*, bool)) {
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->inactivity_timeout = inactivity_timeout;
    list->callback_fn = callback;
}

// Allocate new UEState and append to UEStateList, returning its index or -1 on failure
int ue_state_append(UEStateList* list, unsigned long ue_id, RadioResourceBlock* rrb, bool pending_tx) {
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? (list->capacity * 2) : 8;
        UEState** temp = realloc(list->data, new_capacity * sizeof(UEState*));
        if (!temp) return -1;
        list->data = temp;
        list->capacity = new_capacity;
    }

    pthread_mutex_lock(&list->lock);
    UEState* state = malloc(sizeof(UEState));
    if (!state) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    state->ue_id = ue_id;
    state->rrb = rrb;
    state->pending_tx = pending_tx;
    time(&(state->last_active));
    list->data[list->size] = state;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return list->size - 1;
}

// Iterate over all active UE states, returning the number of iterations or zero on failure
size_t ue_state_iterate(UEStateList* list, void(*fn)(UEState*)) {
    if (!list || !list->data) return 0;
    pthread_mutex_lock(&list->lock);
    size_t count = 0;
    for (size_t i = 0; i < list->size; ++i) {
        UEState* state = list->data[i];
        if (!state || time(NULL) - state->last_active > list->inactivity_timeout) continue;
        fn(state);
        count++;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

// Clean up UEStateList, freeing all resources and closing the mutex
void ue_state_list_free(UEStateList* list) {
    if (!list || !list->data) return;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        UEState* state = list->data[i];
        free(state);
    }
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}
```

