#include <cstdlib>
#include <new>
#include <vector>
#include <mutex>

struct RNTIKey { long long int value; };
struct CRCIndicationPDU {
    RX_UE_INFORMATION_TAG tag;
    long long int rnti;
    CRC_INDICATION_REL8_TAG crcIndicatorTag;
    bool crcFlag;
};
using MemoryPool = std::vector<CRCIndicationPDU*>;
using RNTITable = std::unordered_map<RNTIKey, int>;
std::mutex mtx;
MemoryPool memoryPool;
RNTITable rntiTable;

CRCIndicationPDU* allocatePDU() {
    CRCIndicationPDU* pdu;
    if (memoryPool.empty()) {
        pdu = new CRCIndicationPDU();
        std::srand(std::time(nullptr));
        pdu->crcIndicatorTag.crcFlag = static_cast<uint8_t>(std::rand() & 1);
    } else {
        pdu = memoryPool.back();
        memoryPool.pop_back();
        pdu->crcIndicatorTag.crcFlag = static_cast<uint8_t>(std::rand() & 1);
    }
    return pdu;
}

void deallocatePDU(CRCIndicationPDU* pdu) {
    memoryPool.push_back(pdu);
}

bool allocateAndCheckRNTI(long long int rnti, CRCIndicationPDU** pPdu) {
    std::unique_lock<std::mutex> lock(mtx);
    if (rntiTable.find({rnti}) == rntiTable.end()) {
        rntiTable[{rnti}] = 1;
        *pPdu = allocatePDU();
        return true;
    } else {
        lock.unlock(); // release the lock for concurrent threads
        std::unique_lock<std::mutex> innerLock(mtx);
        while (rntiTable[{rnti}] > 1) {
            rnti++;
            if (rnti >= LLONG_MAX - 2) { // wrap around check
                std::cerr << "Error: RNTI overflow." << std::endl;
                return false;
            }
        }
        rntiTable[{rnti}] = 1;
        *pPdu = allocatePDU();
        return true;
    }
}

size_t getAllocatedStructuresCount() {
    std::unique_lock<std::mutex> lock(mtx);
    return rntiTable.size();
}
