// UE structure definition
struct UE {
    int ue_id;
    RadioResourceBlock* resource_block;
    bool has_pending_request;
};

class NetworkManager {
private:
    std::map<int, UE> ue_states; // thread-safe map to store UE states
    pthread_mutex_t mutex; // mutual exclusion lock for concurrent access

public:
    NetworkManager() {
        pthread_mutex_init(&mutex, NULL);
    }

    ~NetworkManager() {
        pthread_mutex_destroy(&mutex);
    }

    void addUE(int ue_id, RadioResourceBlock* resource_block, bool has_pending_request) {
        pthread_mutex_lock(&mutex);
        ue_states[ue_id] = {ue_id, resource_block, has_pending_request};
        pthread_mutex_unlock(&mutex);
    }

    UE* updateUE(int ue_id, RadioResourceBlock* resource_block, bool has_pending_request) {
        UE *ue;
        pthread_mutex_lock(&mutex);
        auto iter = ue_states.find(ue_id);
        if (iter != ue_states.end()) {
            ue = &iter->second;
            ue->resource_block = resource_block;
            ue->has_pending_request = has_pending_request;
        }
        pthread_mutex_unlock(&mutex);
        return ue;
    }

    void iterateUES(std::function<void(UE&)> callback) {
        pthread_mutex_lock(&mutex);
        for (auto &ue : ue_states) {
            callback(ue.second);
        }
        pthread_mutex_unlock(&mutex);
    }

    char* sizeLimitString(const char *input, int limit) {
        if (strlen(input) + 1 <= limit) {
            char* result = new char[limit];
            strncpy(result, input, limit - 1);
            strncat(result, "/", limit - strlen(result));
            return result;
        } else {
            return NULL;
        }
    }
};
