struct NetInterfaceConfig {
    char ifname[IF_NAMESIZE];
    char ipaddr[INET_ADDRSTRLEN];
    char netmask[INET_ADDRSTRLEN];
    int flags; // custom flags for your application
};

typedef struct ifaddrs IfAddr;
std::set<std::string> uniqueIPs; // to avoid duplicate IP addresses
std::map<std::string, NetInterfaceConfig> netConfigs; // dynamic list of network interface configurations
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER; // for handling race conditions in multi-threaded environment

void loadFromFile(const char* filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        printf("Error: Could not open configuration file.\n");
        return;
    }

    NetInterfaceConfig config;
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        if (!(iss >> config.ifname >> config.ipaddr >> config.netmask)) continue; // ignore invalid lines

        // check for duplicate IP addresses and skip them
        if (uniqueIPs.count(config.ipaddr)) continue;
        uniqueIPs.insert(config.ipaddr);

        netConfigs[config.ifname] = config;
    }
}

void addConfig(const char* ifname, const char* ipaddr, const char* netmask) {
    pthread_mutex_lock(&configMutex);
    NetInterfaceConfig config;
    strcpy(config.ifname, ifname);
    strcpy(config.ipaddr, ipaddr);
    strcpy(config.netmask, netmask);

    // check for duplicate IP addresses and skip them
    if (uniqueIPs.count(config.ipaddr)) {
        pthread_mutex_unlock(&configMutex);
        return;
    }

    uniqueIPs.insert(config.ipaddr);
    netConfigs[ifname] = config;
    pthread_mutex_unlock(&configMutex);
}

void removeConfig(const char* ifname) {
    pthread_mutex_lock(&configMutex);
    auto it = netConfigs.find(ifname);
    if (it == netConfigs.end()) {
        pthread_mutex_unlock(&configMutex);
        return;
    }

    uniqueIPs.erase(it->second.ipaddr);
    netConfigs.erase(it);
    pthread_mutex_unlock(&configMutex);
}

void updateConfig(const char* ifname, const char* ipaddr, const char* netmask) {
    pthread_mutex_lock(&configMutex);
    auto it = netConfigs.find(ifname);
    if (it == netConfigs.end()) {
        pthread_mutex_unlock(&configMutex);
        return;
    }

    strcpy(it->second.ipaddr, ipaddr);
    strcpy(it->second.netmask, netmask);

    // check for duplicate IP addresses and update only if no conflict
    if (uniqueIPs.count(it->second.ipaddr) && uniqueIPs.count(it->second.ipaddr) != it->first) {
        removeConfig(it->first);
        addConfig(ifname, ipaddr, netmask);
    }

    pthread_mutex_unlock(&configMutex);
}
