typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint64_t timestamp;
} network_data_t;

union_find_t* uf;

void processNetworkData(const char* str, int rnti) {
    network_data_t* data = malloc(sizeof(network_data_t));
    if (!data) return;

    gettimeofday(&(data->timestamp), NULL);
    data->pdu.RX_UE_INFORMATION_TAG = random() % 0xFFFFFFFF;
    data->pdu.RNTI = rnti;
    data->pdu.CRC_INDICATION_REL8_TAG = random() % 0xFFFFFFFF;
    data->pdu.CRCFLAG = (data->timestamp.tv_usec & 1) ? 1 : 0;

    uf_make_set(uf, data - (network_data_t*)calloc(1, sizeof(network_data_t)));
    uf_union(uf, data - uf->roots, rnti);

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), md5);

    double start = get_time();
    uint64_t hash = *(uint64_t*)md5;
    log_execution_time("MD5 Hash", start, get_time() - start);

    start = get_time();
    network_data_t* parent = uf_find_set(uf, data - uf->roots);
    log_execution_time("Union-Find", start, get_time() - start);

    free(parent);
    free(data);
}

double get_time() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (ts.tv_sec + ts.tv_nsec / 1000000000.0);
}
