typedef struct set {
    unsigned long parent;
    unsigned long rank;
} UFSET;

void uf_make_set(UFSET* set, int i) {
    set[i].parent = i;
    set[i].rank = 0;
}

int uf_find(UFSET* set, int i) {
    if (set[i].parent != i)
        set[i].parent = uf_find(set, set[i].parent);
    return set[i].parent;
}

void uf_union(UFSET* set, int x, int y) {
    int xroot = uf_find(set, x);
    int yroot = uf_find(set, y);

    if (set[xroot].rank < set[yroot].rank)
        set[xroot].parent = yroot;
    else if (set[xroot].rank > set[yroot].rank)
        set[yroot].parent = xroot;
    else {
        set[yroot].parent = xroot;
        set[xroot].rank++;
    }
}

