        pthread_create(&threads[i], NULL, process_dataset, data + i * BUFFER_SIZE);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], &results[i]);

        void* temp = realloc(final_results, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((i + 1) * BUFFER_SIZE));
