void list_push(struct list_data *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        list->head = list->tail = pdu;
    } else {
        list->tail->next = pdu;
        list->tail = pdu;
    }
    ++(list->size);
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T *list_pop(struct list_data *list) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        pdu = NULL;
    } else {
        pdu = list->head;
        list->head = list->head->next;
        --(list->size);
        if (!list->head) {
            list->tail = NULL;
        }
