    next_time.tv_sec += period_ms / 1000;
    next_time.tv_nsec += (period_ms % 1000) * 1000000;

    while (1) {
        clock_gettime(CLOCK_REALTIME, &next_time);
        if (next_time.tv_sec < time(NULL)) {
            next_time.tv_sec += period_ms / 1000;
            next_time.tv_nsec += (period_ms % 1000) * 1000000;
        }
        pthread_mutex_lock(&list->mutex);
        bool valid = true;
        NFAPI_CRC_INDICATION_PDU_T *pdu = list->head;
        while (pdu) {
            validate_crc(pdu, &valid);
            if (!valid) {
                break;
            }
            pdu = pdu->next;
        }
        pthread_mutex_unlock(&list->mutex);
        if (!valid) {
            // Handle invalid CRC cases here, such as logging or notifying higher-level components.
        }
        clock_gettime(CLOCK_REALTIME, &next_time);
    }
}
