    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
};

void shuffle(NFAPI_CRC_INDICATION_PDU_T *arr, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        size_t j = rand() % n;
        NFAPI_CRC_INDICATION_PDU_T temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

struct array_data* array_init() {
    struct array_data* data = malloc(sizeof(struct array_data));
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for array_data\n");
        return NULL;
    }
    pthread_mutex_init(&data->mutex, NULL);
    data->capacity = MAX_ELEMENTS;
    data->size = 0;
    data->data = malloc(data->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data->data) {
        fprintf(stderr, "Failed to allocate memory for array data\n");
        free(data);
        return NULL;
    }
    return data;
}

void array_push(struct array_data* data, const NFAPI_CRC_INDICATION_PDU_T elem) {
    pthread_mutex_lock(&data->mutex);

    if (data->size >= data->capacity) {
        fprintf(stderr, "Array is full. Cannot add element\n");
        pthread_mutex_unlock(&data->mutex);
        return;
    }

    memcpy((void*)&data->data[data->size], &elem, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->size++;

    if (data->size % SHUFFLE_INTERVAL == 0) {
        shuffle(data->data, data->size);
    }

    pthread_mutex_unlock(&data->mutex);
}

void array_pop(struct array_data* data, size_t index) {
    if (index >= data->size || index >= MAX_ELEMENTS) {
        fprintf(stderr, "Index out of bounds. Cannot remove element\n");
        return;
    }

    pthread_mutex_lock(&data->mutex);

    size_t last = --data->size;
    memcpy((void*)&data->data[index], &data->data[last], sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&data->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* array_get(struct array_data* data, size_t index) {
    if (index >= MAX_ELEMENTS) {
        fprintf(stderr, "Index out of bounds. Cannot get element\n");
        return NULL;
    }

    pthread_mutex_lock(&data->mutex);

    NFAPI_CRC_INDICATION_PDU_T* ret = &data->data[index];

    pthread_mutex_unlock(&data->mutex);
    return ret;
}
