void generateAndProcessCRCIndications(CRCIndicationList* list, size_t N) {
    if (N > 10000 || N == 0) return; // Validation for input parameter N

    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    list->capacity = N;
    list->size = 0;
