    srand(time(NULL)); // Generating a random seed based on current time

    sem_t semaphore;
    sem_init(&semaphore, 0, N); // Semaphore for concurrency control

    for (size_t i = 0; i < N; ++i) {
        bool duplicateRNTI = true;
        size_t rnti;
        do {
            rnti = rand() % 10000 + 1; // Generating RNTI values within the predefined range
            duplicateRNTI = false;

