        list->data[list->size].rxti = rand() % 256; // Generating RX_UE_INFORMATION_TAG value
        list->data[list->size].rnti = rnti;
        list->data[list->size].crcIndicationRel8Tag.crcflag = (rand() % 2) ? 1 : 0; // Setting CRCFLAG randomly

