void push_to_buffer(SensorData* sd, float value) {
    sem_wait(&sd->cb.mem_lock);

    size_t next = (sd->cb.head + 1) % sd->cb.capacity;

    if ((next - sd->cb.tail) == 1) {
        // Buffer is full, drop the oldest value and add new one
        sd->cb.buffer[sd->cb.tail] = value;
        sd->cb.tail = (sd->cb.tail + 1) % sd->cb.capacity;
    } else if ((next - sd->cb.tail) > sd->window_size) {
        // Window has passed, drop all but the window size of values and add new one
        size_t i = sd->cb.tail;
        for (int k = 0; k < sd->window_size; ++k) {
            if ((i + 1) == sd->cb.capacity) i = 0;
            sd->cb.buffer[i] = value;
            i = (i + 1);
        }
        sd->cb.tail = (sd->cb.tail + 1) % sd->cb.capacity;
