#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>

typedef struct {
    gid_t RNTI;
    unsigned char CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG *tag;
    struct lru_cache *cache;
    pthread_mutex_t lock;
} CONTEXT;

struct lru_node {
    struct lru_node *prev, *next;
    char ip[INET6_ADDRSTRLEN];
};

struct lru_cache {
    size_t capacity;
    size_t count;
    struct lru_node *head, *tail;
};

void lru_add(struct lru_cache *cache, const char *ip) {
    struct lru_node *node = malloc(sizeof(*node));
    if (!node) return;
    strcpy(node->ip, ip);
    node->prev = node->next = NULL;
    if (cache->count < cache->capacity) {
        if (cache->head == NULL) {
            cache->head = cache->tail = node;
            cache->count++;
            return;
        }
    } else {
        free(node);
        return;
    }
    struct lru_node *current = cache->head;
    if (cache->count == 1) {
        cache->tail = node;
    }
    while (current != cache->tail) {
        struct lru_node *next = current->next;
        if (next == NULL) break;
        if (lru_access(cache, current)) {
            node->next = next;
            node->prev = current;
            current->next = node;
            current = next;
            break;
        }
        current = next;
    }
    if (current == cache->tail) {
        cache->tail->next = node;
        node->prev = cache->tail;
        cache->tail = node;
    }
    cache->count++;
}

char *get_ip(CONTEXT *context, const char *hostname) {
    struct addrinfo hints, *result, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(hostname, NULL, &hints, &result);
    if (err) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(err));
        return NULL;
    }

    for (rp = result; rp != NULL; rp = rp->ai_next) {
        int family = rp->ai_family;
        char ipstr[INET6_ADDRSTRLEN];
        if (family == AF_INET) {
            struct sockaddr_in *sa = (struct sockaddr_in *)rp->ai_addr;
            inet_ntop(AF_INET, &sa->sin_addr, ipstr, sizeof(ipstr));
            lru_add(context->cache, ipstr);
            pthread_mutex_lock(&context->lock);
            free(rp->ai_canonname);
            rp->ai_canonname = NULL;
            pthread_mutex_unlock(&context->lock);
            free(rp->ai_addr);
            free(rp);
        } else {
            struct sockaddr_in6 *sa = (struct sockaddr_in6 *)rp->ai_addr;
            inet_ntop(AF_INET6, &sa->sin6_addr, ipstr, sizeof(ipstr));
            lru_add(context->cache, ipstr);
            pthread_mutex_lock(&context->lock);
            free(rp->ai_canonname);
            rp->ai_canonname = NULL;
            pthread_mutex_unlock(&context->lock);
            free(rp->ai_addr);
            free(rp);
        }
    }
    freeaddrinfo(result);

    pthread_mutex_lock(&context->lock);
    char *ip = context->cache->head->ip;
    struct lru_node *temp = context->cache->head;
    context->cache->head = temp->next;
    if (context->cache->head == NULL) {
        context->cache->tail = NULL;
    } else {
        temp->next->prev = NULL;
    }
    free(temp);
    context->count--;
    pthread_mutex_unlock(&context->lock);

    return ip;
}

CONTEXT *create_context(size_t capacity) {
    CONTEXT *context = malloc(sizeof(*context));
    if (!context) return NULL;
    context->cache = malloc(sizeof(*context->cache));
    if (!context->cache) goto error;
    context->cache->capacity = capacity;
    context->cache->count = 0;
    context->cache->head = context->cache->tail = NULL;
    pthread_mutex_init(&context->lock, NULL);
    return context;

error:
    free(context);
    return NULL;
}

void destroy_context(CONTEXT *context) {
    if (!context || !context->cache) return;
    while (context->cache->count > 0) {
        char *ip = context->cache->head->ip;
        struct lru_node *temp = context->cache->head;
        context->cache->head = temp->next;
        if (context->cache->head == NULL) {
            context->cache->tail = NULL;
        } else {
            temp->next->prev = NULL;
        }
        free(temp);
        context->cache->count--;
    }
    pthread_mutex_destroy(&context->lock);
    free(context->cache);
    free(context);
}
```

This code includes a dynamic list of `RX_UE_INFORMATION_TAG` structures, a cache for recently resolved IP addresses using an LRU eviction policy, and thread safety. The DNS resolution function uses the getaddrinfo() function from the standard library to perform the DNS lookup, and the cache is managed to avoid memory leaks. The context struct is created and destroyed with create_context() and destroy_context().']

