['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define NUM_THREADS 16
#define MAX_ELEMENTS 1024

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t list_notempty = PTHREAD_COND_INITIALIZER;
static int num_elements = 0;

void* thread_function(void* arg) {
    while (true) {
        pthread_mutex_lock(&list_mutex);
        if (num_elements < MAX_ELEMENTS) {
            NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_pdu) {
                pthread_mutex_unlock(&list_mutex);
                break;
            }

            memset(new_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            new_pdu->crc_indication.crccflag = (bool)rand() % 2;

            pdu_list[num_elements++] = new_pdu;
        }
        pthread_cond_signal(&list_notempty);
        pthread_mutex_unlock(&list_mutex);
    }
    return NULL;
}

void init_pdus() {
    pthread_t threads[NUM_THREADS];

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, &thread_function, NULL)) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

