// Define the MAC_PDU structure
typedef struct MAC_PDU {
    MAC_HEADER header;
    int lcid;
    uint8_t payload[1024]; // Adjust size as needed
} MAC_PDU;

#define MAX_ELEMENTS 5000
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t notifier_cond = PTHREAD_COND_INITIALIZER;
static MAC_PDU *array = NULL;
static int num_elements = 0, max_ops_until_retry = 500;
static time_t last_retry = 0;

// Function to add a new element to the dynamic array
void push(MAC_PDU new_pdu) {
    pthread_mutex_lock(&array_mutex);

    // Handle memory allocation failures gracefully
    if (num_elements >= MAX_ELEMENTS) {
        printf("Error: Reached maximum capacity of %d elements.\n", MAX_ELEMENTS);
        goto cleanup;
    }

    MAC_PDU *temp_array = realloc(array, sizeof(MAC_PDU) * (num_elements + 1));
    if (!temp_array) {
        printf("Error: Failed to allocate memory.\n");
        goto cleanup;
    }
    array = temp_array;
    array[num_elements] = new_pdu;

cleanup:
    pthread_mutex_unlock(&array_mutex);
}

// Function to remove an element by index
void pop(int index) {
    pthread_mutex_lock(&array_mutex);

    if (index < 0 || index >= num_elements) {
        printf("Error: Index out of bounds.\n");
        goto cleanup;
    }

    MAC_PDU *temp_array = malloc(sizeof(MAC_PDU) * (num_elements - 1));
    int i;
    for (i = 0; i < index; ++i) {
        temp_array[i] = array[i];
    }
    for (; i < num_elements - 1; ++i) {
        temp_array[i] = array[i + 1];
    }
    free(array);
    array = temp_array;
    --num_elements;

cleanup:
    pthread_mutex_unlock(&array_mutex);
}

// Function to retrieve an element by index
MAC_PDU get(int index) {
    pthread_mutex_lock(&array_mutex);

    if (index < 0 || index >= num_elements) {
        printf("Error: Index out of bounds.\n");
        MAC_PDU empty_pdu = { .header = {}, .lcid = -1, .payload = {} };
        goto cleanup;
    }

    MAC_PDU ret_pdu = array[index];
cleanup:
    pthread_mutex_unlock(&array_mutex);
    return ret_pdu;
}

// Function to retransmit packets based on the configurable timeout threshold
void retry_packets() {
    pthread_mutex_lock(&array_mutex);

    if (time(NULL) - last_retry >= max_ops_until_retry) {
        int i;
        for (i = 0; i < num_elements; ++i) {
            // Implement your retransmission logic here
        }
        last_retry = time(NULL);
    }

    pthread_mutex_unlock(&array_mutex);
}
