    if (lstat(filepath, &st) != 0 || st.st_size > FILE_SIZE_LIMIT) return NULL;

    bitmap = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fileno(fp = fopen(filepath, "r")), 0);
