};

class DynamicList {
private:
    std::list<NFAPI_CRC_INDICATION_PDU_T> data;
    pthread_mutex_t mutex;
    static constexpr int MAX_N = 10000;

public:
    explicit DynamicList(int n) {
        if (n > MAX_N)
            n = MAX_N;
        for (int i = 0; i < n; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rnti = rand() % RNTI_MAX; // Assuming RNTI_MAX is a predefined maximum value for RNTI
            pdu.crc_indication.crcflag = rand() % 2;
            data.push_back(pdu);
        }
    }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        pthread_mutex_lock(&mutex);
        data.push_back(pdu);
        pthread_mutex_unlock(&mutex);
    }

    const NFAPI_CRC_INDICATION_PDU_T& front() const {
        pthread_mutex_lock(&mutex);
        auto it = data.begin();
        if (it != data.end())
            it++;
        pthread_mutex_unlock(&mutex);
        return *it;
    }

    bool empty() const {
        pthread_mutex_lock(&mutex);
        auto it = data.begin();
        bool result = it == data.end();
        pthread_mutex_unlock(&mutex);
        return result;
    }
};
