struct MACEntityContext {
    std::vector<std::unique_ptr<MACEntity>> entities;
    std::atomic<size_t> current_entity_id{0};
    boost::lockfree::spsc_queue<std::unique_ptr<MACEntity>> queue;
    size_t max_entities;
    size_t min_entities;
    mutex log_mutex;

    MACEntityContext(size_t max, size_t min) : max_entities(max), min_entities(min) {}

    void add_entity(std::unique_ptr<MACEntity> entity, std::function<void()> on_success = [](), std::function<void(const std::string&)> on_error = [](const std::string&)) {
        if (entities.size() + 1 > max_entities) {
            on_error("Reached maximum number of entities");
            return;
        }

        std::unique_ptr<MACEntity> new_entity;
        {
            // If queue is full, add the entity to the vector instead.
            if (queue.full()) {
                entities.push_back(std::move(entity));
                new_entity = std::move(entities.back());
                entities.pop_back();
            } else {
                // Add the entity to the queue and increment the current entity id.
                new_entity = std::move(queue.enqueue());
                std::unique_lock<std::mutex> lock(log_mutex);
                log << "Added MAC Entity: ID=" << current_entity_id++ << std::endl;
            }
        }

        on_success();
    }

