#define MAX_LIST_SIZE 10000
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} node_t;

node_t* head = NULL;
int list_size = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

bool unique_rnti(uint32_t rnti) {
    node_t* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) return false;
        current = current->next;
    }
    return true;
}

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    if (unique_rnti(new_node->data.rnti)) {
        pthread_mutex_lock(&list_lock);
        if (head == NULL) {
            head = new_node;
        } else {
            node_t* current = head;
            while (current->next != NULL) current = current->next;
            current->next = new_node;
        }
        list_size++;
        pthread_mutex_unlock(&list_lock);
    } else {
        free(new_node);
    }
}

NFAPI_CRC_INDICATION_PDU_T* find(uint32_t rnti) {
    node_t* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) break;
        current = current->next;
    }
    return current ? &current->data : NULL;
}

void reset_crcflag(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = find(rnti);
    if (pdu) pdu->crc_indication.crcflag = !pdu->crc_indication.crcflag;
}
