```rust
use std::collections::HashSet;
use std::net::{TcpStream, Shutdown};
use reqwest::Client;
use rand::Rng;

mod pdu {
    pub struct NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: u32,
        rnti: u16,
        crc_indication_rel8_tag: bool,
    }
}

pub struct UEList {
    active_ues: std::sync::RwLock<Vec<NFAPI_CRC_INDICATION_PDU_T>>,
    max_ue_count: usize,
    rnti_set: HashSet<u16>,
}

impl UEList {
    pub fn new(max_ue_count: usize) -> Self {
        UEList {
            active_ues: std::sync::RwLock::new(Vec::with_capacity(max_ue_count)),
            max_ue_count,
            rnti_set: HashSet::new(),
        }
    }

    pub fn add(&self, pdu: NFAPI_CRC_INDICATION_PDU_T) {
        let mut active_ues = self.active_ues.write().unwrap();
        loop {
            if active_ues.len() < self.max_ue_count {
                // Ensure unique RNTI within the list
                if !self.rnti_set.contains(&pdu.rnti) {
                    active_ues.push(pdu);
                    self.rnti_set.insert(pdu.rnti);
                    break;
                }
            } else {
                // Resize the vector to accommodate new users
                let mut temp = Vec::with_capacity(active_ues.len() * 2);
                temp.append(&mut active_ues);
                active_ues = temp;
            }
        }
    }

    pub fn get_ue(&self, rnti: u16) -> Option<&NFAPI_CRC_INDICATION_PDU_T> {
        let active_ues = self.active_ues.read().unwrap();
        active_ues.iter().find(|pdu| pdu.rnti == rnti)
    }
}

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Self {
        let transport = reqwest::transport::Builder::new()
            .tls_client_manager(reqwest::tls::NativeTlsClient::new())
            .build();
        HttpClient {
            client: Client::builder()
                .default_headers(reqwest::header::HeaderMap::new())
                .transport(transport)
                .build()
                .unwrap(),
        }
    }

    pub fn request_builder(&self, url: &str) -> reqwest::blocking::RequestBuilder {
        self.client.get(url)
    }
}
