} PacketCaptureStructure;

struct NetworkMonitor {
    PacketCaptureStructure* packets;
    size_t capacity;
    size_t size;
    sem_t mutex;
    sem_t throttle;
};

void init_network_monitor(struct NetworkMonitor* nm, size_t initial_capacity) {
    nm->packets = calloc(initial_capacity, sizeof(PacketCaptureStructure));
    if (!nm->packets) {
        perror("Memory allocation failed");
        return;
    }

    nm->capacity = initial_capacity;
    nm->size = 0;

    sem_init(&nm->mutex, 0, 1);
    sem_init(&nm->throttle, 0, initial_capacity);
}

void free_network_monitor(struct NetworkMonitor* nm) {
    for (size_t i = 0; i < nm->size; ++i) {
        free(nm->packets[i].payload);
    }

    free(nm->packets);
    sem_destroy(&nm->mutex);
    sem_destroy(&nm->throttle);
}

void capture_packet(struct NetworkMonitor* nm) {
    // Implement your network interface capturing logic here,
    // populate IPHeader, UDPHeader, and generate random Payload data.
