int add_packet_to_network_monitor(struct NetworkMonitor* nm) {
    if (nm->size == nm->capacity) {
        nm->capacity *= 2;
        PacketCaptureStructure *new_packets = realloc(nm->packets, nm->capacity * sizeof(PacketCaptureStructure));
        if (!new_packets) {
            perror("Memory allocation failed");
            return -1;
        }
        nm->packets = new_packets;
    }

    sem_wait(&nm->throttle);

    capture_packet(nm);

    PacketCaptureStructure *current_packets = nm->packets;
    sem_wait(&nm->mutex);
    current_packets[nm->size++] = (PacketCaptureStructure){}; // Initialize the new structure
    sem_post(&nm->mutex);

    sem_post(&nm->throttle);

    return 0;
}

void take_snapshot(struct NetworkMonitor* nm, FILE *fp) {
    sem_wait(&nm->mutex);
    for (size_t i = 0; i < nm->size; ++i) {
        fwrite(&nm->packets[i], sizeof(PacketCaptureStructure), 1, fp);
    }
    sem_post(&nm->mutex);
}
