void gen_pseudo_random(uint32_t *output, size_t num_elements, uint64_t seed) {
    for (size_t i = 0; i < num_elements; ++i) {
        seed = ((seed * 1103515245 + 12345) << 16) ^ (seed >> 32);
        output[i] = seed;
    }
}

void log_message(const char *message) {
