void *create_pdu(void *arg) {
    size_t index = *(size_t *) arg;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *) arg[1];
    uint64_t seed = arg[2];

    pdus[index].rx_ue_information_tag = (uint32_t) index; // Replace with your implementation.
    pdus[index].rnti = index + 100;                        // Replace with your implementation.
    pdus[index].crc_indication_rel8_tag = index * 13;     // Replace with your implementation.

    pdus[index].crcflag = (pdus[index].crc_indication_rel8_tag & 0x7FFFFFFF) == 0;

    return NULL;
}

int create_and_populate_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t num_elements, uint64_t seed) {
    if (num_elements == 0 || pdus == NULL) {
        log_message("Invalid input parameters.");
        return -1;
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *) malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        log_message("Memory allocation failed.");
        return -1;
    }

    gen_pseudo_random((uint32_t *) *pdus, num_elements, seed);

    void *thread_args[MAX_THREADS];
    for (size_t i = 0; i < num_elements / MAX_THREADS; ++i) {
        thread_args[i*MAX_THREADS] = &i;
        thread_args[i*MAX_THREADS + 1] = *pdus;
        thread_args[i*MAX_THREADS + 2] = seed;
        pthread_t thread;
        pthread_create(&thread, NULL, create_pdu, thread_args[i*MAX_THREADS]);
    }

    for (size_t i = 0; i < num_elements / MAX_THREADS; ++i) {
        pthread_join(thread, NULL);
    }

    log_message(sprintf("Successfully created %zu PDUs.", num_elements));
    return 0;
}
