typedef struct _NFAPI_MESSAGE_T {
    uint64_t UE_ID;
    uint16_t PDCP_SN;
    enum { STOP, IDLE, ACTIVE } RLC_STATUS;
    enum { TYPE_A, TYPE_B, CUSTOM } message_type;
    pthread_mutex_t lock;
    int sequence_number;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* create_message(uint64_t UE_ID, enum message_type type, int sequence_number) {
    NFAPI_MESSAGE_T *msg = malloc(sizeof(NFAPI_MESSAGE_T));
    if (!msg) return NULL;

    msg->UE_ID = UE_ID;
    msg->message_type = type;
    msg->sequence_number = sequence_number;
    pthread_mutex_init(&msg->lock, NULL);
    return msg;
}

void destroy_message(NFAPI_MESSAGE_T **msg) {
    if (!msg || !*msg) return;
    free(*msg);
    *msg = NULL;
}

NFAPI_MESSAGE_T** init_messages(size_t N, bool use_sequence_numbers, enum message_type default_message_type) {
    NFAPI_MESSAGE_T **msgs = calloc(N, sizeof(NFAPI_MESSAGE_T*));
    if (!msgs) return NULL;

    for (size_t i = 0; i < N; ++i) {
        msgs[i] = create_message((uint64_t)i, default_message_type, use_sequence_numbers ? i : -1);
        if (!msgs[i]) {
            for (size_t j = 0; j < i; ++j)
                destroy_message(&msgs[j]);
            free(msgs);
            return NULL;
        }
    }
    return msgs;
}

void delete_messages(NFAPI_MESSAGE_T **msgs, size_t N) {
    for (size_t i = 0; i < N; ++i)
        destroy_message(&msgs[i]);
    free(msgs);
}

bool update_message(NFAPI_MESSAGE_T **msgs, size_t index, uint64_t UE_ID, enum message_type type, int sequence_number) {
    if (index >= msgs ? NULL : msgs[index]) {
        pthread_mutex_lock(&msgs[index]->lock);

        if (msgs[index]->UE_ID == UE_ID && msgs[index]->message_type == type) {
            msgs[index]->sequence_number = sequence_number;
            pthread_mutex_unlock(&msgs[index]->lock);
            return true;
        }
        pthread_mutex_unlock(&msgs[index]->lock);
    }
    return false;
}

NFAPI_MESSAGE_T* get_message(NFAPI_MESSAGE_T **msgs, size_t index) {
    if (index >= msgs ? NULL : msgs[index])
        pthread_mutex_lock(&msgs[index]->lock);
    return msgs[index];
}
