} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} list_node_t;

struct list {
    unsigned int capacity;
    unsigned int size;
    list_node_t *head;
    list_node_t *tail;
    pthread_mutex_t mutex;
    pthread_cond_t notifier;
};

void list_init(struct list *list, unsigned int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->notifier, NULL);
}

void list_destroy(struct list *list) {
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->notifier);
    while (list->size > 0) {
        list_node_t *temp = list->head;
        list->head = temp->next;
        free(temp);
        --list->size;
    }
}

bool list_is_full(const struct list *list) {
    return list->size >= list->capacity;
}

void list_add(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list_is_full(list)) {
        unsigned int new_capacity = list->capacity * 2;
        while (list_is_full(list)) {
            new_capacity *= 2;
        }
        list_resize(list, new_capacity);
    }

    list_node_t *new_node = malloc(sizeof(list_node_t));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&list->mutex);
        return;
