    new_node->data = data;
    new_node->next = NULL;

    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

void list_resize(struct list *list, unsigned int new_capacity) {
    if (new_capacity <= list->capacity) {
        return;
    }

    unsigned int i;
    list_node_t **nodes = malloc(sizeof(list_node_t *) * new_capacity);
    if (!nodes) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    for (i = 0; i < new_capacity; ++i) {
        nodes[i] = NULL;
    }

    list_node_t *current = list->head;
    while (current != NULL) {
        list_node_t *next = current->next;
        unsigned int index = current->data.rnti % new_capacity;
        current->next = nodes[index];
        nodes[index] = current;
        current = next;
    }

    free(list->head);
    list->head = nodes[0];
    list->tail = nodes[new_capacity - 1];
    list->capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* list_retrieve(struct list *list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);
    list_node_t *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *data = current->data;
            list_node_t *temp = current;
            current = current->next;
            free(temp);
            pthread_mutex_unlock(&list->mutex);
            return data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void list_remove(struct list *list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);
    list_node_t *current = list->head;
    list_node_t **prev = &list->head;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            *prev = current->next;
            free(current);
            --list->size;
            break;
        }
        prev = &current->next;
        current = current->next;
    }

    if (list_is_empty(list)) {
        list->head = NULL;
        list->tail = NULL;
    }
    pthread_mutex_unlock(&list->mutex);
}

bool list_is_empty(const struct list *list) {
    return list->size == 0;
}

void list_notify(struct list *list) {
    pthread_mutex_lock(&list->mutex);
    pthread_cond_signal(&list->notifier);
    pthread_mutex_unlock(&list->mutex);
}

void list_wait(struct list *list, bool *empty) {
    pthread_mutex_lock(&list->mutex);
    while (!list_is_empty(list)) {
        pthread_cond_wait(&list->notifier, &list->mutex);
    }
    *empty = true;
    pthread_mutex_unlock(&list->mutex);
}
```
