```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structures and macros
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG ctag;
} NFAPI_CRC_INDICATION_PDU_T;

#define IS_VALID_CRC(crci) ((crci.crcflag ^ (crci.crc >> 4)) & 0x1)

// Global variables
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *list = NULL;
size_t capacity = 0;
size_t head = 0, tail = 0;
unsigned int num_valid = 0, num_invalid = 0;
char* filename = "output.txt";
int log_interval = 1000; // number of CRC indications to log before flushing
time_t last_flush = 0;

// Function to validate and add a CRC indication to the list
void push(NFAPI_CRC_INDICATION_PDU_T crci) {
    if (IS_VALID_CRC(crci)) {
        ++num_valid;
    } else {
        ++num_invalid;
    }

    pthread_mutex_lock(&list_lock);

    // Handle the circular buffer
    if ((head + 1) % capacity == tail) {
        // Buffer is full, flush to disk and remove the first element
        if (time(NULL) - last_flush > log_interval) {
            flush_to_file();
            last_flush = time(NULL);
            head = (head + 1) % capacity;
        } else {
            // Buffer is full but we can't flush yet, discard the new element and unlock the mutex
            pthread_mutex_unlock(&list_lock);
            return;
        }
    }

    list[head].tag = crci.tag;
    list[head].rnti = crci.rnti;
    list[head].ctag = crci.ctag;
    head = (head + 1) % capacity;

    pthread_mutex_unlock(&list_lock);
}

// Function to flush the data to a file in the specified format
void flush_to_file() {
    FILE *fp = fopen(filename, "a");
    if (fp != NULL) {
        fprintf(fp, "%llu,%d,%d\n", time(NULL), num_valid, num_invalid);
        fclose(fp);
    }
}
```

