#include <hash_map.h> // Assume you have a predefined hash table implementation

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    int capacity;
    int size;
    Node **table; // Hash table for RNTI values
    pthread_mutex_t mutex;
};

void init_list(struct list* list, int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->table = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i)
        list->table[i] = NULL;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void destroy_list(struct list* list) {
    for (int i = 0; i < list->capacity; ++i) {
        Node *node = list->table[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(list->table);
}

bool insert_element(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        resize_list(list, list->capacity * 2);
    }
    uint32_t hash = hash_function(data.rnti);
    Node **slot = &list->table[hash % list->capacity];
    Node *current = *slot;
    while (current != NULL && current->data.rnti == data.rnti) {
        current = current->next;
    }
    if (current == *slot) { // This is the first entry for this RNTI
        *slot = malloc(sizeof(Node));
        (*slot)->data = data;
        (*slot)->next = NULL;
        ++list->size;
    } else {
        Node *new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = current;
        if (current != NULL)
            current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void remove_element(struct list* list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);
    uint32_t hash = hash_function(rnti);
    Node **slot = &list->table[hash % list->capacity];
    Node *current = *slot;
    if (current == NULL) return; // No entry for this RNTI
    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }
    if (current == NULL) return; // No matching RNTI found

    if (current == *slot) { // Removing the first entry for this RNTI
        *slot = current->next;
    } else {
        Node *prev = *slot;
        while (prev->next != current) prev = prev->next;
        prev->next = current->next;
    }
    free(current);
    --list->size;
    pthread_mutex_unlock(&list->mutex);
}

void sort_list(struct list* list) {
    if (list->size <= 1) return; // No need to sort for small lists
    pthread_mutex_lock(&list->mutex);
    Node** temp = malloc(list->capacity * sizeof(Node*));
    memcpy(temp, list->table, list->capacity * sizeof(Node*));
    qsort(temp, list->size, sizeof(Node*), compare_nodes);
    for (int i = 0; i < list->capacity; ++i)
        list->table[i] = temp[i];
    pthread_mutex_unlock(&list->mutex);
}

void resize_list(struct list* list, int new_capacity) {
    if (new_capacity <= list->capacity) return; // No need to resize if capacity is not increasing

    Node **new_table = malloc(new_capacity * sizeof(Node*));
    for (int i = 0; i < new_capacity; ++i)
        new_table[i] = NULL;

    int old_size = list->size;
    for (int i = 0; i < list->capacity; ++i) {
        Node *current = list->table[i];
        while (current != NULL) {
            Node *next = current->next;
            uint32_t hash = hash_function(current->data.rnti);
            int slot = (hash % new_capacity);
            current->next = new_table[slot];
            new_table[slot] = current;
            current = next;
        }
    }
    free(list->table);
    list->table = new_table;
    list->capacity = new_capacity;
}

int hash_function(uint32_t key) {
    // Use a simple hash function like the one below or use a better hashing algorithm for performance purposes.
    return key % list->capacity;
}

int compare_nodes(const void *a, const void *b) {
    return ((((Node*)a)->data.timestamp - ((Node*)b)->data.timestamp));
}
