typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint64_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    timestamp_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

// Hash table structure for tracking unique RNTI values and maintaining a count of these unique entries.
typedef struct hash_table {
    struct node** table;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

void init_hash_table(HashTable* table) {
    table->size = HASH_TABLE_SIZE;
    table->count = 0;
    table->table = calloc(table->size, sizeof(Node*));
    if (!table->table) {
        perror("Failed to initialize hash table");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&table->lock, NULL);
}

unsigned long hash(uint64_t key) {
    return key % HASH_TABLE_SIZE;
}

void insert_hash_table(HashTable* table, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(data->rnti);
    Node** slot = &table->table[index];
    if (!*slot) {
        *slot = malloc(sizeof(Node));
        if (!*slot) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&table->lock);
            exit(EXIT_FAILURE);
        }
        (*slot)->data = *data;
        (*slot)->next = NULL;
        table->count++;
    } else {
        Node* current = *slot;
        while (current->next)
            current = current->next;

        current->next = malloc(sizeof(Node));
        if (!current->next) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&table->lock);
            exit(EXIT_FAILURE);
        }
        current->next->data = *data;
        current->next->next = NULL;
    }
    pthread_mutex_unlock(&table->lock);
}

