pthread_mutex_t dns_cache_mutex = PTHREAD_MUTEX_INITIALIZER;
char *dns_cache[1024]; // DNS cache array
int dns_cache_size = 0;
time_t dns_cache_expiry_timeout = 60; // DNS cache expiry timeout in seconds

MYSQL *connection_pool = NULL;
int num_connections = 10; // Number of connections in the pool

void *resolve_dns(const char *host) {
    struct hostent *result = gethostbyname(host);

    pthread_mutex_lock(&dns_cache_mutex);

    if (result && time(NULL) < dns_cache_expiry_timeout + dns_cache[dns_cache_size - 1]) {
        memcpy(result, dns_cache[dns_cache_size - 1], sizeof(struct hostent));
    } else {
        memset(dns_cache + dns_cache_size, 0, sizeof(char *) * (1024 - dns_cache_size));
        dns_cache_size = (dns_cache_size + 1) % 1024;
        memcpy(dns_cache[dns_cache_size], result, sizeof(struct hostent));
    }

    pthread_mutex_unlock(&dns_cache_mutex);

    return result;
}

void cleanup_mysql(MYSQL *mysql) {
    mysql_close(mysql);
    free(mysql);
}

MYSQL *get_connection() {
    if (!connection_pool) {
        connection_pool = malloc(num_connections * sizeof(MYSQL));

        for (int i = 0; i < num_connections; ++i) {
            connection_pool[i] = mysql_init(NULL);
            if (!connection_pool[i]) {
                fprintf(stderr, "Failed to initialize MySQL connection\n");
                cleanup_mysql(connection_pool);
                exit(1);
            }
        }
    }

    for (int i = 0; i < num_connections; ++i) {
        if (!mysql_ping(connection_pool[i])) {
            return connection_pool[i];
        }
    }

    // If all connections are busy, create a new one.
