#define MAX_LIST_SIZE 50000
#define MEMORY_THRESHOLD (MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T) / 2)

static NFAPI_CRC_INDICATION_PDU_T* head = NULL;
static NFAPI_CRC_INDICATION_PDU_T* tail = NULL;
static size_t list_size = 0;
static size_t memory_used = 0;
static clock_t start_time;

void log_metrics() {
    printf("Memory usage: %ld bytes\n", memory_used);
    printf("Processing time: %.6f seconds\n", (double)(clock() - start_time) / CLOCKS_PER_SEC);
}

void init_prng(uint32_t seed) {
    srand(seed);
}

uint32_t generate_crcflag(uint32_t rnti) {
    uint32_t prng = rand();
    return (rnti ^ prng) & 0xFFFFFFFF;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        if (list_size > MEMORY_THRESHOLD) {
            log_metrics();
            free_list();
            start_time = clock();
        }
    }
    if (new_node) {
        new_node->RNTI = entry.RNTI;
        new_node->CRC_INDICATION_REL8_TAG = entry.CRC_INDICATION_REL8_TAG;
        new_node->CRCFLAG = generate_crcflag(entry.RNTI);

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
        list_size++;
        memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

void remove_entry(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            if (current == head) {
                head = current->next;
            } else if (current == tail) {
                tail = current->prev;
                tail->next = NULL;
            } else {
                current->prev->next = current->next;
                if (current->next != NULL) {
                    current->next->prev = current->prev;
                } else {
                    tail = current->prev;
                }
            }
            free(current);
            list_size--;
            memory_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            break;
        }
        current = current->next;
    }
}

void free_list() {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (head) {
        head = head->next;
        free(current);
        current = head;
    }
    head = tail = NULL;
    list_size = 0;
    memory_used = 0;
}
```

