void generateUniqueSeed() {
    auto now = std::chrono::system_clock::now().time_since_epoch();
    auto duration = now.count();
    uint64_t pid = std::getpid();

    // hash the values using xorshift128+
    uint64_t combined = (duration ^ pid) + 0x9e3779b97f4a7c15;
    seed.store(combined, std::memory_order_relaxed);
}

NFAPI_CRC_INDICATION_PDU_T* generateStructures(size_t num) {
    if (num > MAX_STRUCTURES) throw "Number of structures exceeds the maximum allowed.";

