        for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
            structures[i].crd_indication_rel8_tag.CRCFLAG.store(0, std::memory_order_relaxed);
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* first = structures.data();
    auto last = first + num;

    for (auto p = first + MAX_STRUCTURES; p != last; ++p) {
