    buf->count = 0;
    sem_init(&buf->full, 0, 0);
    sem_init(&buf->empty, 0, capacity);
    buf->messages = malloc(sizeof(LTE_RRC_MESSAGE_T) * capacity);
    pthread_mutex_init(&buf->mutex, NULL);
}

void buffer_push(struct buffer* buf, LTE_RRC_MESSAGE_T msg) {
