    pthread_mutex_lock(&buf->mutex);
    while (sem_trywait(&buf->full) != 0) {
        pthread_mutex_unlock(&buf->mutex);
        sem_wait(&buf->empty);
        pthread_mutex_lock(&buf->mutex);
    }
    buf->messages[buf->count] = msg;
    ++buf->count;
    sem_post(&buf->empty);
    pthread_mutex_unlock(&buf->mutex);
}

LTE_RRC_MESSAGE_T buffer_pop(struct buffer* buf) {
    LTE_RRC_MESSAGE_T msg;
    pthread_mutex_lock(&buf->mutex);
    while (sem_trywait(&buf->empty) != 0) {
        pthread_mutex_unlock(&buf->mutex);
        sem_wait(&buf->full);
        pthread_mutex_lock(&buf->mutex);
    }
    msg = buf->messages[buf->count - 1];
    memcpy(buf->messages + buf->count - 1, buf->messages, sizeof(LTE_RRC_MESSAGE_T) * (buf->capacity - buf->count));
    --buf->count;
    sem_post(&buf->full);
    pthread_mutex_unlock(&buf->mutex);
    return msg;
}

void buffer_free(struct buffer* buf) {
    free(buf->messages);
    sem_destroy(&buf->full);
    sem_destroy(&buf->empty);
    pthread_mutex_destroy(&buf->mutex);
}
