    return (current_index + 1) % array_length;
}

void resize_list(struct list *list) {
    ListNode **new_nodes = realloc(list->nodes, (list->capacity * 2 + 1) * sizeof(ListNode *));
    if (!new_nodes) return;
    list->nodes = new_nodes;
    list->capacity *= 2;
}

void push_back(struct list *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) resize_list(list);
    ListNode **current = &list->nodes[list->count];
    *current = malloc(sizeof(ListNode));
    if (!*current) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    (*current)->data = *data;
    (*current)->next = NULL;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_first(struct list *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == 0) {
        pthread_mutex_unlock(&list->mutex);
