typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolEntry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PoolEntry* next;
} PoolEntry;

struct ImageMetadata {
    char file_path[256];
    int width, height, bits_per_sample, samples_per_pixel, color_profile_valid;
};

void* GenerateCRCFLAG(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)data;
    pdu->crc_indication.crcflag = rand();
    return NULL;
}

PoolEntry* create_pool(size_t entries) {
    PoolEntry *head, *current, *new_node;
    head = current = NULL;

    for (size_t i = 0; i < entries; ++i) {
        new_node = (PoolEntry*)malloc(sizeof(PoolEntry));
        if (!new_node) {
            perror("Error allocating memory");
            exit(1);
        }
        new_node->pdu.crc_indication.crcflag = 0; // initialize to avoid reusing uninitialized data
        new_node->next = NULL;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = current->next;
        }
    }

    pthread_t threads[entries];
    for (size_t i = 0; i < entries; ++i) {
        if (pthread_create(&threads[i], NULL, GenerateCRCFLAG, &head->pdu)) {
            perror("Error creating thread");
            exit(1);
        }
    }

    for (size_t i = 0; i < entries; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            exit(1);
        }
    }

    return head;
}

void destroy_pool(PoolEntry* pool) {
    PoolEntry *current, *next;

    for (current = pool; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
}

void log_error(const char* message) {
    printf("[Error] %s\n", message);
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, message, strlen(message));
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_Final(digest, &ctx);

    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        printf("%02x", digest[i]);
    }
    printf("\n");
}

