        return;
    }

    *pool = create_pool(entries);
    if (!*pool) {
        log_error("Memory exhaustion or allocation failure during pool initialization");
        return;
    }

    FILE* fp = fopen(metadata_file, "r");
    if (!fp) {
        log_error("Unable to open metadata file");
        destroy_pool(*pool);
        return;
    }

    ImageMetadata img_meta;
