typedef enum { NONE, INFO, DEBUG } LOGGING_LEVEL;
LOGGING_LEVEL logging_level = NONE;

#define MAX_MEMORY_THRESHOLD (10 * 1024 * 1024) // Set your desired maximum memory threshold here (e.g., 10 MB)

struct pdcp_entity {
    MAC_ENTITY_STATISTICS* stats;
    struct pdcp_entity* next;
};

int create_pdcp_entities(struct pdcp_entity** head, int num_entities, LOGGING_LEVEL log_level) {
    unsigned long total_size = sizeof(MAC_ENTITY_STATISTICS) * num_entities;
    struct pdcp_entity* current = NULL, *new_entity, *temp;
    int i;

    if (!total_size || total_size > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Invalid number of entities or memory exceeds threshold.\n");
        return -1;
    }

    current = (struct pdcp_entity*)malloc(sizeof(struct pdcp_entity));
    if (!current) {
        perror("Memory allocation failure\n");
        return -1;
    }

    current->stats = (MAC_ENTITY_STATISTICS*)calloc(num_entities, sizeof(MAC_ENTITY_STATISTICS));
    if (!current->stats) {
        free(current);
        perror("Memory allocation failure\n");
        return -1;
    }

    current->next = NULL;

    *head = current;

    for (i = 1; i < num_entities; ++i) {
        new_entity = (struct pdcp_entity*)malloc(sizeof(struct pdcp_entity));
        if (!new_entity) {
            perror("Memory allocation failure\n");
            return -1;
        }

        new_entity->stats = current->stats + i;
        new_entity->next = NULL;

        if (current->next) {
            temp = current->next;
            while (temp->next)
                temp = temp->next;
            temp->next = new_entity;
        } else {
            current->next = new_entity;
        }
    }

    if (log_level >= INFO) {
        printf("Created %d PDCP entities.\n", num_entities);
        for (i = 0; i < num_entities; ++i)
            printf("PDCP_CONTEXT_ID: %u, SNR: %.2f, ACK/NACK: %u\n",
                   current->stats[i].PDCP_CONTEXT_ID, current->stats[i].SNR,
                   current->stats[i].ACK_NACK);
    }

    return 0;
}

