class PDUList {
private:
    boost::circular_buffer<char> cb_;
    boost::lockfree::slist<NFAPI_CRC_INDICATION_PDU_T> list_;
    std::atomic_uint64_t next_index_{0};

public:
    PDUList() : cb_(cb_buffer_size) {}

    void push(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
