        char* data = cb_.data();
        boost::serialization::serialize(data, pdu);
        list_.push_back(NFAPI_CRC_INDICATION_PDU_T(*reinterpret_cast<const NFAPI_CRC_INDICATION_PDU_T*>(data)));
    }

    void pop(NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (list_.empty()) {
            throw std::runtime_error("Error: List is empty.");
        }

        auto it = list_.begin();
        char* data = const_cast<char*>(reinterpret_cast<const char*>(&(*it)));
        boost::serialization::deserialize(data, pdu);
        list_.pop_front();
    }

    void serializeToFile(const std::string& filename) {
        nlohmann::json j;
        for (auto it = list_.begin(), end = list_.end(); it != end; ++it) {
            j.push_back(it->toJson());
        }
        std::ofstream outfile(filename);
        outfile << j.dump(4);
    }

    void deserializeFromFile(const std::string& filename) {
        std::ifstream infile(filename);
        nlohmann::json j;
        infile >> j;

        for (auto it = j.begin(); it != j.end(); ++it) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.fromJson(*it);
            push(pdu);
        }
    }
};
