}

void link_nodes(CRC_INDICATION_PDU_T **head, CRC_INDICATION_PDU_T *node) {
    if (!*head) {
        *head = node;
        node->prev = NULL;
        node->next = NULL;
    } else {
        node->next = *head;
        (*head)->prev = node;
        *head = node;
        node->prev = NULL;
    }
}

void unlink_node(CRC_INDICATION_PDU_T **head, CRC_INDICATION_PDU_T *node) {
    if (node == *head && !(*head)->next) {
        free(*head);
        *head = NULL;
    } else if (node->prev) {
        node->prev->next = node->next;
        if (node->next)
            node->next->prev = node->prev;
    } else {
        *head = node->next;
        if (*head)
            (*head)->prev = NULL;
    }

    free(node);
}

void process_records(CRC_INDICATION_PDU_T **head, void(*process_func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    CRC_INDICATION_PDU_T *current = *head;
    while (current) {
        process_func(current);
        current = current->next;
    }
}

