typedef struct {
    uint32_t rxti;
    uint16_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

union-find {
    int data;
    struct {
        int parent;
        bool root;
    } uf;
};

struct timeval start, end;
double elapsed;

int* array;
pthread_mutex_t mutex;

NFAPI_CRC_INDICATION_PDU_T* createAndProcessNFAPIData(int N) {
    NFAPI_CRC_INDICATION_PDU_T *data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    union-find *uf_array = calloc(N, sizeof(union-find));

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; ++i) {
        gettimeofday(&start, NULL);

        data[i].rxti = i + 1;
        data[i].rnti = rand() % 0xFFFF;
        data[i].crcflag = rand() % 2;

        pthread_mutex_lock(&mutex);
        int root = uf_array[i].uf.parent == -1 ? true : uf_array[uf_array[i].uf.parent].uf.root;
        if (root) {
            uf_array[i].uf.parent = i;
        } else {
            int parent = uf_array[uf_array[i].uf.parent].uf.parent;
            while (parent != -1 && uf_array[parent].uf.root) {
                parent = uf_array[parent].uf.parent;
            }
            if (parent != -1) {
                uf_array[i].uf.parent = parent;
            } else {
                parent = -1;
            }
            uf_array[parent] = (union-find){ .data = i, .uf = { .parent = -1, .root = true } };
        }
        pthread_mutex_unlock(&mutex);

        gettimeofday(&end, NULL);
        elapsed = 1000.0 * (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000;
        printf("Time taken to populate structure %d: %f ms\n", i, elapsed);
    }

    pthread_mutex_destroy(&mutex);
    free(uf_array);

    return data;
}
