    if (!arr) return NULL;
    arr->capacity = 1024;
    arr->size = 0;
    arr->data = calloc(arr->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

bool crc_array_push(CRCIArray *arr, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (arr->size == arr->capacity) {
        size_t new_cap = arr->capacity + 1024;
        void *tmp = mmap(NULL, new_cap * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (tmp == MAP_FAILED) {
            pthread_mutex_destroy(&arr->lock);
            free(arr->data);
            free(arr);
            return false;
        }
        memcpy(tmp + arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->data, arr->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        munmap((void*)arr->data, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr->data = tmp;
        arr->capacity = new_cap;
    }

    pthread_mutex_lock(&arr->lock);

    size_t i;
    for (i = 0; i < arr->size; ++i) {
        if (arr->data[i].RNTI == pdu->RNTI && arr->data[i].RX_UE_INFORMATION_TAG != pdu->RX_UE_INFORMATION_TAG) {
            pthread_mutex_unlock(&arr->lock);
            return false;
        }
