    arr->data[arr->size] = *pdu;
    ++arr->size;

    pthread_mutex_unlock(&arr->lock);
    return true;
}

void crc_array_remove(CRCIArray *arr, uint16_t rnti) {
    if (arr->size == 0) return;

    pthread_mutex_lock(&arr->lock);

    size_t i;
    for (i = 0; i < arr->size; ++i) {
        if (arr->data[i].RNTI == rnti) {
            memmove(arr->data + i, arr->data + i + 1, (arr->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --arr->size;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

int crc_array_integrity_check(const CRCIArray *arr) {
    if (arr == NULL || arr->size <= 0) return 1;

    size_t i, j;
    for (i = 0; i < arr->size - 1; ++i) {
        for (j = i + 1; j < arr->size; ++j) {
            if (arr->data[i].RNTI >= arr->data[j].RNTI && arr->data[i].RNTI <= arr->data[j].RNTI + 1)
                return 2;
        }
    }
    return 0;
}

void crc_array_destroy(CRCIArray *arr) {
    if (arr != NULL) {
        free(arr->data);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
