const size_t WHITELIST_SIZE = sizeof(WHITELIST) / sizeof(uint32_t);

// Thread-safe buffer and access control
static sem_t pdu_mutex;
static NFAPI_L1_LOGGING_PDU_T *pdu_buffer;
static size_t pdu_buffer_size = 0;
