static const size_t MAX_PDUs = 10000; // Adjust as needed

// Callback function to handle errors or logging failures
typedef void (*error_callback_t)(const char* error_message);
error_callback_t g_error_callback = nullptr;

void nfapi_l1_logging_pdu_init(error_callback_t callback) {
    pthread_attr_t attr;
    pthread_mutexattr_t mutex_attr;
    sem_t log_semaphore;

    // Initialize pthread attributes
    pthread_attr_init(&attr);
    pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM);

    // Initialize mutex attributes
    pthread_mutexattr_init(&mutex_attr);
    pthread_mutexattr_settype(&mutex_attr, PTHREAD_MUTEX_RECURSIVE);

    // Initialize logging semaphore
    sem_init(&log_semaphore, 0, 1);
    sem_init(&pdu_mutex, 0, 1);

    // Set error callback
    g_error_callback = callback;

    // Map memory for the PDUs buffer
    pdu_buffer = mmap(NULL, sizeof(NFAPI_L1_LOGGING_PDU_T) * MAX_PDUs, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pdu_buffer == MAP_FAILED) {
        if (g_error_callback) g_error_callback("Failed to allocate PDUs buffer memory");
        return;
    }

    // Initialize log file and rotation strategy
    log_fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND | O_DIRECT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_fd == -1) {
        if (g_error_callback) g_error_callback("Failed to open log file");
        munmap(pdu_buffer, sizeof(NFAPI_L1_LOGGING_PDU_T) * MAX_PDUs);
        return;
    }
}

void nfapi_l1_logging_pdu_add(const NFAPI_L1_LOGGING_PDU_T* pdu, bool update_log_file) {
    time_t current_time = time(NULL);
    const time_t TIME_WINDOW = 60; // Adjust as needed (seconds)

    // Validate session ID and timestamps
    if (current_time - pdu->timestamp > TIME_WINDOW || !in_array(pdu->session_id, WHITELIST, WHITELIST_SIZE)) {
        if (g_error_callback) g_error_callback("Invalid session ID or timestamp");
        return;
    }

    // Acquire mutex and check for concurrent access limit
    sem_wait(&pdu_mutex);
    if (current_index == pdu_buffer_size) {
        if (g_error_callback) g_error_callback("PDUs buffer is full");
        sem_post(&pdu_mutex);
        return;
    }

    // Copy PDU to the buffer and update counters
    memcpy(&(pdu_buffer[current_index]), pdu, sizeof(NFAPI_L1_LOGGING_PDU_T));
    current_index = (current_index + 1) % MAX_PDUs;
    pdu_buffer_size++;

    // Release mutex and handle log file write
    sem_post(&pdu_mutex);
    if (update_log_file) update_log();
}

void update_log() {
    ssize_t bytes_written;
    size_t index = current_index;

    // Acquire logging semaphore and lock pdu buffer for serialization
    sem_wait(&log_semaphore);
    sem_wait(&pdu_mutex);

    // Write PDUs to the log file, rotating as needed (e.g., circular buffer or fixed-size files)
    while (index != current_index) {
        const NFAPI_L1_LOGGING_PDU_T *pdu = &(pdu_buffer[index]);
        bytes_written = write(log_fd, pdu, sizeof(NFAPI_L1_LOGGING_PDU_T));
        if (bytes_written != sizeof(NFAPI_L1_LOGGING_PDU_T)) {
            if (g_error_callback) g_error_callback("Failed to write PDU to log file");
        }
        index = (index + 1) % MAX_PDUs;
    }

    // Release pdu buffer and log semaphore
    sem_post(&pdu_mutex);
    sem_post(&log_semaphore);
}
