using System;
using System.Collections.Concurrent;
using System.Configuration;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using log4net;
using log4net.Config;

public class DynamicLogger
{
    private static readonly ConcurrentDictionary<string, int> LevelMap = new ConcurrentDictionary<string, int>();
    private static ILog _log;

    static DynamicLogger()
    {
        LoadLevelMap();
        XmlConfigurator.Configure();
        _log = LogManager.GetLogger(typeof(DynamicLogger));
    }

    public static void SetLoggingLevel(string level, int value)
    {
        Interlocked.CompareExchange(ref LevelMap[level], value, default);
        ApplyChanges();
    }

    public static int GetLoggingLevel(string level)
    {
        return LevelMap.GetOrAdd(level, DefaultLevel).Value;
    }

    private static int DefaultLevel => ConfigurationManager.AppSettings["defaultLogLevel"] == null ? 0 : int.Parse(ConfigurationManager.AppSettings["defaultLogLevel"]);

    private static void LoadLevelMap()
    {
        LevelMap.TryAdd("INFO", 1);
        LevelMap.TryAdd("DEBUG", 2);
        // Add more levels as needed, keeping in mind that lower numbers represent more severe log entries.
    }

    private static async Task ApplyChanges()
    {
        _log.Info("Applying changes to logging level.");
        await Task.Delay(TimeSpan.FromSeconds(5)); // Adjust this delay to balance accuracy and performance based on your application's needs.
        XmlConfigurator.Reconfigure();
    }

    public override string ToString()
    {
        return string.Join(", ", LevelMap.Select(x => $"{x.Key}: {x.Value}"));
    }
}
```

