                pdus[i].rnti.len = sizeof(pdus[i].rnti);
                pdus[i].crc_indication.len = sizeof(pdus[i].crc_indication);

                // Ensure buffer overflow by setting appropriate sizes
                pdus[i].ue_tag.val = malloc(pdus[i].ue_tag.len);
                pdus[i].rnti.val = malloc(pdus[i].rnti.len);
                pdus[i].crc_indication.val = malloc(pdus[i].crc_indication.len);

                if (!pdus[i].ue_tag.val || !pdus[i].rnti.val || !pdus[i].crc_indication.val) {
