        pthread_mutex_lock(&list->lock);
        new_node->data.tag = RX_UE_INFORMATION_TAG(); // Implement generating valid RX_UE_INFORMATION_TAG value
        new_node->data.rnti = get_random_rnti();
        new_node->data.crc_indication.CRCFLAG = rand() % 2;
        new_node->next = list->head;
        list->head = new_node;
        pthread_mutex_unlock(&list->lock);
    }

    if (is_debug) {
        log("Created and populated linked list with %d elements.", MAX_ELEMENTS);
    }
}
