class CRCList {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    pthread_mutex_t mutex;
    const char* logFile;

public:
    CRCList(const char* logFile) : logFile(logFile) {
        pthread_mutex_init(&mutex, NULL);
    }

    ~CRCList() {
        for (auto& element : data) {
            if (element != nullptr) {
                delete element.get();
            }
        }
        pthread_mutex_destroy(&mutex);
    }

    void addElement(const NFAPI_CRC_INDICATION_PDU_T& elem) {
        if (elem.rnti >= 0 && elem.rnti <= 65535) {
