            logDetails();
        } else {
            std::cerr << "Invalid RNTI: " << elem.rnti << "\n";
        }
    }

    void logDetails() {
        pthread_mutex_lock(&mutex);
        auto now = time(nullptr);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        std::ostringstream os;
        os << timestamp << ": RNTI: " << data.back()->rnti << ", CRC Flag: " << data.back()->crcTag.crcFlag << "\n";
        std::string logLine = os.str();

        std::ofstream logFileStream(this->logFile, std::ios_base::app);
        if (logFileStream.is_open()) {
            logFileStream << logLine;
            logFileStream.close();
        } else {
            std::cerr << "Failed to open log file: " << this->logFile << "\n";
        }
        pthread_mutex_unlock(&mutex);
    }
};
