typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

static size_t num_allocated = 0;
static size_t num_used = 0;
static size_t max_list_size = 10000;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t list_not_full = PTHREAD_COND_INITIALIZER;
static size_t concurrent_count = 0;

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)aligned_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), 16);
    if (!pdu) {
        return NULL;
    }

    pdu->crc_indication.crcflag = rand() % 2;
    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    aligned_free(pdu);
}

struct list_node* find_node(uint16_t rnti) {
    struct list_node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    struct list_node* new_node = (struct list_node*)aligned_malloc(sizeof(struct list_node), 16);
    if (!new_node) {
        destroy_pdu(pdu);
        return;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    while (num_used >= max_list_size || find_node(new_node->data.rnti) != NULL) {
        if (num_allocated > num_used) {
            destroy_pdu(pdu);
        }
        pthread_cond_wait(&list_not_full, &list_mutex);
    }

    new_node->next = head;
    head = new_node;
    if (++num_used > concurrent_count) {
        concurrent_count = num_used;
        pthread_cond_broadcast(&list_not_full);
    }
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list() {
    pthread_mutex_lock(&list_mutex);
    struct list_node* temp = head;
    if (temp != NULL) {
        head = temp->next;
        --num_used;
        concurrent_count = num_used > 0 ? num_used : 0;
    }
    pthread_mutex_unlock(&list_mutex);
    return &temp->data;
}

void* create_structures(void* arg) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
        if (!pdu) {
            break;
        }

        uint16_t rnti = rand() % 65536; // Assuming RNTI is a 16-bit value
        while (find_node(rnti) != NULL) {
            pdu->rnti = rand() % 65536;
        }

        add_to_list(pdu);

        if (--concurrent_count == 0) {
            pthread_cond_signal(&list_not_full);
        }
    }
    return NULL;
}
