class NetworkConfigManager {
private:
    std::list<NetworkInterfaceConfig> interfaces;
    std::mutex mtx;
    pthread_t syncThreadId;
    bool running = true;

public:
    void initialize(const NetworkInterfaceConfig& config) {
        std::unique_lock<std::mutex> lock(mtx);
        interfaces.push_back(config);
    }

    void configure(size_t index, const NetworkInterfaceConfig& newConfig) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = interfaces.begin();
        std::advance(it, index);
        if (it != interfaces.end()) {
            (*it) = newConfig;
        }
    }

    NetworkInterfaceConfig get(size_t index) const {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = interfaces.begin();
        std::advance(it, index);
        if (it != interfaces.end()) {
            return *it;
        }
        return NetworkInterfaceConfig();
    }

    void startSyncThread() {
        pthread_create(&syncThreadId, nullptr, &NetworkConfigManager::syncThread, this);
    }

    static void* syncThread(void* manager) {
        auto mgr = reinterpret_cast<NetworkConfigManager*>(manager);
        while (mgr->running) {
