#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 50000
#define PROBABILITY_THRESHOLD 0.5

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    // Additional fields can be added here
} NFAPI_CRFC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRFC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node** pdu_list = NULL;
unsigned int capacity = 0;
unsigned int num_elements = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log(const char* message) {
    // Implement logging mechanism here
}

int get_random() {
    return rand() / (RAND_MAX / PROBABILITY_THRESHOLD);
}

void update_pdu(unsigned int index) {
    if (index >= capacity) {
        log("Resizing array due to exceeding capacity");
        unsigned int new_capacity = capacity * 2;
        Node** temp = realloc(pdu_list, new_capacity * sizeof(Node*));
        if (!temp) {
            log("Allocation failure during resize");
            return;
        }
        pdu_list = temp;
        for (unsigned int i = capacity; i < new_capacity; ++i) {
            pdu_list[i] = NULL;
        }
        capacity = new_capacity;
    }

    if (!pdu_list[index]) {
        log("Allocating new PDU");
        pdu_list[index] = malloc(sizeof(Node));
        if (!pdu_list[index]) {
            log("Allocation failure during creation");
            return;
        }
        pdu_list[index]->next = NULL;
    }

    NFAPI_CRFC_INDICATION_PDU_T* pdu = &pdu_list[index]->data;
    // Update pdu fields based on external data sources here
    pdu->crc_indication.crcflag = get_random();
    ++num_elements;
}

void init() {
    if (capacity) free(pdu_list);
    pdu_list = calloc(1, sizeof(Node*));
    capacity = 1;
    num_elements = 0;
}

void destroy() {
    for (unsigned int i = 0; i < capacity; ++i) {
        if (pdu_list[i]) free(pdu_list[i]);
    }
    free(pdu_list);
    pdu_list = NULL;
    capacity = 0;
    num_elements = 0;
}
