    arr->size = 0;
    arr->rssi_threshold = rssi_threshold;
    arr->snr_threshold = snr_threshold;
    sem_init(&arr->mutex, 0, 1);
    arr->data = malloc(capacity * sizeof(CellMeasurementResult*));
}

// Function to add a measurement result to the thread-safe array
void push_to_thread_safe_array(struct thread_safe_array* arr, const CellMeasurementResult* measurement) {
    bool filter = false;

    if (measurement->rssi < arr->rssi_threshold || measurement->snr < arr->snr_threshold)
        filter = true;

    sem_wait(&arr->mutex);
    if (!filter && arr->size < arr->capacity) {
        arr->data[arr->size] = malloc(sizeof(CellMeasurementResult));
        memcpy(arr->data[arr->size], measurement, sizeof(CellMeasurementResult));
        arr->size++;
    }
    sem_post(&arr->mutex);
}

