using System;
using System.Security.Cryptography;
using System.Text;

public byte[] decryptAES_CBC(byte[] ciphertext, byte[] key, byte[] iv, byte padding) {
    if (ciphertext == null || key == null || iv == null || padding < 0 || padding > 7)
        throw new ArgumentException("Invalid input parameters.");

    using (Aes aes = Aes.Create()) {
        aes.Key = new Rfc2898DeriveBytes(key, new byte[16]).GetBytes(aes.KeySize / 8);
        aes.IV = iv;
        ICryptoTransform decryptor = aes.CreateDecryptor();
        MemoryStream ms = new MemoryStream(ciphertext);
        CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        byte[] buffer = new byte[cs.ReadByte()];
        int read;
        while ((read = cs.Read(buffer, 0, buffer.Length)) > 0) {
            if (padding != 0) {
                int paddingLength = buffer[buffer.Length - 1];
                Array.Copy(buffer, 0, buffer, 0, buffer.Length - paddingLength);
                buffer = buffer.Take(buffer.Length - paddingLength).ToArray();
            }
            buffer = buffer.Concat(new byte[read]).ToArray();
        }
        return buffer;
    }
}
