struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

static unsigned int size = 0;
static const unsigned int capacity = 10000;
static struct node* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_cipher(unsigned char *key, unsigned char *iv, unsigned int key_len, unsigned int iv_len, const char *password) {
    SHA1_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, (const unsigned char *) password, strlen(password));
    unsigned char digest[SHA_DIGEST_LENGTH];
    SHA1_Final(digest, &ctx);

    // Initialize AES key and IV using the derived SHA-1 hash.
    for (unsigned int i = 0; i < key_len; ++i) {
        key[i] = digest[i % SHA_DIGEST_LENGTH];
    }

    for (unsigned int i = 0; i < iv_len; ++i) {
        iv[i] = i + 1; // Set a simple IV for this example.
    }
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list_lock);

    if (size >= capacity) {
        struct node *new_head = malloc((capacity + 1024) * sizeof(struct node));
        assert(new_head != NULL);
        new_head->next = head;
        head = new_head;
        capacity *= 2;
    }

    struct node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = malloc(sizeof(struct node));
    assert(current->next != NULL);
    current = current->next;

    memcpy(&(current->data), &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size++;

    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T get_from_list() {
    pthread_mutex_lock(&list_lock);

    if (size == 0) {
        pthread_mutex_unlock(&list_lock);
        return (NFAPI_CRC_INDICATION_PDU_T){};
    }

    struct node* current = head;
    NFAPI_CRC_INDICATION_PDU_T data = current->data;
    head = head->next;
    free(current);
    size--;

    pthread_mutex_unlock(&list_lock);

    return data;
}

// Implement remove_from_list, resize_list, and other necessary functions.
