        if (itemToRemove != null)
            _dataItems.Remove(itemToRemove);
    }

    public void CheckAndCleanup()
    {
        var itemsToRemove = _dataItems.Where(item => _dataItems.Count > _threshold * _maxSize / 100).ToList();
        foreach (var item in itemsToRemove)
