    private const int MinPayloadSize = 100;
    private const int MaxPayloadSize = 1500;
    private const int CacheInvalidationInterval = 60; // in seconds

    private ConcurrentQueue<PacketFrame> _queue;
    private ConcurrentDictionary<string, PacketFrame> _cache;
    private TimeSpan _cacheInvalidationTimer;

    public DynamicPacketHandler()
    {
        _queue = new ConcurrentQueue<PacketFrame>();
        _cache = new ConcurrentDictionary<string, PacketFrame>();
        _cacheInvalidationTimer = TimeSpan.Zero;

        AdjustPacketParameters();
    }

    [MethodImpl(MethodImplOptions.Synchronized)]
    public void Enqueue(PacketFrame packet)
    {
        if (packet.PayloadSize < MinPayloadSize || packet.PayloadSize > MaxPayloadSize)
            throw new ArgumentException($"Invalid payload size: {packet.PayloadSize}");

        _queue.Enqueue(packet);
        if (_queue.Count > MaxQueueLength)
            _queue.Dequeue();
    }

    [MethodImpl(MethodImplOptions.Synchronized)]
    public PacketFrame Dequeue()
    {
        PacketFrame dequeuedPacket;
        if (_queue.TryDequeue(out dequeuedPacket))
            return dequeuedPacket;

        return null;
    }

    [MethodImpl(MethodImplOptions.Synchronized)]
    public PacketFrame GetCache(string key)
    {
        if (_cache.TryGetValue(key, out var result))
            return result;

        return null;
    }

    [MethodImpl(MethodImplOptions.Synchronized)]
    public void AddOrUpdateCache(PacketFrame packet)
    {
        _cache[packet.Id] = packet;

        if (_cacheInvalidationTimer + CacheInvalidationInterval < DateTime.UtcNow)
