#define MAX_CONFIGS 1024

sem_t config_mutex;
LTE_PHY_Config* phy_configs;
size_t num_configs = 0;

void init_phy_configurations(size_t max_configs) {
    if (max_configs > MAX_CONFIGS) {
        fprintf(stderr, "Maximum number of configurations exceeded\n");
        return;
    }

    phy_configs = mmap(NULL, max_configs * sizeof(LTE_PHY_Config), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (phy_configs == MAP_FAILED) {
        perror("Memory mapping error");
        return;
    }

    sem_init(&config_mutex, 0, 1);
    num_configs = max_configs;
}

bool add_config(const LTE_PHY_Config* config) {
    if (num_configs == 0) {
        fprintf(stderr, "No available slots for new configuration\n");
        return false;
    }

    sem_wait(&config_mutex);

    if (!isValidConfig(*config)) {
        fprintf(stderr, "Invalid or unsupported configuration parameters\n");
        sem_post(&config_mutex);
        return false;
    }

    if (getRequiredLatency(*config) > getMaxAllowedLatency()) {
        fprintf(stderr, "Configuration latency requirements exceed allowed limit\n");
        sem_post(&config_mutex);
        return false;
    }

    phy_configs[num_configs - 1] = *config;
    --num_configs;
    sem_post(&config_mutex);

    return true;
}

