int add_config(LTE_PHY_Layer *phy, LTE_CONFIG config) {
    pthread_mutex_lock(&phy->mutex);

    // Validate configuration against hardware version and network conditions
    if (validate_config(config, phy->hardware_version)) {
        // Add the configuration to the dynamic array, sorting it based on expiration time
        config.expiration = time(NULL) + config.expiration;
        size_t i;
        for (i = 0; i < phy->count && compare(&config, phy->configs[i]) > 0; ++i);
        memmove(phy->configs + i + 1, phy->configs + i, (phy->capacity - i) * sizeof(void*));
        phy->configs[i] = &config;
        ++phy->count;

        if (phy->count == phy->capacity) { // Increase the capacity of the dynamic array if necessary
            phy->capacity *= 2;
            void** new_arr = realloc(phy->configs, phy->capacity * sizeof(void*));
            if (!new_arr) return -1; // Error handling for malloc failure
