#include <algorithm>
#include <deque>
#include <functional>
#include <memory>
#include <new>
#include <string>
#include <vector>

struct PDCP_PDU_T {
    float SNR;
};

struct RLC_PDU_T {
    enum class Type { UNKNOWN, AM, RM };
    Type type;
    std::unique_ptr<char[]> data;

    RLC_PDU_T(Type t) : type(t), data(std::make_unique<char[]>(1)) {}
};

struct NFAPI_RRC_PDU_T {
    PDCP_PDU_T pdcpPdu;
    RLC_PDU_T rlcPdu;
};

void initNFAPIRRCPDUs(std::vector<NFAPI_RRC_PDU_T>& ndus, const std::deque<std::string>& strings, float snr, size_t minRLCSize = 1024, size_t maxRLCSize = 8192) {
    size_t nduCount = strings.size();
    ndus.resize(nduCount);

    std::function<RLC_PDU_T*(const RLC_PDU_T*)> createRLCPDU = [minRLCSize, maxRLCSize](const RLC_PDU_T* old) {
        if (old->data->size() < minRLCSize || old->data->size() > maxRLCSize) {
            old->data.reset(new char[std::max(minRLCSize, std::min(maxRLCSize, old->data->size() * 2))]);
        }
        return old;
    };

    auto it = strings.cbegin();
    size_t foundIndex = it != strings.cend() ? std::distance(strings.cbegin(), it) : ndus.size();
    for (size_t i = 0; i < nduCount; ++i) {
        NFAPI_RRC_PDU_T& ndu = ndus[i];

        if (foundIndex != nduCount) {
            std::advance(it, 1);
            foundIndex = it != strings.cend() ? std::distance(strings.cbegin(), it) : nduCount;
        }

        ndu.pdcpPdu.SNR = snr;
        ndu.rlcPdu = RLC_PDU_T::createRLCPDU(&ndu.rlcPdu);
        if (i < foundIndex) {
            ndus[foundIndex].rd_list.insert(ndus[foundIndex].rd_list.end(), it->cbegin(), it->cend());
        } else {
            ndus.back().rd_list.push_back(*it);
        }
    }
}

// Track the maximum memory usage during execution
std::max_heap<size_t> maxMemoryUsageTracker;

void trackMemoryUsage(size_t bytes) {
    maxMemoryUsageTracker.push(bytes);
    if (maxMemoryUsageTracker.size() > 100) {
        maxMemoryUsageTracker.pop();
    }
}
