    char input_file[1024];
    char output_file[1024];
    struct timespec start, end;

    snprintf(input_file, sizeof(input_file), "%s/%s", input_dir, input_files[idx]->d_name);
    snprintf(output_file, sizeof(output_file), "%s/%s.pdf", output_dir, input_files[idx]->d_name);

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Perform conversion using Ghostscript API (replace with your preferred tool's API)
    gs_err = GSAPI_init(&gs_library);
    if (gs_err.err == no_error) {
        gs_err = GSAPI_run_string(&gs_library, "q", input_file, output_file, "");
        // Handle the error returned by Ghostscript API (if any)
    }
    GSAPI_done(&gs_library);

    clock_gettime(CLOCK_MONOTONIC, &end);

    log_info("Image conversion started: %s", input_file);
    if (!gs_err.err) {
        log_info("Image conversion ended successfully: %s", output_file);
    } else {
        log_error("Error during image conversion: %s", gs_err.msg);
        remove(output_file); // Remove the partially created PDF file in case of failure
    }
}

void log_info(const char *format, ...) {
    char buffer[4096];
    va_list args;
    struct timespec now;

    clock_gettime(CLOCK_MONOTONIC, &now);

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    pthread_mutex_lock(&logger_mutex);
    // Asynchronously log the message (replace with your preferred method)
    async_log(now.tv_sec, now.tv_nsec, ASYNC_LOG_INFO, buffer);
    pthread_mutex_unlock(&logger_mutex);
}

void log_error(const char *message) {
    // Asynchronously log the error message (replace with your preferred method)
    async_log(-1, 0, ASYNC_LOG_ERROR, message);
}

void* worker(void *arg) {
    int idx = *(int *) arg;

    for (size_t i = idx; i < input_files_count; i += CONCURRENCY_LIMIT) {
        if (i == input_files_count) break; // Prevent index out of range errors
        convert_image_to_pdf(i);
    }

    pthread_mutex_lock(&concurrency_condition);
    num_active_threads--;
    pthread_cond_signal(&concurrency_condition);
    pthread_mutex_unlock(&concurrency_condition);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s input_dir output_dir temp_dir concurrency_limit\n", argv[0]);
        return 1;
    }

    input_dir = argv[1];
    output_dir = argv[2];
    tmp_dir = argv[3];

    DIR *input_directory = opendir(input_dir);
    if (!input_directory) {
        perror("Error opening input directory");
        return 1;
    }

    struct dirent **files;
    int res = scandir(input_dir, &files, NULL, alphasort);
    if (res == -1) {
        perror("Error reading input directory");
        closedir(input_directory);
        return 1;
    }

    input_files = malloc((res + 1) * sizeof(struct dirent*));
    memcpy(input_files, files, res * sizeof(struct dirent*));
    input_files_count = res;
    free(files);
    closedir(input_directory);

    pthread_t threads[CONCURRENCY_LIMIT];

    while (num_active_threads < CONCURRENCY_LIMIT) {
        pthread_mutex_lock(&concurrency_condition);
        while (num_active_threads >= CONCURRENCY_LIMIT) {
            pthread_cond_wait(&concurrency_condition, &logger_mutex);
        }
        int thread_idx = num_active_threads++;
        pthread_create(&threads[thread_idx], NULL, worker, (void*) &thread_idx);
    }

    for (int i = 0; i < CONCURRENCY_LIMIT; i++) {
        pthread_join(threads[i], NULL);
    }

    free(input_files);

    return 0;
}
