typedef struct _CRC_LIB_HANDLE {
    void* handle;
    int (*calc_checksum)(void*, const NFAPI_CRC_INDICATION_PDU_T*);
} CRC_LIB_HANDLE;

CRC_LIB_HANDLE crc_lib;

void init_crc_lib(const char* library, const char* calc_checksum_func) {
    void* handle = dlopen(library, RTLD_NOW);
    if (!handle) {
        fprintf(stderr, "Error: Could not open CRC calculation library %s\n", library);
        exit(EXIT_FAILURE);
    }

    crc_lib.handle = handle;
    crc_lib.calc_checksum = dlsym(handle, calc_checksum_func);
}

int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !pdu->tag || !pdu->rnti || !pdu->crc_indication || pdu->crc_indication.crcflag < 0 || pdu->crc_indication.crcflag > 1) {
        fprintf(stderr, "Error: Invalid NFAPI_CRC_INDICATION_PDU_T structure\n");
        return -1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(size_t n, CRC_LIB_HANDLE crc_lib) {
    NFAPI_CRC_INDICATION_PDU_T** pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        fprintf(stderr, "Error: Could not allocate memory for PDU list\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t i;
    for (i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Error: Could not allocate memory for PDU #%zu\n", i);
            return NULL;
        }

        pthread_mutex_lock(&mutex);
        // Fill the PDU structure with random data and a randomly set CRCFLAG
        // ...

        pthread_mutex_unlock(&mutex);

        uint32_t checksum = crc_lib.calc_checksum(NULL, pdu);
        pdu->crc_indication.crcflag = (checksum & 1) ? 1 : 0;

        if (validate_pdu(pdu)) {
            fprintf(stderr, "Error: Invalid PDU created during list generation\n");
            free(pdu);
            return NULL;
        }

        pdu_list[i] = pdu;
    }

    return pdu_list;
}

void deallocate_pdu_list(NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t n) {
    if (!pdu_list || !n) return;

    size_t i;
    for (i = 0; i < n; ++i) free(pdu_list[i]);
    free(pdu_list);
}
