    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    size_t ref_count; // Track nodes that are still in use
    struct Node* next;
} Node;

// Dynamic list implementation based on a doubly-linked list with a head and tail node.
typedef struct {
    Node* head;
    Node* tail;
    size_t used; // Number of elements currently in use
    size_t capacity; // Maximum number of elements the list can hold before reallocation is triggered
} List;

List* create_list(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->used = 0;
    list->capacity = initial_capacity;

    return list;
}

Node* create_node() {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data.crcflag = rand() % 2; // Set CRCFLAG to a random value between 0 and 1
    node->ref_count = 1; // Initial reference count is 1 (the head/tail node will not be referenced)
    node->next = NULL;

    return node;
}

void append_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node();
    if (!new_node) return;

    new_node->data = data;

    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    ++(list->used);
}

Node* find_node_by_rnti(List* list, int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) return current;
        current = current->next;
    }

    return NULL;
}

void resize_list(List* list, size_t new_capacity) {
    Node** nodes = realloc(list->head, new_capacity * sizeof(Node));
    if (!nodes) return;

    list->head = nodes;
    list->capacity = new_capacity;
}

void serialize(List* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "{%d, %d, %d, %d} ",
                current->data.tag, current->data.rnti,
                current->data.crc_indication.tag, current->data.crcflag);
        current = current->next;
    }

    fclose(file);
}

void deserialize(List* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T data;
    Node* current_node = NULL;
    Node* new_node = NULL;

    while (fscanf(file, "{%d, %d, %d, %d}", &data.tag, &data.rnti,
                  &data.crc_indication.tag, &data.crcflag) == 4) {
        new_node = create_node();
        if (!new_node) break;

        new_node->data = data;

        if (list->head == NULL) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            current_node->next = new_node;
            current_node = new_node;
        }
    }

    fclose(file);

    if (current_node != NULL) {
        current_node->next = NULL;
        list->tail = current_node;
    }
}
