typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Include necessary fields here
} NFAPI_CRC_INDICATION_PDU_T;

class CRCIndicationPDUList {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> vec; // For cache locality
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> list; // For thread safety during insertion
    std::unordered_set<uint32_t> rntiSet; // To check for unique RNTIs
    pthread_mutex_t mutex; // For synchronization between threads

public:
    CRCIndicationPDUList() {
        pthread_mutex_init(&mutex, NULL);
    }

    ~CRCIndicationPDUList() {
        pthread_mutex_destroy(&mutex);
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        pthread_mutex_lock(&mutex);

        // Insert into the vector for better cache locality, but it might cause contention if multiple threads insert at the same time.
        vec.push_back(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new NFAPI_CRC_INDICATION_PDU_T(pdu)));

        // Insert into the list for thread safety during insertion, but it might cause cache misses due to non-local memory access.
        list.push_back(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new NFAPI_CRC_INDICATION_PDU_T(pdu)));

        // Check for duplicate RNTIs, which might introduce a slight performance overhead but ensures data integrity.
        if (rntiSet.find(pdu.rnti) != rntiSet.end()) {
            // Report any duplicates found
            std::cout << "Duplicate RNTI: " << pdu.rnti << std::endl;
        } else {
            rntiSet.insert(pdu.rnti);
        }

        pthread_mutex_unlock(&mutex);
    }
};
