} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_SIZE 1000

static NFAPI_CRC_INDICATION_PDU_T* data = NULL;
static size_t size = 0;
static mutex_t mtx;
static condition_t cond;

void resize(size_t newSize) {
    if (newSize > MAX_SIZE || newSize == 0) return;

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);
    if (!temp) {
        fprintf(stderr, "Memory allocation failure\n");
        return;
    }

    data = temp;
    size = newSize;
}

void init() {
    if (size != 0) return;

    data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Memory allocation failure\n");
        return;
    }

    size = 1;
}

void log_metrics() {
    printf("Array size: %zu\n", size);
}

void set_crcflag(size_t index, int crcFlag) {
    pthread_mutex_lock(&mtx);
    data[index].crc_indication.CRCFLAG = crcFlag;
    pthread_mutex_unlock(&mtx);
}

int get_crcflag(size_t index) {
    int ret;

    pthread_mutex_lock(&mtx);
    ret = data[index].crc_indication.CRCFLAG;
    pthread_mutex_unlock(&mtx);

    return ret;
}

void* worker(void *arg) {
    int i, crcFlag;

    while (1) {
        pthread_mutex_lock(&cond);
        while (size == 0) pthread_cond_wait(&cond, &mtx);
        pthread_mutex_unlock(&cond);

        resize(size * 2);

        for (i = size - 1; i >= 0; --i) {
            crcFlag = rand() % 2;
            set_crcflag(i, crcFlag);
        }
    }

    return NULL;
}

void start() {
    pthread_t threads[MAX_SIZE];
    size_t i;

    pthread_mutex_init(&mtx, NULL);
    pthread_cond_init(&cond, NULL);

    for (i = 0; i < MAX_SIZE; ++i)
        pthread_create(&threads[i], NULL, worker, NULL);
}

void stop() {
    size = 0;
    pthread_mutex_destroy(&mtx);
    pthread_cond_destroy(&cond);

    for (size_t i = 0; i < MAX_SIZE; ++i)
        pthread_join(threads[i], NULL);

    free(data);
}
