// Function to add a new LTE UE context
void add_ue_context(uint64_t ue_id, const std::list<std::pair<uint32_t, uint32_t>>& bwp_configs) {
    pthread_mutex_lock(&ue_contexts_mutex);
    ue_contexts[ue_id] = std::make_shared<LTE_UE_Context>(ue_id);
    for (const auto& config : bwp_configs) {
