        ue_contexts[ue_id]->bwp_configs.push_back(config);
    }
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to update an existing LTE UE context's BWP configurations
void update_ue_context_bwp(uint64_t ue_id, const std::list<std::pair<uint32_t, uint32_t>>& new_bwp_configs) {
    pthread_mutex_lock(&ue_contexts_mutex);
    if (ue_contexts.find(ue_id) != ue_contexts.end()) {
        std::unique_lock<std::mutex> lock(ue_contexts[ue_id]->bwp_mutex);
        for (const auto& config : new_bwp_configs) {
            ue_contexts[ue_id]->bwp_configs.push_back(config);
        }
    }
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to identify inactive LTE UE contexts for cleanup
void clean_inactive_contexts() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&ue_contexts_mutex);
    auto it = ue_contexts.begin();
    while (it != ue_contexts.end()) {
        if ((current_time - it->second->last_activity_time) > INACTIVITY_THRESHOLD) {
            it = ue_contexts.erase(it);
        } else {
            ++it;
        }
    }
    pthread_mutex_unlock(&ue_contexts_mutex);
}
