void insertAtHead(Node* new_node) {
    if (hash_table.size == MAX_LIST_SIZE || !new_node) return;

    if (hash_table.size > 0) {
        hash_table.table[0]->prev = new_node;
        new_node->next = hash_table.table[0];
        hash_table.table[0] = new_node;
    } else {
        hash_table.table[0] = new_node;
    }

    ++hash_table.size;
}

// Search for a node with the given PCI value in the list.
Node* findNode(unsigned short pci) {
    for (int i = 0; i < hash_table.size && i < hash_table.capacity; ++i) {
        if (hash_table.table[i]) {
            if (hash_table.table[i]->data.PCI == pci) return hash_table.table[i];
            if (!hash_table.table[i]->next) break;
        }
    }

    return NULL;
}

// Remove a node with the given PCI value from the list.
void removeNode(unsigned short pci) {
    Node* current = hash_table.table[0];

    while (current != NULL) {
        if (current->data.PCI == pci) {
            if (current->prev) current->prev->next = current->next;
            else hash_table.table[0] = current->next;

            if (current->next) current->next->prev = current->prev;

            free(current);
            --hash_table.size;
        }
        current = current->next;
    }
}

// Clear and reset the linked list to zero size after every CLEAR_INTERVAL iterations.
void clearList() {
    if (hash_table.size && hash_table.size % CLEAR_INTERVAL == 0) {
        Node* current = hash_table.table[0];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }

        hash_table.size = 0;
    }
}

// Function to manage the dynamically sized linked list of NFAPI_RRC_PDU_T structures.
void manageList() {
