    if (contexts.find(context.getUEID()) == contexts.end()) { // Check for potential duplication efficiently
        contexts[context.getUEID()] = context;
    }
    contextListMutex.unlock();
}

void updateBWPConfigurations(int ueID, const std::vector<BWPConfiguration>& newBWPConfigs) {
