    (*arr)->mutex = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&(*arr)->free_slots, 0, (*arr)->capacity);
}

void resize_lte_dl_frameinfo(struct lte_dl_frameinfo* arr) {
