void initializeAndConfigureNetworkResources(int M, unsigned long seed, LoggingInterface logging, const struct ConfigSchema* schema) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NetworkConfig* configs = malloc(M * sizeof(NetworkConfig));

    if (!configs) {
        logging("Failed to allocate memory for network configurations.");
        return;
    }

    srand(seed);

    for (int i = 0; i < M; ++i) {
        pthread_mutex_lock(&mutex);
        NetworkConfig* current = &configs[i];

        while (!isValidConfig(*current, *schema)) {
            current->bandwidth = (double)(rand() * (schema->max_bandwidth - schema->min_bandwidth) + schema->min_bandwidth);
            current->latency = (double)(rand() * (schema->max_latency - schema->min_latency) + schema->min_latency);
            current->qos_settings = rand() % (schema->max_qos - schema->min_qos + 1) + schema->min_qos;
        }

        pthread_mutex_unlock(&mutex);
    }

    logging("Initialized %d network configurations.", M);
}

bool isValidConfig(NetworkConfig config, const struct ConfigSchema schema) {
    return (config.bandwidth >= schema.min_bandwidth && config.bandwidth <= schema.max_bandwidth)
           && (config.latency >= schema.min_latency && config.latency <= schema.max_latency)
           && (config.qos_settings >= schema.min_qos && config.qos_settings <= schema.max_qos);
}
