        if (!pdus[i].RX_UE_INFORMATION_TAG || pdus[i].RNTI == 0) {
            continue;
        }

        for (size_t j = start_index; j < i; ++j) {
            if (pdus[j].RX_UE_INFORMATION_TAG == pdus[i].RX_UE_INFORMATION_TAG || pdus[j].RNTI == pdus[i].RNTI) {
                goto retry;
            }
        }

        return pdus[i].RNTI = rand() % MAX_RNTI + 1;

    retry:
        continue;
    }

