typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *next, *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _list {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.CRCFLAG = pseudo_random_number();
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

void insert(List *list, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list->mutex);

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->next = list->head;
        list->head->prev = new_node;
        list->head = new_node;
    }

    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

void remove(List *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == list->tail && list->head == node) {
        free(list->head);
        list->head = NULL;
        list->tail = NULL;
    } else if (list->head == node) {
        list->head = list->head->next;
        free(node);
        --list->size;
    } else if (list->tail == node) {
        list->tail = list->tail->prev;
        free(node);
        --list->size;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        free(node);
        --list->size;
    }

    pthread_mutex_unlock(&list->mutex);
}

void iterate(List *list, void (*function)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->mutex);

    for (NFAPI_CRC_INDICATION_PDU_T *node = list->head; node != NULL; node = node->next) {
        function(node);
    }

    pthread_mutex_unlock(&list->mutex);
}
