    uint64_t tx_collisions; // Transmitted collisions count
    double if_speed; // Interface speed (Mbps)
    union {
        uint64_t v1; // Version 1 fields
        struct {
            uint32_t tx_errors; // Transmit errors count (added in version 2)
            uint64_t rx_length_errors; // Received length errors count (added in version 2)
        } v2;
    } stats;
