    char* compressed_data; // Compressed statistics data (if compressed)
} nic_statistics_t;

int initialize_nic_stats(nic_statistics_t** stats, size_t* num_interfaces, int version) {
    *stats = malloc(sizeof(nic_statistics_t) * *num_interfaces);
    if (*stats == NULL) {
        perror("Memory allocation failed");
        return 1;
    }

    struct ifaddrs* interfaces = NULL;
    int result = getifaddrs(&interfaces, NULL);
    if (result != 0) {
        perror("getifaddrs: ");
        free(*stats);
        return 1;
    }

    nic_statistics_t* current = *stats;
    struct ifaddrs* ifa = interfaces;
    size_t allocated = *num_interfaces;
    while (ifa != NULL && allocated > 0) {
        if (ifa->ifa_name == NULL || strlen(ifa->ifa_name) >= IF_NAMESIZE) {
            free(*stats);
            freeifaddrs(interfaces);
            return 1;
        }

        strncpy(current->if_name, ifa->ifa_name, IF_NAMESIZE);
        strncpy(current->if_vendor, ifa->ifa_data->td_manuf, IF_VENDORSIZE);
        current->if_status = ifa->ifa_flags & IFF_UP ? 'U' : 'D';
        current->if_index = *(uint32_t*) ifa->ifa_data->sa;

        // Populate other fields based on the given version and specific hardware capabilities, available memory, etc.

        allocated--;
        current++;
        ifa = ifa->ifa_next;
    }

    freeifaddrs(interfaces);

    // Initialize the version-specific fields for each structure based on the provided version
    if (version > 1) {
        for (size_t i = 0; i < *num_interfaces; ++i) {
            nic_statistics_t* interface = &((nic_statistics_t*)*stats)[i];
            if (version == 2) {
                interface->stats.v2.tx_errors = 0;
                interface->stats.v2.rx_length_errors = 0;
            }
        }
    }

    return 0;
}
