// Custom network statistics structure definition
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NetworkInterfaceStats;

// Shared memory segment definition for storing interface stats
#define SHM_SIZE (sizeof(NetworkInterfaceStats) * NUM_INTERFACES)
void* shm_segment;
pthread_mutex_t shm_mutex;

// Function to initialize and populate the network statistics array
void init_network_stats() {
    int i;

    // Allocate shared memory segment
    shm_segment = mmap(NULL, SHM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shm_segment == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    // Initialize mutex for shared memory access synchronization
    pthread_mutex_init(&shm_mutex, NULL);

    // Populate the network statistics array with dynamic metadata from configuration files or network discovery protocols
    // ...

    // Set CRCFLAG to randomly determined values for each interface (e.g., using rand() function)
    NetworkInterfaceStats* stats = shm_segment;
    for (i = 0; i < NUM_INTERFACES; ++i, ++stats) {
        stats->CRCFLAG = rand() % 2;
    }
}

// Function to deallocate shared memory and other resources upon program exit
void cleanup() {
    if (shm_segment != MAP_FAILED) {
        munmap(shm_segment, SHM_SIZE);
    }
    pthread_mutex_destroy(&shm_mutex);
}
