Message* initMessages(int num_messages, int payload_len) {
    Message *msgs = (Message *)malloc(num_messages * sizeof(Message));

    // Handle potential allocation failures
    if (!msgs) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_messages; ++i) {
