class CRCList {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mt19937 rng;
    int min, max;
    uint64_t seed;

public:
    CRCList(int min = 0, int max = RAND_MAX, uint64_t seed = std::random_device{}());
    ~CRCList();
    void setSeed(uint64_t seed);
    int getMin() const;
    int getMax() const;
    uint64_t getSeed() const;
    const std::vector<NFAPI_CRC_INDICATION_PDU_T>& getData() const;
    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu);
    void serialize(std::ostream& os) const;
    void deserialize(std::istream& is);
    void logEvent();
};

inline CRCList::CRCList(int min, int max, uint64_t seed) : rng(seed), min(min), max(max), seed(seed) {}

inline CRCList::~CRCList() {}

inline void CRCList::setSeed(uint64_t seed) { rng.seed(seed); }

inline int CRCList::getMin() const { return min; }

inline int CRCList::getMax() const { return max; }

inline uint64_t CRCList::getSeed() const { return seed; }

inline const std::vector<NFAPI_CRC_INDICATION_PDU_T>& CRCList::getData() const { return data; }

inline void CRCList::add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    data.emplace_back(pdu);
    if (data.size() > max * 0.75) {
        data.erase(begin(data), begin(data) + data.size() / 4);
    }
}

inline void CRCList::serialize(std::ostream& os) const {
    boost::archive::text_oarchive oa(os);
    oa & boost::serialization::make_nvp("data", data);
}

inline void CRCList::deserialize(std::istream& is) {
    boost::archive::text_iarchive ia(is);
    ia & boost::serialization::make_nvp("data", data);
}

inline void CRCList::logEvent() {
    static thread_local std::deque<CRCList const*> logs;
    logs.push_back(this);
    if (logs.size() > 1024) {
        logs.pop_front();
    }
    SPDLOG_INFO("Random number generation event.");
}
```

