// Function to create a new packet and initialize its mutex lock
Packet* create_packet() {
    Packet *p = malloc(sizeof(Packet));
    if (!p) {
        fprintf(stderr, "Failed to allocate memory for packet\n");
        return NULL;
    }
    pthread_mutex_init(&p->lock, NULL);
    p->next = NULL;
    return p;
}

// Function to add a new packet to the list with RNTI validation and logging
void add_packet(PacketList *list, Packet *new_packet) {
    if (list->count == 0) {
        list->head = new_packet;
        list->tail = new_packet;
    } else {
        pthread_mutex_lock(&list->list_lock);
        list->tail->next = new_packet;
        list->tail = new_packet;
        pthread_mutex_unlock(&list->list_lock);
    }

    // Validate RNTI and log conflicts, if any
    Packet *current = list->head;
    while (current != NULL) {
        if (current->rnti == new_packet->rnti && current != new_packet) {
            fprintf(stderr, "RNTI conflict detected: %d\n", new_packet->rnti);
        }
        current = current->next;
    }
