    }

    free(packet);
}

// Function to process the incoming packets, handling concurrency using pthreads
void* process_thread(void *arg) {
    PacketList *list = arg;

    for (;;) {
        // Wait for new packet and acquire lock before processing it
        Packet *packet = NULL;
        pthread_mutex_lock(&list->list_lock);
        if (list->head != NULL) {
            packet = list->head;
            list->head = list->head->next;
            if (list->head == NULL) {
                list->tail = NULL;
            }
            --list->count;
        }
        pthread_mutex_unlock(&list->list_lock);

        if (packet != NULL) {
            process_packet(packet);
        }
    }
}

