#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <ifaddrs.h>

typedef struct {
    char ifname[IF_NAMESIZE];
    char ip[INET_ADDRSTRLEN];
    char netmask[INET_ADDRSTRLEN];
} NIM_CONFIG;

struct nim_config_list {
    NIM_CONFIG config;
    struct nim_config_list *next;
};

void read_nim_config(FILE *file, struct nim_config_list **head) {
    char line[256];
    struct nim_config_list *current = NULL, *new_node = NULL;

    while (fgets(line, sizeof(line), file)) {
        NIM_CONFIG config;
        sscanf(line, "%s %s %s", config.ifname, config.ip, config.netmask);

        if (strlen(config.ifname) > IF_NAMESIZE - 1 || strlen(config.ip) > INET_ADDRSTRLEN - 1 || strlen(config.netmask) > INET_ADDRSTRLEN - 1) {
            continue;
        }

        new_node = (struct nim_config_list *)malloc(sizeof(struct nim_config_list));
        if (!new_node) {
            fprintf(stderr, "Out of memory\n");
            return;
        }

        memcpy(&new_node->config, &config, sizeof(NIM_CONFIG));
        new_node->next = NULL;

        if (!*head) {
            *head = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }
}

void init_nim_config(const char *datafiles[], int num_files, struct nim_config_list **head) {
    for (int i = 0; i < num_files; ++i) {
        FILE *file = fopen(datafiles[i], "r");
        if (!file) {
            fprintf(stderr, "Could not open file: %s\n", datafiles[i]);
            continue;
        }

        read_nim_config(file, head);
        fclose(file);
    }
}
```
