void init_transport_channels(unsigned int num_channels, lte_transport_channel_t* transport_channels[], system_specific_failure_model_t* failure_model, log_handler_t* log_handler) {
    unsigned int i;
    transport_channel_id_t id = 0;
    lte_transport_channel_status_t** channel_statuses;
    bool success = true;

    channel_statuses = (lte_transport_channel_status_t**) malloc(num_channels * sizeof(lte_transport_channel_status_t*));
    if (!channel_statuses) {
        log_handler("Failed to allocate memory for transport channels status array.");
        success = false;
        goto cleanup;
    }

    for (i = 0; i < num_channels && success; ++i) {
        transport_channels[i] = lte_transport_channel_create();
        if (!transport_channels[i]) {
            log_handler("Failed to create transport channel.");
            success = false;
            id = i;
            break;
        }

        channel_statuses[i] = malloc(sizeof(lte_transport_channel_status_t));
        if (!channel_statuses[i]) {
            log_handler("Failed to allocate memory for transport channel status.");
            success = false;
            id = i;
            break;
        }

        channel_statuses[i]->transport_channel_id = id++;
        channel_statuses[i]->error = failure_model->generate_failure(channel_statuses[i]);
    }

cleanup:
    for (; i < num_channels; ++i) {
        if (channel_statuses[i]) {
            free(channel_statuses[i]);
            channel_statuses[i] = NULL;
        }
    }

    free(channel_statuses);

    if (!success) {
        log_handler("Initialization of transport channels failed.");
        for (i = id; i < num_channels; ++i) {
            lte_transport_channel_destroy(transport_channels[i]);
            transport_channels[i] = NULL;
        }
    }
}
