    char *destination_path;
    int rotation_size;
    bool gzipped;
} LoggerConfig;

struct LoggingEnvironment {
    size_t num_loggers;
    LoggerConfig **loggers;
    pthread_mutex_t lock;
};

struct LoggingEnvironment *init_logging_environment() {
    struct LoggingEnvironment *env = malloc(sizeof(struct LoggingEnvironment));
    if (!env) return NULL;

    env->num_loggers = 0;
    env->loggers = NULL;
    pthread_mutex_init(&env->lock, NULL);

    return env;
}

static void free_logger(LoggerConfig *logger) {
    if (logger->destination_path) free(logger->destination_path);
    free(logger);
}

void add_logger_config(struct LoggingEnvironment *env, const char *json_data) {
    // Parse JSON data and validate it here.
    // If parsing fails or the configuration is invalid, return early without adding to env->loggers.

    LoggerConfig *new_logger = malloc(sizeof(LoggerConfig));
    json_object *log_obj = json_tokener_parse(json_data);
    if (log_obj && json_object_get_type(log_obj) == json_type_object) {
        json_object *log_level_obj = json_object_object_get(log_obj, "log_level");
        json_object *dest_path_obj = json_object_object_get(log_obj, "destination_path");
        json_object *rotation_size_obj = json_object_object_get(log_obj, "rotation_size");
        json_object *gzipped_obj = json_object_object_get(log_obj, "gzipped");

        if (log_level_obj && dest_path_obj && rotation_size_obj && gzipped_obj) {
            new_logger->log_level = parse_log_level(json_object_get_int(log_level_obj));
            new_logger->destination_path = strdup(json_object_get_string(dest_path_obj));
            new_logger->rotation_size = json_object_get_int(rotation_size_obj);
            new_logger->gzipped = json_object_get_boolean(gzipped_obj);
        } else {
            free(new_logger);
            return;
        }
    } else {
        free(new_logger);
        return;
    }

    pthread_mutex_lock(&env->lock);
    if (env->num_loggers + 1 > env->max_loggers) {
        // Handle memory constraints and graceful degradation here.
    }
    env->loggers = realloc(env->loggers, sizeof(LoggerConfig *) * (env->num_loggers + 1));
    if (!env->loggers) {
        pthread_mutex_unlock(&env->lock);
        free(new_logger);
        return;
    }
    env->loggers[env->num_loggers] = new_logger;
    env->num_loggers++;
    pthread_mutex_unlock(&env->lock);
}

void load_logging_configs(struct LoggingEnvironment *env, const char *const *json_files) {
    // Implement caching mechanism for efficient reuse of parsed JSON data.

    for (size_t i = 0; json_files[i] != NULL; ++i) {
        FILE *fp = fopen(json_files[i], "r");
        if (!fp) continue; // Skip file open errors and move on to the next one.

        char *json_data = NULL;
        size_t json_len = 0;
        size_t read_len;

        read_len = getline(&json_data, &json_len, fp);
        while (read_len > 0 && !feof(fp)) {
            add_logger_config(env, json_data);
            read_len = getline(&json_data, &json_len, fp);
        }

        free(json_data);
        fclose(fp);
    }
}

void cleanup_logging_environment(struct LoggingEnvironment *env) {
    pthread_mutex_destroy(&env->lock);
    for (size_t i = 0; i < env->num_loggers; ++i) {
        free_logger(env->loggers[i]);
    }
    free(env->loggers);
    free(env);
}
