#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

#define BUFFER_MAX_SIZE 1024
#define LOGGING_ENABLED 1

NFAPI_CRC_INDICATION_PDU_T buffer[BUFFER_MAX_SIZE];
size_t head = 0, tail = 0;
pthread_mutex_t mutex;
pthread_cond_t not_full, not_empty;

void reset_buffer() {
    head = tail = 0;
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&not_full, NULL);
    pthread_cond_init(&not_empty, NULL);
}

int add_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&mutex);
    while ((head + 1) % BUFFER_MAX_SIZE == tail || buffer[(head + 1) % BUFFER_MAX_SIZE].timestamp != 0) {
        pthread_cond_wait(&not_full, &mutex);
    }

    buffer[(head + 1) % BUFFER_MAX_SIZE] = *entry;
    entry->timestamp = time(NULL);
    head = (head + 1) % BUFFER_MAX_SIZE;
    if (LOGGING_ENABLED) printf("Added entry\n");

    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&mutex);
    return 0;
}

int remove_oldest_entry() {
    pthread_mutex_lock(&mutex);
    while (tail == head) {
        pthread_cond_wait(&not_empty, &mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T oldest = buffer[tail];
    tail = (tail + 1) % BUFFER_MAX_SIZE;
    if (LOGGING_ENABLED) printf("Removed oldest entry\n");

    pthread_mutex_unlock(&mutex);
    return 0;
}

void iterate_forward() {
    pthread_mutex_lock(&mutex);
    size_t current = tail;
    while (current != head) {
        printf("Iterated forward: %d, %d, %d, %ld\n", buffer[current].tag.value, buffer[current].rnti, buffer[current].crc_indication.crc_flag, buffer[current].timestamp);
        current = (current + 1) % BUFFER_MAX_SIZE;
    }
    pthread_mutex_unlock(&mutex);
}

void iterate_reverse() {
    pthread_mutex_lock(&mutex);
    size_t current = head;
    while (current != tail) {
        current = (current + BUFFER_MAX_SIZE - 1) % BUFFER_MAX_SIZE;
        printf("Iterated reverse: %d, %d, %d, %ld\n", buffer[current].tag.value, buffer[current].rnti, buffer[current].crc_indication.crc_flag, buffer[current].timestamp);
    }
    pthread_mutex_unlock(&mutex);
}
```

This code provides a circular buffer implementation using mutexes and condition variables for thread safety. The buffer is configured to hold up to BUFFER_MAX_SIZE structures, and the add_entry() function handles edge cases like buffer overflows gracefully by waiting until space becomes available.

You may need to adjust the code to fit your specific data types (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG) and provide logging functionality as requested. The provided iterate_forward() and iterate_reverse() functions demonstrate how to safely iterate over the buffer entries in both directions.

Remember to release any allocated resources when resetting the buffer using a function like reset_buffer(). You can also implement configuration options for enabling or disabling logging dynamically at runtime by modifying the LOGGING_ENABLED constant.']

