#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/mman.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct project* project;
    struct dependency** dependencies;
} list_entry;

struct project {
    char name[256];
    int budget;
    struct tm start_date;
    struct dependency** dependencies;
    struct project *next;
};

struct dependency {
    struct project* project;
    struct dependency* next;
};

#define BUFFER_SIZE 10000
static list_entry* buffer = NULL;
static size_t count = 0, head = 0, tail = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE* log_file = NULL;

void init_logging() {
    char filename[] = "log.txt";
    log_file = fopen(filename, "w");
}

void log(const char* message) {
    if (log_file == NULL)
        init_logging();
    time_t current_time;
    char time_str[26];
    current_time = time(NULL);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
    fprintf(log_file, "%s: %s\n", time_str, message);
}

void cleanup() {
    if (buffer) {
        for (size_t i = head; i < tail; ++i) {
            free(buffer[i].project->name);
            free(buffer[i].project);
        }
        free(buffer);
    }

    if (log_file)
        fclose(log_file);
}

int add_project(const char* name, int budget, struct tm start_date, ...) {
    va_list args;
    struct project* new_project = malloc(sizeof(struct project));
    if (!new_project) {
        perror("malloc failed");
        return -1;
    }
    memset(new_project, 0, sizeof(*new_project));
    strncpy(new_project->name, name, sizeof(new_project->name));
    new_project->budget = budget;
    memcpy(&new_project->start_date, &start_date, sizeof(struct tm));

    pthread_mutex_lock(&mutex);
    if (count >= BUFFER_SIZE) {
        size_t oldest = head;
        if (++oldest == BUFFER_SIZE)
            oldest = 0;
        free(buffer[oldest].project);
        buffer[oldest].project = NULL;
        --count;
    }

    va_start(args, start_date);
    while (true) {
        struct dependency* new_dep = malloc(sizeof(*new_dep));
        if (!new_dep) {
            perror("malloc failed");
            goto error;
        }
        new_dep->project = NULL;
        new_dep->next = buffer[tail].dependencies;

        struct project* dep_project = va_arg(args, struct project*);
        if (!dep_project) {
            free(new_dep);
            break;
        }
        new_dep->project = dep_project;

        buffer[tail].dependencies = &new_dep->next;
        if (va_arg(args, int))
            continue;
        break;
    }
    va_end(args);

    buffer[tail].project = new_project;
    buffer[tail].timestamp = time(NULL);
    ++count;
    tail = (tail + 1) % BUFFER_SIZE;
    log("Added project: name=%s, budget=%d, start_date=%s", new_project->name, new_project->budget, asctime(&new_project->start_date));
    return 0;

error:
    pthread_mutex_unlock(&mutex);
    free(new_project);
    return -1;
}

int remove_project(struct project* project) {
    pthread_mutex_lock(&mutex);
    size_t index = (size_t)(project - buffer[head].project);
    if (index >= BUFFER_SIZE)
        index -= BUFFER_SIZE;

    struct dependency** current = &buffer[head].dependencies;
    for (size_t i = head; i != index; ++i) {
        if (!current || !*current) {
            log("Invalid project reference");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        current = &(*current)->next;
    }

    struct dependency** dependencies = &buffer[index].dependencies;
    while (*dependencies) {
        struct dependency* temp = *dependencies;
        *dependencies = temp->next;
        free(temp);
    }

    free(project->name);
    free(project);
    --count;
    if (index == head) {
        if (!++head)
            head = BUFFER_SIZE;
    }
    log("Removed project: name=%s", project->name);
    pthread_mutex_unlock(&mutex);
    return 0;
}
