#define MAX_LIST_SIZE 1024
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t count = 0;
static size_t capacity = 0;
static pthread_mutex_t mutex;
static FILE* logfile;

void create_log(const char *filename) {
    logfile = fopen(filename, "w");
}

void log_entry(NFAPI_CRC_INDICATION_PDU_T element) {
    if (logfile != NULL) {
        fprintf(logfile, "RNTI: %d CRCFLAG: %d\n", element.rnti, element.crc_indication_rel8_tag);
    }
}

bool add_element(NFAPI_CRCI_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&mutex);

    if (count == capacity && capacity != MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (capacity + 1));

        if (!temp) {
            pthread_mutex_unlock(&mutex);
            return false;
        }

        list = temp;
        capacity++;
    }

    // Check for duplicate RNTI entries and log them to aid in debugging and auditing.
    bool found_duplicate = false;
    size_t i;
    for (i = 0; i < count; ++i) {
        if (list[i].rnti == new_element->rnti) {
            found_duplicate = true;
            break;
        }
    }

    if (found_duplicate) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    list[count] = *new_element;
    count++;

    pthread_mutex_unlock(&mutex);
    log_entry(list[count - 1]); // Log the newly added element.

    return true;
}

void serialize_list(FILE* output) {
    if (list && capacity > 0) {
        fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, output);
    }
}

// Implement the error mask function to determine the CRCFLAG based on specific conditions.
// This example demonstrates a simple example where CRCFLAG is set when an RNTI value is even.
bool determine_crcflag(uint16_t rnti) {
    return (rnti & 1) == 0;
}

// Main function to populate the list with NFAPI_CRC_INDICATION_PDU_T structures based on a variable number of UE identifiers.
void populate_list(const uint16_t* ue_identifiers, size_t num_ue_identifiers) {
    if (num_ue_identifiers == 0 || !ue_identifiers)
        return;

    size_t i;
    for (i = 0; i < num_ue_identifiers; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_element = { .rx_ue_information_tag = RX_UE_INFORMATION_TAG,
                                                  .rnti = ue_identifiers[i],
                                                  .crc_indication_rel8_tag = determine_crcflag(ue_identifiers[i]) ? CRC_INDICATION_REL8_TAG : NO_CRC_INDICATION_REL8_TAG,
                                                  .crcflag = determine_crcflag(ue_identifiers[i]) };
        add_element(&new_element);
    }
}
