// Maximum allowable list size (M) is adjustable at runtime
#define MAX_LIST_SIZE 1024

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
struct nfapi_crc_indication_pdu {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
