};

// Define the structure for thread-safe list management
struct list_manager {
    struct nfapi_crc_indication_pdu* data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
};

// Function to initialize a list manager with an initial capacity of N
struct list_manager* create_list_manager(size_t n) {
    struct list_manager* manager = malloc(sizeof(struct list_manager));
    if (!manager) return NULL;

    // Ensure proper initialization of the mutex
    pthread_mutex_init(&manager->lock, NULL);

    manager->data = calloc(n, sizeof(struct nfapi_crc_indication_pdu));
    if (!manager->data) {
        free(manager);
        return NULL;
    }

    manager->capacity = n;
    manager->count = 0;
    return manager;
}

// Function to add an element to the list, handling errors and updates to count and capacity if necessary
void add_to_list(struct list_manager* manager, const struct nfapi_crc_indication_pdu* pdu) {
    // Lock the mutex before modifying shared data
    pthread_mutex_lock(&manager->lock);

    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->data[i].rnti == pdu->rnti) {
            // RNTIs must be unique, so if we find a duplicate, do not add the element
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count >= manager->capacity) {
        // If we reach the maximum capacity, double the capacity and reallocate memory
        manager->capacity *= 2;
        manager->data = realloc(manager->data, manager->capacity * sizeof(struct nfapi_crc_indication_pdu));
        if (!manager->data) {
            // If reallocation fails, free existing data and return an error
            pthread_mutex_unlock(&manager->lock);
            free(manager);
            return;
        }
    }

    manager->data[manager->count] = *pdu;
    ++manager->count;

    // Unlock the mutex after modifying shared data
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a random CRCFLAG value for a new struct
uint8_t get_random_crcflag() {
    return (rand() % 2) == 0 ? 1 : 0;
}

// Function to create and add a new struct to the list, ensuring unique RNTIs and handling errors
void generate_and_add_pdu(struct list_manager* manager) {
    // Create a new struct with a random RNTI and CRCFLAG
    struct nfapi_crc_indication_pdu pdu = { .rnti = rand() % UINT32_MAX, .crc_indication_rel8_tag.crcflag = get_random_crcflag() };

    // Attempt to add the new struct to the list
    if (add_to_list(manager, &pdu)) {
        // If successful, print success message and return
        printf("Successfully added PDU with RNTI: %u\n", pdu.rnti);
        return;
    } else {
        // If unsuccessful, print error message and return
        printf("Error: Failed to add PDU due to unique RNTI violation or memory allocation failure\n");
    }
}

// Function to dynamically update the maximum list size (M) from an external data source
void set_max_list_size(struct list_manager* manager, size_t new_max_list_size) {
    // Lock the mutex before modifying shared data
    pthread_mutex_lock(&manager->lock);

    if (new_max_list_size > MAX_LIST_SIZE || new_max_list_size < manager->capacity) {
        free(manager->data);
        manager->data = calloc(new_max_list_size, sizeof(struct nfapi_crc_indication_pdu));
        if (!manager->data) {
            // If reallocation fails, free existing data and unlock the mutex
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->capacity = new_max_list_size;
    }

    // Unlock the mutex after modifying shared data
    pthread_mutex_unlock(&manager->lock);
}
