    public class DatabaseProcessor
    {
        private IMongoDatabase _database;

        public DatabaseProcessor()
        {
            var connectionString = ConfigurationManager.AppSettings["DatabaseConnection"];
            _database = new MongoClient(connectionString).GetDatabase("MyDatabase");
        }

        public async Task<DataTableReader> ProcessByteArrayAsync(byte[] data)
        {
            var query = JsonConvert.SerializeObject(data); // Serialize byte array to string for dynamic query construction
            var collection = _database.GetCollection<BsonDocument>("MyCollection");

            try
            {
                var result = await collection.Aggregate()
                    .Match(x => x["content"].Equals(query))
                    .Project(x => new BsonDocument("_id", 0).AddRange(new BsonDocument[]{x["data"]})) // Project only data field
                    .FirstOrDefaultAsync();

                if (result == null) return null;

                var dt = DataTable.FromQuery(result["data"].ToString()); // Deserialize byte array from string to DataTable
                return dt.CreateDataReader();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing data: {ex}");
                throw;
            }
        }

        public IEnumerable<Tuple<string, Func<byte[], byte[]>, params object[]>> GetCryptographicAlgorithms()
        {
            var assembly = Assembly.GetExecutingAssembly();

            var algorithms = from t in assembly.GetTypes()
                             where typeof(ICryptoAlgorithm).IsAssignableFrom(t)
                             select new Tuple<string, Func<byte[], byte[]>, params object[]>(t.Name, (Func<byte[], byte[]>) Delegate.CreateDelegate(typeof(Func<byte[], byte[]>), Activator.CreateInstance(t)), t.GetCustomAttributes(false).OfType<CryptoAlgorithmParameterAttribute>().Select(a => a.Parameter).ToArray());

            return algorithms;
        }
    }

    public interface ICryptoAlgorithm
    {
        byte[] ComputeHash(byte[] data, params object[] parameters);
        byte[] Encrypt(byte[] data, params object[] parameters);
        byte[] Decrypt(byte[] data, params object[] parameters);
    }

    [AttributeUsage(AttributeTargets.Method)]
    public class CryptoAlgorithmParameterAttribute : Attribute
    {
        public readonly object Parameter;

        public CryptoAlgorithmParameterAttribute(object parameter) => this.Parameter = parameter;
    }
}
