#include <pthread.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>

#define MAX_ARRAY_SIZE 10000
#define PRUNE_INTERVAL 60 // in seconds
typedef struct Message {
    char payload[256];
    time_t timestamp;
    pid_t id;
} Message;

struct MessageQueue {
    Message* array;
    size_t size;
    size_t capacity;
    sem_t mutex;
    sem_t notFull;
    sem_t notEmpty;
    time_t prune_last;
};

void message_queue_init(struct MessageQueue* q, size_t initial_capacity) {
    q->array = malloc(initial_capacity * sizeof(Message));
    q->size = 0;
    q->capacity = initial_capacity;
    sem_init(&q->mutex, 0, 1);
    sem_init(&q->notFull, 0, initial_capacity);
    sem_init(&q->notEmpty, 0, 0);
}

void message_queue_destroy(struct MessageQueue* q) {
    free(q->array);
    sem_destroy(&q->mutex);
    sem_destroy(&q->notFull);
    sem_destroy(&q->notEmpty);
}

bool message_queue_is_full(const struct MessageQueue* q) {
    return q->size == q->capacity;
}

bool message_queue_can_push(const struct MessageQueue* q) {
    return sem_trywait(&q->notFull);
}

void message_queue_push(struct MessageQueue* q, const Message* m) {
    if (!message_queue_can_push(q)) {
        // Handle overflow.
        return;
    }
    sem_wait(&q->mutex);
    memcpy(q->array + q->size, m, sizeof(Message));
    q->size++;
    if (q->size == 1) {
        sem_post(&q->notEmpty);
    }
    sem_post(&q->mutex);
}

void message_queue_prune(struct MessageQueue* q) {
    time_t now = time(NULL);
    if (now - q->prune_last < PRUNE_INTERVAL) {
        return;
    }
    q->prune_last = now;

    sem_wait(&q->mutex);
    size_t i = 0;
    for (; i < q->size; ++i) {
        if ((now - q->array[i].timestamp) > PRUNE_INTERVAL) {
            Message* to_be_pruned = &q->array[i];
            // Prune the message, notify external service, and shift remaining elements.
            // Implement pruning logic here.
            break;
        }
    }
    memmove(q->array, q->array + i, (q->size - i) * sizeof(Message));
    q->size -= i;
    if (q->size == 0) {
        sem_post(&q->notEmpty);
    }
    sem_post(&q->mutex);
}
