#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define M 100 // Maximum number of structures to store

struct LRU_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LRU_node *prev;
    struct LRU_node *next;
};

typedef struct LRU_node LRU_node;

struct lru_list {
    LRU_node *head;
    LRU_node *tail;
    size_t size;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock; // For read operations
};

typedef struct lru_list LRU_list;

LRU_list* create_lru_list() {
    LRU_list *list = malloc(sizeof(LRU_list));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for LRU list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void lru_add(LRU_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    LRU_node *new_node = malloc(sizeof(LRU_node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return;
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->size == M) {
        LRU_node *lru_node = list->head;
        if (lru_node) {
            list->head = lru_node->next;
            free(lru_node);
            --list->size;
        }
    }
    pthread_rwlock_wrlock(&list->rwlock); // Write lock to update the list

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    ++list->size;
    pthread_rwlock_unlock(&list->rwlock); // Release write lock
    pthread_mutex_unlock(&list->lock);
}

void lru_remove(LRU_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    LRU_node *current = list->head;
    bool found = false;

    pthread_mutex_lock(&list->lock);
    pthread_rwlock_rdlock(&list->rwlock); // Read lock to iterate through the list

    while (current != NULL) {
        if (current->data == data) {
            found = true;
            break;
        }
        current = current->next;
    }

    if (!found) {
        pthread_mutex_unlock(&list->lock);
        pthread_rwlock_unlock(&list->rwlock);
        return;
    }

    if (current == list->head) {
        list->head = current->next;
    }

    if (current->prev)
        current->prev->next = current->next;

    if (current->next)
        current->next->prev = current->prev;

    if (current == list->tail) {
        list->tail = current->prev;
    }

    --list->size;
    free(current);

    pthread_rwlock_unlock(&list->rwlock); // Release read lock
