class LtePhyStatsList {
private:
    std::list<std::shared_ptr<LtePhyStats>> data;
    std::atomic<size_t> size{0};
    std::mutex mutex;

public:
    void push_back(const std::shared_ptr<LtePhyStats>& stats) {
        std::lock_guard<std::mutex> lock(mutex);
        data.emplace_back(stats);
        ++size;
    }

    const std::shared_ptr<LtePhyStats>& front() const {
        std::lock_guard<std::mutex> lock(mutex);
        return *data.begin();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex);
        return size;
    }
};

class LtePhyStatsManager {
private:
    LtePhyStatsList statsList;
    std::unique_ptr<externalDataFetcher> dataFetcher;
    bool isRunning{true};

    void workerThread() {
        while (isRunning) {
            auto stats = dataFetcher->fetchMetrics();
            if (stats) {
                std::lock_guard<std::shared_mutex> lock(statsList.get_shared_mutex());
                statsList.push_back(std::make_shared<LtePhyStats>(*stats));
            }
        }
    }

public:
    LtePhyStatsManager() : dataFetcher(new externalDataFetcher()) {
        std::thread worker(workerThread, shared_from_this());
        worker.detach();
    }

    ~LtePhyStatsManager() { isRunning = false; }

    const std::shared_ptr<LtePhyStats>& getFrontStats() const {
        std::lock_guard<std::shared_mutex> lock(statsList.get_shared_mutex());
        return statsList.front();
    }
};
