#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

#define MAX_LIST_SIZE 10000
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    sem_t lock;
} NFAPI_CRC_INDICATION_PDU;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU *data;
    struct list_node *next;
} ListNode;

struct dynamic_list {
    ListNode *head;
    ListNode *tail;
    size_t length;
    sem_t grow_sem;
    sem_t shrink_sem;
};

void init_dynamic_list(struct dynamic_list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->length = 0;
    sem_init(&list->grow_sem, 0, MAX_LIST_SIZE);
    sem_init(&list->shrink_sem, 0, 0);
}

void append(struct dynamic_list* list, NFAPI_CRC_INDICATION_PDU* data) {
    ListNode *new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        printf("Error: Out of memory\n");
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    sem_wait(&list->grow_sem);
    if (list->length >= MAX_LIST_SIZE) {
        printf("Error: List is full\n");
        free(new_node);
        sem_post(&list->shrink_sem);
        return;
    }
    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    sem_post(&list->grow_sem);
    ++(list->length);
}

void remove(struct dynamic_list* list, size_t index) {
    ListNode *current = list->head;
    ListNode *prev = NULL;

    sem_wait(&list->shrink_sem);

    if (index >= list->length) {
        printf("Error: Index out of range\n");
        sem_post(&list->shrink_sem);
        return;
    }

    for (size_t i = 0; i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        printf("Error: Index out of range\n");
        sem_post(&list->shrink_sem);
        return;
    }

    if (prev)
        prev->next = current->next;
    else
        list->head = current->next;

    if (!current->next)
        list->tail = prev;

    free(current->data);
    free(current);
    --(list->length);
    sem_post(&list->shrink_sem);
}

NFAPI_CRC_INDICATION_PDU* get_nth(struct dynamic_list* list, size_t index) {
    ListNode *current = list->head;

    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (!current) {
        printf("Error: Index out of range\n");
        return NULL;
    }

    sem_wait(&current->data->lock);
    NFAPI_CRC_INDICATION_PDU* data = current->data;
    sem_post(&current->data->lock);
    return data;
}

void log_event(const char *message) {
    // Implement logging mechanism here
}
```

