struct TCP_CONNECTION {
    pthread_mutex_t mutex;
    pid_t connection_id;
    time_t transaction_timestamp;
    char data_buffer[MAX_BUFFER_SIZE];
};

// Function to initialize and populate an array of TCP_CONNECTION structures
void init_connections(struct TCP_CONNECTION **connections, size_t max_connections) {
    struct rlimit mem_limit;
    if (getrlimit(RLIMIT_DATA, &mem_limit) == -1) {
        fprintf(stderr, "Error: Cannot get memory limit\n");
        exit(EXIT_FAILURE);
    }

    double max_memory = mem_limit.rlim_max * 0.8; // Limit to 80% of available system resources
    size_t buffer_size_range = (MAX_BUFFER_SIZE * max_memory) / 100;

    *connections = mmap(NULL, sizeof(struct TCP_CONNECTION) * max_connections, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (*connections == MAP_FAILED) {
        perror("Error: Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < max_connections; ++i) {
        pthread_mutex_init(&(*connections)[i].mutex, NULL);
        (*connections)[i].connection_id = getpid();
        (*connections)[i].transaction_timestamp = time(NULL);
        srand((*connections)[i].connection_id * i + time(NULL));
        size_t data_buffer_size = rand() % buffer_size_range + 1;
        memset((*connections)[i].data_buffer, rand(), data_buffer_size);
    }
}

// Function to handle memory exhaustion scenarios gracefully
void handle_memory_exhaustion(struct TCP_CONNECTION **connections) {
    size_t max_connections = (sizeof(*connections)) / sizeof(**connections);
    if (max_connections > 1) { // Reduce number of connections if memory exhaustion occurs
        *connections += max_connections / 2;
        memset(*connections, 0, sizeof(struct TCP_CONNECTION));
    }
}
```
