}

void update(unsigned int id, const LTEPHYCONTEXT *context) {
    if (!validate_id(id)) {
        log("Error: Invalid configuration ID.");
        return;
    }
    pthread_mutex_lock(&configs_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (configs[i].id == id) {
            configs[i] = *context;
            break;
        }
    }
    pthread_mutex_unlock(&configs_mutex);
}

void delete(unsigned int id) {
    if (!validate_id(id)) {
        log("Error: Invalid configuration ID.");
        return;
    }
    pthread_mutex_lock(&configs_mutex);
    size_t index = -1;
    for (size_t i = 0; i < size; ++i) {
        if (configs[i].id == id) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        memmove(&configs[index], &configs[index + 1], (size - index - 1)*sizeof(LTEPHYCONTEXT));
        --size;
    }
    pthread_mutex_unlock(&configs_mutex);
}
