#define MAX_CONFIGS 10000

struct LTEPHYCONTEXT {
    unsigned int id;
    std::vector<double> uplink_params; // bandwidth, subcarrier spacing, center frequency
    std::vector<double> downlink_params;
};

std::atomic<int> num_configs{0};
std::map<unsigned int, LTEPHYCONTEXT*> config_map;
sem_t config_mutex;

void add_config(LTEPHYCONTEXT* config) {
    if (num_configs >= MAX_CONFIGS) {
        std::cerr << "Error: Maximum number of configurations reached." << std::endl;
        return;
    }

    sem_wait(&config_mutex);
    config->id = num_configs++;
    config_map[config->id] = config;
    sem_post(&config_mutex);
}

void update_config(unsigned int id, LTEPHYCONTEXT* new_config) {
    auto it = config_map.find(id);
    if (it == config_map.end()) {
        std::cerr << "Error: Configuration not found." << std::endl;
        return;
    }

    sem_wait(&config_mutex);
    *it->second = *new_config;
    sem_post(&config_mutex);
}

void delete_config(unsigned int id) {
    auto it = config_map.find(id);
    if (it == config_map.end()) {
        std::cerr << "Error: Configuration not found." << std::endl;
        return;
    }

    sem_wait(&config_mutex);
    delete it->second;
    config_map.erase(it);
    sem_post(&config_mutex);
}

