```cpp
#include <iostream>
#include <random>
#include <boost/lockfree/queue.hpp>
#include <boost/unordered_map.hpp>
#include <cstdint>

struct RX_UE_INFORMATION_TAG { uint16_t tag; };
struct RNTI { uint32_t value; };
struct CRC_INDICATION_REL8_TAG { bool crcflag; };
struct NFAPI_CRC_INDICATION_PDU_T { RX_UE_INFORMATION_TAG rx_ue_info; RNTI rnti; CRC_INDICATION_REL8_TAG crc_indication; };

typedef boost::lockfree::queue<NFAPI_CRC_INDICATION_PDU_T> PDUQueue;

boost::unordered_map<uint32_t, uint64_t> rntiMap; // Hashing table for RNTI uniqueness check

void generate_pdus(size_t N, PDUQueue& pduQ) {
    static std::mt19937 prng(std::random_device{}());
    auto genRnti = [&prng]() -> RNTI {
        uint64_t hash = prng();
        while (rntiMap.count(hash)) hash = prng();
        rntiMap[hash] = hash; // Mark as used in the hash table
        return static_cast<RNTI>(hash);
    };

    for (size_t i = 0; i < N; ++i) {
        RX_UE_INFORMATION_TAG tag{static_cast<uint16_t>(i % 256)};
        auto rnti = genRnti();
        auto crcIndication{rand() & 1}; // Set CRCFLAG to 0 or 1 randomly
        pduQ.push(NFAPI_CRC_INDICATION_PDU_T{tag, rnti, {crcIndication}});
    }
}
```

