typedef struct {
    char *url;
    CURL *curl_handle;
    NFAPI_CRC_INDICATION_PDU_T *data;
    int index;
    pthread_mutex_t lock;
} DownloadTask;

static size_t write_data(void *ptr, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    DownloadTask *task = (DownloadTask *)userp;
    json_object *header_obj = json_tokener_parse(ptr);
    struct stat st;
    char *filename = json_object_get_string(json_object_get(header_obj, "Content-Disposition"));
    if (stat(filename, &st) == 0 && S_ISREG(st.st_mode)) {
        task->last_modified_timestamp = st.st_mtime;
    }
    json_decref(header_obj);
    free(ptr);
    return realsize;
}

void *fetch_data(void *arg) {
