    CURLcode res;
    res = curl_easy_setopt(task->curl_handle, CURLOPT_URL, task->url);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    res = curl_easy_setopt(task->curl_handle, CURLOPT_WRITEFUNCTION, write_data);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set write callback: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    res = curl_easy_perform(task->curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Fetch failed: %s\n", curl_easy_strerror(res));
    }

    // Extract and process the downloaded data here

    return NULL;
}

void create_crc_indications(int N, const char *base_url[], int max_threads, long timeout_ms, int *crc_flags, char **random_strings) {
    pthread_t threads[max_threads];
    DownloadTask tasks[max_threads];
    for (int i = 0; i < max_threads; ++i) {
        tasks[i].url = base_url[i % arraylen(base_url)];
        tasks[i].data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (int j = 0; j < N; ++j) {
            tasks[i].data[j].rx_ue_information_tag = rand();
            tasks[i].data[j].rnti = rand();
            tasks[i].data[j].crc_indication_rel8_tag = (uint16_t)(rand() & 0xFFFF);
        }
        tasks[i].index = i;
        pthread_mutex_init(&tasks[i].lock, NULL);
        tasks[i].curl_handle = curl_easy_init();
    }

    long start = time(NULL);
    for (int i = 0; i < max_threads; ++i) {
        pthread_create(&threads[i], NULL, fetch_data, &tasks[i]);
    }

    // Wait for all threads to finish and gather results

    long elapsed = time(NULL) - start;
    if (elapsed > timeout_ms) {
        fprintf(stderr, "Execution took too long: %ld ms\n", elapsed);
    }
}
