#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag; // based on the parity of RNTI value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRCI_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t mutex; // for thread safety
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);
    return new_node;
}

void push_back(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }
    Node* last = *head_ref;
    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
}

Node* pop_front(Node** head_ref) {
    if (*head_ref == NULL) return NULL;
    Node* temp = *head_ref;
    *head_ref = (*head_ref)->next;
    free(temp);
    return temp;
}

void clear_list(Node** head_ref) {
    while (*head_ref != NULL) {
        Node* temp = pop_front(head_ref);
        free(temp);
    }
}

