typedef struct {
    MAC_INST* mac_inst;
    PHY_INST* phy_inst;
} LTE_DL_FRAMEINFO;

struct frame_list_node {
    LTE_DL_FRAMEINFO frame_info;
    struct frame_list_node *next;
};

typedef struct frame_list_node FrameListNode;

struct manage_dl_frames {
    FrameListNode** frames;
    size_t capacity;
    size_t count;
    semaphore_t lock;
};

void init_manage_dl_frames(struct manage_dl_frames* dl_frames, size_t initial_capacity) {
    dl_frames->capacity = initial_capacity;
    dl_frames->count = 0;
    sem_init(&dl_frames->lock, 0, 1);
    dl_frames->frames = (FrameListNode**)calloc(initial_capacity, sizeof(FrameListNode*));
}

void destroy_manage_dl_frames(struct manage_dl_frames* dl_frames) {
    for (size_t i = 0; i < dl_frames->capacity; ++i) {
        FrameListNode *node = dl_frames->frames[i];
        free(node);
    }
    free(dl_frames->frames);
    sem_destroy(&dl_frames->lock);
}

FrameListNode* acquire_list_node() {
    FrameListNode* node = (FrameListNode*)malloc(sizeof(FrameListNode));
    if (!node) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    return node;
}

void release_list_node(FrameListNode *node) {
    free(node);
}

void lock(struct manage_dl_frames* dl_frames) {
    sem_wait(&dl_frames->lock);
}

void unlock(struct manage_dl_frames* dl_frames) {
    sem_post(&dl_frames->lock);
}

bool add_frame_info(struct manage_dl_frames* dl_frames, LTE_DL_FRAMEINFO frame_info) {
    lock(dl_frames);
    if (dl_frames->count >= dl_frames->capacity) {
        size_t new_capacity = dl_frames->capacity * 2;
        FrameListNode** temp_array = (FrameListNode**)realloc(dl_frames->frames, new_capacity * sizeof(FrameListNode*));
        if (!temp_array) {
            fprintf(stderr, "Out of memory\n");
            unlock(dl_frames);
            return false;
        }
        dl_frames->frames = temp_array;
        dl_frames->capacity = new_capacity;
    }
    FrameListNode *node = acquire_list_node();
    node->frame_info = frame_info;
    node->next = dl_frames->frames[dl_frames->count];
    dl_frames->frames[dl_frames->count] = node;
    ++dl_frames->count;
    unlock(dl_frames);
    return true;
}

void update_frame_info(struct manage_dl_frames* dl_frames, size_t index, LTE_DL_FRAMEINFO new_frame_info) {
    lock(dl_frames);
    if (index >= dl_frames->count) {
        unlock(dl_frames);
        return;
    }
    FrameListNode* node = dl_frames->frames[index];
    node->frame_info = new_frame_info;
    unlock(dl_frames);
}

void iterate_frame_infos(struct manage_dl_frames* dl_frames, void (*operation)(LTE_DL_FRAMEINFO)) {
    lock(dl_frames);
    FrameListNode *current = dl_frames->frames[0];
    for (size_t i = 0; i < dl_frames->count; ++i) {
        FrameListNode *next = current->next;
        operation(current->frame_info);
        release_list_node(current);
        current = next;
    }
    unlock(dl_frames);
}
```

