    if (!tmp_list) {
        fprintf(stderr, "Failed to allocate memory for cleanup.\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    size_t i = current_count - 1, j = 0;
    while (i >= max_count / 2) {
        tmp_list[j++] = dynamic_list[i--];
    }

    free(dynamic_list + max_count / 2);
    dynamic_list = realloc(tmp_list, (current_count - elements_to_remove) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_list) {
        fprintf(stderr, "Failed to reallocate memory for updated list.\n");
        free(tmp_list);
        return;
    }

    current_count -= elements_to_remove;

    pthread_mutex_unlock(&list_mutex);

    free(tmp_list + elements_to_remove);
}

void* cleanup_thread(void* arg) {
    while (true) {
        pthread_mutex_lock(&list_mutex);

        if (!cleanup_required || current_count < max_count / 2) {
            pthread_cond_wait(&not_full_cond, &list_mutex);
        }

        cleanup();
        usleep(100000); // Adaptive adjustment of the frequency of cleanup operations.

        pthread_mutex_unlock(&list_mutex);
    }

    return NULL;
}

void init() {
    dynamic_list = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_list) {
        fprintf(stderr, "Failed to allocate memory for dynamic list.\n");
        return;
    }

    pthread_mutex_init(&list_mutex, NULL);
    pthread_cond_init(&not_full_cond, NULL);
    pthread_cond_init(&not_empty_cond, NULL);

    pthread_t cleanup_tid;
    if (pthread_create(&cleanup_tid, NULL, &cleanup_thread, NULL)) {
        fprintf(stderr, "Failed to create cleanup thread.\n");
    }
}
```
