#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pq.h>
#include <stdbool.h>
#define NFAPI_CRCI_SIZE sizeof(NFAPI_CRCI_INDICATION_PDU_T)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRCI_INDICATION_PDU_T;

PQ *create_queue(size_t capacity) {
    PQ *queue = pq_new();
    if (!queue) return NULL;
    queue->pool = malloc(capacity * NFAPI_CRCI_SIZE);
    if (!queue->pool) {
        pq_free(queue);
        return NULL;
    }
    queue->len = 0;
    queue->capacity = capacity;
    return queue;
}

bool add_element(PQ *queue, const NFAPI_CRCI_INDICATION_PDU_T *element) {
    if (queue->len + 1 > queue->capacity) return false;

    memcpy(queue->pool + queue->len * NFAPI_CRCI_SIZE, element, NFAPI_CRCI_SIZE);
    pq_push(queue, queue->len++);
    pq_sort(queue, (PQCMPFUNC)compare_elements);
    return true;
}

bool compare_elements(const void *a, const void *b) {
    const NFAPI_CRCI_INDICATION_PDU_T *ia = a;
    const NFAPI_CRCI_INDICATION_PDU_T *ib = b;
    return ia->RX_UE_INFORMATION_TAG < ib->RX_UE_INFORMATION_TAG;
}

void generate_list(PQ **queue, size_t max_elements) {
    srand(time(NULL));
    NFAPI_CRCI_INDICATION_PDU_T element = {0};
    *queue = create_queue(max_elements);

    for (size_t i = 0; i < max_elements; ++i) {
        do {
            element.RNTI = rand() % 0xFFFF + 1; // RNTI values in [1,65535]
        } while ((*queue)->len > 0 && (*queue)->pool[(*queue)->len * NFAPI_CRCI_SIZE].RNTI == element.RNTI);

        element.CRC_INDICATION.CRCFLAG = (rand() % 2) ? true : false; // Randomly set CRCFLAG to either true or false
        add_element(*queue, &element);
    }
}

void free_list(PQ *queue) {
    if (!queue) return;
    free(queue->pool);
    pq_free(queue);
}
```

