#include <arpa/inet.h>

typedef struct TCPConnectionEntry {
    in_addr_t client_ip;
    in_addr_t server_ip;
    int connection_id;
    double throughput_kbps;
    pthread_mutex_t entry_lock;
    time_t last_health_check;
    struct TCPConnectionEntry *next;
} TCPConnectionEntry;

typedef struct ConnectionList {
    TCPConnectionEntry *head;
    TCPConnectionEntry *tail;
    unsigned int size;
    pthread_mutex_t list_lock;
    double current_load;
} ConnectionList;

ConnectionList connections = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0.0};

// Utility function for creating and initializing TCPConnectionEntry
TCPConnectionEntry* create_entry(in_addr_t client_ip, in_addr_t server_ip, int connection_id) {
    TCPConnectionEntry *new_entry = (TCPConnectionEntry*) malloc(sizeof(TCPConnectionEntry));
    if (!new_entry) return NULL;
    pthread_mutex_init(&new_entry->entry_lock, NULL);
    new_entry->client_ip = client_ip;
    new_entry->server_ip = server_ip;
    new_entry->connection_id = connection_id;
    new_entry->throughput_kbps = 0.0;
    new_entry->last_health_check = time(NULL);
    new_entry->next = NULL;
    return new_entry;
}

// Function to add a TCPConnectionEntry to the list
void add_connection(TCPConnectionEntry *new_entry) {
    pthread_mutex_lock(&connections.list_lock);
    if (!connections.head) {
        connections.head = new_entry;
        connections.tail = new_entry;
    } else {
        connections.tail->next = new_entry;
        connections.tail = new_entry;
    }
    connections.size++;
    pthread_mutex_unlock(&connections.list_lock);
}

// Function to handle connection health checks and clean up
void manage_connections(ConnectionList *connections) {
    // Adaptive resource usage logic here (e.g., exponential backoff, load-based frequency adjustments)
    // ...

    pthread_mutex_lock(&connections->list_lock);
    TCPConnectionEntry *current = connections->head;
    while (current != NULL) {
        if ((time(NULL) - current->last_health_check) > 60) {
            // Handle health check, update throughput and last_health_check here
            // ...
        }
        current = current->next;
    }
    pthread_mutex_unlock(&connections->list_lock);
}

// Function to remove a TCPConnectionEntry from the list by connection ID
void remove_connection(int connection_id) {
    pthread_mutex_lock(&connections.list_lock);
    TCPConnectionEntry *current = connections.head;
    TCPConnectionEntry *previous = NULL;

    while (current != NULL) {
        if (current->connection_id == connection_id) {
            if (previous == NULL) {
                connections.head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            connections->size--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&connections.list_lock);
}
