#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct UEInfoNode {
    char RX_UE_Information;
    unsigned int RNTI;
    bool CRC_Indication;
    struct UEInfoNode *next;
} UEInfoNode;

UEInfoNode* create_node(char RX_UE_Information, unsigned int RNTI) {
    UEInfoNode* node = (UEInfoNode*)malloc(sizeof(UEInfoNode));
    if (!node) return NULL;

    node->RX_UE_Information = RX_UE_Information;
    node->RNTI = RNTI;
    node->CRC_Indication = rand() % 2 == 0;
    node->next = NULL;
    return node;
}

void validate_list(UEInfoNode* head) {
    UEInfoNode* current = head;
    if (!current) return;

    while (current->next != NULL) {
        if (current->RNTI == current->next->RNTI) {
            fprintf(stderr, "Invalid RNTI value. Duplicate found.\n");
            exit(1);
        }
        current = current->next;
    }
}

UEInfoNode* initialize_list(unsigned int num_nodes, char (*get_RX_UE_Information)(void), unsigned int (*get_RNTI)(void)) {
    UEInfoNode* head = NULL;
    UEInfoNode* current = NULL;
    srand(time(NULL));

    for (unsigned int i = 0; i < num_nodes; ++i) {
        UEInfoNode* new_node = create_node(get_RX_UE_Information(), get_RNTI());
        if (!new_node) return NULL;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    validate_list(head);
    return head;
}
```

