#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct LTE_DL_FRAMEINFO {
    MAC_INST *macInst;
    PHY_INST *phyInst;
    // other members as needed
} LTE_DL_FRAMEINFO;

// Thread-safe dynamic array of LTE_DL_FRAMEINFO structures using a reader-writer lock
struct lteFrameManager {
    size_t numFrames;
    size_t capacity;
    LTE_DL_FRAMEINFO *frames;
    pthread_rwlock_t rwLock;
};

// Helper function to initialize the lteFrameManager struct
void initLteFrameManager(struct lteFrameManager *manager) {
    manager->numFrames = 0;
    manager->capacity = 0;
    manager->frames = NULL;
    pthread_rwlock_init(&manager->rwLock, NULL);
}

// Helper function to deallocate the memory allocated by lteFrameManager
void freeLteFrameManager(struct lteFrameManager *manager) {
    if (manager->frames != NULL) {
        free(manager->frames);
        manager->frames = NULL;
    }
    pthread_rwlock_destroy(&manager->rwLock);
}

// Helper function to double the capacity of the dynamic array
void resizeLteFrameManager(struct lteFrameManager *manager) {
    if (manager->capacity == 0) manager->capacity = 1;
    size_t newCapacity = manager->capacity * 2;

    LTE_DL_FRAMEINFO *newFrames = realloc(manager->frames, newCapacity * sizeof(LTE_DL_FRAMEINFO));
    if (!newFrames) {
        fprintf(stderr, "Failed to allocate memory for lteFrameManager\n");
        return;
    }
    manager->frames = newFrames;
    manager->capacity = newCapacity;
}

// Function to add a new entry to the dynamic array
void addLteFrameInfo(struct lteFrameManager *manager, MAC_INST *macInst, PHY_INST *phyInst) {
    // Acquire write lock to ensure thread safety
    pthread_rwlock_wrlock(&manager->rwLock);

    if (manager->numFrames == manager->capacity) resizeLteFrameManager(manager);

    manager->frames[manager->numFrames].macInst = macInst;
    manager->frames[manager->numFrames].phyInst = phyInst;

    manager->numFrames++;

    // Release write lock to allow other threads to read the array
    pthread_rwlock_unlock(&manager->rwLock);
}

// Function to update an existing entry in the dynamic array
void updateLteFrameInfo(struct lteFrameManager *manager, size_t index, MAC_INST *macInst, PHY_INST *phyInst) {
    // Acquire write lock to ensure thread safety
    pthread_rwlock_wrlock(&manager->rwLock);

    if (index >= manager->numFrames) {
        fprintf(stderr, "Invalid index: %zu\n", index);
        pthread_rwlock_unlock(&manager->rwLock);
        return;
    }

    manager->frames[index].macInst = macInst;
    manager->frames[index].phyInst = phyInst;

    // Release write lock to allow other threads to read the array
    pthread_rwlock_unlock(&manager->rwLock);
}

// Function to iterate over the dynamic array and perform operations on each LTE_DL_FRAMEINFO instance
void iterateOverFrames(struct lteFrameManager *manager, void (*func)(LTE_DL_FRAMEINFO *)) {
    // Acquire read lock to allow multiple threads to read the array concurrently
    pthread_rwlock_rdlock(&manager->rwLock);

    for (size_t i = 0; i < manager->numFrames; ++i) {
        func(&manager->frames[i]);
    }

    // Release read lock to allow other threads to write the array
    pthread_rwlock_unlock(&manager->rwLock);
}
```

This code example demonstrates an initial implementation of a `lteFrameManager` function, providing safe access and modification capabilities while preventing unintended side effects on the array's integrity. It also implements thread safety using a reader-writer lock, dynamic resizing, and memory management. However, further refinement and optimization may be necessary based on actual performance requirements and specific edge cases.']

