    // Perform necessary checks to ensure the index is valid
    if (index >= MAX_LTE_DL_FRAMES || frames[index].mac_inst != NULL) {
        fprintf(stderr, "Invalid or already occupied frame index\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    frames[index].mac_inst = mac_inst;
    frames[index].phy_inst = phy_inst;

    pthread_mutex_unlock(&mutex);
