    pthread_mutex_lock(&mutex);

    // Perform necessary checks to ensure the index is valid
    if (index >= MAX_LTE_DL_FRAMES || frames[index].mac_inst == NULL) {
        fprintf(stderr, "Invalid or empty frame index\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

