void *fetch_data(void *element);

int initializeLTEConfigAndProcessDOMTree(Context context) {
    this->context = context;

    lte_phy_configs = (LTE_PHY_CONFIG*)malloc(sizeof(LTE_PHY_CONFIG)*16);
    memset(lte_phy_configs, 0, sizeof(LTE_PHY_CONFIG)*16);

    pdu_list = (NFAPI_CRC_INDICATION_PDU**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU*)*32);
    memset(pdu_list, 0, sizeof(NFAPI_CRC_INDICATION_PDU*)*32);

    sem_init(&sem_pdu_list, 0, 0);

    xmlDocPtr doc = xmlReadFile("dom_file.xml", NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        return -1;
    }

    xmlNodePtr current_node = xmlRootElement(doc);

    int pdu_index = 0;
    while (current_node != NULL) {
        if (xmlStrcmp(current_node->name, (xmlChar *)"element")) {
            current_node = current_node->next;
            continue;
        }

        xmlNodePtr content_node = current_node->xmlChildrenNode;
        if (content_node == NULL) {
            current_node = current_node->next;
            continue;
        }

        if (xmlStrcmp(content_node->name, (xmlChar *)"content")) {
            current_node = current_node->next;
            continue;
        }

        char* content = xmlNodeGetContent(content_node);
        if (strlen(content) > context.bandwidth_limit) {
            fprintf(stderr, "Content size exceeds limit\n");
            free(content);
            current_node = current_node->next;
            continue;
        }

        pthread_t data_fetch_thread;
        pdu_list[pdu_index] = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        memset(pdu_list[pdu_index], 0, sizeof(NFAPI_CRC_INDICATION_PDU));
        strcpy(pdu_list[pdu_index]->RX_UE_INFORMATION_TAG, "123456789012");
        pdu_list[pdu_index]->RNTI = rand() % 1 << 16 | rand() % 1 << 8 | rand() % 1 << 1;
        pdu_list[pdu_index]->CRCFLAG = rand() % 2;
        strcpy(pdu_list[pdu_index]->content, content);

        sem_wait(&sem_pdu_list);
        pthread_create(&data_fetch_thread, NULL, fetch_data, (void*)current_node);
        sem_post(&sem_pdu_list);

        current_node = current_node->next;
        pdu_index++;
    }

    xmlFreeDoc(doc);
    xmlCleanupParser();

    return 0;
}

void *fetch_data(void *element) {
