import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

public class DisjointPairFinder {
    private final UF uf;
    private final ExecutorService executor;

    public DisjointPairFinder(int capacity) {
        uf = new BatchUF(capacity);
        executor = Executors.newCachedThreadPool();
    }

    public void processStream(IntStream stream) {
        stream.parallel().forEach(this::processElement);
    }

    private void processElement(int element) {
        int root = uf.find(element);
        if (uf.isRoot(root)) {
            executor.submit(() -> uf.reportRoot(root));
        } else {
            int otherRoot = uf.find(root - 1);
            executor.submit(() -> uf.reportDiscrepancy(element, root, otherRoot));
        }
        uf.union(element, element + 1);
    }

    // UF implementation omitted for brevity. Here's a simplified version:
