            return find(id[x]);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;
            // Perform the union and update sizes
            ...
        }

        public boolean isRoot(int x) {
            return id[x] == x;
        }

        public void reportRoot(int root) {
