    uint8_t reconfiguration_command;
    pthread_mutex_t mutex;
} NFAPI_RRC_RECONFIGURATION_PDU_T;

typedef struct node {
    NFAPI_RRC_RECONFIGURATION_PDU_T data;
    struct node *next;
} node_t;

node_t* create_element(NFAPI_RRC_RECONFIGURATION_PDU_T data) {
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return NULL;
    new_node->data = data;
    pthread_mutex_init(&new_node->data.mutex, NULL);
    new_node->next = NULL;
    return new_node;
}

bool is_valid_command(uint8_t command) {
    // Implement your validation logic here.
    // Example: Return true if the command is in a predefined set of valid values.
    return command >= 0 && command < 10;
}

void check_adjacent_cells(node_t* current, node_t** head) {
    if (!current || !current->next) return;

    while (current != *head && current->next->cell_id == current->cell_id)
        current = current->next;
}

void ensure_no_adjacent_consecutive_cells(node_t** head, node_t* new_element) {
    if (!*head) {
        *head = new_element;
        return;
    }

    check_adjacent_cells((*head)->next, head);
    if ((*head)->next && (*head)->next->cell_id == new_element->data.cell_id) {
        // Handle the case where we need to reallocate memory.
        node_t *current = *head;
        while (current->next->cell_id == new_element->data.cell_id)
            current = current->next;

        while (current->next) {
            node_t* temp = current->next;
            current->next = current->next->next;
            free(temp);
        }
    }

    new_element->next = *head;
    *head = new_element;
}

node_t* create_list(size_t length) {
    node_t* head = NULL;
    for (size_t i = 0; i < length; ++i) {
        NFAPI_RRC_RECONFIGURATION_PDU_T data = {
            .recipient_identity = rand(),
            .cell_id = i,
            .reconfiguration_command = rand() % 10 + 1
        };

        if (!is_valid_command(data.reconfiguration_command)) continue;

        node_t* new_element = create_element(data);
        if (!new_element) return NULL;

        ensure_no_adjacent_consecutive_cells(&head, new_element);
    }

    return head;
}
```

