        return NULL;
    }

    const int max_digits = 6;
    int digits = (strlen(input) - strlen(get_extension(input)) + max_digits) / 2;
    if (digits > max_digits) digits = max_digits;

    size_t len = strlen(input) + digits + 1 + sizeof...(file_types); // +1 for the dot and the null terminator
    if (len > 255) return NULL;

    char *new_filename = malloc(len);
    if (!new_filename) {
        perror("Memory allocation failure");
        return NULL;
    }

    sprintf(new_filename, "%s.%0*d.", input, digits, rand() % (1 << (sizeof...(file_types) * 8)));
    strcat(new_filename, file_types[rand() % sizeof...(file_types)]);

    return new_filename;
}

// Function to get the filename extension
const char *get_extension(const char *filename) {
    const int extension_len = sizeof(file_types[0]) - 1;
    for (size_t i = strlen(filename); i-- && *filename != '.'; ) {}

    if (*filename == '\0') return "";
    size_t ext_start = i + 1, ext_len = strlen(&filename[ext_start]);
    if (ext_len <= extension_len) {
        memcpy(extension, &filename[ext_start], ext_len);
        extension[ext_len] = '\0';
    } else {
        memcpy(extension, &filename[ext_start], sizeof(file_types[0]) - 1);
        extension[sizeof(file_types[0]) - 1] = '\0';
        ext_len = sizeof(file_types[0]) - 1;
    }

    return extension;
}

// Function to retrieve metadata for a given filename from the external API
void *get_metadata(void *arg) {
    cache_entry *entry = arg;
    char *metadata = calloc(METADATA_BUFFER_SIZE, sizeof(char));
    if (!metadata) {
        perror("Memory allocation failure");
        return NULL;
    }

    // Retrieve metadata from the external API and store it in the cache entry
    // ... (API specific code)

    pthread_mutex_lock(&entry->lock);
    free(entry->metadata);
    entry->metadata = metadata;
    pthread_mutex_unlock(&entry->lock);

    return NULL;
}

// Function to get the metadata for a given filename from the cache or retrieve it if not present in the cache
char *get_cached_metadata(const char *filename) {
    size_t hash = hash64(filename, strlen(filename));
    for (size_t i = 0; i < cache_size; ++i) {
        if (hash == cache[i].hash && strcmp(cache[i].filename, filename) == 0) {
            pthread_mutex_lock(&cache[i].lock);
            char *metadata = cache[i].metadata;
            pthread_mutex_unlock(&cache[i].lock);
            return metadata;
        }
    }

    // If the cache is full, evict the least recently used entry to make space for a new one
    if (cache_size == cache_capacity) {
        size_t least_recently_used = 0;
        time_t now = time(NULL);
        for (size_t i = 1; i < cache_size; ++i) {
            if (now - cache[least_recently_used].access_time > cache[i].access_time) {
                least_recently_used = i;
            }
        }

        pthread_mutex_lock(&cache[least_recently_used].lock);
        free(cache[least_recently_used].metadata);
        cache[least_recently_used].metadata = NULL;
        pthread_mutex_unlock(&cache[least_recently_used].lock);
        cache_size--;
    }

    // Allocate a new entry in the cache and start a thread to retrieve metadata from the external API
    cache_entry *new_entry = realloc(cache, sizeof(cache_entry) * (++cache_size));
    if (!new_entry) {
        perror("Memory allocation failure");
        return NULL;
    }
    cache = new_entry;

    pthread_mutex_init(&new_entry->lock, NULL);
    strcpy(new_entry->filename, filename);
    memcpy(extension, get_extension(filename), strlen(get_extension(filename)));
    new_entry->ext_len = strlen(extension);
    new_entry->metadata = NULL;
    new_entry->hash = hash64(filename, strlen(filename));

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, get_metadata, new_entry)) {
        perror("Thread creation failure");
        free(new_entry);
        return NULL;
    }

    return NULL; // Returns immediately since the metadata will be retrieved asynchronously
}

// Helper function to generate a 64-bit hash from a filename
uint64_t hash64(const char *str, size_t len) {
    uint64_t h = 0x811c9dc5;
    for (size_t i = 0; i < len; ++i) {
        h = h * 0x100000001b3 + str[i];
    }
    return h ^ (h >> 32);
}
