typedef struct {
    char *line;
    int num_fields;
    double sum, avg;
    pthread_mutex_t mutex;
} record;

void* process_record(void *arg) {
    record *r = (record *) arg;
    int i;
    for (i = 0; i < r->num_fields - 3; ++i)
        r->sum += atof(strtok(r->line, ","));

    double *arr = (double *) malloc((r->num_fields - 3) * sizeof(double));
    for (i = i; i < r->num_fields; ++i)
        arr[i-i] = atof(strtok(NULL, ","));

    qsort(arr, r->num_fields - 3, sizeof(double), (int (*)(const void*, const void*))comp_double);

    r->avg = arr[r->num_fields - 3] + arr[r->num_fields - 2] + arr[r->num_fields - 1];
    r->sum += r->avg;

    free(arr);
    pthread_mutex_lock(&r->mutex);
    // Append avg to the line and prepend sum
    char *end = strstr(r->line, ",") + 1;
    strcpy(end, ",");
    sprintf(end+1, "%.6f", r->avg);
    end += strlen(r->avg)+2;
    sprintf(r->line, "%" PRIi64 ",", r->sum);
    strcat(r->line, r->line + i);
    pthread_mutex_unlock(&r->mutex);
    free(r->line);
    return NULL;
}

int main() {
    FILE *fp = fopen("largefile.txt", "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    record *records = (record *) malloc(100 * sizeof(record));
    int num_records = 0, i, j;
    for (i = 0; ; ++i) {
        records[i].line = NULL;
        records[i].num_fields = 0;
        records[i].sum = 0.0;
        records[i].avg = 0.0;
        pthread_mutex_init(&records[i].mutex, NULL);
    }

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        record *current = &records[num_records % 100];
        current->line = strdup(line);
        int fields = 0;
        for (i = 0; line[i] != '\0'; ++i)
            if (line[i] == ',')
                ++fields;
        current->num_fields = fields + 1;
        pthread_t tid;
        if (pthread_create(&tid, NULL, process_record, current)) {
            perror("pthread_create");
            break;
        }
        ++num_records;
    }

    for (i = 0; i < num_records % 100; ++i) {
        record *current = &records[i];
        pthread_join(current->tid, NULL);
        // Process the final result
        pthread_mutex_lock(&current->mutex);
        printf("%s\n", current->line);
        free(current->line);
        pthread_mutex_unlock(&current->mutex);
    }

    for (i = 0; i < 100; ++i)
        pthread_join(records[i].tid, NULL);

    fclose(fp);
    free(records);
    return 0;
}

int comp_double(const void *a, const void *b) {
    return (*(double *) a > *(double *) b ? 1 : -1);
}
