```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <atomic>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <future>

// LineProcessor class for processing each line
class LineProcessor {
public:
    using LineData = std::vector<double>;

    explicit LineProcessor(std::mutex& dataMutex) : _dataMutex(dataMutex) {}

    void processLine(const std::string& line) {
        std::istringstream iss(line);
        std::string field;
        LineData data;

        // Process fields and calculate weighted average
        int counter = 0;
        while (std::getline(iss, field, ',')) {
            data.push_back(std::stod(field));
            counter++;
        }

        double sum = 0;
        for (size_t i = counter - 3; i < counter; ++i)
            sum += data[i] * (i - counter + 4);

        std::unique_lock<std::mutex> lock(_dataMutex);
        _lines.emplace_back(sum / static_cast<double>(counter - 3));
    }

private:
    std::vector<LineData> _lines;
    std::mutex _dataMutex;
};

// FileReader class for reading the file line by line
class FileReader {
public:
    explicit FileReader(const std::string& filename, LineProcessor& processor)
        : _filename(filename), _processor(processor) {}

    void start() {
        std::ifstream inputFile(_filename);
        if (!inputFile.is_open()) {
            std::cerr << "Error opening file: " << _filename << std::endl;
            return;
        }

        std::string line;
        while (std::getline(inputFile, line))
            _processor.processLine(line);
    }

private:
    const std::string _filename;
    LineProcessor& _processor;
};

// UserProfileManager class for managing user profiles
class UserProfileManager {
public:
    using ProfileMap = std::map<int, std::vector<double>>;
    using ProfilePtr = std::shared_ptr<ProfileMap>;

    static ProfilePtr createProfileManager() {
        auto manager = std::make_shared<ProfileMap>();
        return manager;
    }

    void addProfile(const int id, const LineData& data) {
        std::unique_lock<std::mutex> lock(_mutex);
        _profiles[id] = data;
    }

    void removeProfile(const int id) {
        std::unique_lock<std::mutex> lock(_mutex);
        _profiles.erase(id);
    }

    LineData getProfile(const int id) const {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = _profiles.find(id);
        if (it == _profiles.end())
            throw std::out_of_range("Invalid user profile ID");
        return it->second;
    }

private:
    ProfileMap _profiles;
    std::mutex _mutex;
};

int main() {
    // Initialize synchronization variables and shared resources
    std::mutex dataMutex;
    LineProcessor processor(dataMutex);
    UserProfileManager profiles = UserProfileManager::createProfileManager();
    FileReader reader("large_file.txt", processor);

    // Concurrently process file lines and update user profiles
    const int numThreads = 4;
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        auto processedLinesFuture = processor.processLineAsync();
        threads.emplace_back([&profiles, &dataMutex, processedLinesFuture]() {
            while (!processedLinesFuture.wait_for(std::chrono::seconds(1)) || !processedLinesFuture.valid()) {}

            // Process the lines and update user profiles
            const LineData& lines = *processedLinesFuture.get();
            for (const auto& line : lines) {
                int id = static_cast<int>(line);
                profiles->addProfile(id, { line });
            }
        });
    }

    reader.start();
    for (auto& thread : threads)
        thread.join();

    return 0;
}
```

