from typing import List, Optional, Tuple

def read_config(filepath: str) -> Tuple[List[str], int]:
    lines = []
    seq_number = 0

    try:
        with open(filepath, "r") as f:
            for line in f:
                lines.append(line.strip())

            if not lines:
                raise ValueError("Configuration file is empty.")

            seq_number = int(re.search(r"\d+", lines[-1]).group(0))

    except FileNotFoundError:
        print(f"Error: {filepath} not found.", file=sys.stderr)
        sys.exit(1)

    except ValueError as e:
        print(f"Invalid line format in configuration file: {e}", file=sys.stderr)
        sys.exit(1)

    return lines, seq_number
