    uint16_t crctag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T nfapi_data[N];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *generateData(void *arg) {
    int id = *(int*)arg;
    for (int i = id*N/10; (i < (id+1)*N/10) && (i < N); ++i) {
        nfapi_data[i].rxti = rand();
        nfapi_data[i].rnti = rand();
        nfapi_data[i].crcflag = rand()%2;
        nfapi_data[i].crctag = rand();
        pthread_mutex_lock(&lock);
        // Synchronize access to shared memory
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void generateNfalist(int numThreads) {
    pthread_t threads[numThreads];
    int threadId[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        threadId[i] = i;
        pthread_create(&threads[i], NULL, generateData, &threadId[i]);
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
}
