#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    DL_FRAME_RX_INFO dl_frame_rx_info;
    PHY_RRC_CENTRALIZED_DETECTION_INFO phy_rrc_cdi;
    // Add any additional fields as needed
} LTE_DL_FRAME_MSG;

typedef struct node {
    LTE_DL_FRAME_MSG data;
    struct node* next;
} Node;

struct dynamic_array {
    Node** data;
    int capacity;
    int size;
    sem_t lock;
};

void init_dynamic_array(struct dynamic_array* array, int capacity) {
    array->data = malloc(capacity * sizeof(Node*));
    array->capacity = capacity;
    array->size = 0;
    array->lock = sem_init(sem_unbounded, 1, 1);
}

void resize_dynamic_array(struct dynamic_array* array) {
    if (array->size == array->capacity) {
        int new_capacity = array->capacity * 2;
        Node** temp = realloc(array->data, new_capacity * sizeof(Node*));
        if (!temp) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        array->data = temp;
        array->capacity = new_capacity;
    }
}

void add_entry(struct dynamic_array* array, LTE_DL_FRAME_MSG msg) {
    sem_wait(&array->lock);
    resize_dynamic_array(array);
    array->data[array->size] = malloc(sizeof(Node));
    if (!array->data[array->size]) {
        fprintf(stderr, "Memory allocation failed\n");
        sem_post(&array->lock);
        return;
    }
    array->data[array->size]->data = msg;
    array->data[array->size]->next = NULL;
    array->size++;
    sem_post(&array->lock);
}

void update_entry(struct dynamic_array* array, int id, LTE_DL_FRAME_MSG msg) {
    Node** curr = array->data;
    sem_wait(&array->lock);

    for (int i = 0; i < array->size; ++i) {
        if (&curr[i]->data->unique_identifier == &id) {
            curr[i]->data = msg;
            break;
        }
        curr = &(curr[i]->next);
    }

    sem_post(&array->lock);
}

LTE_DL_FRAME_MSG* find_entry(struct dynamic_array* array, int id) {
    Node** curr = array->data;
    LTE_DL_FRAME_MSG* result = NULL;

    sem_wait(&array->lock);

    for (int i = 0; i < array->size; ++i) {
        if (&curr[i]->data->unique_identifier == &id) {
            result = &(curr[i]->data);
            break;
        }
        curr = &(curr[i]->next);
    }

    sem_post(&array->lock);
    return result;
}
```

