struct rrc_list {
    size_t length;
    size_t capacity;
    NFAPI_RRC_RECONFIGURATION_PDU_T *data;
    sem_t lock;
};

struct rrc_list* create_rrc_list(size_t initial_capacity) {
    struct rrc_list *list = malloc(sizeof(struct rrc_list));
    if (!list) return NULL;
    list->length = 0;
    list->capacity = initial_capacity;
    list->data = calloc(initial_capacity, sizeof(NFAPI_RRC_RECONFIGURATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    sem_init(&list->lock, 0, 1);
    return list;
}

void destroy_rrc_list(struct rrc_list *list) {
    if (list->data) free(list->data);
    free(list);
}

size_t capacity(const struct rrc_list *list) {
    return list->capacity;
}

size_t length(const struct rrc_list *list) {
    return list->length;
}

NFAPI_RRC_RECONFIGURATION_PDU_T* get(struct rrc_list *list, size_t index) {
    sem_wait(&list->lock);
    NFAPI_RRC_RECONFIGURATION_PDU_T* ret = &list->data[index];
    sem_post(&list->lock);
    return ret;
}

bool set(struct rrc_list *list, size_t index, const NFAPI_RRC_RECONFIGURATION_PDU_T *value) {
    bool ret = false;
    sem_wait(&list->lock);
    if (index < list->length && index < list->capacity) {
        list->data[index] = *value;
        ret = true;
    }
    sem_post(&list->lock);
    return ret;
}

void push(struct rrc_list *list, const NFAPI_RRC_RECONFIGURATION_PDU_T *element) {
    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->data = realloc(list->data, new_capacity * sizeof(NFAPI_RRC_RECONFIGURATION_PDU_T));
        if (!list->data) return;
        list->capacity = new_capacity;
    }

    sem_wait(&list->lock);
    list->data[list->length] = *element;
    list->length++;
    sem_post(&list->lock);
}

void iterate(struct rrc_list *list, void (*fn)(NFAPI_RRC_RECONFIGURATION_PDU_T*)) {
    if (!list || !fn) return;
    sem_wait(&list->lock);
    for (size_t i = 0; i < list->length; ++i) {
        fn(get(list, i));
    }
    sem_post(&list->lock);
}
