public:
    NetworkEventManager(std::unique_ptr<logging::Logger> logger) : runningBackgroundTask(true), logger(std::move(logger)) {
        std::thread processThread(std::bind(&NetworkEventManager::processEvents, this));
        processThread.detach();
    }

    void addEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(eventsMutex);
        events.push_back(event);
        for (auto& tag : event.tags) {
            taggedEvents[tag].push_back(&event);
        }
    }

    std::vector<NetworkEvent*> getEventsByTag(const std::string& tag) const {
        std::lock_guard<std::mutex> lock(eventsMutex);
        auto it = taggedEvents.find(tag);
        if (it != taggedEvents.end()) {
            return it->second;
        }
        return {};
    }

    void logEvent(const NetworkEvent& event) {
        logger->log(event);
    }

    void stopProcessing() {
        runningBackgroundTask = false;
    }

    void startProcessingAfterDelay(std::chrono::milliseconds delay) {
        backgroundTasks.emplace_back([this, delay]() { runningBackgroundTask = true; });
        std::unique_ptr<std::future<void>> taskFuture = std::make_unique<std::future<void>>(backgroundTasks.front());
        std::thread taskThread([taskFuture, this]() {
            std::this_thread::sleep_for(delay);
            taskFuture->get();
        });
        taskThread.detach();
    }
};
