    return l;
}

// Function to merge two buddies
void merge(Allocator* alloc, void *chunk) {
    unsigned char *b0 = (unsigned char*)chunk - sizeof(unsigned long);
    unsigned char *b1 = (unsigned char*)chunk;
    unsigned long budget = *((unsigned long*)b0 >> 3);
    alloc->budget += budget;
}

// Allocate a new chunk of memory
void* Allocator_alloc(Allocator* alloc, size_t sz) {
    pthread_mutex_lock(&alloc->lock);
    if (sz > alloc->budget) {
