#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct NFAPI_RRC_RECONFIGURATION_PDU_T {
    uint32_t CellIdentity;
    uint8_t RRC_VERSION;
    /* Include RRC_CONFIGURATION_INFO structure here */
} NFAPI_RRC_RECONFIGURATION_PDU;

typedef struct node {
    NFAPI_RRC_RECONFIGURATION_PDU data;
    struct node* next;
} Node;

struct dyn_list {
    unsigned int capacity, size;
    Node* head, *tail;
    pthread_mutex_t mutex;
};

DynList* create_dyn_list(unsigned int capacity) {
    DynList* list = (DynList*) malloc(sizeof(DynList));
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void push(DynList* list, NFAPI_RRC_RECONFIGURATION_PDU data) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    if (list->size >= list->capacity && list->capacity > 16) {
        reallocate_dyn_list(list, list->capacity * 2);
    }
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_RRC_RECONFIGURATION_PDU pop(DynList* list) {
    if (!list->head) return (NFAPI_RRC_RECONFIGURATION_PDU){0, 0};

    pthread_mutex_lock(&list->mutex);
    NFAPI_RRC_RECONFIGURATION_PDU data = list->head->data;
    Node* temp = list->head;
    list->head = list->head->next;
    free(temp);
    list->size--;
    if (list->size <= list->capacity / 4 && list->capacity > 16) {
        reallocate_dyn_list(list, list->capacity / 2);
    }
    pthread_mutex_unlock(&list->mutex);
    return data;
}

void iterate(DynList* list, void (*callback)(NFAPI_RRC_RECONFIGURATION_PDU)) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void reallocate_dyn_list(DynList* list, unsigned int new_capacity) {
    Node** nodes = (Node**) malloc(new_capacity * sizeof(Node*));
    unsigned int i;
    pthread_mutex_lock(&list->mutex);

    for (i = 0; i < list->size; ++i) {
        Node* current = list->head;
        if (i == 0) list->head = nodes[i];
        if (current != NULL) {
            current->next = nodes + (i+1);
        }
    }

    free(list->head);
    list->head = nodes;
    list->tail = nodes + list->size - 1;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->mutex);
}
```

