volatile int exit_flag = 0;

void* create_segments(void *arg) {
    HashNode **bucket = (HashNode**) arg;
    int i;

    for (i = 0; i < 10000 && !exit_flag; ++i) {
        TCP_SEGMENT segment = create_segment((uint32_t) rand());
        insert_segment(bucket, segment);
    }
}

int main(int argc, char *argv[]) {
