// Thread-safe function to generate a unique filename with the given criteria
uint64_t generate_unique_id(const char *filename, const char *file_type) {
    // Calculate the number of digits based on the original filename length
    uint32_t num_digits = strlen(filename) > 10 ? 10 : strlen(filename);

    // Generate a timestamp in microseconds
    uint64_t timestamp = (uint64_t)time(NULL) * 1000 + gethrtime();

    // Ensure the unique ID is unique within the directory and does not exceed 10 digits
    while (true) {
        uint64_t id = timestamp % (pow(10, num_digits));
        char new_filename[10 + strlen(file_type)];
        snprintf(new_filename, sizeof(new_filename), "%s%0*lu.%s", filename, num_digits, id, file_type);

        struct stat st;
        if (stat(new_filename, &st) != -1 && S_ISREG(st.st_mode)) {
            continue; // File already exists, try again with a new ID
        }

        return id;
    }
}

char* generate_modified_filename(const char *filename) {
    char *file_type = get_file_type(dirname(realpath(filename, NULL)));
    if (!file_type) {
        log_error("Failed to infer file type.");
        return NULL;
    }

    uint64_t id = generate_unique_id(filename, file_type);
    if (id == UINT64_MAX) {
        log_error("Failed to generate a unique filename.");
        free(file_type);
        return NULL;
    }

    char new_filename[10 + strlen(filename) + strlen(file_type)];
    snprintf(new_filename, sizeof(new_filename), "%s%0*lu.%s", filename, strlen(filename), id, file_type);
    return new_filename;
}
