    while (1) {
        if (TIFFStripSize(tif) <= 0) break;

        uint8_t *buf = malloc(TIFFStripSize(tif));
        if (!buf) {
            fprintf(stderr, "Error: Failed to allocate memory for TIFF strip\n");
            *errorCode = 2;
            goto cleanup;
        }

        if (TIFFReadEncodedStrip(tif, buf, rowsPerStrip) != rowsPerStrip) {
