            fprintf(stderr, "Error: Missing image dimensions\n");
            *errorCode = 5;
            free(buf);
            goto cleanup;
        }

        if (TIFFGetField(tif, TIFFTagBitspixel, &sampleBitDepth) < 1 ||
            TIFFGetField(tif, TIFFTagPhotometricInterpretation, &photometricInterpretation) < 1 ||
            TIFFGetField(tif, TIFFTagOrientation, &orientation) < 1 ||
            TIFFGetField(tif, TIFFTagSamplePerPixel, &samplesPerPixel) < 1 ||
            TIFFGetField(tif, TIFFTagFillOrder, &fillOrder) < 1) {
            fprintf(stderr, "Error: Missing image properties\n");
            *errorCode = 6;
            free(buf);
            goto cleanup;
        }

        // Validate against predefined template
