#include <algorithm>
#include <forward_list>
#include <string>
#include <stdexcept>

void insertStringAfterTag(std::forward_list<std::string>& dataList, const std::string& targetTag, const std::string& insertedString) {
    if (dataList.empty()) {
        throw std::runtime_error("List is empty");
    }

    auto it = dataList.begin();
    while (it != dataList.end() && (*it) != targetTag) {
        ++it;
    }

    if (it == dataList.end()) {
        dataList.push_back(insertedString);
    } else {
        dataList.insertafter(it, insertedString);
    }
}
