using System.Threading.Tasks;
using System.Text.Json;
using Microsoft.Extensions.Logging;

public interface IPageElementService
{
    Task<Unit> UpdateElementAsync(string pageSectionId, string elementId, string content);
}

public class PageElementService : IPageElementService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<PageElementService> _logger;

    public PageElementService(HttpClient httpClient, ILogger<PageElementService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task<Unit> UpdateElementAsync(string pageSectionId, string elementId, string content)
    {
        try
        {
            var requestUri = $"api/pageelements/{pageSectionId}/{elementId}";
            var httpResponse = await _httpClient.PostAsJsonAsync(requestUri, new { Content = content });
            httpResponse.EnsureSuccessStatusCode();

            _logger.LogInformation($"Updated page element: {elementId}");
            return Unit.Value;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error updating page element: {elementId}");
            throw;
        }
    }
}

public async Task<IActionResult> UpdatePageElement(string pageSectionId, string elementId, string content)
{
    var service = _serviceProvider.GetService<IPageElementService>();
    await service.UpdateElementAsync(pageSectionId, elementId, content);

    return Json(new { RefreshRequired = true });
}
