typedef struct {
    int measurementIdentity;
    int rssi;
    double snr;
} CellMeasurementResults;

struct sensorNode {
    pthread_t threadId;
    bool isActive;
    CellMeasurementResults measurement;
};

pthread_mutex_t dataMutex = PTHREAD_MUTEX_INITIALIZER;
struct sensorNode* sensors;
const int numSensors;
const int maxIdentity;
const int rssiThreshold;
const double snrThreshold;
const int reportInterval;

void generateMeasurements() {
    for (int i = 0; i < numSensors; ++i) {
        struct sensorNode* node = &sensors[i];
        if (!node->isActive) continue;

        // Simulate data acquisition delay
        usleep(rand() % 1000000);

        node->measurement.rssi = rand() % maxIdentity - rssiThreshold;
        node->measurement.snr = (double)(rand() % 100) / 100; // generate SNR between 0 and 1
    }
}

void* sensorThread(void* arg) {
    int index = *(int*)arg;
    struct sensorNode* node = &sensors[index];

    while (true) {
        if (!node->isActive) continue;

        generateMeasurements();
        pthread_mutex_lock(&dataMutex);
        // Store measurement in the shared data array
        sensors[index] = *node;
        pthread_mutex_unlock(&dataMutex);

        sleep(reportInterval);
    }

    return NULL;
}

void generateAndAggregateMeasurements() {
    pthread_t threads[numSensors];
    int ids[numSensors];

    for (int i = 0; i < numSensors; ++i) {
        sensors[i].isActive = true;
        ids[i] = i;
        pthread_create(&threads[i], NULL, sensorThread, &ids[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numSensors; ++i) {
        pthread_join(threads[i], NULL);
    }
}

