#include <NFAPI_CRC_INDICATION_PDU_T.h> // External library header for data structures
#include <UE_STATE_MANAGER.h> // External library header for managing UE state information

// Define mutex for thread-safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

struct element {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct element *next;
};

// Function to generate a random RNTI value within the supported range
unsigned long generate_rnti() {
    static unsigned long last = 0;
    // Dynamically adjust the starting point and step based on the constraints
    unsigned long step = 1000000 / MAX_SUPPORTED_RNTI;
    last = (last + step) % MAX_SUPPORTED_RNTI;
    return last++;
}

void create_list(int num_elements) {
    struct element *head = NULL, *tail = NULL, *temp;
    for (int i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&list_mutex);
        // Allocate memory for the new structure and initialize its members
        temp = (struct element *)malloc(sizeof(struct element));
        temp->data.RX_UE_INFORMATION_TAG = i;
        temp->data.RNTI = generate_rnti();
        temp->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Update pointers to maintain the list and ensure no two consecutive structures have the same RNTI value
        if (head == NULL || head->data.RNTI != temp->data.RNTI) {
            if (!head) {
                head = tail = temp;
            } else {
                tail->next = temp;
                tail = temp;
            }
        } else {
            free(temp); // Free the memory if the RNTI value is not valid
            pthread_mutex_unlock(&list_mutex);
            continue;
        }
        pthread_mutex_unlock(&list_mutex);
    }
}
```

