typedef struct {
    uint32_t rnti;
    sem_t pdcp_pdu_mutex;
    pthread_mutex_t stats_mutex;
    struct PDCP_PDU *pdcp_pdu_list; // List of PDCP Protocol Data Units (PDUs)
    struct Statistics statistics; // Track packet loss and retransmissions
} UEContext;

// Dynamic allocation and deallocation
UEContext *ue_context_create(uint32_t rnti) {
    UEContext *ue_ctx = mmap(NULL, sizeof(UEContext), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!ue_ctx) return NULL;

    sem_init(&ue_ctx->pdcp_pdu_mutex, 1, 1);
    pthread_mutex_init(&ue_ctx->stats_mutex, NULL);

    ue_ctx->rnti = rnti;
    ue_ctx->pdcp_pdu_list = NULL;
    memset(&ue_ctx->statistics, 0, sizeof(struct Statistics));

    return ue_ctx;
}

void ue_context_destroy(UEContext **ue_ctx) {
    if (!ue_ctx || !*ue_ctx) return;

    sem_destroy(&(*ue_ctx)->pdcp_pdu_mutex);
    pthread_mutex_destroy(&(*ue_ctx)->stats_mutex);
    munmap((void*)*ue_ctx, sizeof(UEContext));

    *ue_ctx = NULL;
}

// Efficient retrieval and update operations
UEContext *ue_context_find(const UEContext **contexts, size_t context_count, uint32_t rnti) {
    for (size_t i = 0; i < context_count; ++i) {
        if ((*contexts + i)->rnti == rnti) return (*contexts + i);
    }

    return NULL;
}

UEContext *ue_context_add(UEContext **contexts, size_t *context_count, uint32_t rnti) {
    UEContext *new_context = ue_context_create(rnti);

    if (!new_context) return NULL;

    // Conflict resolution strategy: find an empty slot or handle duplicates gracefully
    for (size_t i = 0; i < *context_count; ++i) {
        if ((*contexts + i)->rnti == rnti && (*contexts + i) != new_context) {
            ue_context_destroy(&new_context);
            return NULL;
        }
    }

    *contexts = realloc(*contexts, sizeof(UEContext) * ++*context_count);

    if (!*contexts) {
        ue_context_destroy(&new_context);
        return NULL;
    }

    (*contexts)[*context_count - 1] = new_context;
    return new_context;
}

// External data sources integration and performance optimization
void update_ue_contexts(const UEContext **contexts, size_t context_count, json_t *data) { // Parse JSON data here
    for (size_t i = 0; i < context_count; ++i) {
        // Efficiently integrate updates without introducing latency or errors
        update_ue_context((*contexts + i), data);
    }
}
