    CRC_INDICATION_REL8_TAG crcindication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

static Node** list = NULL;
static const unsigned int MAX_ELEMENTS = 100000;
static unsigned int elements_count = 0;
static unsigned int max_rnti = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init() {
    if (list) return;
    list = calloc(MAX_ELEMENTS, sizeof(Node*));
}

unsigned int get_index(unsigned int rnti) {
    unsigned int index = (rnti % MAX_ELEMENTS);
    // Handle potential integer overflow issues
    if (index >= MAX_ELEMENTS) {
        index -= MAX_ELEMENTS;
    }
    return index;
}

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    unsigned int rnti = data.rnti;
    unsigned int index = get_index(rnti);

    // Ensure no two consecutive structures share the same RNTI value
    if (elements_count > 0 && list[index]->data.rnti == rnti) {
        rnti++;
    }

    Node* node = malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;

    // Update max_rnti if necessary
    if (rnti > max_rnti) {
        max_rnti = rnti;
    }

    // Insert the new node at the correct position in the list
    Node* current = list[index];
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    node->next = current->next;
    current->next = node;

    elements_count++;

    // Validate the integrity of the generated CRC indications
    if (!validate_crc(data.crcindication)) {
        free(node);
        insert(data);  // Retry generating the list until a valid configuration is achieved
    }

    pthread_mutex_unlock(&mutex);
}

void clean() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        Node* current = list[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(list);
    list = NULL;
    elements_count = 0;
    max_rnti = 0;

    pthread_mutex_unlock(&mutex);
}
```

