#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int priority;
    size_t tag_count;
    char *data;
} Item;

typedef struct Node Node;
struct Node {
    Item item;
    Node *next;
};

Node* create_node(Item item) {
    Node *new_node = malloc(sizeof(Node));
    new_node->item = item;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node **head, Node *new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        *head = new_node;
    }
}

Item* extract_item(Node **head, size_t *len) {
    if (*head == NULL) return NULL;
    Node *temp = *head;
    *head = temp->next;
    *len = strlen(temp->item.data);
    Item *result = &temp->item;
    free(temp);
    return result;
}

int cmp_func(const void *a, const void *b) {
    const Item *ia = a;
    const Item *ib = b;

    if (ia->priority < ib->priority) return 1;
    if (ia->priority > ib->priority) return -1;
    if (ia->tag_count < ib->tag_count) return -1;
    if (ia->tag_count > ib->tag_count) return 1;
    return strcmp(ia->data, ib->data);
}

void sort_list(Node **head) {
    qsort(*head, LLONG_MAX, sizeof(Item), cmp_func);
}

size_t count_tags(const char *str) {
    size_t count = 0;
    for (; *str != '\0'; str++) {
        if (*str == '#') count++;
    }
    return count;
}

Node* process_list(Node *head, size_t limit) {
    Node *current = head;
    Node *result_head = NULL;
    Node *result_tail = NULL;

    while (current != NULL) {
        const size_t len = strlen(current->item.data);
        if (len <= limit) {
            Item item = current->item;
            item.tag_count = count_tags(item.data);
            Node *new_node = create_node(item);
            if (result_head == NULL) {
                result_head = new_node;
                result_tail = new_node;
            } else {
                result_tail->next = new_node;
                result_tail = new_node;
            }
        }
        current = current->next;
    }

    sort_list(&result_head);

    return result_head;
}
```

