#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t rnti;
    pthread_mutex_t pdcp_list_lock;
    pthread_cond_t pdcp_list_cv;
    struct PDCP_PDU* pdcp_list;
    struct Statistics stats;
    time_t creation_time;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context** contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t pool_lock;
    void* pool;
} ContextPool;

void init_context(LTE_UE_Context* ctx) {
    ctx->pdcp_list = NULL;
    ctx->stats.packet_loss = 0;
    ctx->stats.retransmissions = 0;
    ctx->creation_time = time(NULL);
}

void destroy_context(LTE_UE_Context* ctx) {
    if (ctx->pdcp_list != NULL) free(ctx->pdcp_list);
}

ContextPool* create_context_pool() {
    ContextPool* pool = malloc(sizeof(ContextPool));
    pool->capacity = 10000;
    pool->count = 0;
    pool->pool = calloc(pool->capacity, sizeof(LTE_UE_Context*));
    pthread_mutex_init(&pool->pool_lock, NULL);
    return pool;
}

void destroy_context_pool(ContextPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        LTE_UE_Context* ctx = pool->contexts[i];
        destroy_context(ctx);
    }
    free(pool->pool);
    free(pool);
}

LTE_UE_Context* acquire_context(ContextPool* pool, uint32_t rnti) {
    pthread_mutex_lock(&pool->pool_lock);
    for (size_t i = 0; i < pool->capacity; ++i) {
        LTE_UE_Context* ctx = pool->contexts[i];
        if (!ctx || ctx->rnti == rnti) {
            if (ctx) init_context(ctx);
            pool->count++;
            pthread_mutex_unlock(&pool->pool_lock);
            return ctx;
        }
    }
    pthread_mutex_unlock(&pool->pool_lock);

    LTE_UE_Context* new_ctx = malloc(sizeof(LTE_UE_Context));
    init_context(new_ctx);
    new_ctx->rnti = rnti;
    pool->contexts[i % pool->capacity] = new_ctx;
    pool->count++;
    return new_ctx;
}

void release_context(ContextPool* pool, LTE_UE_Context* ctx) {
    pthread_mutex_lock(&pool->pool_lock);
    if (ctx->rnti == 0 || !pool->contexts[ctx->rnti]) {
        free(ctx);
        pool->count--;
    } else {
        LTE_UE_Context* tmp = pool->contexts[ctx->rnti];
        pool->contexts[ctx->rnti] = ctx;
        ctx->rnti = 0;
        pool->contexts[pool->count++] = tmp;
    }
    pthread_mutex_unlock(&pool->pool_lock);
}

void purge_inactive_contexts(ContextPool* pool) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&pool->pool_lock);
    for (size_t i = 0; i < pool->count; ++i) {
        LTE_UE_Context* ctx = pool->contexts[i];
        if (current_time - ctx->creation_time > CONFIG_INACTIVE_TIMEOUT) {
            destroy_context(ctx);
            memmove(pool->contexts + i, pool->contexts + i + 1, --pool->count - i);
        }
    }
    pthread_mutex_unlock(&pool->pool_lock);
}

