UEStatusRecord* init_ue_status_records(size_t num_records) {
    UEStatusRecord* records = malloc(num_records * sizeof(UEStatusRecord));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        UEStatusRecord* record = records + i;
        snprintf(record->imsi, sizeof(record->imsi), "%llu", rand()); // Random IMSI (64-bit unsigned integer)
        record->cellId = rand() % 10000; // Random cell ID between 0 and 9999
        record->s1_connections = calloc(MAX_CONNECTIONS, sizeof(S1Connection));
        if (!record->s1_connections) {
            perror("Memory allocation failed");
            return NULL;
        }
        record->connection_count = 0;
        record->capacity = MAX_CONNECTIONS;
        pthread_mutex_init(&record->mutex, NULL);
    }

    return records;
}

void add_s1_connection(UEStatusRecord* record, int connection_id, bool active) {
    if (record->connection_count >= record->capacity) {
        S1Connection* new_connections = realloc(record->s1_connections, (record->capacity + MAX_CONNECTIONS) * sizeof(S1Connection));
        if (!new_connections) {
            perror("Memory allocation failed");
            return;
        }
        record->s1_connections = new_connections;
        record->capacity += MAX_CONNECTIONS;
    }

    pthread_mutex_lock(&record->mutex);
    record->s1_connections[record->connection_count].id = connection_id;
    record->s1_connections[record->connection_count].active = active;
    ++record->connection_count;
    pthread_mutex_unlock(&record->mutex);
}

