namespace nfp_manager {

class NFPIManager {
public:
    struct Entry {
        RX_UE_INFORMATION_TAG tag;
        int rnti;
        CRC_INDICATION_REL8_TAG crc_indication;
        bool crcflag;
    };

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu);
    bool update(int rnti, const NFAPI_CRC_INDICATION_PDU_T& pdu);
    bool remove(int rnti);

    void serialize(const std::string& file_name);
    std::vector<NFAPI_CRC_INDICATION_PDU_T> deserialize(const std::string& file_name);

private:
    std::unordered_map<int, std::unique_ptr<Entry>> entries_;
    mutable std::mutex mtx_;
    // Logging integration
    static Logger logger_;
};

inline void NFPIManager::add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    std::unique_ptr<Entry> entry = std::make_unique<Entry>();
    std::copy(pdu.begin(), pdu.end(), entry.get());
    entries_.emplace(pdu.rnti, std::move(entry));
    logger_.info("Added entry with RNTI: ", pdu.rnti);
}

inline bool NFPIManager::update(int rnti, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    auto it = entries_.find(rnti);
    if (it == entries_.end()) return false;
    std::copy(pdu.begin(), pdu.end(), it->second.get());
    logger_.info("Updated entry with RNTI: ", rnti);
    return true;
}

inline bool NFPIManager::remove(int rnti) {
    auto it = entries_.find(rnti);
    if (it == entries_.end()) return false;
    it->second.reset();
    entries_.erase(rnti);
    logger_.info("Removed entry with RNTI: ", rnti);
