#include <iostream>
#include <list>
#include <random>
#include <json/json.h>
#include <mutex>
#include <unordered_map>
#include <memory>

class Logger {
public:
    void log(int rnti, bool crcFlag) {
        std::lock_guard<std::mutex> lock(logMutex);
        logData.emplace_back({rnti, crcFlag});
    }

private:
    std::vector<std::pair<int, bool>> logData;
    std::mutex logMutex;
};

class RandomValueGenerator {
public:
    explicit RandomValueGenerator(const Json::Value& config) : minRNTI(config["minRNTI"].asInt()), maxRNTI(config["maxRNTI"].asInt()), minCRCFlag(config["minCRCFlag"].asBool()), maxCRCFlag(config["maxCRCFlag"].asBool()) {}
    void setCacheEnabled(bool enabled) { cacheEnabled = enabled; }

    std::list<NFAPI_CRC_INDICATION_PDU_T> generateValues(size_t N) {
        std::list<NFAPI_CRC_INDICATION_PDU_T> result;
        std::unique_ptr<std::unordered_map<int, bool>> rntiToCrcFlagCache(new std::unordered_map<int, bool>());

        if (cacheEnabled) {
            for (auto& cacheEntry : *rntiToCrcFlagCache) {
                result.push_back({RX_UE_INFORMATION_TAG(), cacheEntry.first, CRC_INDICATION_REL8_TAG(cacheEntry.second), std::bitset<32>(0)});
            }
        }

        std::mt19937 gen(std::random_device{}());
        std::uniform_int_distribution<> rntiDistrib(minRNTI, maxRNTI);
        std::uniform_int_distribution<> crcFlagDistrib(0, 1);

        for (size_t i = 0; i < N; ++i) {
            int rnti = rntiDistrib(gen);
            bool crcFlag = crcFlagDistrib(gen) > crcFlagDistrib.second - 0.1 ? true : false;

            if (cacheEnabled && rntiToCrcFlagCache->find(rnti) != rntiToCrcFlagCache->end()) {
                result.push_back({RX_UE_INFORMATION_TAG(), rnti, CRC_INDICATION_REL8_TAG(rntiToCrcFlagCache->at(rnti)), std::bitset<32>(0)});
            } else {
                result.push_back({RX_UE_INFORMATION_TAG(), rnti, CRC_INDICATION_REL8_TAG(crcFlag), std::bitset<32>(0)});
                if (cacheEnabled) {
                    rntiToCrcFlagCache->emplace(rnti, crcFlag);
                }
            }
        }

        return result;
    }

    const std::list<std::pair<int, bool>>& getLogData() const {
        return logger.logData;
    }

    void ToString(std::ostream& out) const {
        out << "Min RNTI: " << minRNTI << ", Max RNTI: " << maxRNTI << ", Min CRC Flag: " << minCRCFlag << ", Max CRC Flag: " << maxCRCFlag;
    }

private:
    int minRNTI, maxRNTI;
    bool minCRCFlag, maxCRCFlag;
    Logger logger;
    bool cacheEnabled = false;
};
```
