#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 1024

typedef struct {
    uint32_t rxi;
    uint32_t rnti;
    uint32_t cif;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRCI_PDU_T data;
    struct node* prev;
    struct node* next;
};

struct list {
    struct node* head;
    struct node* tail;
    size_t size;
};

// Custom memory allocator
void* custom_malloc(size_t size) {
    void* mem = malloc(size + sizeof(size_t));
    if (!mem) return NULL;

    // Track the allocated block's size and its position in the free list.
    ((size_t*)((char*)mem + size))[0] = size;
    ((size_t*)((char*)mem + size))[1] = (size_t)((char*)mem - (char*)free_list);

    return (char*)mem + sizeof(size_t);
}

void custom_free(void* ptr) {
    if (!ptr) return;

    // Update the free list.
    size_t* meta = (size_t*)((char*)ptr - sizeof(size_t));
    ((size_t*)((char*)free_list + (*meta)))[1] = (size_t)((char*)meta - (char*)free_list);
}

struct list* create_list() {
    struct list* list = malloc(sizeof(struct list));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

void destroy_list(struct list* list) {
    struct node* current = list->head;
    while (current) {
        struct node* next = current->next;
        custom_free(current);
        current = next;
    }
    free(list);
}

void log_operation(struct list* list, const char* operation, time_t timestamp) {
    // Log the insertion/deletion operation and relevant metadata.
    printf("%s operation at %s: size=%zu\n", operation, ctime(&timestamp), list->size);
}

void insert(struct list* list, const NFAPI_CRCI_PDU_T* data) {
    struct node* new_node = custom_malloc(sizeof(struct node));
    if (!new_node) return;

    new_node->data = *data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->size == MAX_ELEMENTS) {
        // Resize the list if it's full.
        struct node** tmp_head = &list->head;
        struct node** current = &list->head;
        size_t new_max_elements = MAX_ELEMENTS * 2;

        while (*current != NULL) {
            *tmp_head = *current;
            tmp_head = &((*current)->next);
            current = tmp_head;
        }

        list->tail = custom_malloc(sizeof(struct node));
        if (!list->tail) return;
        list->tail->prev = NULL;
        list->tail->next = list->head;
        list->head->prev = list->tail;
        free(*tmp_head);

        MAX_ELEMENTS = new_max_elements;
    }

    if (list->size == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    log_operation(list, "insert", time(NULL));
    list->size++;
}

void remove(struct list* list) {
    if (list->size == 0) return;

    struct node* current = list->head;
    if (current->next == NULL) {
        free(current);
        list->head = list->tail = NULL;
    } else {
        struct node* next = current->next;
        free(current);
        current = next;
        list->size--;
    }

    log_operation(list, "remove", time(NULL));
}

