class DoublyLinkedList {
private:
    std::list<Node> nodes;
public:
    void insert(const NFAPI_CRC_INDICATION_PDU_T& item) {
        Node new_node;
        new_node.data = item;

        if (nodes.empty()) {
            new_node.prev = nodes.end();
            new_node.next = nodes.begin();
            nodes.push_back(std::move(new_node));
        } else {
            auto it = nodes.begin();
            std::advance(it, 1); // skip the first node
            new_node.prev = --it;
            new_node.next = it;
            it->prev = &new_node;
            nodes.insert(it, std::move(new_node));
        }
    }

    Node* remove(Node* node) {
        auto it = node->prev;
        auto next_it = node->next;

        if (it != nodes.end())
            it->next = next_it;
        if (next_it != nodes.begin())
            next_it->prev = it;

        nodes.erase(node);
        return node;
    }
};

