import hashlib
import os
import sys
import time
from contextlib import suppress

def md5_file(file_path, log_freq=10_000_000, retention=7):
    with open(file_path, 'rb') as f:
        total = f.seek(0, 2)
        start = time.time()
        hasher = hashlib.md5()
        chunk_size = 8192
        curr_log = "hash_log.txt"
        log = open(curr_log, 'a')

        while f.tell() < total:
            data = f.read(chunk_size)
            hasher.update(data)

            if (f.tell() - start) / total * 100 >= log_freq:
                log.write(f"{time.ctime()} {hasher.hexdigest()}\n")
                curr_log = f"hash_log_{retention}.txt"
                with open(curr_log, 'w+') as new_log:
                    new_log.write("")
                    log = open(curr_log, 'a')

        log.close()

    return hasher.hexdigest()
