from concurrent.futures import ThreadPoolExecutor, as_completed
import psutil
import shutil
from urllib.request import urlretrieve
import requests
from gevent import monkey, lock

monkey.tick()  # Monkeypatch for better Gevent integration with Python3.X

class FileLock:
    def __init__(self, file_path):
        self.file_path = file_path
        self.lock = lock()

    def acquire(self):
        return self.lock.acquire(blocking=True)

    def release(self):
        self.lock.release()

def get_size(file_path):
    try:
        return os.path.getsize(file_path)
    except Exception as e:
        print(f"Error while getting size of {file_path}: {e}")
        return -1

def md5_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(4096)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def calculate_remaining_time(size, downloaded=0):
    download_speed = psutil.disk_io_counters().read_bytes / time.perf_counter()
    remaining = (size - downloaded) / download_speed
    return remaining if remaining > 0 else 0

def download_file(url, file_path):
    print(f"Downloading {url} to {file_path}")
    urlretrieve(url, file_path)

def hash_files(file_list, lock_manager):
    processed = []
    total_size = sum([get_size(f) for f in file_list])

    def job(file_path, idx):
        with FileLock(file_path) as lock:
            if not lock.acquire():
                return

        file_size = get_size(file_path)
        processed.append((file_path, file_size))
        if file_size == -1:
            print(f"Failed to read size of {file_path}")
            return

        hashed = md5_hash(file_path)
        print(f"Hash for {file_path}: {hashed}")
        print(f"Size: {file_size} bytes, remaining time: {calculate_remaining_time(file_size)}")

    with ThreadPoolExecutor() as executor:
        for file in file_list:
            url = file.get('url', None)
            if url:
                executor.submit(download_file, url, file)
            else:
                executor.submit(job, file, len(file_list))

        for _ in as_completed(executor):
            pass

    results = [(p[0], p[1], md5_hash(p[0])) for p in processed if not getsize(p[0]) == -1]
    return {r[0]: (r[1], r[2]) for r in sorted(results, key=lambda x: x[1])}

def main():
    file_list = [{'url': 'https://example.com/file1', 'path': '/path/to/file1'}, {'path': '/path/to/file2'}]
    hashes = hash_files(file_list, FileLock)
    print(hashes)

if __name__ == "__main__":
    main()
