bool add_node(NFAPI_CRC_INDICATION_PDU_T node) {
    ListNode* newNode = malloc(sizeof(ListNode));
    if (!newNode) return false;

    newNode->data = node;
    newNode->next = NULL;
    pthread_mutex_init(&newNode->mutex, NULL);

    ListNode* current = head;
    ListNode* previous = NULL;

    if (current == NULL) {
        head = newNode;
        return true;
    }

    while (current != NULL && current->RNTI == node.RNTI) {
        if (previous == NULL) {
            free(newNode);
            return false;
        }
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        previous->next = newNode;
        return true;
    }

    pthread_mutex_lock(&newNode->mutex);
    newNode->next = current;
    pthread_mutex_unlock(&newNode->mutex);

    return true;
}

bool update_node(uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T updatedData) {
    ListNode* current = head;

    while (current != NULL && current->RNTI != RNTI)
        current = current->next;

    if (current == NULL)
        return false;

    pthread_mutex_lock(&current->mutex);
    current->data = updatedData;
    pthread_mutex_unlock(&current->mutex);

    return true;
}

bool remove_node(uint32_t RNTI) {
    ListNode* current = head;
    ListNode* previous = NULL;

    while (current != NULL && current->RNTI == RNTI) {
        if (previous == NULL) {
            head = current->next;
            break;
        }
        previous = current;
        current = current->next;
    }

    if (current == NULL)
        return false;

    pthread_mutex_lock(&(previous ? previous->mutex : listLock));
    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&(previous ? previous->mutex : listLock));

