    CRC_INDICATION_REL8_TAG crc_indication_tag;
    bool CRCFlag;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->tag = RX_UE_INFORMATION_TAG{.value = 0xDEADBEEF};
    pdu->RNTI = rand();
    pdu->crc_indication_tag = CRC_INDICATION_REL8_TAG{.value = 0xC0DEF00D};
    pdu->CRCFlag = rand() % 2;
}

bool is_corrupted(double random) {
    return (random <= 0.1);
}

void* create_pdu(void *param) {
    int *index = param;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*) param;
    double random = ((double) rand() / RAND_MAX);

    if (is_corrupted(random)) {
        pdus[*index].tag.value = 0xDEADBEEF | 1; // Set a specific bit to indicate corruption
    } else {
        initialize_structure(&pdus[*index]);
    }
    (*index)++;
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_array(int N) {
    int i, size;
    pthread_t threads[N];
    pthread_attr_t attr;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    if (N <= 0) {
        fprintf(stderr, "Error: Invalid input for array size\n");
        return NULL;
    }

    size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(size);
    if (!pdus) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        return NULL;
    }

    pthread_attr_init(&attr);
    pthread_mutex_init(&lock, NULL);

    for (i = 0; i < N; ++i) {
        int *index = &i;
        pthread_create(&threads[i], &attr, create_pdu, &pdus + i);
    }

    for (int j = 0; j < N; ++j) {
        pthread_join(threads[j], NULL);
    }

    pthread_mutex_destroy(&lock);
    pthread_attr_destroy(&attr);

    if (N != pthread_mutex_trylock(&lock)) { // Check for race condition during concurrent access to pdus[]
        fprintf(stderr, "Error: Race condition detected\n");
        free(pdus);
        return NULL;
    }

    int corrupted = 0;
    for (i = 0; i < N; ++i) {
        if ((pdus[i].tag.value & 1) == 1) { // Check for corruption by checking specific bit
            corrupted++;
        }
    }

    if (corrupted > 0 && corrupted < N * 0.1) {
        fprintf(stderr, "Warning: Corrupted data detected (%d out of %d structures)\n", corrupted, N);
    } else if (corrupted >= N * 0.1) {
        fprintf(stderr, "Error: High level of corruption detected (%d out of %d structures)\n", corrupted, N);
        free(pdus);
        return NULL;
    }

    pthread_mutex_unlock(&lock);
    return pdus;
}
```

