NicListNode* create_node(char mac[], char ip[], char subnet_mask[], int status) {
    NicListNode* new_node = mmap(NULL, sizeof(NicListNode), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!new_node) return NULL;
    memcpy(&new_node->config.mac, mac, 18);
    memcpy(&new_node->config.ip, ip, 16);
    memcpy(&new_node->config.subnet_mask, subnet_mask, 16);
    new_node->config.status = status;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void add_to_list(NicListNode* node) {
    pthread_rwlock_wrlock(&list_lock);
    NicListNode* current = head;
    if (!current) {
        head = node;
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_rwlock_unlock(&list_lock);
}

void* get_node(char mac[]) {
    pthread_rwlock_rdlock(&list_lock);
    NicListNode* current = head;
    while (current) {
        if (!strcmp(current->config.mac, mac)) break;
        current = current->next;
    }
    if (current) pthread_rwlock_unlock(&list_lock);
    else pthread_rwlock_unlock(&list_lock);
    return current;
}

void update_node(NicListNode* node, char ip[], char subnet_mask[], int status) {
    memcpy(&node->config.ip, ip, 16);
    memcpy(&node->config.subnet_mask, subnet_mask, 16);
    node->config.status = status;
}
