#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} nfapi_crc_list_t;

void init_nfapi_crc_list(nfapi_crc_list_t* list, size_t max_entries) {
    list->capacity = max_entries > 0 ? max_entries : 16;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory for nfapi crc list\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void free_nfapi_crc_list(nfapi_crc_list_t* list) {
    if (list->data) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
    }
}

bool add_to_nfapi_crc_list(nfapi_crc_list_t* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->length >= list->capacity) {
        void* temp = realloc(list->data, list->capacity * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            fprintf(stderr, "Failed to resize memory for nfapi crc list\n");
            return false;
        }
        list->data = temp;
        list->capacity *= 2;
    }
    pthread_mutex_lock(&list->lock);
    list->data[list->length++] = *pdu;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void test_nfapi_crc_list() {
