struct ip_addr *resolve_hostname(const char *hostname, ip_preference preference) {
    struct addrinfo hints;
    struct addrinfo *res, *addr = NULL;
    int error;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = (preference == IPV4) ? AF_INET : AF_INET6;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_NUMERICHOST | AI_CANONNAME;

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error) {
        log("DNS resolution failed: getaddrinfo()");
        return NULL;
    }

    for (struct addrinfo *curr = res; curr != NULL; curr = curr->ai_next) {
        size_t ip_len = (curr->ai_family == AF_INET) ? IP_LENGTH : IP_LENGTH + 16;

        if (ip_len > MAX_ATTEMPTS || curr->ai_addrlen > ip_len) {
            log("DNS resolution failed: buffer overflow");
            continue;
        }

        struct ip_addr *ip = malloc(sizeof(struct ip_addr));
        if (!ip) {
            log("DNS resolution failed: out of memory");
            return NULL;
        }

        memcpy(ip->addr, curr->ai_addr, ip_len);
        ip->length = ip_len;

        if (pthread_mutex_lock(&curr->ai_data->addrinfo_data.ai_mutex)) {
            free(ip);
            log("DNS resolution failed: pthread_mutex_lock()");
            continue;
        }

        if (curr->ai_canonname && strcmp(hostname, curr->ai_canonname)) {
            // Log alias found
        }

        if (!addr) {
            addr = ip;
            continue;
        }

        // Validate IP address and update the most appropriate one based on preference
        if (preference == BOTH && curr->ai_family == AF_INET6) {
            addr = ip;
            break;
        } else if (addr->length < ip->length) {
            free(addr);
            addr = ip;
        }

        pthread_mutex_unlock(&curr->ai_data->addrinfo_data.ai_mutex);
    }

    freeaddrinfo(res);
    return addr;
}

