#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    int id;
    unsigned char priority;
    bool status;
} Task;

struct task_list {
    size_t len;
    size_t cap;
    Task* tasks;
};

void task_list_init(struct task_list* list, size_t capacity) {
    list->len = 0;
    list->cap = capacity;
    list->tasks = malloc(capacity * sizeof(Task));
}

void import_tasks(struct task_list* list, char* data_source) {
    FILE* file = fopen(data_source, "r");
    if (!file) {
        perror("Error opening data source file");
        return;
    }

    Task current_task;
    size_t tasks_count = 0;

    while (fscanf(file, "%d%*c %hhu%*c %d%*c\n", &current_task.id, &current_task.priority, &current_task.status) == 3) {
        if (tasks_count > 0 && current_task.priority == list->tasks[tasks_count - 1].priority) {
            fprintf(stderr, "Error: Two tasks have the same priority.\n");
            break;
        }

        if (list->len >= list->cap) {
            Task* new_tasks = realloc(list->tasks, sizeof(Task) * (list->cap + 100));
            if (!new_tasks) {
                perror("Error allocating memory");
                break;
            }
            list->cap += 100;
            list->tasks = new_tasks;
        }

        current_task.priority -= 1; // Prioritize lower priority numbers
        list->tasks[tasks_count++] = current_task;
    }

    fclose(file);
}

void configure_tasks(struct task_list* list, void(*config)(Task*, ...)) {
    import_tasks(list, "data.txt"); // Replace with the actual data source path
    for (size_t i = 0; i < tasks_count; ++i) {
        config(&list->tasks[i]);
    }
}

// Example usage:
struct task_list list;
task_list_init(&list, 100);
configure_tasks(&list, [](Task* task, int additional_data) { /* Custom configuration logic here */ });
```
