typedef struct Node {
    char *str;
    int priority;
    struct Link **links;
    size_t num_links;
} Node;

typedef struct Link {
    struct Node *node1;
    struct Node *node2;
    int weight;
} Link;

Node* create_node(char *str, int priority) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->str = strdup(str);
    node->priority = priority;
    node->links = NULL;
    node->num_links = 0;
    return node;
}

Link* create_link(Node *node1, Node *node2) {
    if (node1 == node2 || node1->num_links >= 1000 || node2->num_links >= 1000)
        return NULL;

    Link *link = (Link *)malloc(sizeof(Link));
    link->node1 = node1;
    link->node2 = node2;
    link->weight = rand() % 100 + 1; // Generate random weight between 1 and 100

    // Add the link to both nodes' lists of links, ensuring no duplicates.
    for (size_t i = 0; i < node1->num_links; ++i) {
        if (node1->links[i]->node2 == node2) {
            link->node1->links[i] = link;
            return link;
        }
    }
    node1->links = realloc(node1->links, sizeof(Link *) * (node1->num_links + 1));
    node1->links[node1->num_links++] = link;

    for (size_t i = 0; i < node2->num_links; ++i) {
        if (node2->links[i]->node1 == node1) {
            link->node2->links[i] = link;
            return link;
        }
    }
    node2->links = realloc(node2->links, sizeof(Link *) * (node2->num_links + 1));
    node2->links[node2->num_links++] = link;

    return link;
}

void remove_link(Node *node1, Node *node2) {
    for (size_t i = 0; i < node1->num_links; ++i) {
        if (node1->links[i]->node2 == node2) {
            free(node1->links[i]);
            memmove(&(node1->links[i]), &(node1->links[i+1]), sizeof(Link *) * (node1->num_links - i - 1));
            --node1->num_links;
            break;
        }
    }
}

Node** get_nodes() {
    static Node **nodes = NULL;
    return nodes;
}
```

