    UE data;
    struct list_node *next;
} ListNode;

// Synchronized list structure using pthread_mutex_t for thread safety
struct synchronized_list {
    ListNode *head;
    pthread_mutex_t mutex;
};

SynchronizedList* create_synchronized_list() {
    SynchronizedList *list = malloc(sizeof(SynchronizedList));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_ue(SynchronizedList* list, UE ue) {
    pthread_mutex_lock(&list->mutex);

    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->data = ue;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

UE* get_ue_by_id(SynchronizedList* list, int id) {
    UE *result = NULL;
    pthread_mutex_lock(&list->mutex);

    ListNode *current = list->head;
    while (current != NULL) {
        if (current->data.id == id) {
            result = &current->data;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return result;
}

void update_signal_strength(SynchronizedList* list) {
    // Simulate network conditions to periodically update signal strengths
    pthread_mutex_lock(&list->mutex);

    ListNode *current = list->head;
    while (current != NULL) {
        current->data.signal_strength += rand() % 10 + 1; // Generate random values for signal strength updates
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

