#define MAX_ELEMENTS 10000
#define BUFFER_SIZE (MAX_ELEMENTS * 2)
#define AGE_THRESHOLD 300 // seconds
#define SIZE_THRESHOLD (1 << 20) // 1MB
#define IMPORTANT_CLEANUP_INTERVAL 60 // seconds

NFAPI_CRC_INDICATION_PDU_T *data = NULL;
size_t currentSize = 0;
size_t maxIndex = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;

void addNotification(NFAPI_CRC_INDICATION_PDU_T notification) {
    pthread_mutex_lock(&mutex);
    if (currentSize + 1 >= BUFFER_SIZE) {
        free(data);
        data = realloc(data, (BUFFER_SIZE *= 2));
        maxIndex = BUFFER_SIZE - 1;
    }
    data[currentSize++] = notification;
    data[currentSize - 1].timestamp = time(NULL);
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&notEmpty);
}

void removeOldNotifications() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    size_t i;
    for (i = 0; i < currentSize; ++i) {
        if ((data[i].timestamp + AGE_THRESHOLD < ts.tv_sec) && !data[i].important) {
            if (i != maxIndex) {
                memmove(data + i, data + i + 1, --currentSize - i);
            } else {
                --maxIndex;
            }
        }
    }
}

void cleanupImportantNotifications() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    size_t i;
    for (i = 0; i < currentSize; ++i) {
        if (data[i].timestamp + IMPORTANT_CLEANUP_INTERVAL < ts.tv_sec && data[i].important) {
            data[i].important = false;
        }
    }
}

void *listenAPI(void *arg) {
    // Implement listening API logic here
}

void iterateNotifications(void (*function)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < currentSize; ++i) {
        function(data[i]);
    }
    pthread_mutex_unlock(&mutex);
}
```

