    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
    bool important;
    bool crcflag; // randomly set at creation
} NFAPI_CRC_INDICATION_PDU_T;

struct buffer {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t head, tail;
    pthread_mutex_t mutex;
};

void init_buffer(struct buffer *b, size_t capacity) {
    b->capacity = capacity;
    b->head = b->tail = 0;
    b->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    pthread_mutex_init(&b->mutex, NULL);
}

void enqueue(struct buffer *b, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&b->mutex);
    b->data[(b->head + 1) % b->capacity] = data;
    b->head = (b->head + 1) % b->capacity;
    pthread_mutex_unlock(&b->mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(struct buffer *b) {
    NFAPI_CRC_INDICATION_PDU_T res;
    pthread_mutex_lock(&b->mutex);
    if (b->head == b->tail) {
        res.important = false;
        res.timestamp = 0; // or current time for debugging purposes
        pthread_mutex_unlock(&b->mutex);
        return res;
    }
    res = b->data[b->tail];
    b->tail = (b->tail + 1) % b->capacity;
    pthread_mutex_unlock(&b->mutex);
    return res;
}

void cleanup(struct buffer *b, time_t age_threshold, bool important_only) {
    pthread_mutex_lock(&b->mutex);
    for (size_t i = b->tail; i != b->head; i = (i + 1) % b->capacity) {
        if (!important_only && b->data[i].timestamp + age_threshold < time(NULL)) {
            free(b->data + i);
        }
    }
    pthread_mutex_unlock(&b->mutex);
}
```

This code provides the basic structure for managing a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions for enqueueing new notifications (`enqueue`), dequeuing old ones (`dequeue`), cleaning up non-important notifications that exceed an age threshold (`cleanup`), and concurrent access control via a mutex (`pthread_mutex_lock` and `pthread_mutex_unlock`).

The enqueue function adds new data to the buffer, ensuring it does not overflow by using modulo arithmetic on array indexing. The dequeue function safely removes an item from the buffer while handling potential edge cases where the buffer is empty. The cleanup function iterates over the buffer and frees memory for elements that have expired or are non-important, if requested.

A buffer mechanism is implemented to handle occasional data bursts without overwhelming memory resources by using a fixed-size array and modulo arithmetic for indexing. The trade-off between immediate cleanup and potential memory consumption is evaluated through the choice of age thresholds and cleaning up only non-important elements, allowing important notifications to persist even if they exceed size or age constraints.

Concurrent access control and graceful handling of unexpected interruptions are addressed by using a mutex for synchronization between threads. Potential race conditions are handled by ensuring that the cleanup function iterates over the buffer in a thread-safe manner, with all modifications done under the mutex lock. The code does not include explicit logging, but it can be easily integrated into the existing functions as needed.

Finally, the design is adaptable to varying network conditions through the flexible handling of incoming notifications and the buffer mechanism's ability to accommodate occasional data bursts without overwhelming memory resources."]

