typedef struct aes_ctx {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} AES_CTX;

static void derive_key(const uint8_t *password, size_t password_len, const uint8_t *salt, size_t salt_len, uint8_t *derived_key, size_t derived_key_len) {
    EVP_PBKDF2(*pbkdf2_ctx, password, password_len, salt, salt_len, PBKDF2_ITERATIONS, SHA256, derived_key, derived_key_len);
}

static AES_CTX *aes_init(const uint8_t *password, size_t password_len, const uint8_t *salt, size_t salt_len) {
    AES_CTX *ctx = (AES_CTX *)malloc(sizeof(AES_CTX));
    if (!ctx) return NULL;

    uint8_t derived_key[AES_BLOCK_SIZE];
    derive_key(password, password_len, salt, salt_len, derived_key, sizeof(derived_key));

    memcpy(ctx->key.d, derived_key, AES_BLOCK_SIZE);
    RAND_bytes(ctx->iv, AES_BLOCK_SIZE);

    return ctx;
}

