void init_notification_list(struct notification_list* list, size_t initial_size) {
    if (initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY)
        initial_size = MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->buffer = mmap(NULL, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->buffer == MAP_FAILED) {
