        exit(EXIT_FAILURE);
    }

    list->capacity = initial_size;
    list->head = 0;
    list->tail = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_notification(struct notification_list* list, const NFAPI_CRC_INDICATION_PDU_T* notification) {
    pthread_mutex_lock(&list->lock);

    // Ensure the buffer is not full before adding a new notification
    if ((list->head + 1) % list->capacity == list->tail) {
        size_t new_size = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = mremap(list->buffer, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), MREMAP_MAYMOVE);
        if (new_buffer == MAP_FAILED) {
            perror("mremap failed");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->capacity = new_size;
        list->buffer = new_buffer;
    }

    // Add the notification to the buffer
    list->buffer[(list->head) % list->capacity] = *notification;
    (list->head)++;

    pthread_mutex_unlock(&list->lock);
}

void remove_old_notifications(struct notification_list* list, time_t current_time, bool is_important) {
    pthread_mutex_lock(&list->lock);

    size_t start = (is_important ? list->head : list->tail) - 1;
    for (size_t i = start; i != (is_important ? list->head : list->tail); ) {
        if ((list->buffer[i].tag & IMPORTANT_TAG) == is_important) {
            if (time_diff(current_time, list->buffer[i].timestamp) > TIME_WINDOW || list->buffer[i].payload_size > MAX_PAYLOAD) {
                memmove(&list->buffer[i], &list->buffer[(i + 1) % list->capacity], (list->tail - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }
        i = (i + 1) % list->capacity;
    }

    if ((list->head - list->tail) > MAX_CONCURRENT) {
        size_t new_size = list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = mremap(list->buffer, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), MREMAP_MAYMOVE);
        if (new_buffer == MAP_FAILED) {
            perror("mremap failed");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->capacity = new_size;
        list->buffer = new_buffer;
    }

    pthread_mutex_unlock(&list->lock);
}

