import os, hashlib, time, sys

def md5file(path):
    file = open(path, 'rb')
    hasher = hashlib.md5()
    chunk_size = 1024 * 64

    while True:
        data = file.read(chunk_size)
        if not data:
            break
        hasher.update(data)

    file.close()
    return hasher.hexdigest(), os.path.getmtime(path), os.path.islink(path)

def walkdir(root, visited=None):
    if not visited:
        visited = set()

    for entry in os.scandir(root):
        path = entry.path

        if entry.is_file():
            hashed, mtime, islink = md5file(path)
            yield (hashed, mtime, islink), path

        elif entry.is_dir() and path not in visited:
            visited.add(path)
            for subitem in walkdir(path, visited):
                yield subitem

def traverse(root):
    visited = set()
    total = 0
    processed = 0
    for item, path in walkdir(root, visited):
        if item[1] >= processed + 100e6:
            print(f"Processed {processed} MB, {len(visited)} files processed.")
            processed += 100e6
        total += 1
        hashed, mtime, islink = item
        print(f"Processing file: {path}, size={os.path.getsize(path)}, islink={islink}")
