#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct DataPacket {
    int packet_id;
    time_t timestamp;
    void *payload; // Dynamically allocated data
    struct DataPacket *prev, *next;
};

typedef struct {
    struct DataPacket *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_doubly_linked_list(DoublyLinkedList* list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_valid_data(const void *data) {
    // Replace this with your own validation logic based on the actual data structure
    return data != NULL && *(int*)data > 0;
}

void* generate_data() {
    int data = rand() % 100 + 1;
    void *new_data = malloc(sizeof(int));
    if (new_data) {
        *(int *)new_data = data;
    }
    return new_data;
}

void populate_list(DoublyLinkedList* list, int num_packets) {
    pthread_t threads[num_packets];
    for (size_t i = 0; i < num_packets; ++i) {
        pthread_create(&threads[i], NULL, generate_packet_and_insert, list);
    }
    for (size_t i = 0; i < num_packets; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* generate_packet_and_insert(void *arg) {
    DoublyLinkedList *list = (DoublyLinkedList *)arg;
    void *data = generate_data();
    if (is_valid_data(data)) {
        struct DataPacket *new_node = malloc(sizeof(struct DataPacket));
        if (new_node) {
            new_node->packet_id = rand() % 1000 + 1;
            new_node->timestamp = time(NULL);
            new_node->payload = data;
            new_node->prev = new_node->next = NULL;

            pthread_mutex_lock(&list->lock);
            if (list->head == NULL) {
                list->head = new_node;
                list->tail = new_node;
            } else {
                list->tail->next = new_node;
                new_node->prev = list->tail;
                list->tail = new_node;
            }
            pthread_mutex_unlock(&list->lock);
        }
    }
    free(data); // Release memory even if there was an error or early termination
    pthread_exit(NULL);
}
```

This implementation creates a doubly-linked list, handles concurrent access with a mutex lock, and minimizes memory leaks by properly releasing resources. It also gracefully handles missing or stale data by only inserting valid packets into the linked list. The function is optimized for performance under high-load conditions by utilizing multiple threads to generate and populate the list simultaneously."]

