    img_info.width = *(const int*)img_data++;
    img_info.height = *(const int*)img_data++;

    if (bit_depth < 1 || bit_depth > 16 || num_components < 1 || num_components > 4) {
        printf("Error: Unsupported bit depth or number of components.\n");
        goto cleanup;
    }

    const uint8_t* img_data_ptr = img_data;
    int component_index = 0;
    for (int i = 0; i < num_components; ++i) {
        int samples_per_pixel = *(const int*)img_data_ptr++;

        if (samples_per_pixel != 1 && samples_per_pixel != img_info.width * img_info.height) {
            printf("Error: Incorrect number of samples per pixel.\n");
            goto cleanup;
        }

        int component_size = samples_per_pixel * img_info.bit_depth / 8;
        if (component_index == 0) {
            img_info.data = malloc(img_info.width * img_info.height * component_size);
        } else if (component_index < num_components) {
            img_info.data = realloc(img_info.data, img_info.width * img_info.height * component_size);
        } else {
            printf("Error: Extra samples detected.\n");
            goto cleanup;
        }

        memcpy(img_info.data, img_data_ptr, component_size * img_info.width * img_info.height);

        const char* color_profile = (const char*)img_data_ptr + (3 * component_size * img_info.width * img_info.height);
        memcpy(img_info.color_profile, color_profile, 4 + 3 * (num_components - 1));

        img_data_ptr += component_size * img_info.width * img_info.height;
        component_index++;
    }

    // Perform metadata extraction, SHA-256 hash computation, and integrity check here
    // ...

    for (int i = 0; i < num_packets; ++i) {
        CRC_INDICATION_REL8_TAG* crc_indication = &packet_list[i].crc_indication;
        crc_indication->rnti = i;
        crc_indication->crcflag = rand() % 2;
    }

cleanup:
    if (file) fclose(file);
    if (img_info.data) free(img_info.data);
    if (packet_list) free(packet_list);
}
