```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryManager {
    void** memoryBlocks;
    FILE* logFile;
    pthread_mutex_t lock;
    size_t capacity;
    size_t allocatedSize;
} MemoryManager;

MemoryManager memoryManager;

void initMemoryManager(const char* logFileName) {
    memoryManager.memoryBlocks = NULL;
    memoryManager.logFile = fopen(logFileName, "w");
    if (!memoryManager.logFile) {
        perror("Failed to open log file");
    }
    pthread_mutex_init(&memoryManager.lock, NULL);
    memoryManager.capacity = 0;
    memoryManager.allocatedSize = 0;
}

void writeToMemoryLog(const char* message) {
    if (memoryManager.logFile != NULL) {
        pthread_mutex_lock(&memoryManager.lock);
        fprintf(memoryManager.logFile, "%s\n", message);
        fflush(memoryManager.logFile);
        pthread_mutex_unlock(&memoryManager.lock);
    }
}

void* allocateBlock(size_t size) {
    void* block;
    if (memoryManager.capacity <= memoryManager.allocatedSize + size) {
        writeToMemoryLog("Reallocating memory");
        memoryManager.capacity *= 2;
        block = realloc(memoryManager.memoryBlocks, memoryManager.capacity * sizeof(void*));
        if (!block) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
    } else {
        block = memoryManager.memoryBlocks + memoryManager.allocatedSize;
    }
    memset(block, 0, size);
    memoryManager.allocatedSize += size;
    return block;
}

void freeBlock(void* block) {
    pthread_mutex_lock(&memoryManager.lock);
    free(block);
    pthread_mutex_unlock(&memoryManager.lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocateArray(size_t size) {
    void* block = allocateBlock(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T* array = block;
    for (size_t i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2;
    }
    return array;
}
```

In this example, the `MemoryManager` structure is responsible for logging memory allocation activities and managing memory blocks using a custom allocator function `allocateBlock`. The `allocateArray` function creates an array of the specified size, initializes each structure with valid values, and returns a pointer to the allocated memory.

It is essential to call `initMemoryManager()` before any calls to `allocateArray()`, providing the desired log file name. If you want to clean up resources when the program terminates, consider adding a function to deinitialize and clean up the MemoryManager.

To use this code with multiple threads, make sure to call `pthread_mutex_lock()` before any modifications to shared data (memory blocks) and `pthread_mutex_unlock()` after that. This ensures thread safety when accessing the shared memory manager.']

