    if (index >= manager->length || index < 0) {
        log_error("Index out of bounds in CRCI_PDU_MANAGER");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    memcpy(manager->data[index], pdu, sizeof(CRC_INDICATION_PDU));
    pthread_mutex_unlock(&manager->lock);
