// Iterate over the dynamic array and perform operations on the CRCFLAG
void crc_pdu_manager_iterate(CRCI_PDU_MANAGER* manager, void(*operation)(CRC_INDICATION_PDU*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->length; ++i) {
        operation(manager->data[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Deallocate memory for the dynamic array and the CRCI_PDU_MANAGER structure
void crc_pdu_manager_free(CRCI_PDU_MANAGER* manager) {
    pthread_mutex_destroy(&manager->lock);

