typedef struct {
    pthread_mutex_t mutex;
    sem_t notFull, notEmpty; // Semaphores for producer and consumer synchronization
    size_t capacity;        // Current buffer capacity
    size_t head, tail;      // Head and Tail indices of the circular buffer
    NFAPI_CRC_INDICATION_PDU_T* buffer;  // Pointer to the dynamically allocated array
} CircularBuffer_t;

CircularBuffer_t* createCB(size_t initialSize) {
    CircularBuffer_t *cb = malloc(sizeof(CircularBuffer_t));
    if (!cb) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cb->capacity = initialSize;
    cb->buffer = calloc(initialSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cb->buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        free(cb);
        return NULL;
    }
    pthread_mutex_init(&cb->mutex, NULL);
    sem_init(&cb->notFull, 0, cb->capacity);
    sem_init(&cb->notEmpty, 0, 0);
    cb->head = cb->tail = 0;
    return cb;
}

void destroyCB(CircularBuffer_t* cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->mutex);
    free(cb);
}

bool addElement(CircularBuffer_t* cb, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (sem_wait(&cb->notFull) < 0) {
        fprintf(stderr, "Semaphore wait failed\n");
        return false;
    }
    pthread_mutex_lock(&cb->mutex);
    size_t next = cb->head + 1 == cb->capacity ? 0 : cb->head + 1;
    memcpy(&cb->buffer[next], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cb->head = next;
    pthread_mutex_unlock(&cb->mutex);
    sem_post(&cb->notEmpty);
    return true;
}

bool removeElement(CircularBuffer_t* cb) {
    if (sem_wait(&cb->notEmpty) < 0) {
        fprintf(stderr, "Semaphore wait failed\n");
        return false;
    }
    pthread_mutex_lock(&cb->mutex);
    const size_t next = cb->tail + 1 == cb->capacity ? 0 : cb->tail + 1;
    NFAPI_CRC_INDICATION_PDU_T* data = &cb->buffer[cb->tail];
    cb->tail = next;
    pthread_mutex_unlock(&cb->mutex);
    sem_post(&cb->notFull);
    return true;
}

