void *token_cache; // LRU cache implementation

int token_validation(const char *token_str, size_t len, const char *log_tag) {
    jsmn_parser parser;
    jsmn_object tokens;
    int ret = JSMN_OK;
    bool valid = true;
    time_t expiration;

    jsmn_init(&parser);
    ret = jsmn_parse(token_str, len, &tokens, sizeof(tokens));

    if (ret < 0) {
        // Malformed JSON or allocation failure
        printf("%s: Malformed JSON\n", log_tag);
        return -1;
    }

    if (ret == 0 || tokens.count < 4) {
        // Invalid number of required fields
        printf("%s: Insufficient fields\n", log_tag);
        return -2;
    }

    if (strcmp(tokens.names[2], "Bearer") != 0) {
        // Incorrect token type
        printf("%s: Invalid token_type (%s)\n", log_tag, tokens.names[2]);
        return -3;
    }

    if (!strlen(token_str)) {
        // Empty access_token
        printf("%s: Empty access_token\n", log_tag);
        return -4;
    }

    if (tokens.values[1] > 3600 * config.timeout / 1000) {
        // Expired expires_in
        printf("%s: Expired token\n", log_tag);
        return -5;
    }

    expiration = time(NULL) + tokens.values[1];
    if (tokens.count > 4 && strlen(token_str) < 16 || strlen(token_str) > 128) {
        // Invalid refresh_token length
        printf("%s: Invalid refresh_token length\n", log_tag);
        return -6;
    }

    pthread_mutex_lock(&cache_lock);
    if (token_cache && access(token_cache, F_WRLCK) == 0) {
        // Token is already in the cache and being accessed by another thread
        pthread_mutex_unlock(&cache_lock);
        return -7;
    }
    pthread_mutex_unlock(&cache_lock);

    if (expiration - time(NULL) > config.cache_timeout) {
        // Token is valid and not yet expired, cache it temporarily
        pthread_mutex_lock(&cache_lock);
        mmap_cache(token_str, len, token_cache);
        pthread_mutex_unlock(&cache_lock);
    } else {
        // Token has already expired or is not valid for caching
        valid = false;
    }

    if (valid) {
        // Token is valid and can be used for further processing
        return 0;
    }

    // Token is invalid, but it may still be useful to log the failure
    if (config.log_threshold <= ++g_num_failures) {
        printf("%s: Invalid token\n", log_tag);
    }
    return -8;
}
```

