    if (udata->conn->id < 0 || udata->conn->id > INT_MAX) {
        free(udata->password);
        return -3;
    }

    if (!udata->log_cb || udata->log_cb("DEBUG") != 0) {
        free(udata->password);
        return -4;
    }

    // All checks passed, continue with further processing.

    return 0;
}

void free_userdata(UserData *udata) {
    if (udata) {
        free(udata->password);
        free(udata->conn);
        free(udata);
    }
