#include <iostream>
#include <map>
#include <list>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <thread>
#include <chrono>

struct UEContextInfo {
    int imsi;
    int rnti;
    bool crcStatus;
};

class UEContextManager {
private:
    std::map<int, UEContextInfo> contexts;
    std::list<UEContextInfo> cleanupQueue;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic_uint64_t cleanedCount = {0};
    std::atomic_bool cleaningInProgress = {false};

public:
    void addContext(const UEContextInfo& context) {
        // Use find() instead of insert() to handle duplicate IMSI entries gracefully
        auto it = contexts.find(context.imsi);
        if (it != contexts.end()) {
            it->second.rnti = context.rnti;
            it->second.crcStatus = context.crcStatus;
        } else {
            contexts[context.imsi] = context;
        }
    }

    void updateContext(const UEContextInfo& context) {
        auto it = contexts.find(context.imsi);
        if (it != contexts.end()) {
            it->second = context;
        }
    }

    void startCleanup() {
        cleaningInProgress.store(true);
        // Add a delay to simulate background cleanup process
        std::this_thread::sleep_for(std::chrono::seconds(5));

        std::lock_guard<std::mutex> lock(mtx);
        for (auto& context : contexts) {
            if (!context.second.crcStatus && std::find(cleanupQueue.begin(), cleanupQueue.end(), context.second) == cleanupQueue.end()) {
                cleanupQueue.push_back(context.second);
                ++cleanedCount;
            }
        }
        cleaningInProgress.store(false);
        cv.notify_all();
    }

    void runCleanupThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this](){ return cleaningInProgress.load() || !cleanupQueue.empty(); });

            if (!cleaningInProgress.load()) {
                auto context = cleanupQueue.front();
                cleanupQueue.pop_front();
                contexts.erase(context.imsi);
                ++cleanedCount;
            }
        }
    }

    void logMetrics() const {
        std::cout << "Cleaned Context Count: " << cleanedCount << std::endl;
        // Add error handling and logging for potential errors encountered during cleanup
    }
};
```
