#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <limits.h>
#include <sys/mman.h>

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    size_t payloadSize;
    pthread_mutex_t lock;
} DataPacket;

typedef struct HashMapNode {
    DataPacket* dataPacket;
    struct HashMapNode* next;
} HashMapNode;

struct HashMap {
    size_t size;
    HashMapNode** nodes;
    pthread_mutex_t mutex;
};

HashMap* createHashMap(size_t size) {
    HashMap* hashMap = malloc(sizeof(HashMap));
    hashMap->size = size;
    hashMap->nodes = calloc(size, sizeof(HashMapNode*));
    hashMap->mutex = PTHREAD_MUTEX_INITIALIZER;
    return hashMap;
}

DataPacket* createDataPacket(int* uniqueID) {
    DataPacket* dataPacket = malloc(sizeof(DataPacket));
    dataPacket->packetID = *uniqueID;
    dataPacket->timestamp = time(NULL);
    dataPacket->payloadSize = rand() % 100 + 50; // Payload size within the range [50, 150]
    pthread_mutex_init(&dataPacket->lock, NULL);
    *uniqueID += 1;
    return dataPacket;
}

int hashFunction(const void* key) {
    time_t timestamp = *(time_t*)key;
    int hashValue = (int)(timestamp % UINT_MAX);
    return hashValue < 0 ? -hashValue : hashValue;
}

HashMapNode* findEntry(HashMap* hashMap, time_t timestamp) {
    int hashValue = hashFunction(&timestamp);
    HashMapNode* currentNode = hashMap->nodes[hashValue];

    while (currentNode != NULL) {
