    newNode->dataPacket = dataPacket;
    newNode->next = hashMap->nodes[hashValue];
    hashMap->nodes[hashValue] = newNode;

    return true;
}

void removeDataPacket(HashMap* hashMap, DataPacket* dataPacket) {
