#define BUFFER_SIZE 1024
#define MAP_SIZE (BUFFER_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T))

atomic_t next_index = ATOMIC_VAR_INIT(0);
volatile atomic_int buffer_full = ATOMIC_VAR_INIT(0);
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
void* buffer_addr;

int add_data(NFAPI_CRC_INDICATION_PDU_T data) {
    if (buffer_full.load()) return -1; // Buffer is full, cannot add more data

    pthread_mutex_lock(&buffer_lock);
    NFAPI_CRC_INDICATION_PDU_T* buf = buffer_addr + atomic_load(&next_index) % BUFFER_SIZE;

    if (buf->rnti != 0 && !is_valid_crcflag(buf->crcflag)) { // Check for valid CRCFLAG
        pthread_mutex_unlock(&buffer_lock);
        return -1;
    }

    buf->rnti = data.rnti;
    buf->crcflag = data.crcflag;
    buf->tag = data.tag;
    buf->crc_indication = data.crc_indication;

    atomic_fetch_add(&next_index, 1);
    pthread_mutex_unlock(&buffer_lock);
    return 1;
}

int get_data(NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!buffer_full.load()) return -1; // Buffer is empty, cannot get more data

    pthread_mutex_lock(&buffer_lock);
    NFAPI_CRC_INDICATION_PDU_T* buf = buffer_addr + atomic_load(&next_index) % BUFFER_SIZE;

    if (buf->rnti == 0 || is_invalid_rnti(buf->rnti)) { // Check for valid RNTI
        pthread_mutex_unlock(&buffer_lock);
        return -1;
    }

    *data = *buf;
    buf->rnti = 0; // Mark as processed
    pthread_mutex_unlock(&buffer_lock);
    return 1;
}

int external_source_handler(void) {
    RNTI new_rnti = get_new_rnti(); // Get the latest RNTI assignments from the external source

    if (new_rnti <= 0) return -1; // Error in data acquisition

    pthread_mutex_lock(&buffer_lock);
    NFAPI_CRC_INDICATION_PDU_T* buf = buffer_addr + atomic_load(&next_index) % BUFFER_SIZE;

    while (buf->rnti != 0 && !is_valid_rnti(buf->rnti)) {
        if (next_index.load() == atomic_load(&next_index) + BUFFER_SIZE) break; // Circular buffer overflow

        buf = buffer_addr + (atomic_load(&next_index) + 1) % BUFFER_SIZE;
    }

    if (buf->rnti == 0) {
        buf->rnti = new_rnti;
        pthread_mutex_unlock(&buffer_lock);
        return 1;
    }

    pthread_mutex_unlock(&buffer_lock);
    return -1; // RNTI already in use
}

void cleanup() {
    if (munmap(buffer_addr, MAP_SIZE) < 0) fprintf(stderr, "Error unmapping buffer\n");
    pthread_mutex_destroy(&buffer_lock);
}

int init() {
    buffer_addr = mmap(NULL, MAP_SIZE, PROT_READ | PROT_WRITE, MAP_FIXED | MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    if (buffer_addr == MAP_FAILED) return -1; // Error in memory mapping

    buffer_full.store(0);
    return 0;
}
```

