static int num_cells = 0;
static const int cells_growth_factor = 2;

// Custom reallocation strategy function that minimizes memory overhead
void grow_cells(void) {
    CELL_ELEMENT *new_head = malloc(num_cells * cells_growth_factor * sizeof(CELL_ELEMENT));
    if (new_head == NULL) {
        return; // Handle error and free memory as needed
    }
    memcpy(new_head, head, num_cells * sizeof(CELL_ELEMENT));
    free(head);
    head = new_head;
}

// Thread-safe function to add a cell to the dynamic array
void add_cell(const CELL_CONFIG *config) {
    sem_wait(&lock);

    if (num_cells == 0) {
        head = malloc(sizeof(CELL_ELEMENT));
        if (!head) {
            // Handle error and free acquired memory as needed
            sem_post(&lock);
            return;
        }
        memcpy(&head->config, config, sizeof(CELL_CONFIG));
        num_cells++;
    } else if (num_cells >= head->next) {
        grow_cells();
        CELL_ELEMENT *new_element = &head[num_cells];
        memcpy(&new_element->config, config, sizeof(CELL_CONFIG));
        new_element->next = NULL;
        num_cells++;
    } else {
        CELL_ELEMENT *current = head;
        while (current->next != NULL && current->next + 1 < &head[num_cells]) {
            current = current->next;
        }
        CELL_ELEMENT *new_element = malloc(sizeof(CELL_ELEMENT));
        if (!new_element) {
            // Handle error and free acquired memory as needed
            sem_post(&lock);
            return;
        }
        memcpy(&new_element->config, config, sizeof(CELL_CONFIG));
        new_element->next = current->next;
        current->next = new_element;
        num_cells++;
    }

    sem_post(&lock);
}

