// Custom hash table using boost lockfree queue and unordered map
class DynamicList {
public:
    explicit DynamicList(size_t capacity) : buckets_(capacity) {}

    void insert(const PduData& data, std::function<void(const PduData&)> callback) {
        auto it = buckets_[hashFunction(data.rnti)].emplace_back(data);
        it->first->second->assign(it->first, data);
