    if (current_elements == MAX_ELEMENTS) {
        pthread_cond_wait(&not_full, &mutex);
    }

    mac_receipt_records[current_elements] = *record;
    current_elements++;
    mac_receipt_record_resize(); // Lazy allocation strategy

    pthread_mutex_unlock(&mutex);
}

void mac_receipt_record_pull(MAC_FRAME_RECEIPT_RECORD_T* record) {
    pthread_mutex_lock(&mutex);

    if (current_elements == 0) {
