import java.nio.LinkedHashMap;
import java.nio.MapMessage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.ConcurrentModificationException;
import java.util.List;
import java.util.Random;
import java.util.concurrent.locks.ReentrantLock;

public class NFAPICRCIndicationPDUManager {
    private static final int MAX_ELEMENTS = 50000;
    private static final double CRCFLAG_PROBABILITY_THRESHOLD = 0.5;
    private static final ReentrantLock lock = new ReentrantLock();
    private List<NFAPI_CRC_INDICATION_PDU_T> data;
    private int currentSize;
    private LinkedHashMap<Long, Integer> serializationIndices;

    public NFAPICRCIndicationPDUManager() {
        this.data = new ArrayList<>(MAX_ELEMENTS);
        this.currentSize = 0;
        this.serializationIndices = new LinkedHashMap<>(MAX_ELEMENTS, 0.75f);
    }

    public void addPDU(RX_UE_INFORMATION_TAG tag, long rnti, CRC_INDICATION_REL8_TAG crcIndication) {
        lock.lock();
        try {
            if (currentSize >= MAX_ELEMENTS) {
                resizeArray();
            }
            data.add(new NFAPI_CRC_INDICATION_PDU_T(tag, rnti, crcIndication));
            setCRCFlagProbabilistically(data.size() - 1);
            serializationIndices.put(rnti, currentSize);
            currentSize++;
        } finally {
            lock.unlock();
        }
    }

    private void resizeArray() {
        List<NFAPI_CRC_INDICATION_PDU_T> newData = new ArrayList<>(data.size() * 2);
        System.arraycopy(data.toArray(), 0, newData.toArray(), 0, data.size());
        data = newData;
    }

    private void setCRCFlagProbabilistically(int index) {
        if (new Random().nextDouble() < CRCFLAG_PROBABILITY_THRESHOLD) {
            data.get(index).setCRCFlag(true);
        }
    }

    public ByteArray serializePDUs() {
        lock.lock();
        try {
            if (currentSize == 0) {
                throw new IllegalStateException("No PDUs to serialize.");
            }
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            ObjectOutputStream objectOutputStream = new ObjectOutputStream(outputStream);
            for (Integer index : serializationIndices.keySet()) {
                if (!data.get(index).isCRCFlag() && index < currentSize) {
                    objectOutputStream.writeObject(data.get(index));
                }
            }
            return outputStream.toByteArray();
        } finally {
            lock.unlock();
        }
    }

    public void deserializePDUs(ByteArray byteArray) {
        try {
            ByteArrayInputStream inputStream = new ByteArrayInputStream(byteArray);
            ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
            while (true) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                try {
                    pdu = (NFAPI_CRC_INDICATION_PDU_T) objectInputStream.readObject();
                } catch (Exception e) {
