typedef struct {
    unsigned int downlink_channel;
    unsigned int uplink_channel;
} lte_phy_config;

struct lte_phy_array {
    size_t size;
    size_t capacity;
    lte_phy_config *data;
    pthread_mutex_t mutex;
};

void* shared_memory_map(void *addr, size_t size) {
    void *result = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (result == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return result;
}

void lte_phy_array_init(struct lte_phy_array *array, size_t initial_capacity) {
    array->data = shared_memory_map(NULL, sizeof(lte_phy_config) * initial_capacity);
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
}

void lte_phy_array_destroy(struct lte_phy_array *array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}

bool lte_phy_array_add(struct lte_phy_array *array, const lte_phy_config config) {
    if (array->size == array->capacity) {
        void *new_data = shared_memory_map(NULL, sizeof(lte_phy_config) * (array->capacity + 128));
        memcpy(new_data, array->data, array->size * sizeof(lte_phy_config));
        free(array->data);
        array->data = new_data;
        array->capacity *= 2;
    }
    pthread_mutex_lock(&array->mutex);
    lte_phy_config *current_data = array->data + array->size++;
    current_data->downlink_channel = config.downlink_channel;
    current_data->uplink_channel = config.uplink_channel;
    pthread_mutex_unlock(&array->mutex);
    return true;
}

lte_phy_config *lte_phy_array_get(const struct lte_phy_array *array, size_t index) {
    if (index >= array->size) {
        // Handle out of bounds access gracefully
        return NULL;
    }
    pthread_mutex_lock(&array->mutex);
    lte_phy_config *result = array->data + index;
    pthread_mutex_unlock(&array->mutex);
    return result;
}
```

