```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <atomic>
#include <mutex>
#include <random>
#include <chrono>
#include <thread>
#include <future>
#include <memory>
#include <cassert>

struct CRCIndicationPDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class CRCSynchronizedArray {
private:
    std::vector<CRIndicationPDU_T> array;
    std::mutex mtx;
    std::atomic<size_t> element_count = 0;

public:
    void push(const CRCIndicationPDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        while (array.size() >= element_count + 1) {
            mtx.wait(lock, [this] { return array.size() > element_count + 1; });
        }

        array[element_count++] = pdu;
    }

    void pop(CRIndicationPDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        while (element_count == 0) {
            mtx.wait(lock, [this] { return element_count > 0; });
        }

        assert(element_count > 0);
        pdu = array[--element_count];
    }

    size_t size() const {
        std::unique_lock<std::mutex> lock(mtx);
        return element_count;
    }
};

// Example usage:
void worker(CRCSynchronizedArray& array) {
    CRCIndicationPDU_T pdu;
    pdu.rnti = std::rand();
    pdu.crc_indication.crcflag = (std::rand() % 2);

    // Generate a random RX_UE_INFORMATION_TAG for simplicity.
    pdu.rx_ue_info = (RX_UE_INFORMATION_TAG)std::chrono::steady_clock::now().time_since_epoch().count();

    array.push(pdu);
}

int main() {
    const int num_threads = 10;
    CRCSynchronizedArray array;
    std::vector<std::thread> threads;

    for (int i = 0; i < num_threads; ++i) {
        threads.push_back(std::thread(worker, std::ref(array)));
    }

    for (auto& t : threads) {
        t.join();
    }

    // Iterate over the array and print elements.
    for (const auto& pdu : array) {
        std::cout << "RX_UE_INFORMATION_TAG: " << pdu.rx_ue_info << ", RNTI: " << pdu.rnti
            << ", CRC_INDICATION_REL8_TAG: CRCFLAG=" << pdu.crc_indication.crcflag << "\n";
    }
}
