['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

#define MAX_USERS 1024
#define BUFFER_SIZE 1024

typedef struct LTE_ENB_TASK_T {
    uint32_t transport_tag;
    uint64_t ue_id;
    void* data_buffer;
} LTE_ENB_TASK_T;

sem_t array_lock;
int array_size = 0;
LTE_ENB_TASK_T* array;

void init() {
    if ((array = mmap(NULL, MAX_USERS * sizeof(LTE_ENB_TASK_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    sem_init(&array_lock, 0, 1);
}

void add_entry(LTE_ENB_TASK_T* entry) {
    if (array_size == MAX_USERS) {
        fprintf(stderr, "Array is full\n");
        return;
    }

    sem_wait(&array_lock);
    array[array_size++] = *entry;
    sem_post(&array_lock);
}

void update_entry(uint64_t ue_id, void* data) {
    for (int i = 0; i < array_size; ++i) {
        if (sem_trywait(&array_lock)) {
            if (array[i].ue_id == ue_id) {
                memcpy(array[i].data_buffer, data, BUFFER_SIZE);
                sem_post(&array_lock);
                return;
            }
        }
    }
}

void* iterate_over_array() {
    void* result = NULL;
    LTE_ENB_TASK_T temp;

    sem_wait(&array_lock);
    for (int i = 0; i < array_size; ++i) {
        temp = array[i];
        memcpy(array + i, array + i + 1, sizeof(LTE_ENB_TASK_T) * (array_size - i));
        if (temp.data_buffer) {
            result = temp.data_buffer;
        }
    }
    memmove(array + array_size - 1, &array[0], sizeof(LTE_ENB_TASK_T) * (MAX_USERS - array_size));
    sem_post(&array_lock);

    return result;
}

void log_array_change() {
    fprintf(stderr, "Array size: %d\n", array_size);
}

void cleanup() {
    munmap(array, MAX_USERS * sizeof(LTE_ENB_TASK_T));
    sem_destroy(&array_lock);
}
```

This code uses a memory-mapped file for efficient memory usage and thread safety through the use of a semaphore. The array_lock semaphore is used to serialize access to the array, ensuring that only one thread modifies it at a time. The add_entry function checks if the array is full before adding a new entry, and the update_entry function iterates over the entire array to find the specified UE_ID. The iterate_over_array function returns an iterator for safely iterating over all elements in the array, allowing for efficient cache locality.

The log_array_change function logs array size changes, and the cleanup function deallocates the memory-mapped file when the program terminates. This solution handles out-of-memory conditions gracefully by preventing new entries from being added when the array is full, rather than abruptly failing.']

