struct LTE_ENB_TASK_T {
    uint32_t transportTag;
    uint64_t ueId;
    char buffer[BUFFER_SIZE];
};

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFlag;
};

class LTE_ENB {
private:
    std::vector<LTE_ENB_TASK_T> tasks;
    std::unordered_map<uint32_t, NFAPI_CRC_INDICATION_PDU_T> crcIndications;
    static std::random_device rd;
    static std::mt19937 gen;
    static std::uniform_int_distribution<> distribution;

public:
    LTE_ENB() : tasks(MAX_UES), crcIndications(MAX_UES) {
        for (auto& indication : crcIndications) {
            indication.second.RNTI = GetUniqueRNTI();
            indication.second.CRCFlag = false;
        }
    }

    LTE_ENB_TASK_T* addTask(uint64_t ueId, const char* data, size_t size) {
        auto it = tasks.emplace(tasks.end(), LTE_ENB_TASK_T{GetUniqueTransportTag(), ueId});
        if (!it.second) { // Out of memory
            std::cerr << "Out of memory" << std::endl;
            return nullptr;
        }
        memcpy(it.first->buffer, data, size);
        return it.first;
    }

    NFAPI_CRC_INDICATION_PDU_T* getCrcIndication(uint64_t ueId) {
        auto it = crcIndications.find(ueId);
        if (it != crcIndications.end())
            return &it->second;
        return nullptr;
    }

private:
    static uint32_t GetUniqueRNTI() {
        static std::atomic<uint32_t> rnti = 1;
        return rnti++;
    }

    static uint32_t GetUniqueTransportTag() {
        static std::atomic<uint32_t> transportTag = 0;
        return transportTag++;
    }
};

std::random_device LTE_ENB::rd;
std::mt19937 LTE_ENB::gen(LTE_ENB::rd());
std::uniform_int_distribution<>::param_type LTE_ENB::distribution(0, 65535);
```

