    int uplink_channel;
    std::atomic<int> version;
};

class LtePhyConfigManager {
private:
    std::vector<std::shared_ptr<LTE_PHY_CONFIG>> configs_;
    mutex mtx_;
    atomic<int> nextId_;

public:
    void addOrUpdate(const LTE_PHY_CONFIG& config, int expectedVersion) {
        // Implement bulk operations here if needed.
        std::lock_guard<mutex> lock(mtx_);

        auto it = std::find_if(configs_.begin(), configs_.end(),
                               [&](const auto& cfg) { return cfg->version == expectedVersion; });

        if (it != configs_.end()) {
            (*it)->downlink_channel = config.downlink_channel;
            (*it)->uplink_channel = config.uplink_channel;
            ++(*it)->version;
        } else {
            auto newConfig = std::make_shared<LTE_PHY_CONFIG>();
            newConfig->downlink_channel = config.downlink_channel;
            newConfig->uplink_channel = config.uplink_channel;
            newConfig->version = nextId_;
            ++nextId_;
            configs_.push_back(newConfig);
        }
    }

    std::shared_ptr<LTE_PHY_CONFIG> getByIndex(size_t index, int expectedVersion) {
        std::lock_guard<mutex> lock(mtx_);

        auto it = configs_.find(index);
        if (it != configs_.end() && it->use_count() > 0 && it->lock()->version == expectedVersion) {
            return *it;
        } else {
            // Handle potential race conditions or outdated data here.
            return nullptr;
        }
    }
};
