    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp; // Store the entry's timestamp for expiration check
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    gsl_list *entries;
    pthread_mutex_t lock;
    void (*callback)(NFAPI_CRC_INDICATION_PDU_T* entry);
} NFAPI_CRC_INDICATION_LIST_T;

void destroy_entry(void *data) {
    NFAPI_CRC_INDICATION_PDU_T *entry = data;
    free(entry);
}

int compare_entry(const void *a, const void *b) {
    return memcmp(&((NFAPI_CRC_INDICATION_PDU_T*)a)->tag, &((NFAPI_CRC_INDICATION_PDU_T*)b)->tag, sizeof(RX_UE_INFORMATION_TAG));
}

NFAPI_CRC_INDICATION_LIST_T* create_list(size_t max_size) {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->entries = gsl_list_alloc(compare_entry);
    list->lock = PTHREAD_MUTEX_INITIALIZER;
    return list;
}

void add_entry(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    if (gsl_list_length(list->entries) >= max_size) {
        // Prune outdated entries
        while (gsl_list_length(list->entries)) {
            NFAPI_CRC_INDICATION_PDU_T *oldest = gsl_list_min(list->entries);
            if (time(NULL) - oldest->timestamp > EXPIRATION_THRESHOLD) {
                gsl_list_remove(list->entries, oldest);
                free(oldest);
            } else break;
        }

        // Resize the list if necessary
        if (gsl_list_length(list->entries) >= max_size) {
            GSL_LLIST *new_list = gsl_list_resize(list->entries, compare_entry);
            list->entries = new_list;
        }
    }

    // Add the entry and call the callback if set
    gsl_list_append(list->entries, entry);
    if (list->callback) {
        list->callback(entry);
    }

    pthread_mutex_unlock(&list->lock);
}

void set_callback(NFAPI_CRC_INDICATION_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T* entry)) {
    list->callback = callback;
}

void free_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    gsl_list_foreach(list->entries, (gfunc_t)destroy_entry);
    gsl_list_free(list->entries);
    free(list);
    pthread_mutex_unlock(&list->lock);
}
