NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(size_t num_structures, uint32_t seed, bool verbose) {
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
    srand(seed);

    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_indications) {
        print_error("Memory allocation failed for crc_indications.");
        return NULL;
    }

    uint32_t last_crci_flag = rand() % (1 << 31);
    bool retry = true;

    for (size_t i = 0; i < num_structures && retry; ++i) {
        crc_indications[i].RX_UE_INFORMATION_TAG.tag = i + 1;
        crc_indications[i].RNTI = rand() % MAX_RNTI_VALUE;
        crc_indications[i].CRC_INDICATION_REL8_TAG.tag = REL8_TAG_VALUE;

