        last_crci_flag ^= 1;

        // Retry if memory allocation fails
        if (!verbose) {
            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(crc_indications, ((i + 2) < num_structures) ? sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0);
            if (!temp) {
                print_error("Memory allocation failed during iteration.");
                retry = false;
                break;
            }
            crc_indications = temp;
        }
    }

    // Free extra memory if the loop ended before reaching num_structures
    free((void *)(crc_indications + num_structures));

    return (num_structures == retry) ? crc_indications : NULL;
}
