void seeded_random(unsigned long *state, unsigned long *value) {
    *value ^= (*value << 13);
    *value ^= (*value >> 17);
    *value ^= (*value << 5);
    *state *= 0x85ebca6b;
    *value += *state;
}

int generate_structures(size_t N, unsigned long seed, size_t max_memory, NFAPI_CRC_INDICATION_PDU_T **data) {
    if (N <= 0) return INVALID_INPUT;
    if (max_memory < sizeof(NFAPI_CRCI_INDICATION_PDU_T)) return TOO_SMALL_MEMORY;

    unsigned long state = seed;
