        seeded_random(&state, &crccflags[i]);
        data[i]->crc_indication.CRCFLAG = ((i * now + state) % 2);
    }

    pthread_mutex_destroy(&mutex);

    logging_function(LOGGING_LEVEL_INFO, "Structure population complete");

    return 0;
